def normalize_device_type(value: str) -> str:
    if value in DEVICE_TYPES:
        return value
    lowered = value.strip().casefold()
    return _DEVICE_TYPE_ALIASES.get(lowered, next(
        (kind for kind in DEVICE_TYPES if kind.casefold() == lowered), TYPE_UNKNOWN,
    ))


def ui_text(lang: str, vi: str, en: str, zh: str) -> str:
    return {"en": en, "zh": zh}.get(lang, vi)


