def now_str() -> str:
    return datetime.now().strftime("%Y-%m-%d %H:%M:%S")


def new_id(prefix: str = "dev") -> str:
    return f"{prefix}_{uuid.uuid4().hex[:8]}"


def get_data_dir() -> Path:
    local_app_data = os.environ.get("LOCALAPPDATA")
    data_dir = (Path(local_app_data) / APP_NAME) if local_app_data else (Path.home() / ".lanmap")
    data_dir.mkdir(parents=True, exist_ok=True)
    return data_dir


def enable_windows_dpi_awareness() -> None:
    if sys.platform != "win32":
        return
    try:
        ctypes.windll.shcore.SetProcessDpiAwareness(1)
    except Exception:
        try:
            ctypes.windll.user32.SetProcessDPIAware()
        except Exception:
            pass


def find_bundled_asset(filename: str) -> Path | None:
    """Tìm tệp ảnh/icon đi kèm (LanMap1.png, LanMap-Storm.ico) cả khi chạy trong PyCharm lẫn khi đóng gói .exe."""
    candidates: list[Path] = []
    meipass = getattr(sys, "_MEIPASS", None)
    if meipass:
        candidates.append(Path(meipass) / filename)
    if getattr(sys, "frozen", False):
        candidates.append(Path(sys.executable).resolve().parent / filename)
    try:
        candidates.append(Path(__file__).resolve().parent / filename)
    except Exception:
        pass
    candidates.append(Path.cwd() / filename)
    for c in candidates:
        if c.exists():
            return c
    return None


def generate_logo_files(target_dir: Path | None = None) -> tuple[Path | None, Path | None]:
    if Image is None or ImageDraw is None:
        return None, None
    out_dir = target_dir or get_data_dir()
    out_dir.mkdir(parents=True, exist_ok=True)
    png_path = out_dir / "lanmap_logo.png"
    ico_path = out_dir / "lanmap.ico"

    size = 512
    img = Image.new("RGBA", (size, size), (0, 0, 0, 0))
    d = ImageDraw.Draw(img)
    pad = 24
    d.rounded_rectangle([pad, pad, size - pad, size - pad], radius=110, fill=(15, 42, 82, 255), outline=(56, 189, 248, 255), width=12)

    center = (256, 236)
    nodes = [(140, 150), (372, 150), (132, 344), (256, 376), (380, 344)]
    for nx, ny in nodes:
        d.line([center, (nx, ny)], fill=(125, 211, 252, 235), width=14)
    d.line([nodes[0], nodes[1]], fill=(56, 189, 248, 120), width=8)
    for i, (nx, ny) in enumerate(nodes):
        r = 30
        col = (34, 197, 94, 255) if i != 4 else (250, 204, 21, 255)
        d.ellipse([nx - r, ny - r, nx + r, ny + r], fill=col, outline=(255, 255, 255, 255), width=8)
    cr = 48
    d.ellipse([center[0] - cr, center[1] - cr, center[0] + cr, center[1] + cr], fill=(14, 165, 233, 255), outline=(255, 255, 255, 255), width=10)
    d.ellipse([center[0] - 16, center[1] - 16, center[0] + 16, center[1] + 16], fill=(255, 255, 255, 255))

    logo_256 = img.resize((256, 256), Image.Resampling.LANCZOS)
    logo_256.save(png_path, format="PNG")
    logo_256.save(ico_path, format="ICO", sizes=[(16, 16), (32, 32), (48, 48), (64, 64), (128, 128), (256, 256)])
    return png_path, ico_path


def create_windows_desktop_shortcut() -> tuple[bool, str]:
    if sys.platform != "win32":
        return False, "Tính năng tạo biểu tượng Desktop chỉ hỗ trợ trên Windows."
    try:
        data_dir = get_data_dir()
        data_dir.mkdir(parents=True, exist_ok=True)
        storm_ico = find_bundled_asset("LanMap-Storm.ico")
        if storm_ico and storm_ico.exists():
            ico_path = data_dir / "LanMap-Storm.ico"
            if storm_ico.resolve() != ico_path.resolve():
                ico_path.write_bytes(storm_ico.read_bytes())
        else:
            _, ico_path = generate_logo_files(data_dir)
        desktop = Path(os.environ.get("USERPROFILE", str(Path.home()))) / "Desktop"
        if not desktop.exists():
            desktop = Path.home() / "Desktop"
        shortcut_path = desktop / f"{APP_NAME}.lnk"
        if getattr(sys, "frozen", False):
            target, args, workdir = sys.executable, "", str(Path(sys.executable).parent)
        else:
            target, args, workdir = sys.executable, f'"{Path(__file__).resolve()}"', str(Path(__file__).resolve().parent)
        icon_str = str(ico_path) if ico_path and ico_path.exists() else target
        ps_script = (
            f'$ws = New-Object -ComObject WScript.Shell; '
            f'$sc = $ws.CreateShortcut("{shortcut_path}"); '
            f'$sc.TargetPath = "{target}"; '
            f'$sc.Arguments = \'{args}\'; '
            f'$sc.WorkingDirectory = "{workdir}"; '
            f'$sc.IconLocation = "{icon_str},0"; '
            f'$sc.Description = "LanMap - Quan ly va giam sat mang noi bo"; '
            f'$sc.Save()'
        )
        subprocess.run(["powershell", "-NoProfile", "-ExecutionPolicy", "Bypass", "-Command", ps_script], check=True, capture_output=True, creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0x08000000))
        return True, f"Đã tạo biểu tượng LanMap ngoài Desktop:\n{shortcut_path}"
    except Exception as exc:
        return False, f"Không thể tạo biểu tượng Desktop: {exc}"


def _parse_version_tuple(ver: str) -> tuple[int, int, int] | None:
    matched = re.fullmatch(r"v?(\d+)\.(\d+)\.(\d+)", ver.strip(), flags=re.IGNORECASE)
    if not matched:
        return None
    major, minor, patch = matched.groups()
    return int(major), int(minor), int(patch)


def check_github_release(repo: str) -> dict[str, Any]:
    clean_repo = repo.strip().strip("/")
    if not re.fullmatch(r"[A-Za-z0-9-]+/[A-Za-z0-9_.-]+", clean_repo):
        return {"ok": False, "error": "Nhập kho GitHub theo dạng ten-tai-khoan/LanMap."}
    url = f"https://api.github.com/repos/{clean_repo}/releases/latest"
    req = urllib.request.Request(url, headers={"User-Agent": f"{APP_NAME}/{APP_VERSION}"})
    try:
        with urllib.request.urlopen(req, timeout=8) as resp:
            data = json.loads(resp.read().decode("utf-8", errors="replace"))
        latest_tag = str(data.get("tag_name", "")).strip()
        html_url = str(data.get("html_url", f"https://github.com/{clean_repo}/releases"))
        body = str(data.get("body", "")).strip() or "Phiên bản phát hành mới trên GitHub."
        latest_version = _parse_version_tuple(latest_tag)
        current_version = _parse_version_tuple(APP_VERSION)
        if latest_version is None or current_version is None:
            return {"ok": False, "error": "Tag phát hành cần có dạng v3.9.1 để LanMap so sánh phiên bản."}
        download_url = next(
            (str(asset["browser_download_url"]) for asset in data.get("assets", [])
             if str(asset.get("name", "")).casefold() == "lanmap.exe" and asset.get("browser_download_url")),
            html_url,
        )
        return {
            "ok": True,
            "has_update": latest_version > current_version,
            "latest_tag": latest_tag or "N/A",
            "html_url": html_url,
            "download_url": download_url,
            "notes": body[:600],
        }
    except urllib.error.HTTPError as exc:
        if exc.code == 404:
            return {"ok": False, "error": "GitHub chưa trả về bản phát hành công khai cho kho này. Kiểm tra tên kho và mục Releases."}
        return {"ok": False, "error": f"GitHub trả về lỗi HTTP {exc.code}. Hãy thử lại sau."}
    except (OSError, ValueError) as exc:
        return {"ok": False, "error": f"Không đọc được GitHub Releases: {exc}"}


