@dataclass
class ServiceCheck:
    name: str
    port: int
    status: str = STATUS_UNCHECKED
    last_checked: str = ""

    def to_dict(self) -> dict[str, Any]:
        return asdict(self)

    @classmethod
    def from_dict(cls, data: dict[str, Any]) -> "ServiceCheck":
        return cls(
            name=str(data.get("name", "Dịch vụ")),
            port=int(data.get("port", 80)),
            status=str(data.get("status", STATUS_UNCHECKED)),
            last_checked=str(data.get("last_checked", "")),
        )


@dataclass
class CanvasAnnotation:
    """Hình vẽ khu vực (khung chữ nhật, hình tròn có/không tô màu) hoặc ghi chú trên sơ đồ như Cisco Packet Tracer."""

    id: str = field(default_factory=lambda: new_id("ann"))
    kind: str = "note"  # "note" | "rect" | "oval"
    x1: float = 120.0
    y1: float = 120.0
    x2: float = 340.0
    y2: float = 260.0
    text: str = "Ghi chú"
    color: str = "#0284c7"
    fill_hex: str = ""
    color_name: str = "Xanh dương"
    filled: bool = True
    dashed: bool = False
    floor: str = DEFAULT_FLOOR

    def to_dict(self) -> dict[str, Any]:
        return asdict(self)

    @classmethod
    def from_dict(cls, data: dict[str, Any]) -> "CanvasAnnotation":
        cname = str(data.get("color_name", "Xanh dương"))
        if cname not in DRAW_COLOR_PALETTE:
            cname = "Xanh dương"
        return cls(
            id=str(data.get("id", new_id("ann"))),
            kind=str(data.get("kind", "note")),
            x1=float(data.get("x1", 120.0)),
            y1=float(data.get("y1", 120.0)),
            x2=float(data.get("x2", 340.0)),
            y2=float(data.get("y2", 260.0)),
            text=str(data.get("text", "")),
            color=str(data.get("color", DRAW_COLOR_PALETTE[cname][0])),
            fill_hex=str(data.get("fill_hex", "")),
            color_name=cname,
            filled=bool(data.get("filled", True)),
            dashed=bool(data.get("dashed", False)),
            floor=str(data.get("floor", DEFAULT_FLOOR)) or DEFAULT_FLOOR,
        )


@dataclass
class Device:
    id: str = field(default_factory=lambda: new_id("dev"))
    name: str = "Thiết bị mới"
    ip: str = ""
    extra_ips: list[str] = field(default_factory=list)
    mac: str = ""
    vendor: str = ""
    device_type: str = TYPE_UNKNOWN
    group: str = "Chung"
    floor: str = DEFAULT_FLOOR
    location: str = ""
    notes: str = ""
    subnet: str = ""
    trusted: bool = True
    snmp_info: str = ""
    is_gateway: bool = False
    is_this_pc: bool = False
    registered: bool = True
    x: float = 160.0
    y: float = 160.0
    status: str = STATUS_UNCHECKED
    latency_ms: float | None = None
    last_checked: str = ""
    consecutive_failures: int = 0
    in_incident: bool = False
    incident_started_at: str = ""
    total_checks: int = 0
    online_checks: int = 0
    latency_history: list[float | None] = field(default_factory=list)
    services: list[ServiceCheck] = field(default_factory=list)

    @property
    def uptime_percent(self) -> float | None:
        return round((self.online_checks / self.total_checks) * 100.0, 1) if self.total_checks > 0 else None

    def to_dict(self) -> dict[str, Any]:
        data = asdict(self)
        data["services"] = [s.to_dict() for s in self.services]
        return data

    @classmethod
    def from_dict(cls, data: dict[str, Any]) -> "Device":
        return cls(
            id=str(data.get("id", new_id("dev"))),
            name=str(data.get("name", "Thiết bị")),
            ip=str(data.get("ip", "")),
            extra_ips=[str(x) for x in data.get("extra_ips", [])],
            mac=str(data.get("mac", "")),
            vendor=str(data.get("vendor", "")),
            device_type=normalize_device_type(str(data.get("device_type", TYPE_UNKNOWN))),
            group=str(data.get("group", "Chung")),
            floor=str(data.get("floor", DEFAULT_FLOOR)) or DEFAULT_FLOOR,
            location=str(data.get("location", "")),
            notes=str(data.get("notes", "")),
            subnet=str(data.get("subnet", "")),
            trusted=bool(data.get("trusted", True)),
            snmp_info=str(data.get("snmp_info", "")),
            is_gateway=bool(data.get("is_gateway", False)),
            is_this_pc=bool(data.get("is_this_pc", False)),
            registered=bool(data.get("registered", True)),
            x=float(data.get("x", 160.0)),
            y=float(data.get("y", 160.0)),
            status={"online": STATUS_ONLINE, "offline": STATUS_NO_PING}.get(
                str(data.get("status", "")).lower(), str(data.get("status", STATUS_UNCHECKED)),
            ),
            latency_ms=data.get("latency_ms", None),
            last_checked=str(data.get("last_checked", "")),
            consecutive_failures=int(data.get("consecutive_failures", 0)),
            in_incident=bool(data.get("in_incident", False)),
            incident_started_at=str(data.get("incident_started_at", "")),
            total_checks=int(data.get("total_checks", 0)),
            online_checks=int(data.get("online_checks", 0)),
            latency_history=list(data.get("latency_history", []))[-20:],
            services=[ServiceCheck.from_dict(s) for s in data.get("services", [])],
        )


@dataclass
class NetworkLink:
    id: str = field(default_factory=lambda: new_id("lnk"))
    source_id: str = ""
    target_id: str = ""
    confirmed: bool = True

    def connects(self, a: str, b: str) -> bool:
        return (self.source_id == a and self.target_id == b) or (self.source_id == b and self.target_id == a)

    def to_dict(self) -> dict[str, Any]:
        return asdict(self)

    @classmethod
    def from_dict(cls, data: dict[str, Any]) -> "NetworkLink":
        return cls(
            id=str(data.get("id", new_id("lnk"))),
            source_id=str(data.get("source_id", "")),
            target_id=str(data.get("target_id", "")),
            confirmed=bool(data.get("confirmed", True)),
        )


@dataclass
class IncidentRecord:
    id: str = field(default_factory=lambda: new_id("inc"))
    timestamp: str = ""
    device_id: str = ""
    device_name: str = ""
    ip: str = ""
    event_type: str = "Mất phản hồi"
    details: str = ""

    def to_dict(self) -> dict[str, Any]:
        return asdict(self)

    @classmethod
    def from_dict(cls, data: dict[str, Any]) -> "IncidentRecord":
        return cls(
            id=str(data.get("id", new_id("inc"))),
            timestamp=str(data.get("timestamp", "")),
            device_id=str(data.get("device_id", "")),
            device_name=str(data.get("device_name", "")),
            ip=str(data.get("ip", "")),
            event_type=str(data.get("event_type", "Mất phản hồi")),
            details=str(data.get("details", "")),
        )


@dataclass
class AdapterInfo:
    name: str
    adapter_type: str
    ip: str
    netmask: str
    subnet_cidr: str
    gateway: str = ""
    is_virtual: bool = False
    is_up: bool = True

    def display_label(self) -> str:
        gw = self.gateway if self.gateway else "Không có"
        return f"[{self.adapter_type}] {self.name} — IP: {self.ip} | Dải: {self.subnet_cidr} | GW: {gw}"


@dataclass
class FaultIsolationResult:
    suspect_device_id: str
    suspect_device_name: str
    upstream_name: str
    affected_device_ids: list[str]
    highlighted_link_ids: list[str]
    message: str


@dataclass
class AppState:
    first_run_done: bool = False
    language: str = "vi"
    selected_adapter_name: str = ""
    selected_ip: str = ""
    selected_subnet: str = ""
    selected_gateway: str = ""
    known_gateway_mac: str = ""
    github_repo: str = DEFAULT_GITHUB_REPO
    network_authorized: bool = False
    vlan_scan_inputs: str = ""
    monitor_interval_sec: int = DEFAULT_MONITOR_INTERVAL_SEC
    failure_threshold: int = DEFAULT_FAILURE_THRESHOLD
    show_subnet_group: bool = False
    show_auto_links: bool = False
    appearance_mode: str = "System"
    canvas_theme: str = "Nền chấm tối"
    floors: list[str] = field(default_factory=lambda: [DEFAULT_FLOOR])
    active_floor: str = DEFAULT_FLOOR
    devices: list[Device] = field(default_factory=list)
    links: list[NetworkLink] = field(default_factory=list)
    annotations: list[CanvasAnnotation] = field(default_factory=list)
    incidents: list[IncidentRecord] = field(default_factory=list)

    def to_dict(self) -> dict[str, Any]:
        return {
            "first_run_done": self.first_run_done,
            "language": self.language,
            "selected_adapter_name": self.selected_adapter_name,
            "selected_ip": self.selected_ip,
            "selected_subnet": self.selected_subnet,
            "selected_gateway": self.selected_gateway,
            "known_gateway_mac": self.known_gateway_mac,
            "github_repo": self.github_repo,
            "network_authorized": self.network_authorized,
            "vlan_scan_inputs": self.vlan_scan_inputs,
            "monitor_interval_sec": self.monitor_interval_sec,
            "failure_threshold": self.failure_threshold,
            "show_subnet_group": self.show_subnet_group,
            "show_auto_links": self.show_auto_links,
            "appearance_mode": self.appearance_mode,
            "canvas_theme": self.canvas_theme,
            "floors": self.floors,
            "active_floor": self.active_floor,
            "devices": [d.to_dict() for d in self.devices],
            "links": [lnk.to_dict() for lnk in self.links],
            "annotations": [a.to_dict() for a in self.annotations],
            "incidents": [inc.to_dict() for inc in self.incidents[-500:]],
        }

    @classmethod
    def from_dict(cls, data: dict[str, Any]) -> "AppState":
        theme = str(data.get("canvas_theme", "Nền chấm tối"))
        if theme not in CANVAS_THEMES:
            theme = "Nền chấm tối"
        lang = str(data.get("language", "vi"))
        if lang not in I18N:
            lang = "vi"
        return cls(
            first_run_done=bool(data.get("first_run_done", False)),
            language=lang,
            selected_adapter_name=str(data.get("selected_adapter_name", "")),
            selected_ip=str(data.get("selected_ip", "")),
            selected_subnet=str(data.get("selected_subnet", "")),
            selected_gateway=str(data.get("selected_gateway", "")),
            known_gateway_mac=str(data.get("known_gateway_mac", "")),
            github_repo=str(data.get("github_repo", DEFAULT_GITHUB_REPO)),
            network_authorized=bool(data.get("network_authorized", False)),
            vlan_scan_inputs=str(data.get("vlan_scan_inputs") or ""),
            monitor_interval_sec=int(data.get("monitor_interval_sec", DEFAULT_MONITOR_INTERVAL_SEC)),
            failure_threshold=int(data.get("failure_threshold", DEFAULT_FAILURE_THRESHOLD)),
            show_subnet_group=bool(data.get("show_subnet_group", False)),
            show_auto_links=bool(data.get("show_auto_links", False)),
            appearance_mode=str(data.get("appearance_mode", "System")),
            canvas_theme=theme,
            floors=[str(f) for f in data.get("floors", [DEFAULT_FLOOR]) if str(f).strip()] or [DEFAULT_FLOOR],
            active_floor=str(data.get("active_floor", DEFAULT_FLOOR)) or DEFAULT_FLOOR,
            devices=[Device.from_dict(d) for d in data.get("devices", [])],
            links=[NetworkLink.from_dict(lnk) for lnk in data.get("links", [])],
            annotations=[CanvasAnnotation.from_dict(a) for a in data.get("annotations", [])],
            incidents=[IncidentRecord.from_dict(inc) for inc in data.get("incidents", [])],
        )


# =============================================================================
# 3. LƯU TRỮ JSON, XUẤT CSV & KHẮC PHỤC SỰ CỐ THÔNG MINH
# =============================================================================

class StateRepository:
    def __init__(self, data_dir: Path | None = None) -> None:
        self.data_dir = data_dir or get_data_dir()
        self.data_dir.mkdir(parents=True, exist_ok=True)
        self.state_file = self.data_dir / "lanmap_state.json"

    def load_state(self) -> AppState:
        if not self.state_file.exists():
            return AppState()
        try:
            raw = json.loads(self.state_file.read_text(encoding="utf-8"))
            if isinstance(raw, dict):
                return AppState.from_dict(raw)
        except Exception:
            pass
        return AppState()

    def save_state(self, state: AppState) -> None:
        tmp = self.state_file.with_suffix(".tmp")
        tmp.write_text(json.dumps(state.to_dict(), ensure_ascii=False, indent=2), encoding="utf-8")
        tmp.replace(self.state_file)

    @staticmethod
    def export_incidents_csv(incidents: list[IncidentRecord], target_path: Path) -> int:
        target_path.parent.mkdir(parents=True, exist_ok=True)
        with target_path.open("w", encoding="utf-8-sig", newline="") as f:
            writer = csv.writer(f)
            writer.writerow(["Thời điểm", "Loại sự kiện", "Tên thiết bị", "Địa chỉ IP", "Chi tiết"])
            for rec in incidents:
                writer.writerow([rec.timestamp, rec.event_type, rec.device_name, rec.ip, rec.details])
        return len(incidents)

    @staticmethod
    def export_devices_csv(devices: list[Device], target_path: Path) -> int:
        target_path.parent.mkdir(parents=True, exist_ok=True)
        with target_path.open("w", encoding="utf-8-sig", newline="") as f:
            writer = csv.writer(f)
            writer.writerow(["Tên thiết bị", "IP", "MAC", "Hãng", "Loại", "Tầng", "Nhóm", "Vị trí", "Trạng thái", "Uptime (%)", "Độ trễ (ms)", "Tin cậy"])
            for d in devices:
                up = f"{d.uptime_percent:.1f}%" if d.uptime_percent is not None else "—"
                lat = f"{d.latency_ms:.1f}" if d.latency_ms is not None else "—"
                writer.writerow([d.name, d.ip, d.mac, d.vendor, d.device_type, d.floor, d.group, d.location, d.status, up, lat, "Tin cậy" if d.trusted else "Thiết bị lạ"])
        return len(devices)

    @staticmethod
    def backup_topology(devices: list[Device], links: list[NetworkLink], annotations: list[CanvasAnnotation], incidents: list[IncidentRecord], subnet: str, gateway: str, target_path: Path, floors: list[str] | None = None) -> None:
        floor_list = list(dict.fromkeys([DEFAULT_FLOOR, *(floors or []), *(d.floor for d in devices if d.floor), *(a.floor for a in annotations if a.floor)]))
        payload = {
            "format": f"{APP_NAME}_Backup",
            "version": APP_VERSION,
            "exported_at": now_str(),
            "subnet": subnet,
            "gateway": gateway,
            "floors": floor_list,
            "devices": [d.to_dict() for d in devices],
            "links": [lnk.to_dict() for lnk in links],
            "annotations": [a.to_dict() for a in annotations],
            "incidents": [inc.to_dict() for inc in incidents],
        }
        target_path.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")

    @staticmethod
    def restore_topology(source_path: Path) -> tuple[list[Device], list[NetworkLink], list[CanvasAnnotation], list[IncidentRecord], str, str]:
        raw = json.loads(source_path.read_text(encoding="utf-8"))
        if not isinstance(raw, dict) or "devices" not in raw or "links" not in raw:
            raise ValueError("Tệp sao lưu không đúng định dạng LanMap JSON.")
        return (
            [Device.from_dict(d) for d in raw.get("devices", [])],
            [NetworkLink.from_dict(lnk) for lnk in raw.get("links", [])],
            [CanvasAnnotation.from_dict(a) for a in raw.get("annotations", [])],
            [IncidentRecord.from_dict(inc) for inc in raw.get("incidents", [])],
            str(raw.get("subnet") or raw.get("subnet_cidr") or ""),
            str(raw.get("gateway", "")),
        )


def get_remediation_steps(device: Device, faults: list[FaultIsolationResult], lang: str = "vi") -> list[str]:
    """Đưa ra phương pháp khắc phục cụ thể theo ngôn ngữ (vi / en / zh) khi thiết bị gặp sự cố hoặc bị đánh dấu lạ."""
    steps: list[str] = []
    for f in faults:
        if f.suspect_device_id == device.id or device.id in f.affected_device_ids:
            if lang == "en":
                steps.extend([
                    f"1. Check power & port LEDs on '{f.suspect_device_name}'.",
                    f"2. Reseat or replace the uplink cable between '{f.suspect_device_name}' and '{f.upstream_name}'.",
                    f"3. Restart '{f.suspect_device_name}' and click 'Check' again.",
                ])
            elif lang == "zh":
                steps.extend([
                    f"1. 检查 '{f.suspect_device_name}' 的电源及端口指示灯。",
                    f"2. 重新插拔或更换 '{f.suspect_device_name}' 到 '{f.upstream_name}' 的上行网线。",
                    f"3. 重启 '{f.suspect_device_name}' 后点击“检测”。",
                ])
            else:
                steps.extend([
                    f"1. Kiểm tra nguồn điện và đèn cổng trên '{f.suspect_device_name}'.",
                    f"2. Rút cắm lại dây uplink nối từ '{f.suspect_device_name}' lên '{f.upstream_name}'.",
                    f"3. Khởi động lại '{f.suspect_device_name}' rồi bấm 'Kiểm tra' lại.",
                ])
            return steps

    if not device.trusted:
        if lang == "en":
            steps.extend([
                "1. Verify whether this unknown device belongs to your office/lab (check Vendor, MAC, Open Ports).",
                "2. If recognized, click '✓ Approve Trusted' to clear the yellow warning badge (!).",
                "3. If unauthorized, open Router 'Web Admin' to block its MAC or change the Wi-Fi password.",
            ])
        elif lang == "zh":
            steps.extend([
                "1. 核实该陌生设备是否属于本机房/办公室（查看厂商、MAC、开放端口）。",
                "2. 若确认安全，点击“✓ 批准为可信设备”以消除黄色警告标记 (!)。",
                "3. 若为非法接入，请打开路由器“网页管理”拉黑该 MAC 或修改 Wi-Fi 密码。",
            ])
        else:
            steps.extend([
                "1. Xác minh xem thiết bị lạ này có thuộc phòng máy/văn phòng không (dựa vào Hãng, MAC, Cổng mở).",
                "2. Nếu là thiết bị quen, bấm '✓ Duyệt Thiết bị tin cậy' để tắt cảnh báo chấm vàng (!).",
                "3. Nếu là thiết bị truy cập trái phép, mở 'Web quản trị' trên Router để chặn MAC hoặc đổi mật khẩu Wi-Fi.",
            ])

    if device.status == STATUS_NO_PING:
        if device.is_gateway or device.device_type == TYPE_ROUTER:
            steps.extend(
                [
                    "1. Router may be blocking ICMP Ping (normal if Internet still works).",
                    "2. If Internet is down, check fiber/WAN cable and restart the modem/router.",
                ] if lang == "en" else (
                    ["1. 路由器可能禁用了 ICMP Ping（若上网正常则属正常现象）。", "2. 若全网断线，请检查光纤/WAN 口并重启路由器。"]
                    if lang == "zh" else
                    ["1. Router có thể đang tắt phản hồi Ping (ICMP) — nếu máy vẫn vào mạng bình thường thì không phải lỗi.", "2. Nếu toàn phòng mất mạng, kiểm tra nguồn & dây WAN/cáp quang rồi khởi động lại Router."]
                )
            )
        elif device.device_type in (TYPE_PHONE, TYPE_TV):
            steps.extend([
                ui_text(lang, "Kiểm tra Wi-Fi, tên mạng và địa chỉ IP của thiết bị.",
                        "Check Wi-Fi, the network name and the device IP address.", "检查 Wi-Fi、网络名称和设备 IP。"),
                ui_text(lang, "Thử kết nối lại Wi-Fi. Thiết bị có thể vẫn vào mạng dù không trả lời Ping.",
                        "Reconnect to Wi-Fi. The device can be online while ignoring Ping.", "重新连接 Wi-Fi。设备可能在线但不响应 Ping。"),
            ])
        elif device.device_type == TYPE_PRINTER:
            steps.extend(
                [
                    "1. Check printer power, sleep mode, and Ethernet/Wi-Fi connection.",
                    "2. Run 'Port Scan' to verify port 9100 (Raw Print) and check if DHCP changed its IP.",
                ] if lang == "en" else (
                    ["1. 检查打印机电源、休眠状态及网线/Wi-Fi 连接。", "2. 点击“端口扫描”检查 9100 端口，确认 DHCP 是否更改了打印机 IP。"]
                    if lang == "zh" else
                    ["1. Kiểm tra máy in có đang tắt nguồn, ngủ đông hoặc lỏng cáp mạng/mất Wi-Fi không.", "2. Bấm 'Quét cổng' kiểm tra cổng 9100 và xem DHCP có cấp đổi IP máy in không."]
                )
            )
        else:
            steps.extend(
                [
                    "1. Check if the device is powered off/sleeping (try 'Wake (WoL)' if wired).",
                    "2. Verify Windows Firewall is not blocking ICMP Echo Request (Ping).",
                    "3. Check LAN cable / Wi-Fi signal and run 'Traceroute' to find where packets stop.",
                ] if lang == "en" else (
                    ["1. 检查设备是否关机或休眠（有线连接可尝试“远程唤醒”）。", "2. 检查系统防火墙是否拦截了 ICMP Ping。", "3. 检查网线/Wi-Fi 并运行“路由追踪”定位断点。"]
                    if lang == "zh" else
                    ["1. Kiểm tra máy có đang tắt nguồn/ngủ không (thử bấm 'Bật máy (WoL)' nếu cắm dây LAN).", "2. Kiểm tra Windows Firewall có đang chặn ICMP Ping không.", "3. Kiểm tra dây mạng/Wi-Fi và bấm 'Traceroute' để xem gói tin dừng ở đâu."]
                )
            )
    return steps


def export_html_report(devices: list[Device], incidents: list[IncidentRecord], subnet: str, target_path: Path) -> int:
    """Xuất báo cáo kiểm kê & sức khỏe mạng LAN dạng trang HTML đẹp để mở bằng Chrome hoặc in PDF nộp thầy."""
    reg = [d for d in devices if d.registered]
    online = sum(1 for d in reg if d.status == STATUS_ONLINE)
    offline = sum(1 for d in reg if d.status == STATUS_NO_PING)
    rogue = sum(1 for d in reg if not d.trusted)
    rows_html = []
    for d in sorted(reg, key=lambda x: (x.floor, x.device_type, x.name.lower())):
        badge = "#16a34a" if d.status == STATUS_ONLINE else ("#dc2626" if d.status == STATUS_NO_PING else "#64748b")
        up = f"{d.uptime_percent:.1f}%" if d.uptime_percent is not None else "—"
        lat = f"{d.latency_ms:.1f} ms" if d.latency_ms is not None else "—"
        trust = "✓ Tin cậy" if d.trusted else "⚠ Thiết bị lạ"
        rows_html.append(
            f"<tr><td><b>{d.name}</b></td><td>{d.ip or 'L2'}</td><td>{d.mac or '—'}</td>"
            f"<td>{d.device_type}</td><td>{d.vendor or '—'}</td><td>{d.floor}</td>"
            f"<td><span style='color:{badge};font-weight:bold'>{d.status}</span></td>"
            f"<td>{lat}</td><td>{up}</td><td>{trust}</td></tr>"
        )
    html = f"""<!doctype html><html lang="vi"><head><meta charset="utf-8">
<title>LanMap Network Audit Report</title>
<style>
body{{font-family:'Segoe UI',Arial,sans-serif;background:#f8fafc;color:#0f172a;margin:28px}}
h1{{margin:0 0 4px;color:#0369a1}} .sub{{color:#475569;margin-bottom:18px}}
.cards{{display:flex;gap:14px;margin-bottom:20px}}
.card{{flex:1;background:#fff;border:1px solid #e2e8f0;border-radius:10px;padding:14px 18px}}
.card .n{{font-size:26px;font-weight:700}}
table{{width:100%;border-collapse:collapse;background:#fff;border-radius:10px;overflow:hidden;box-shadow:0 1px 4px rgba(0,0,0,.06)}}
th,td{{padding:9px 11px;border-bottom:1px solid #e2e8f0;text-align:left;font-size:13px}}
th{{background:#0f172a;color:#fff}}
tr:hover{{background:#f1f5f9}}
</style></head><body>
<h1>LanMap v{APP_VERSION} — Báo cáo Kiểm kê & Giám sát Mạng LAN</h1>
<div class="sub">Dải mạng: <b>{subnet or 'N/A'}</b> | Thời điểm xuất: <b>{now_str()}</b></div>
<div class="cards">
  <div class="card"><div>Tổng thiết bị</div><div class="n">{len(reg)}</div></div>
  <div class="card"><div>Đang phản hồi</div><div class="n" style="color:#16a34a">{online}</div></div>
  <div class="card"><div>Mất phản hồi</div><div class="n" style="color:#dc2626">{offline}</div></div>
  <div class="card"><div>Thiết bị lạ (chưa duyệt)</div><div class="n" style="color:#d97706">{rogue}</div></div>
</div>
<table><thead><tr><th>Tên thiết bị</th><th>IP</th><th>MAC</th><th>Loại</th><th>Hãng</th><th>Tầng</th><th>Trạng thái</th><th>Độ trễ</th><th>Uptime</th><th>Tin cậy</th></tr></thead>
<tbody>{''.join(rows_html)}</tbody></table>
</body></html>"""
    target_path.write_text(html, encoding="utf-8")
    return len(reg)


def run_internet_diagnostics(gateway: str) -> list[tuple[str, bool, str]]:
    """Chẩn đoán sức khỏe mạng: thử ICMP Ping trước, nếu Firewall trường/công ty chặn ICMP thì tự đo qua TCP để ra độ trễ thật."""
    results: list[tuple[str, bool, str]] = []
    checks: list[tuple[str, str, int]] = []
    if gateway:
        checks.append((f"Gateway nội bộ ({gateway})", gateway, 80))
    checks.extend([("Google DNS (8.8.8.8)", "8.8.8.8", 53), ("Cloudflare (1.1.1.1)", "1.1.1.1", 443)])

    for label, host, tcp_port in checks:
        ok, lat = ping_host(host, timeout_ms=1000)
        if ok:
            results.append((label, True, f"{lat:.1f} ms (ICMP Ping)" if lat is not None else "Phản hồi (ICMP)"))
        else:
            t0 = time.perf_counter()
            if check_tcp_port(host, tcp_port, timeout=1.5):
                dt = (time.perf_counter() - t0) * 1000.0
                results.append((label, True, f"{dt:.0f} ms qua TCP/{tcp_port} (Firewall mạng đang chặn ICMP Ping)"))
            else:
                results.append((label, False, "Không phản hồi (Firewall chặn cả ICMP & TCP)"))

    t0 = time.perf_counter()
    try:
        ip_res = socket.gethostbyname("github.com")
        dt = (time.perf_counter() - t0) * 1000.0
        results.append(("Phân giải DNS (github.com)", True, f"{ip_res} ({dt:.0f} ms)"))
    except Exception:
        results.append(("Phân giải DNS (github.com)", False, "Lỗi DNS / Không có Internet"))
    return results


def query_netbios_name(ip: str, timeout: float = 0.45) -> str:
    """Đọc tên thật của Windows PC & Máy in mạng (EPSONA30336, BRN..., DESKTOP-...) qua NetBIOS UDP 137 trong ~20ms."""
    pkt = (
        b"\x82\x28\x00\x00\x00\x01\x00\x00\x00\x00\x00\x00"
        b"\x20CKAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\x00\x00\x21\x00\x01"
    )
    sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    sock.settimeout(timeout)
    try:
        sock.sendto(pkt, (ip, 137))
        data, _ = sock.recvfrom(1024)
        if len(data) > 57:
            num_names = data[56]
            offset = 57
            for _ in range(min(num_names, 12)):
                if offset + 18 > len(data):
                    break
                raw_name = data[offset:offset + 15].decode("ascii", errors="ignore").strip()
                suffix = data[offset + 15]
                flags = (data[offset + 16] << 8) | data[offset + 17]
                is_group = bool(flags & 0x8000)
                if raw_name and not is_group and suffix in (0x00, 0x20):
                    return raw_name
                offset += 18
    except Exception:
        pass
    finally:
        try:
            sock.close()
        except Exception:
            pass
    return ""


def get_wifi_analysis_text() -> str:
    """Phân tích tín hiệu Wi-Fi hiện tại & các mạng Wi-Fi xung quanh (SSID, kênh phát, % sóng, tốc độ Mbps)."""
    if sys.platform != "win32":
        return "Tính năng phân tích sóng Wi-Fi (netsh wlan) chỉ hỗ trợ trên Windows."
    parts: list[str] = []
    for title, cmd in (
        ("=== THÔNG SỐ WI-FI ĐANG KẾT NỐI ===", ["netsh", "wlan", "show", "interfaces"]),
        ("=== CÁC MẠNG WI-FI & KÊNH PHÁT XUNG QUANH ===", ["netsh", "wlan", "show", "networks", "mode=bssid"]),
    ):
        try:
            out = subprocess.check_output(cmd, text=True, encoding="utf-8", errors="ignore", timeout=6, creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0x08000000))
            parts.append(f"{title}\n{out.strip()}")
        except Exception as exc:
            parts.append(f"{title}\nKhông đọc được dữ liệu: {exc}")
    return "\n\n".join(parts)


def get_public_wan_info() -> str:
    """Tra cứu IP công khai (WAN), nhà mạng (ISP) và vị trí."""
    try:
        req = urllib.request.Request("http://ip-api.com/json/?fields=status,country,city,isp,org,query", headers={"User-Agent": f"{APP_NAME}/{APP_VERSION}"})
        with urllib.request.urlopen(req, timeout=6) as resp:
            d = json.loads(resp.read().decode("utf-8", errors="replace"))
        if d.get("status") == "success":
            return f"IP Công khai (WAN): {d.get('query')}\nNhà mạng (ISP): {d.get('isp')}\nTổ chức: {d.get('org')}\nKhu vực: {d.get('city')}, {d.get('country')}"
    except Exception:
        pass
    try:
        req2 = urllib.request.Request("https://api.ipify.org?format=json", headers={"User-Agent": f"{APP_NAME}/{APP_VERSION}"})
        with urllib.request.urlopen(req2, timeout=6) as resp2:
            d2 = json.loads(resp2.read().decode("utf-8", errors="replace"))
        return f"IP Công khai (WAN): {d2.get('ip')}"
    except Exception as exc:
        return f"Không tra cứu được IP công khai: {exc}"


def grab_http_title_and_server(
    ip: str, port: int = 80, timeout: float = 0.65, *, tls: bool = False,
) -> tuple[str, str]:
    """Đọc tiêu đề và header của trang quản trị, không đăng nhập."""
    def read_prefix(sock: socket.socket) -> bytes:
        sock.sendall(
            f"GET / HTTP/1.0\r\nHost: {ip}\r\nUser-Agent: LanMap\r\nConnection: close\r\n\r\n".encode("ascii")
        )
        deadline = time.monotonic() + timeout
        raw = bytearray()
        while len(raw) < 4096:
            remaining = deadline - time.monotonic()
            if remaining <= 0:
                break
            sock.settimeout(remaining)
            try:
                chunk = sock.recv(min(1024, 4096 - len(raw)))
            except TimeoutError:
                break
            if not chunk:
                break
            raw.extend(chunk)
            if b"</title" in raw.lower() and b"\r\n\r\n" in raw:
                break
        return bytes(raw)

    try:
        with socket.create_connection((ip, port), timeout=timeout) as sock:
            if tls:
                # Một số switch dùng chứng chỉ tự ký. Dữ liệu đọc chỉ là gợi ý nhận diện.
                context = ssl.SSLContext(ssl.PROTOCOL_TLS_CLIENT)
                context.check_hostname = False
                context.verify_mode = ssl.CERT_NONE
                with context.wrap_socket(sock, server_hostname=ip) as secured:
                    raw = read_prefix(secured)
            else:
                raw = read_prefix(sock)
    except (OSError, ValueError):
        return "", ""
    txt = raw.decode("utf-8", errors="ignore")
    headers, _, body = txt.partition("\r\n\r\n")
    srv_m = re.search(r"(?im)^Server:[ \t]*([^\r\n]{1,100})", headers)
    tit_m = re.search(r"(?is)<title[^>]*>([^<]{2,100})</title>", body)
    srv = srv_m.group(1).strip() if srv_m else ""
    tit = re.sub(r"\s+", " ", tit_m.group(1)).strip() if tit_m else ""
    return tit, srv

def grab_tcp_banner(ip: str, port: int, timeout: float = 0.7) -> str:
    """Đọc banner dịch vụ (SSH, FTP, SMTP, Telnet) kiểu Nmap -sV."""
    try:
        with socket.create_connection((ip, port), timeout=timeout) as s:
            s.settimeout(timeout)
            data = s.recv(256)
            return data.decode("utf-8", errors="ignore").strip().splitlines()[0][:80] if data else ""
    except Exception:
        return ""


def detect_os_by_ping_ttl(ip: str) -> tuple[str, int | None]:
    """Đoán hệ điều hành dựa theo giá trị TTL trong gói phản hồi Ping (kỹ thuật kinh điển của Nmap)."""
    try:
        cmd = ["ping", "-n", "1", "-w", "900", ip] if sys.platform == "win32" else ["ping", "-c", "1", "-W", "1", ip]
        out = subprocess.check_output(cmd, text=True, encoding="utf-8", errors="ignore", timeout=2.5, creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0x08000000))
        m = re.search(r"(?i)TTL[=:](\d+)", out)
        if m:
            ttl = int(m.group(1))
            if ttl <= 64:
                return f"Linux / Android / iOS / macOS (TTL={ttl})", ttl
            if ttl <= 128:
                return f"Windows PC / Laptop (TTL={ttl})", ttl
            return f"Router / Switch / Thiết bị mạng (TTL={ttl})", ttl
    except Exception:
        pass
    return "Không đọc được TTL (chặn ICMP)", None


def list_smb_shared_folders(ip: str) -> list[tuple[str, str, str]]:
    """Liệt kê các thư mục & máy in đang được chia sẻ qua mạng (SMB) trên IP mục tiêu."""
    if sys.platform != "win32":
        return []
    shares: list[tuple[str, str, str]] = []
    try:
        out = subprocess.check_output(
            ["net", "view", f"\\\\{ip}", "/all"],
            text=True, encoding="utf-8", errors="ignore", timeout=5,
            creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0x08000000),
        )
        in_table = False
        for line in out.splitlines():
            if line.strip().startswith("---"):
                in_table = True
                continue
            if not in_table:
                continue
            if not line.strip() or "completed successfully" in line.lower() or "thành công" in line.lower():
                break
            parts = re.split(r"\s{2,}", line.strip())
            if len(parts) >= 2:
                sname = parts[0]
                stype = parts[1]
                sdesc = parts[2] if len(parts) >= 3 else ""
                shares.append((sname, stype, sdesc))
    except Exception:
        pass
    return shares


def run_nmap_style_deep_scan(dev: Device) -> str:
    """Quét chuyên sâu 1 thiết bị kiểu Kali / Nmap (-O -sV): OS TTL + 18 cổng dịch vụ + Banner + HTTP Title + SNMP + SMB Shares."""
    ip = dev.ip
    lines = [
        "=== KẾT QUẢ QUÉT CHI TIẾT LANMAP ===",
        f"Thiết bị : {dev.name} ({ip})",
        f"MAC      : {dev.mac or 'Chưa có'} | Hãng: {dev.vendor or 'Chưa rõ'}",
    ]
    os_guess, _ = detect_os_by_ping_ttl(ip)
    lines.append(f"Hệ điều hành (TTL): {os_guess}")

    scan_ports = [
        (21, "FTP"), (22, "SSH"), (23, "Telnet"), (53, "DNS"), (80, "HTTP"),
        (135, "MSRPC"), (139, "NetBIOS"), (443, "HTTPS"), (445, "SMB"),
        (554, "RTSP Camera"), (631, "IPP Printer"), (1433, "MSSQL"), (3306, "MySQL"),
        (3389, "RDP"), (5900, "VNC"), (8008, "Smart TV/Cast"), (8080, "HTTP-Alt"), (9100, "RAW Printer"),
    ]
    open_list: list[tuple[int, str, str]] = []
    def _chk(pt: tuple[int, str]) -> tuple[int, str, str] | None:
        port, svc = pt
        if not check_tcp_port(ip, port, timeout=0.65):
            return None
        info = ""
        if port in (80, 8080, 631):
            tit, srv = grab_http_title_and_server(ip, port, timeout=0.7)
            info = " | ".join(x for x in (tit, srv) if x)
        elif port in (21, 22, 23):
            info = grab_tcp_banner(ip, port, timeout=0.7)
        return (port, svc, info)

    with ThreadPoolExecutor(max_workers=18) as pool:
        for res in pool.map(_chk, scan_ports):
            if res:
                open_list.append(res)

    lines.append(f"\n--- CỔNG DỊCH VỤ ĐANG MỞ ({len(open_list)}) ---")
    if open_list:
        for port, svc, info in sorted(open_list):
            lines.append(f"  {port:<6}/tcp   OPEN   {svc:<14} {info}")
    else:
        lines.append("  Không phát hiện cổng phổ biến nào mở (hoặc Firewall chặn).")

    snmp_desc = query_snmp_sysdescr(ip) if dev.device_type in (TYPE_ROUTER, TYPE_SWITCH, TYPE_WIFI, TYPE_SERVER) else ""
    if snmp_desc:
        lines.append(f"\n--- THÔNG TIN SNMP ---\n  {snmp_desc}")

    shares = list_smb_shared_folders(ip) if any(port == 445 for port, _, _ in open_list) else []
    if shares:
        lines.append(f"\n--- THƯ MỤC / MÁY IN CHIA SẺ SMB ({len(shares)}) ---")
        for sname, stype, sdesc in shares:
            lines.append(f"  \\\\{ip}\\{sname:<18} [{stype}] {sdesc}")
    return "\n".join(lines)


def send_lan_message(ip: str, sender_name: str, text: str) -> tuple[bool, str]:
    """Gửi tin nhắn trực tiếp tới thiết bị qua mạng LAN (LanMap Chat UDP 55123 + thử lệnh Windows msg.exe)."""
    sent_udp = False
    try:
        payload = json.dumps({"app": APP_NAME, "from": sender_name, "text": text, "time": now_str().split()[-1]}, ensure_ascii=False).encode("utf-8")
        with socket.socket(socket.AF_INET, socket.SOCK_DGRAM) as s:
            s.sendto(payload, (ip, LANMAP_CHAT_PORT))
        sent_udp = True
    except Exception:
        pass

    win_msg_ok = False
    if sys.platform == "win32":
        try:
            r = subprocess.run(
                ["msg", "*", f"/SERVER:{ip}", f"[{sender_name} via LanMap]: {text}"],
                capture_output=True, text=True, timeout=3,
                creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0x08000000),
            )
            win_msg_ok = (r.returncode == 0)
        except Exception:
            pass

    if win_msg_ok:
        return True, f"✓ Đã bật thông báo Windows + gửi LanMap Chat tới {ip}!"
    if sent_udp:
        return True, f"✓ Đã gửi gói tin LanMap Chat tới {ip}:{LANMAP_CHAT_PORT} (máy đích sẽ hiện thông báo ngay nếu đang mở LanMap; Windows msg.exe cần bật AllowRemoteRPC trên máy đích)."
    return False, f"Không gửi được tin nhắn tới {ip}."


def inspect_http_ssl(target: str) -> str:
    """Kiểm tra HTTP Header bảo mật & Chứng chỉ SSL/TLS của website hoặc IP nội bộ (kiểu Kali Web Audit)."""
    clean = target.strip().replace("https://", "").replace("http://", "").split("/")[0]
    host = clean.split(":")[0]
    lines = [f"=== KIỂM TRA WEB & CHỨNG CHỈ SSL: {clean} ==="]
    for scheme in ("https", "http"):
        try:
            req = urllib.request.Request(f"{scheme}://{clean}", headers={"User-Agent": f"{APP_NAME}/{APP_VERSION}"})
            ctx = ssl._create_unverified_context() if scheme == "https" else None
            with urllib.request.urlopen(req, timeout=6, context=ctx) as resp:
                lines.append(f"\n[{scheme.upper()}] Status: {resp.status}")
                for h in ("Server", "X-Powered-By", "Strict-Transport-Security", "X-Frame-Options", "Content-Security-Policy"):
                    val = resp.headers.get(h)
                    lines.append(f"  {h}: {val or '(Chưa cấu hình)'}")
                break
        except Exception as exc:
            lines.append(f"[{scheme.upper()}] Không kết nối được: {exc}")

    try:
        ctx = ssl.create_default_context()
        with socket.create_connection((host, 443), timeout=5) as sock:
            with ctx.wrap_socket(sock, server_hostname=host) as ssock:
                cert = ssock.getpeercert()
                issuer = dict(x[0] for x in cert.get("issuer", ()))
                subj = dict(x[0] for x in cert.get("subject", ()))
                lines.append("\n=== CHỨNG CHỈ SSL / TLS (Cổng 443) ===")
                lines.append(f"  Cấp cho (CN) : {subj.get('commonName', '—')}")
                lines.append(f"  Nhà phát hành: {issuer.get('organizationName', issuer.get('commonName', '—'))}")
                lines.append(f"  Hiệu lực đến : {cert.get('notAfter', '—')}")
    except Exception as exc:
        lines.append(f"\n[SSL 443] Không đọc được chứng chỉ SSL: {exc}")
    return "\n".join(lines)



LANMAP_DISCOVER_PORT = 55125


def discover_lanmap_clients_udp(timeout: float = 0.9) -> dict[str, dict[str, str]]:
    """Phát gói tin UDP 55125 tìm nhanh toàn bộ máy đang chạy LanMap Client trong mạng LAN (lấy Tên tự đặt, Chủ máy & MAC)."""
    found: dict[str, dict[str, str]] = {}
    sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    try:
        sock.setsockopt(socket.SOL_SOCKET, socket.SO_BROADCAST, 1)
        sock.settimeout(0.25)
        sock.sendto(b"DISCOVER_LANMAP_CLIENT", ("255.255.255.255", LANMAP_DISCOVER_PORT))
        end_t = time.monotonic() + timeout
        while time.monotonic() < end_t:
            try:
                data, addr = sock.recvfrom(2048)
                obj = json.loads(data.decode("utf-8", errors="ignore"))
                if isinstance(obj, dict) and obj.get("app") == "LanMapClient":
                    found[addr[0]] = {
                        "name": str(obj.get("name", "")).strip(),
                        "owner": str(obj.get("owner", "")).strip(),
                        "mac": str(obj.get("mac", "")).strip().upper(),
                    }
            except socket.timeout:
                continue
            except Exception:
                continue
    except Exception:
        pass
    finally:
        try:
            sock.close()
        except Exception:
            pass
    return found


def query_client_hello(ip: str, timeout: float = 0.55) -> dict[str, str] | None:
    """Hỏi nhanh cổng 55124 xem IP này có cài LanMap Client không (không cần PIN cho lệnh hello công khai)."""
    try:
        req = json.dumps({"action": "hello"}).encode("utf-8") + b"\n"
        with socket.create_connection((ip, LANMAP_AGENT_PORT), timeout=timeout) as s:
            s.settimeout(timeout)
            s.sendall(req)
            raw = s.recv(2048).decode("utf-8", errors="ignore").splitlines()[0]
            obj = json.loads(raw)
            if isinstance(obj, dict) and obj.get("ok") and obj.get("app") == "LanMapClient":
                return {
                    "name": str(obj.get("name", "")).strip(),
                    "owner": str(obj.get("owner", "")).strip(),
                    "mac": str(obj.get("mac", "")).strip().upper(),
                }
    except Exception:
        pass
    return None

def query_lanmap_agent(ip: str, pin: str, action: str = "sysinfo", payload: str = "", timeout: float = 4.0) -> dict[str, Any]:
    """Kết nối đồng bộ tới ứng dụng LanMap Client (lanmap_agent.py, cổng TCP 55124) có xác thực mã PIN."""
    try:
        req = json.dumps({"pin": pin, "action": action, "payload": payload, "from": socket.gethostname()}, ensure_ascii=False).encode("utf-8") + b"\n"
        with socket.create_connection((ip, LANMAP_AGENT_PORT), timeout=timeout) as sock:
            sock.settimeout(timeout)
            sock.sendall(req)
            raw = b""
            while len(raw) < 65536:
                chunk = sock.recv(4096)
                if not chunk:
                    break
                raw += chunk
                if b"\n" in chunk:
                    break
        if not raw:
            return {"ok": False, "error": "Client không trả về dữ liệu."}
        return json.loads(raw.decode("utf-8", errors="replace").splitlines()[0])
    except Exception as exc:
        return {"ok": False, "error": f"Không kết nối được LanMap Client tại {ip}:{LANMAP_AGENT_PORT} (máy đích chưa mở lanmap_agent.py hoặc bị Firewall chặn).\nChi tiết: {exc}"}


_SWITCH_IDENTITY = re.compile(
    r"(?:\b(?:managed\s+switch|network\s+switch|ethernet\s+switch|catalyst|procurve|"
    r"powerswitch|flexfabric|comware|edgeswitch|unifi\s+switch)|"
    r"\b(?:tl[-_ ]?sg|gs|sg|sx|cbs|usw|ex|c29|c35|c37|c38|c92|c93|c94|c95)\d{2,5}(?=\b|[a-z-])|"
    r"\b(?:sw|switch)[-_ ]?[a-z]{0,12}\d{1,4}\b|^switch\s*$)",
    re.IGNORECASE,
)


def _looks_like_switch(identity: str) -> bool:
    return bool(_SWITCH_IDENTITY.search(identity or ""))


def classify_device_smart(mac: str = "", hostname: str = "", open_ports: set[int] | None = None) -> tuple[str, str]:
    """Tự nhận diện thông minh Hãng & Loại thiết bị (Smart TV, Máy in, Laptop/PC, Điện thoại, Server, Router/Wi-Fi)."""
    hn = (hostname or "").strip().lower()
    ports = open_ports or set()
    clean_mac = (mac or "").strip().upper().replace("-", ":")
    prefix = clean_mac[:8] if len(clean_mac) >= 8 else ""
    vendor, oui_type = OUI_VENDORS.get(prefix, ("", TYPE_UNKNOWN))

    if _looks_like_switch(hn) or oui_type == TYPE_SWITCH:
        return (vendor or "Switch quản lý", TYPE_SWITCH)
    if re.search(r"\b(?:router|gateway)(?:\b|\d)", hn):
        return (vendor or "Router", TYPE_ROUTER)

    # 0. Camera IP / Đầu ghi NVR-DVR (RTSP 554, Hikvision 8000, Dahua 37777, ONVIF 8899)
    if bool(ports & {554, 8000, 37777, 8899}) or any(k in hn for k in ("hikvision", "dahua", "ezviz", "imou", "tapo", "reolink", "kbvision", "ipcam", "camera", "nvr", "dvr", "axis", "foscam")):
        return (vendor or "Camera IP", TYPE_CAMERA)

    # 1. Smart TV (Android TV / Chromecast / Samsung / LG / Sony)
    if any(k in hn for k in ("tv", "bravia", "tizen", "webos", "chromecast", "androidtv", "lgwebos", "samsungtv")) or bool(ports & {8008, 8009, 8001, 3000}):
        return (vendor or "Smart TV", TYPE_TV)

    # 2. Máy in mạng (HP, Brother BRN/BRW, Epson, Canon NPI, cổng 9100/631)
    if (9100 in ports or 631 in ports) or any(k in hn for k in ("brn", "brw", "epson", "hp-", "canon", "npi", "printer", "mfp", "laserjet", "ricoh", "xerox")) or oui_type == TYPE_PRINTER:
        return (vendor or "Máy in mạng", TYPE_PRINTER)

    # 3. Router / Switch / Wi-Fi
    if any(k in hn for k in ("router", "gateway", "mikrotik", "tplink", "unifi", "cisco", "switch", "ap-")) or oui_type in (TYPE_ROUTER, TYPE_SWITCH, TYPE_WIFI):
        return (vendor or "Hạ tầng mạng", oui_type if oui_type != TYPE_UNKNOWN else TYPE_WIFI)

    # 4. Máy tính / Laptop (Windows SMB 445/135/3389 hoặc tên DESKTOP-/LAPTOP-/WIN-/PC/MACBOOK)
    if bool(ports & {445, 135, 3389}) or any(k in hn for k in ("desktop-", "laptop-", "win-", "pc", "macbook", "imac", "msi", "asus", "dell", "lenovo", "acer", "thinkpad")):
        return (vendor or "Windows / Laptop", TYPE_PC)

    # 5. Điện thoại / Di động (cổng iOS 62078, tên iPhone/iPad/Android/Galaxy/Xiaomi/Oppo/Vivo hoặc MAC ngẫu nhiên)
    is_rand_mac = len(clean_mac) >= 2 and clean_mac[1] in ("2", "6", "A", "E")
    if (62078 in ports) or any(k in hn for k in ("iphone", "ipad", "android", "galaxy", "redmi", "xiaomi", "oppo", "vivo", "realme", "pixel", "oneplus", "phone")) or oui_type == TYPE_PHONE:
        return (vendor or "Di động", TYPE_PHONE)

    # 6. Server / NAS (cổng SSH 22 hoặc Web 80/443 khi không phải PC/Printer)
    if bool(ports & {22, 80, 443, 8080}) or any(k in hn for k in ("server", "nas", "synology", "ubuntu", "linux", "proxmox", "esxi")):
        return (vendor or "Server / Web", TYPE_SERVER)

    # 7. Thiết bị dùng MAC ngẫu nhiên (iOS 14+ / Android 10+ mặc định bật Private Wi-Fi Address)
    if is_rand_mac:
        return ("Di động (MAC ngẫu nhiên)", TYPE_PHONE)

    if oui_type != TYPE_UNKNOWN:
        return (vendor, oui_type)
    if hn:
        return (vendor or "Thiết bị mạng", TYPE_PC)
    return (vendor, TYPE_UNKNOWN)


def send_raw_print_9100(ip: str, payload: bytes, timeout: float = 4.0) -> tuple[bool, str]:
    """Gửi lệnh in trực tiếp qua giao thức RAW TCP cổng 9100 tới máy in mạng (HP, Brother, Epson, Canon...)."""
    try:
        with socket.create_connection((ip, 9100), timeout=timeout) as sock:
            sock.sendall(payload)
        return True, f"Đã gửi lệnh in thành công tới máy in {ip} (cổng 9100)."
    except Exception as exc:
        return False, f"Không kết nối được cổng in 9100 trên {ip}: {exc}"


def run_speedtest_live(on_progress: Callable[[str, float, float, float], None], cancel_event: threading.Event) -> dict[str, Any]:
    """Đo tốc độ mạng thực tế (Ping ms, Download Mbps, Upload Mbps) qua Cloudflare Speedtest."""
    ping_ms = 0.0
    dl_mbps = 0.0
    ul_mbps = 0.0

    on_progress("Đang đo độ trễ (Ping)...", 0.0, 0.0, 0.0)
    pings = []
    for _ in range(3):
        if cancel_event.is_set():
            return {"cancelled": True}
        ok, lat = ping_host("1.1.1.1", timeout_ms=1200)
        if ok and lat is not None:
            pings.append(lat)
    ping_ms = round(sum(pings) / len(pings), 1) if pings else 0.0
    on_progress("Đang đo tốc độ Tải xuống (Download)...", ping_ms, 0.0, 0.0)

    try:
        url_dl = "https://speed.cloudflare.com/__down?bytes=10000000"
        req = urllib.request.Request(url_dl, headers={"User-Agent": f"{APP_NAME}/{APP_VERSION}"})
        t0 = time.perf_counter()
        total_b = 0
        with urllib.request.urlopen(req, timeout=15) as resp:
            while not cancel_event.is_set():
                chunk = resp.read(131072)
                if not chunk:
                    break
                total_b += len(chunk)
                dt = max(0.05, time.perf_counter() - t0)
                dl_mbps = round((total_b * 8.0) / (dt * 1_000_000.0), 2)
                on_progress(f"Đang tải xuống... {dl_mbps:.2f} Mbps", ping_ms, dl_mbps, 0.0)
                if dt > 7.0:
                    break
    except Exception as exc:
        return {"ok": False, "error": f"Lỗi đo Download: {exc}", "ping": ping_ms, "dl": dl_mbps, "ul": 0.0}

    if cancel_event.is_set():
        return {"cancelled": True}

    on_progress("Đang đo tốc độ Tải lên (Upload)...", ping_ms, dl_mbps, 0.0)
    try:
        payload = b"0" * 3_000_000
        req_up = urllib.request.Request(
            "https://speed.cloudflare.com/__up",
            data=payload,
            method="POST",
            headers={"User-Agent": f"{APP_NAME}/{APP_VERSION}", "Content-Type": "application/octet-stream"},
        )
        t1 = time.perf_counter()
        with urllib.request.urlopen(req_up, timeout=15) as resp_up:
            resp_up.read()
        dt_up = max(0.05, time.perf_counter() - t1)
        ul_mbps = round((len(payload) * 8.0) / (dt_up * 1_000_000.0), 2)
        on_progress("Hoàn tất!", ping_ms, dl_mbps, ul_mbps)
    except Exception:
        ul_mbps = 0.0

    return {"ok": True, "ping": ping_ms, "dl": dl_mbps, "ul": ul_mbps}


# =============================================================================
# 4. CÔNG CỤ QUẢN TRỊ CHỦ ĐỘNG, LƯU LƯỢNG & PHÁT HIỆN MẠNG
# =============================================================================

def send_wake_on_lan(mac_address: str) -> tuple[bool, str]:
    clean = re.sub(r"[^0-9a-fA-F]", "", mac_address or "")
    if len(clean) != 12:
        return False, "Thiết bị chưa có địa chỉ MAC hợp lệ (ví dụ AA:BB:CC:DD:EE:FF)."
    try:
        magic = b"\xff" * 6 + bytes.fromhex(clean) * 16
        with socket.socket(socket.AF_INET, socket.SOCK_DGRAM) as s:
            s.setsockopt(socket.SOL_SOCKET, socket.SO_BROADCAST, 1)
            s.sendto(magic, ("255.255.255.255", 9))
        return True, f"Đã gửi gói tin bật máy từ xa (Wake-on-LAN) tới MAC {mac_address}."
    except Exception as exc:
        return False, f"Lỗi gửi Wake-on-LAN: {exc}"


def _build_snmp_v2c_get(community: str, oid_bytes: bytes) -> bytes:
    def tlv(tag: int, val: bytes) -> bytes:
        n = len(val)
        return bytes([tag]) + (bytes([n]) if n < 128 else bytes([0x81, n])) + val
    varbind = tlv(0x30, tlv(0x06, oid_bytes) + b"\x05\x00")
    pdu = tlv(0xA0, tlv(0x02, b"\x01\x01") + tlv(0x02, b"\x00") + tlv(0x02, b"\x00") + tlv(0x30, varbind))
    return tlv(0x30, tlv(0x02, b"\x01") + tlv(0x04, community.encode("ascii")) + pdu)


def query_snmp_sysdescr(ip: str, community: str = "public", timeout: float = 1.0) -> str:
    oid = bytes([0x2B, 0x06, 0x01, 0x02, 0x01, 0x01, 0x01, 0x00])
    try:
        with socket.socket(socket.AF_INET, socket.SOCK_DGRAM) as sock:
            sock.settimeout(timeout)
            sock.connect((ip, 161))
            sock.send(_build_snmp_v2c_get(community, oid))
            data = sock.recv(2048)
        idx = data.find(oid)
        if idx == -1:
            return ""
        rest = data[idx + len(oid):]
        pos = rest.find(b"\x04")
        if pos == -1 or pos + 2 >= len(rest):
            return ""
        length, start = rest[pos + 1], pos + 2
        if length & 0x80:
            nb = length & 0x7F
            length = int.from_bytes(rest[start:start + nb], "big")
            start += nb
        return rest[start:start + length].decode("utf-8", errors="replace").strip()
    except Exception:
        return ""


def open_ssh_console(ip: str, user: str = "admin") -> tuple[bool, str]:
    if sys.platform != "win32":
        return False, "Mở SSH trực tiếp hỗ trợ trên Windows."
    try:
        subprocess.Popen(["cmd", "/c", "start", "cmd", "/k", f"ssh {user}@{ip}"])
        return True, f"Đã mở cửa sổ SSH tới {user}@{ip}."
    except Exception as exc:
        return False, f"Không mở được SSH: {exc}"


def open_rdp_session(ip: str) -> tuple[bool, str]:
    if sys.platform != "win32":
        return False, "Remote Desktop (mstsc) chỉ hỗ trợ trên Windows."
    try:
        subprocess.Popen(["mstsc", f"/v:{ip}"])
        return True, f"Đã mở Remote Desktop tới {ip}."
    except Exception as exc:
        return False, f"Không mở được Remote Desktop: {exc}"


def open_shared_folder(ip: str) -> tuple[bool, str]:
    if sys.platform != "win32":
        return False, "Mở thư mục chia sẻ SMB hỗ trợ trên Windows."
    try:
        os.startfile(f"\\\\{ip}")  # type: ignore[attr-defined]
        return True, f"Đang mở thư mục chia sẻ mạng \\\\{ip}."
    except Exception as exc:
        return False, f"Không mở được \\\\{ip}: {exc}"


def list_active_app_connections(limit: int = 25) -> list[tuple[str, str, str]]:
    if psutil is None:
        return []
    rows: list[tuple[str, str, str]] = []
    proc_names: dict[int, str] = {}
    try:
        for conn in psutil.net_connections(kind="inet"):
            if not conn.raddr:
                continue
            pid = conn.pid or 0
            if pid not in proc_names:
                try:
                    proc_names[pid] = psutil.Process(pid).name() if pid else "System"
                except Exception:
                    proc_names[pid] = f"PID {pid}"
            rows.append((proc_names[pid], f"{conn.raddr.ip}:{conn.raddr.port}", conn.status))
            if len(rows) >= limit:
                break
    except Exception:
        pass
    return rows


LATENCY_RE = re.compile(r"(?:time|th[oờ]i\s*gian)\s*[=<]\s*([\d.]+)\s*ms", re.IGNORECASE)
ARP_LINE_RE = re.compile(r"(\d{1,3}(?:\.\d{1,3}){3})\s+([0-9a-fA-F]{2}(?:[:-][0-9a-fA-F]{2}){5})")


def _subproc_flags() -> int:
    return getattr(subprocess, "CREATE_NO_WINDOW", 0x08000000) if sys.platform == "win32" else 0


def _is_valid_ipv4(val: str) -> bool:
    try:
        ipaddress.IPv4Address(val)
        return True
    except Exception:
        return False


def is_virtual_adapter_name(name: str) -> bool:
    return any(k in name.lower() for k in VIRTUAL_ADAPTER_KEYWORDS)


def classify_adapter_type(name: str, is_virtual: bool) -> str:
    if is_virtual:
        return "Ảo / VPN"
    low = name.lower()
    if any(k in low for k in ("wi-fi", "wifi", "wlan", "wireless", "802.11")):
        return "Wi-Fi"
    if any(k in low for k in ("ethernet", "lan", "local area", "eth", "enp", "eno")):
        return "Ethernet"
    return "Khác"


def _compute_subnet_cidr(ip: str, netmask: str) -> str:
    try:
        return str(ipaddress.IPv4Interface(f"{ip}/{netmask}").network)
    except Exception:
        parts = ip.split(".")
        return f"{parts[0]}.{parts[1]}.{parts[2]}.0/24" if len(parts) == 4 else f"{ip}/24"


def _get_windows_gateways_by_ip() -> dict[str, str]:
    gateways: dict[str, str] = {}
    if sys.platform != "win32":
        return gateways
    try:
        proc = subprocess.run(["route", "print", "-4"], capture_output=True, text=True, timeout=6, errors="replace", creationflags=_subproc_flags())
        for line in proc.stdout.splitlines():
            parts = line.split()
            if len(parts) >= 4 and parts[0] == "0.0.0.0" and parts[1] == "0.0.0.0":
                gw, iface_ip = parts[2], parts[3]
                if _is_valid_ipv4(gw) and _is_valid_ipv4(iface_ip) and iface_ip not in gateways:
                    gateways[iface_ip] = gw
    except Exception:
        pass
    return gateways


def _parse_windows_ipconfig() -> list[AdapterInfo]:
    adapters: list[AdapterInfo] = []
    if sys.platform != "win32":
        return adapters
    try:
        enc = locale.getpreferredencoding(False) or "utf-8"
        proc = subprocess.run(["ipconfig"], capture_output=True, timeout=6, creationflags=_subproc_flags())
        text = proc.stdout.decode(enc, errors="replace")
    except Exception:
        return adapters
    name = ip = mask = gw = ""

    def flush() -> None:
        if name and _is_valid_ipv4(ip) and not ip.startswith(("127.", "169.254.")):
            m = mask if _is_valid_ipv4(mask) else "255.255.255.0"
            virt = is_virtual_adapter_name(name)
            adapters.append(AdapterInfo(name, classify_adapter_type(name, virt), ip, m, _compute_subnet_cidr(ip, m), gw if _is_valid_ipv4(gw) else "", virt))

    ip_re = re.compile(r"(\d{1,3}(?:\.\d{1,3}){3})")
    for raw in text.splitlines():
        line = raw.rstrip()
        if not line:
            continue
        if not line.startswith(" ") and line.endswith(":"):
            flush()
            name = line[:-1].strip()
            for prefix in ("Wireless LAN adapter ", "Ethernet adapter ", "Unknown adapter "):
                if name.startswith(prefix):
                    name = name[len(prefix):].strip()
            ip = mask = gw = ""
            continue
        m = ip_re.search(line)
        if not m:
            continue
        low = line.lower()
        if "ipv4" in low or "ip address" in low:
            ip = m.group(1)
        elif "subnet mask" in low:
            mask = m.group(1)
        elif "default gateway" in low:
            gw = m.group(1)
    flush()
    return adapters


def list_network_adapters(include_virtual: bool = False) -> list[AdapterInfo]:
    adapters: list[AdapterInfo] = []
    gateways = _get_windows_gateways_by_ip()
    if psutil is not None:
        try:
            addrs = psutil.net_if_addrs()
            stats = psutil.net_if_stats()
            for iface_name, addr_list in addrs.items():
                st = stats.get(iface_name)
                if st is not None and not st.isup:
                    continue
                virt = is_virtual_adapter_name(iface_name)
                for addr in addr_list:
                    if addr.family == socket.AF_INET:
                        ip = addr.address
                        if not _is_valid_ipv4(ip) or ip.startswith(("127.", "169.254.")):
                            continue
                        mask = addr.netmask or "255.255.255.0"
                        adapters.append(AdapterInfo(iface_name, classify_adapter_type(iface_name, virt), ip, mask, _compute_subnet_cidr(ip, mask), gateways.get(ip, ""), virt))
        except Exception:
            adapters = []
    if not adapters and sys.platform == "win32":
        adapters = _parse_windows_ipconfig()
    adapters.sort(key=lambda a: (1 if a.is_virtual else 0, 0 if a.gateway else 1, 0 if a.adapter_type in ("Wi-Fi", "Ethernet") else 1, a.name.lower()))
    if not include_virtual:
        real = [a for a in adapters if not a.is_virtual]
        if real:
            return real
    return adapters


def get_all_local_ipv4s() -> list[str]:
    ips: list[str] = []
    for adp in list_network_adapters(include_virtual=True):
        if adp.ip not in ips:
            ips.append(adp.ip)
    return ips


@dataclass
class DiscoveredHost:
    ip: str
    reachable: bool
    latency_ms: float | None = None
    mac: str = ""
    hostname: str = ""
    vendor: str = ""
    guessed_type: str = TYPE_UNKNOWN
    is_gateway: bool = False
    is_this_pc: bool = False


def ping_host(ip: str, timeout_ms: int = 450) -> tuple[bool, float | None]:
    cmd = ["ping", "-n", "1", "-w", str(timeout_ms), ip] if sys.platform == "win32" else ["ping", "-c", "1", "-W", str(max(1, (timeout_ms + 999) // 1000)), ip]
    try:
        proc = subprocess.run(cmd, capture_output=True, text=True, timeout=max(2.0, timeout_ms / 1000.0 + 1.5), errors="replace", creationflags=_subproc_flags())
        out = proc.stdout or ""
        if proc.returncode == 0 and ("TTL=" in out.upper() or LATENCY_RE.search(out)):
            m = LATENCY_RE.search(out)
            return True, round(float(m.group(1)), 1) if m else 1.0
        return False, None
    except Exception:
        return False, None


def run_traceroute_fast(ip: str) -> str:
    cmd = ["tracert", "-d", "-h", "6", "-w", "450", ip] if sys.platform == "win32" else ["traceroute", "-n", "-m", "6", "-w", "1", ip]
    try:
        proc = subprocess.run(cmd, capture_output=True, text=True, timeout=14, errors="replace", creationflags=_subproc_flags())
        return (proc.stdout or proc.stderr or "Không có phản hồi.").strip()
    except Exception as exc:
        return f"Không chạy được traceroute: {exc}"


def read_arp_table(interface_ip: str = "") -> dict[str, str]:
    mapping: dict[str, str] = {}
    try:
        command = ["arp", "-a"]
        if interface_ip and sys.platform == "win32":
            command += ["-N", interface_ip]
        proc = subprocess.run(command, capture_output=True, text=True, timeout=5, errors="replace", creationflags=_subproc_flags())
        for line in proc.stdout.splitlines():
            m = ARP_LINE_RE.search(line)
            if m:
                mac = m.group(2).replace("-", ":").upper()
                if mac not in ("FF:FF:FF:FF:FF:FF", "00:00:00:00:00:00"):
                    mapping[m.group(1)] = mac
    except Exception:
        pass
    return mapping


def detect_arp_anomalies(arp_map: dict[str, str], gateway_ip: str, known_gateway_mac: str) -> tuple[list[IncidentRecord], str]:
    alerts: list[IncidentRecord] = []
    ts = now_str()
    new_gw_mac = known_gateway_mac
    if gateway_ip and gateway_ip in arp_map:
        curr_mac = arp_map[gateway_ip]
        if known_gateway_mac and curr_mac != known_gateway_mac:
            alerts.append(
                IncidentRecord(
                    timestamp=ts, device_id="arp_gw", device_name=f"Gateway ({gateway_ip})", ip=gateway_ip,
                    event_type="Cảnh báo ARP",
                    details=f"MAC của Gateway đổi từ {known_gateway_mac} sang {curr_mac} (kiểm tra nguy cơ giả mạo ARP).",
                )
            )
        new_gw_mac = curr_mac
    return alerts, new_gw_mac


def check_tcp_port(ip: str, port: int, timeout: float = 0.55) -> bool:
    try:
        with socket.create_connection((ip, int(port)), timeout=timeout):
            return True
    except Exception:
        return False


def scan_common_ports(ip: str) -> list[ServiceCheck]:
    ts = now_str()
    found: list[ServiceCheck] = []
    with ThreadPoolExecutor(max_workers=7) as pool:
        futs = {pool.submit(check_tcp_port, ip, port, 0.55): (port, name) for port, name in COMMON_TCP_PORTS}
        for fut in as_completed(futs):
            port, name = futs[fut]
            if fut.result():
                found.append(ServiceCheck(name=name, port=port, status="Hoạt động", last_checked=ts))
    found.sort(key=lambda s: s.port)
    return found


def _resolve_hostname_fast(ip: str, timeout: float = 1.6) -> str:
    """Lấy tên thật thiết bị cực nhanh: ưu tiên NetBIOS UDP 137 (~20ms cho PC & Máy in), sau đó mới dùng DNS PTR."""
    nb = query_netbios_name(ip, timeout=0.45)
    if nb:
        return nb
    res: list[str] = [""]
    def _w() -> None:
        try:
            res[0] = socket.gethostbyaddr(ip)[0].split(".")[0]
        except Exception:
            pass
    t = threading.Thread(target=_w, daemon=True)
    t.start()
    t.join(timeout)
    return res[0]


def fingerprint_device_fast(ip: str, mac: str) -> tuple[str, str, str]:
    """Nhận diện chuẩn xác (Máy in, Laptop/PC, Smart TV, Điện thoại, Server) với timeout đủ cho mạng Wi-Fi."""
    cli_info = query_client_hello(ip, timeout=0.45)
    if cli_info:
        c_name = cli_info.get("name") or _resolve_hostname_fast(ip, timeout=0.6)
        c_owner = cli_info.get("owner") or "Đã cài Client"
        return c_name, f"LanMap Client ({c_owner})", TYPE_PC
    hostname = _resolve_hostname_fast(ip, timeout=1.35)
    open_ports: set[int] = set()
    probe_ports = (9100, 631, 554, 8000, 37777, 8899, 445, 135, 3389, 62078, 8008, 8001, 3000, 80, 443, 22, LANMAP_AGENT_PORT)
    with ThreadPoolExecutor(max_workers=12) as ppool:
        futs = {ppool.submit(check_tcp_port, ip, p, 0.75): p for p in probe_ports}
        for f in as_completed(futs):
            try:
                if f.result():
                    open_ports.add(futs[f])
            except Exception:
                pass
    if not hostname and (80 in open_ports or 631 in open_ports):
        tit, srv = grab_http_title_and_server(ip, 80 if 80 in open_ports else 631, timeout=0.6)
        if tit and len(tit) >= 3 and not any(b in tit.lower() for b in ("home", "index", "login", "welcome", "301", "302", "400", "401", "403", "404", "500", "moved", "error", "redirect", "bad request", "forbidden")):
            hostname = tit[:28]
        elif srv and not hostname:
            hostname = srv.split("/")[0][:24]
    vendor, guessed = classify_device_smart(mac, hostname, open_ports)
    return hostname, vendor, guessed


def discover_subnet(adapter: AdapterInfo, cancel_event: threading.Event, progress_cb: Callable[[int, int, str], None] | None = None) -> tuple[list[DiscoveredHost], dict[str, str], bool]:
    try:
        net = ipaddress.IPv4Network(adapter.subnet_cidr, strict=False)
        if net.num_addresses > 256:
            net = ipaddress.IPv4Network(f"{adapter.ip}/24", strict=False)
        targets = [str(h) for h in net.hosts()]
    except Exception:
        p = adapter.ip.split(".")
        prefix = ".".join(p[:3]) if len(p) == 4 else "192.168.1"
        targets = [f"{prefix}.{i}" for i in range(1, 255)]

    if adapter.gateway and adapter.gateway not in targets:
        targets.insert(0, adapter.gateway)
    if adapter.ip and adapter.ip not in targets:
        targets.insert(0, adapter.ip)

    total = len(targets)
    found: dict[str, DiscoveredHost] = {}
    completed = 0

    def probe(ip: str) -> tuple[str, bool, float | None]:
        if cancel_event.is_set():
            return ip, False, None
        if ip == adapter.ip:
            return ip, True, 0.5
        ok, lat = ping_host(ip, timeout_ms=380)
        return ip, ok, lat

    pool = ThreadPoolExecutor(max_workers=64)
    try:
        futs = {pool.submit(probe, ip): ip for ip in targets}
        for fut in as_completed(futs):
            if cancel_event.is_set():
                for pending in futs:
                    pending.cancel()
                return list(found.values()), {}, True
            try:
                ip, ok, lat = fut.result()
            except Exception:
                ip, ok, lat = futs[fut], False, None
            completed += 1
            if ok or ip == adapter.gateway or ip == adapter.ip:
                found[ip] = DiscoveredHost(ip, ok, lat, is_gateway=(ip == adapter.gateway and bool(adapter.gateway)), is_this_pc=(ip == adapter.ip))
            if progress_cb and (completed % 5 == 0 or completed == total):
                progress_cb(completed, total, f"Ping {ip}")
    finally:
        pool.shutdown(wait=False, cancel_futures=True)

    arp_map = read_arp_table()
    hosts_list = list(found.values())
    h_total = max(1, len(hosts_list))
    if progress_cb:
        progress_cb(0, h_total, f"Đang nhận diện hãng & loại cho {len(hosts_list)} máy...")

    def enrich(host: DiscoveredHost) -> str:
        if host.ip in arp_map:
            host.mac = arp_map[host.ip]
        if host.is_this_pc:
            host.hostname = socket.gethostname()
            host.guessed_type = TYPE_THIS_PC
            return host.ip
        if host.is_gateway:
            host.vendor, _ = classify_device_smart(host.mac)
            host.guessed_type = TYPE_ROUTER
            return host.ip
        if cancel_event.is_set():
            return host.ip
        hn, vendor, gtype = fingerprint_device_fast(host.ip, host.mac)
        host.hostname = hn
        host.vendor = vendor
        host.guessed_type = gtype
        return host.ip

    epool = ThreadPoolExecutor(max_workers=32)
    try:
        efuts = {epool.submit(enrich, h): h for h in hosts_list}
        done_e = 0
        for fut in as_completed(efuts):
            if cancel_event.is_set():
                break
            done_e += 1
            try:
                eip = fut.result(timeout=4.0)
            except Exception:
                eip = efuts[fut].ip
            if progress_cb and (done_e % 2 == 0 or done_e == h_total):
                progress_cb(done_e, h_total, f"Nhận diện {eip}")
    finally:
        epool.shutdown(wait=False, cancel_futures=True)

    return hosts_list, arp_map, cancel_event.is_set()


FAST_INVENTORY_PORTS = (445, LANMAP_AGENT_PORT, 80, 443, 554, 9100)
DEEP_INVENTORY_PORTS = (22, 23, 80, 135, 443, 445, 554, 631, 8080, 8291, 9100, LANMAP_AGENT_PORT)


def parse_inventory_networks(raw: str) -> list[ipaddress.IPv4Network]:
    """Mỗi VLAN cần một CIDR đã biết. Chấp nhận nhiều dòng, dấu phẩy hoặc dải octet."""
    networks = set()
    for token in re.split(r"[,;\s]+", raw.strip()):
        if not token:
            continue
        span = re.fullmatch(r"(\d+\.\d+)\.(\d+)-(\d+)\.0(/\d+)?", token)
        try:
            if span:
                prefix, first, last, mask = span.groups()
                lo, hi = int(first), int(last)
                if not 0 <= lo <= hi <= 255:
                    raise ValueError
                networks.update(
                    ipaddress.IPv4Network(f"{prefix}.{index}.0{mask or '/24'}", strict=False)
                    for index in range(lo, hi + 1)
                )
            else:
                if "/" not in token:
                    raise ValueError
                networks.add(ipaddress.IPv4Network(token, strict=False))
        except ValueError:
            raise ValueError(f"Dải IPv4 chưa hợp lệ: {token}. Ví dụ: 192.168.10.0/24.") from None
    ordered = sorted(networks)
    for left, right in zip(ordered, ordered[1:]):
        if left.overlaps(right):
            raise ValueError(f"Hai dải bị chồng lấn: {left} và {right}. Hãy nhập mỗi subnet một lần.")
    if not ordered:
        raise ValueError("Hãy nhập ít nhất một dải IPv4 theo CIDR.")
    return ordered


def inventory_host_count(net: ipaddress.IPv4Network) -> int:
    return net.num_addresses - 2 if net.prefixlen < 31 else net.num_addresses


def scan_network_inventory(
    nets: list[ipaddress.IPv4Network],
    adapter: AdapterInfo | None,
    deep: bool,
    cancel: threading.Event,
    progress: Callable[[int, int, str], None],
) -> tuple[dict[str, list[DiscoveredHost]], dict[str, str]]:
    results: dict[str, list[DiscoveredHost]] = {str(net): [] for net in nets}
    targets = ((str(net), str(addr)) for net in nets for addr in net.hosts())
    total = sum(inventory_host_count(net) for net in nets)
    done = 0
    local_ip = adapter.ip if adapter else ""
    gateway = adapter.gateway if adapter else ""
    local_subnet = adapter.subnet_cidr if adapter else ""
    arp_before = read_arp_table(local_ip) if local_ip else {}
    arp_after: dict[str, str] = {}
    ports = DEEP_INVENTORY_PORTS if deep else FAST_INVENTORY_PORTS

    def probe(cidr: str, ip: str) -> DiscoveredHost | None:
        if cancel.is_set():
            return None
        if ip == local_ip:
            return DiscoveredHost(ip, True, 0.0, hostname=socket.gethostname(),
                                  guessed_type=TYPE_THIS_PC, is_this_pc=True)
        online, latency = ping_host(ip, timeout_ms=550 if deep else 320)
        open_ports = set()
        if deep or not online or ip == gateway:
            for port in ports:
                if cancel.is_set():
                    return None
                if check_tcp_port(ip, port, timeout=0.25 if deep else 0.12):
                    open_ports.add(port)
                    if not deep:
                        break
        elif check_tcp_port(ip, LANMAP_AGENT_PORT, timeout=0.12):
            open_ports.add(LANMAP_AGENT_PORT)
        mac = arp_before.get(ip, "") if cidr == local_subnet else ""
        is_gateway = bool(gateway and ip == gateway)
        if not (online or open_ports or is_gateway):
            return None
        hostname = ""
        if deep and (online or open_ports) and not cancel.is_set():
            hostname = _resolve_hostname_fast(ip, timeout=0.55)
            kind = TYPE_SWITCH if _looks_like_switch(hostname) else TYPE_UNKNOWN
            for web_port in (443, 80, 8080):
                if kind == TYPE_SWITCH or cancel.is_set():
                    break
                if web_port not in open_ports:
                    continue
                title, server = grab_http_title_and_server(ip, web_port, timeout=0.45, tls=web_port == 443)
                banner = f"{title} {server}".lower()
                if _looks_like_switch(banner):
                    hostname = title or hostname or "Switch"
                    kind = TYPE_SWITCH
                elif kind == TYPE_UNKNOWN:
                    if any(word in banner for word in ("router", "mikrotik", "openwrt", "pfsense", "draytek")):
                        hostname = title or hostname or "Router"
                        kind = TYPE_ROUTER
                    elif any(word in banner for word in ("access point", "unifi", "wireless ap")):
                        hostname = title or hostname or "Bộ phát Wi-Fi"
                        kind = TYPE_WIFI
        else:
            kind = TYPE_UNKNOWN
        if LANMAP_AGENT_PORT in open_ports:
            hello = query_client_hello(ip, timeout=0.45)
        else:
            hello = None
        vendor, guessed = classify_device_smart(mac, hostname, open_ports)
        if hello:
            hostname = hello.get("name") or hostname
            mac = hello.get("mac") or mac
            vendor = f"LanMap Client ({hello.get('owner') or 'Đã kết nối'})"
            kind = TYPE_PC
        if is_gateway:
            kind = TYPE_ROUTER
        if kind == TYPE_UNKNOWN:
            kind = guessed
        return DiscoveredHost(
            ip, online or bool(open_ports), latency, mac, hostname, vendor, kind,
            is_gateway=is_gateway,
        )

    with ThreadPoolExecutor(max_workers=40) as executor:
        # Giữ hàng đợi nhỏ kể cả khi quét nhiều VLAN hoặc subnet lớn.
        while not cancel.is_set():
            batch = list(islice(targets, 80))
            if not batch:
                break
            pending = {executor.submit(probe, cidr, ip): (cidr, ip) for cidr, ip in batch}
            for future in as_completed(pending):
                if cancel.is_set():
                    for item in pending:
                        item.cancel()
                    break
                cidr, ip = pending[future]
                host = future.result()
                if host:
                    results[cidr].append(host)
                done += 1
                if done % 16 == 0 or done == total:
                    progress(done, total, ip)
    if local_ip and not cancel.is_set() and local_subnet in results:
        arp_after = read_arp_table(local_ip)
        local_net = ipaddress.IPv4Network(local_subnet)
        known = {host.ip for host in results[local_subnet]}
        for ip, mac in arp_after.items():
            addr = ipaddress.IPv4Address(ip)
            if (ip not in known and arp_before.get(ip) != mac and addr in local_net
                    and not (local_net.prefixlen < 31 and addr in (local_net.network_address, local_net.broadcast_address))):
                results[local_subnet].append(DiscoveredHost(ip, True, mac=mac))
        for host in results[local_subnet]:
            if not host.mac:
                host.mac = arp_after.get(host.ip, "")
            if host.mac and host.guessed_type == TYPE_UNKNOWN:
                vendor, kind = classify_device_smart(host.mac, host.hostname)
                host.vendor, host.guessed_type = vendor, kind
    # Pha nhận diện nhanh (song song 32 luồng) cho các thiết bị phản hồi để nhận đúng Điện thoại / PC / Camera / Máy in / TV
    to_enrich = [
        h for hosts_in_cidr in results.values() for h in hosts_in_cidr
        if not h.is_this_pc and not h.is_gateway and (
            h.guessed_type == TYPE_UNKNOWN or not h.vendor or not h.hostname
        )
    ]
    if to_enrich and not cancel.is_set():
        e_total = len(to_enrich)
        e_done = 0
        progress(0, e_total, f"Đang nhận diện hãng & loại cho {e_total} thiết bị...")

        def _enrich_host(h: DiscoveredHost) -> str:
            if cancel.is_set():
                return h.ip
            try:
                hn, vd, gt = fingerprint_device_fast(h.ip, h.mac)
                if hn and not h.hostname:
                    h.hostname = hn
                if vd and (not h.vendor or h.vendor.startswith("Di động")):
                    h.vendor = vd
                if gt != TYPE_UNKNOWN and h.guessed_type != TYPE_SWITCH:
                    h.guessed_type = gt
            except Exception:
                pass
            return h.ip

        with ThreadPoolExecutor(max_workers=32) as epool:
            efuts = {epool.submit(_enrich_host, h): h for h in to_enrich}
            for ef in as_completed(efuts):
                if cancel.is_set():
                    for p in efuts:
                        p.cancel()
                    break
                e_done += 1
                try:
                    eip = ef.result(timeout=4.0)
                except Exception:
                    eip = efuts[ef].ip
                if e_done % 2 == 0 or e_done == e_total:
                    progress(e_done, e_total, f"Nhận diện {eip}")
    return results, arp_after


def place_inventory_groups(
    state: AppState, groups: dict[str, list[Device]], by_floor: bool,
) -> None:
    """Dựng khung cho đúng CIDR đã quét, giữ vị trí thiết bị nằm ngoài kết quả."""
    members = {dev.id for devices in groups.values() for dev in devices}
    annotation_ids = {f"vlan:{cidr}" for cidr in groups}
    state.annotations = [ann for ann in state.annotations if ann.id not in annotation_ids]
    existing_bottom = [dev.y + 75 for dev in state.devices if dev.registered and dev.id not in members]
    existing_bottom += [max(ann.y1, ann.y2) for ann in state.annotations]
    start_y = max(existing_bottom, default=0) + 65
    position_y = start_y
    row_bottom = start_y
    left = 60.0
    for index, (cidr, devices) in enumerate(sorted(
        groups.items(), key=lambda item: ipaddress.IPv4Network(item[0], strict=False),
    )):
        if by_floor:
            floor = next((f for f in state.floors if f.endswith(f" · {cidr}")), "")
            if not floor:
                floor = f"Tầng {len(state.floors)} · {cidr}"
                state.floors.append(floor)
        else:
            floor = DEFAULT_FLOOR
        if index % 2 == 0:
            position_y = row_bottom + (48 if index else 0)
            left = 60.0
        for dev in devices:
            dev.registered = True
            dev.floor = floor
            dev.subnet = cidr
        width, height = _layout_device_rows(devices, left, position_y)
        bottom = position_y + height
        row_bottom = max(row_bottom, bottom)
        state.annotations.append(CanvasAnnotation(
            id=f"vlan:{cidr}", kind="rect", x1=left, y1=position_y, x2=left + width, y2=bottom,
            text=floor if by_floor else f"Khu {index + 1} · {cidr}",
            color="#0891b2", filled=False, dashed=True, floor=floor,
        ))
        left += width + 52.0


def auto_connect_to_gateway(devices: list[Device], links: list[NetworkLink]) -> int:
    reg = [d for d in devices if d.registered]
    gateways: dict[str, Device] = {}
    for dev in reg:
        if dev.is_gateway:
            gateways.setdefault(dev.subnet, dev)
    for dev in reg:
        if dev.device_type == TYPE_ROUTER:
            gateways.setdefault(dev.subnet, dev)
    linked_ids = {x for lnk in links for x in (lnk.source_id, lnk.target_id)}
    added = 0
    for dev in reg:
        gw = gateways.get(dev.subnet) or (next(iter(gateways.values()), None) if not dev.subnet else None)
        if gw is None or dev.id == gw.id or dev.id in linked_ids:
            continue
        links.append(NetworkLink(source_id=gw.id, target_id=dev.id, confirmed=False))
        added += 1
    return added


def merge_discovered_devices(
    existing_devices: list[Device],
    existing_links: list[NetworkLink],
    discovered_hosts: list[DiscoveredHost],
    adapter: AdapterInfo,
    all_local_ips: list[str],
    register_infrastructure: bool = True,
) -> tuple[list[Device], list[NetworkLink], int]:
    ts = now_str()
    devices = list(existing_devices)
    links = list(existing_links)
    new_count = 0

    local_ip_set = {ip for ip in all_local_ips if ip}
    if adapter.ip:
        local_ip_set.add(adapter.ip)
    extra_ips = [ip for ip in sorted(local_ip_set) if ip != adapter.ip]

    def find_match(host: DiscoveredHost) -> Device | None:
        if host.is_this_pc or host.ip in local_ip_set:
            for d in devices:
                if d.is_this_pc:
                    return d
        return next((d for d in devices if d.ip == host.ip and not d.is_this_pc), None)

    for host in discovered_hosts:
        if not host.is_this_pc and host.ip in local_ip_set:
            continue
        matched = find_match(host)
        status = STATUS_ONLINE if host.reachable else STATUS_NO_PING

        if matched is not None:
            matched.status = status
            matched.latency_ms = host.latency_ms
            matched.last_checked = ts
            matched.total_checks += 1
            if host.reachable:
                matched.online_checks += 1
                matched.consecutive_failures = 0
                matched.latency_history = (matched.latency_history + [host.latency_ms])[-20:]
            if host.vendor.startswith("LanMap Client ("):
                matched.vendor = host.vendor
            if host.mac and not matched.mac:
                matched.mac = host.mac
            if host.vendor and not matched.vendor:
                matched.vendor = host.vendor
            if matched.device_type == TYPE_UNKNOWN and host.guessed_type != TYPE_UNKNOWN:
                matched.device_type = host.guessed_type
            if matched.device_type != TYPE_UNKNOWN and (
                matched.name.startswith("Chưa xác định") or matched.name.startswith("Thiết bị .")
            ):
                suffix = matched.ip.rsplit(".", 1)[-1] if matched.ip else ""
                matched.name = host.hostname or f"{matched.device_type} .{suffix}"
            if not matched.subnet and adapter.subnet_cidr:
                matched.subnet = adapter.subnet_cidr
            if host.is_gateway:
                matched.is_gateway = True
            if matched.is_this_pc:
                matched.ip = adapter.ip or matched.ip
                matched.subnet = adapter.subnet_cidr
                matched.extra_ips = extra_ips
        else:
            if host.is_this_pc:
                devices.append(
                    Device(
                        name=f"Máy này ({host.hostname})" if host.hostname else "Máy này",
                        ip=host.ip, extra_ips=extra_ips, mac=host.mac, device_type=TYPE_THIS_PC,
                        group="Hạ tầng", location="Máy đang chạy LanMap", subnet=adapter.subnet_cidr,
                        trusted=True, is_this_pc=True, registered=register_infrastructure, x=260.0, y=310.0,
                        status=STATUS_ONLINE, latency_ms=host.latency_ms, last_checked=ts, total_checks=1, online_checks=1,
                    )
                )
            elif host.is_gateway:
                devices.append(
                    Device(
                        name=f"Gateway ({host.ip})",
                        ip=host.ip, mac=host.mac, vendor=host.vendor, device_type=TYPE_ROUTER, group="Hạ tầng",
                        location="Cổng mạng mặc định",
                        notes="Lấy từ cấu hình mạng. Nếu không trả lời ping, thiết bị vẫn có thể đang hoạt động.",
                        subnet=adapter.subnet_cidr, trusted=True, is_gateway=True, registered=register_infrastructure,
                        x=460.0, y=95.0, status=status, latency_ms=host.latency_ms, last_checked=ts,
                        total_checks=1, online_checks=1 if host.reachable else 0,
                    )
                )
            else:
                label_prefix = host.guessed_type if host.guessed_type != TYPE_UNKNOWN else "Thiết bị"
                default_name = host.hostname or f"{label_prefix} .{host.ip.split('.')[-1]}"
                devices.append(
                    Device(
                        name=default_name,
                        ip=host.ip, mac=host.mac, vendor=host.vendor, device_type=host.guessed_type, group="Chung",
                        subnet=adapter.subnet_cidr, trusted=False, registered=False,
                        status=status, latency_ms=host.latency_ms, last_checked=ts,
                        total_checks=1, online_checks=1 if host.reachable else 0,
                    )
                )
                new_count += 1

    auto_connect_to_gateway(devices, links)
    return devices, links, new_count


def find_shortest_path(devices: list[Device], links: list[NetworkLink], start_id: str, end_id: str) -> list[str]:
    if start_id == end_id:
        return [start_id]
    reg_ids = {d.id for d in devices if d.registered}
    if start_id not in reg_ids or end_id not in reg_ids:
        return []
    adj: dict[str, list[str]] = {did: [] for did in reg_ids}
    for lnk in links:
        if lnk.source_id in reg_ids and lnk.target_id in reg_ids:
            adj[lnk.source_id].append(lnk.target_id)
            adj[lnk.target_id].append(lnk.source_id)
    q: deque[list[str]] = deque([[start_id]])
    visited = {start_id}
    while q:
        path = q.popleft()
        for nxt in adj[path[-1]]:
            if nxt == end_id:
                return path + [nxt]
            if nxt not in visited:
                visited.add(nxt)
                q.append(path + [nxt])
    return []


def check_devices_batch(devices: list[Device], cancel_event: threading.Event | None = None) -> list[tuple[str, bool, float | None, dict[int, bool]]]:
    def probe(dev: Device) -> tuple[str, bool, float | None, dict[int, bool]]:
        if not dev.ip:
            return dev.id, True, None, {}
        ok, lat = (True, 0.5) if dev.is_this_pc else ping_host(dev.ip, timeout_ms=650)
        svcs = {s.port: check_tcp_port(dev.ip, s.port) for s in dev.services}
        return dev.id, ok, lat, svcs

    results: list[tuple[str, bool, float | None, dict[int, bool]]] = []
    if not devices:
        return results
    with ThreadPoolExecutor(max_workers=min(24, len(devices))) as pool:
        futs = [pool.submit(probe, d) for d in devices]
        for fut in as_completed(futs):
            if cancel_event and cancel_event.is_set():
                break
            try:
                results.append(fut.result())
            except Exception:
                pass
    return results


def _format_downtime(start_s: str, end_s: str) -> str:
    try:
        sec = max(0, int((datetime.strptime(end_s, "%Y-%m-%d %H:%M:%S") - datetime.strptime(start_s, "%Y-%m-%d %H:%M:%S")).total_seconds()))
        return f"{sec} giây" if sec < 60 else f"{sec // 60} phút {sec % 60} giây"
    except Exception:
        return ""


def apply_monitor_result(
    device: Device,
    reachable: bool,
    latency_ms: float | None,
    service_results: dict[int, bool],
    checked_at: str | None = None,
    failure_threshold: int = DEFAULT_FAILURE_THRESHOLD,
) -> IncidentRecord | None:
    if not device.ip:
        return None
    ts = checked_at or now_str()
    device.last_checked = ts
    device.total_checks += 1
    for svc in device.services:
        if svc.port in service_results:
            svc.status = "Hoạt động" if service_results[svc.port] else "Không kết nối"
            svc.last_checked = ts

    if reachable:
        device.online_checks += 1
        was_down = device.in_incident
        started = device.incident_started_at
        device.status = STATUS_ONLINE
        device.latency_ms = latency_ms
        device.consecutive_failures = 0
        device.in_incident = False
        device.incident_started_at = ""
        device.latency_history = (device.latency_history + [latency_ms])[-20:]
        if was_down:
            dur = _format_downtime(started, ts)
            extra = f" (gián đoạn {dur})" if dur else ""
            return IncidentRecord(timestamp=ts, device_id=device.id, device_name=device.name, ip=device.ip, event_type="Phục hồi", details=f"Đã phản hồi ping trở lại ({latency_ms} ms){extra}.")
        return None

    device.consecutive_failures += 1
    device.latency_ms = None
    device.latency_history = (device.latency_history + [None])[-20:]
    if device.consecutive_failures >= failure_threshold:
        device.status = STATUS_NO_PING
        if not device.in_incident:
            device.in_incident = True
            device.incident_started_at = ts
            return IncidentRecord(timestamp=ts, device_id=device.id, device_name=device.name, ip=device.ip, event_type="Mất phản hồi", details=f"Không phản hồi ping {device.consecutive_failures} lần liên tiếp (thiết bị vẫn có thể đang chạy nếu chặn ICMP).")
    elif device.status == STATUS_UNCHECKED:
        device.status = STATUS_NO_PING
    return None


def analyze_fault_isolation(devices: list[Device], links: list[NetworkLink]) -> list[FaultIsolationResult]:
    reg = {d.id: d for d in devices if d.registered}
    confirmed = [lnk for lnk in links if lnk.confirmed and lnk.source_id in reg and lnk.target_id in reg]
    if not confirmed:
        return []
    adj: dict[str, list[tuple[str, str]]] = {did: [] for did in reg}
    for lnk in confirmed:
        adj[lnk.source_id].append((lnk.target_id, lnk.id))
        adj[lnk.target_id].append((lnk.source_id, lnk.id))

    roots = [d.id for d in reg.values() if d.is_gateway] or [d.id for d in reg.values() if d.device_type == TYPE_ROUTER]
    parent_of: dict[str, str | None] = {}
    parent_link_of: dict[str, str | None] = {}
    children_of: dict[str, list[tuple[str, str]]] = {did: [] for did in reg}
    visited: set[str] = set()
    for root in roots:
        if root in visited:
            continue
        q: deque[str] = deque([root])
        visited.add(root)
        parent_of[root] = None
        parent_link_of[root] = None
        while q:
            curr = q.popleft()
            for nxt, lid in adj[curr]:
                if nxt not in visited:
                    visited.add(nxt)
                    parent_of[nxt] = curr
                    parent_link_of[nxt] = lid
                    children_of[curr].append((nxt, lid))
                    q.append(nxt)

    results: list[FaultIsolationResult] = []
    hubs = sorted(reg.values(), key=lambda d: (0 if d.device_type in (TYPE_SWITCH, TYPE_WIFI) else 1, d.name.lower()))
    for hub in hubs:
        if hub.device_type not in {TYPE_SWITCH, TYPE_WIFI, TYPE_ROUTER} and len(adj[hub.id]) < 3:
            continue
        pairs = children_of[hub.id] if hub.id in visited else adj[hub.id]
        down = [(cid, lid) for cid, lid in pairs if reg[cid].status == STATUS_NO_PING and (reg[cid].in_incident or reg[cid].consecutive_failures >= 1)]
        if len(down) < 2:
            continue
        up_id = parent_of.get(hub.id)
        up_link = parent_link_of.get(hub.id)
        up_name = reg[up_id].name if up_id and up_id in reg else "router / tuyến mạng phía trên"
        names = ", ".join(reg[cid].name for cid, _ in down[:4])
        if len(down) > 4:
            names += f" và {len(down) - 4} thiết bị khác"
        hl_links = [lid for _, lid in down] + ([up_link] if up_link else [])
        results.append(
            FaultIsolationResult(
                hub.id, hub.name, up_name, [hub.id] + [cid for cid, _ in down], hl_links,
                f"Gợi ý dựa trên dữ liệu sơ đồ và ping (chưa khẳng định nguyên nhân đã xác minh): Có {len(down)} thiết bị cùng nối qua '{hub.name}' đang không phản hồi ({names}).",
            )
        )
    return results


