class PeriodicMonitor:
    def __init__(self, get_devices_cb: Callable[[], list[Device]], on_results_cb: Callable[[Any], None], interval_sec: int = 15) -> None:
        self._get_devices = get_devices_cb
        self._on_results = on_results_cb
        self.interval_sec = max(5, interval_sec)
        self._stop_event = threading.Event()
        self._thread: threading.Thread | None = None

    def start(self, interval_sec: int | None = None) -> None:
        if interval_sec is not None:
            self.interval_sec = max(5, interval_sec)
        if self._thread and self._thread.is_alive():
            return
        self._stop_event.clear()
        self._thread = threading.Thread(target=self._loop, daemon=True)
        self._thread.start()

    def stop(self) -> None:
        self._stop_event.set()

    def _loop(self) -> None:
        while not self._stop_event.is_set():
            devs = self._get_devices()
            if devs:
                res = check_devices_batch(devs, cancel_event=self._stop_event)
                if not self._stop_event.is_set():
                    self._on_results(res)
            self._stop_event.wait(self.interval_sec)


