# 6. VÙNG VẼ SƠ ĐỒ MẠNG (THÊM ICON ĐIỆN THOẠI + VẼ HÌNH / GHI CHÚ CISCO + XẾP GỌN)
# =============================================================================

class TopologyCanvas(ctk.CTkFrame):
    def __init__(
        self,
        master: ctk.CTkBaseClass,
        on_selection_changed: Callable[[set[str]], None],
        on_create_link: Callable[[str, str], None],
        on_add_annotation: Callable[[CanvasAnnotation], None],
        on_delete_annotation: Callable[[str], None],
        on_layout_changed: Callable[[], None],
        on_status_msg: Callable[[str], None],
    ) -> None:
        super().__init__(master, corner_radius=10)
        self._on_selection_changed = on_selection_changed
        self._on_create_link = on_create_link
        self._on_add_annotation = on_add_annotation
        self._on_delete_annotation = on_delete_annotation
        self._on_layout_changed = on_layout_changed
        self._on_status_msg = on_status_msg

        # "select" | "box" | "link" | "note" | "rect" | "oval"
        self.mode = "select"
        self.scale = 1.0
        self.offset_x = 0.0
        self.offset_y = 0.0
        self.show_subnet_group = False
        self.show_auto_links = True
        self.demo_mode = False
        self.canvas_theme = "Nền chấm tối"

        self._all_devices: list[Device] = []
        self._global_devices: dict[str, Device] = {}
        self._visible_devices: list[Device] = []
        self._links: list[NetworkLink] = []
        self._annotations: list[CanvasAnnotation] = []
        self._is_filtered = False
        self._selected_ids: set[str] = set()
        self._link_source_id: str | None = None
        self._fault_device_ids: set[str] = set()
        self._fault_suspect_ids: set[str] = set()
        self._fault_link_ids: set[str] = set()

        self._anim_after_id: str | None = None
        self._anim_path: list[str] = []
        self._anim_seg_idx = 0
        self._anim_t = 0.0
        self._anim_returning = False
        self._anim_broken_at: tuple[float, float, str] | None = None
        self._anim_packet_pos: tuple[float, float, str, str] | None = None
        self._anim_passed_edges: set[tuple[str, str]] = set()

        self._dragging_group = False
        self._drag_last_world = (0.0, 0.0)
        self._drag_moved = False
        self._pending_sel_notify = False
        self._marquee_start: tuple[int, int] | None = None
        self._marquee_end: tuple[int, int] | None = None
        self._shape_start: tuple[float, float] | None = None
        self._shape_end: tuple[float, float] | None = None
        self.selected_ann_id: str | None = None
        self._dragging_ann_id: str | None = None
        self._ann_drag_moved: bool = False
        self.draw_color_name: str = "Xanh dương"
        self.draw_outline_hex: str = "#0284c7"
        self.draw_fill_hex: str = "#dbeafe"
        self.draw_filled: bool = True
        self.draw_dashed: bool = False
        self.show_floor_bands: bool = False
        self._panning = False
        self._pan_start = (0, 0)
        self._pan_origin = (0.0, 0.0)
        self._redraw_after_id: str | None = None

        self.canvas = tk.Canvas(self, highlightthickness=0, bd=0)
        self.canvas.pack(fill="both", expand=True, padx=2, pady=2)
        self.canvas.bind("<Button-1>", self._on_left_down)
        self.canvas.bind("<B1-Motion>", self._on_left_drag)
        self.canvas.bind("<ButtonRelease-1>", self._on_left_up)
        self.canvas.bind("<Button-3>", self._on_pan_down)
        self.canvas.bind("<B3-Motion>", self._on_pan_drag)
        self.canvas.bind("<ButtonRelease-3>", self._on_pan_up)
        self.canvas.bind("<Double-Button-1>", self._on_double_click)
        self.canvas.bind("<MouseWheel>", lambda e: self._zoom_at(1.12 if e.delta > 0 else 1 / 1.12, e.x, e.y))
        self.canvas.bind("<Configure>", lambda _e: self._schedule_redraw())

    def set_theme(self, theme_name: str) -> None:
        if theme_name in CANVAS_THEMES:
            self.canvas_theme = theme_name
            self.redraw()

    def set_mode(self, mode: str) -> None:
        self.mode = mode
        self._link_source_id = None
        self._marquee_start = self._marquee_end = None
        self._shape_start = self._shape_end = None
        self.canvas.configure(cursor="crosshair" if mode != "select" else "arrow")
        self.redraw()

    def set_data(self, devices: list[Device], links: list[NetworkLink], annotations: list[CanvasAnnotation], selected_ids: set[str], filtered_ids: set[str] | None, faults: list[FaultIsolationResult], show_subnet_group: bool, show_auto_links: bool, demo_mode: bool, global_devices: list[Device] | None = None) -> None:
        self._all_devices = [d for d in devices if d.registered]
        self._global_devices = {d.id: d for d in (global_devices if global_devices is not None else devices) if d.registered}
        self._is_filtered = filtered_ids is not None
        self._visible_devices = [d for d in self._all_devices if filtered_ids is None or d.id in filtered_ids]
        self._links = list(links)
        self._annotations = list(annotations)
        self._selected_ids = set(selected_ids)
        self.show_subnet_group = show_subnet_group
        self.show_auto_links = show_auto_links
        self.demo_mode = demo_mode
        self._fault_device_ids = {cid for f in faults for cid in f.affected_device_ids}
        self._fault_suspect_ids = {f.suspect_device_id for f in faults}
        self._fault_link_ids = {lid for f in faults for lid in f.highlighted_link_ids}
        self.redraw()

    def stop_packet_animation(self) -> None:
        if self._anim_after_id:
            try:
                self.after_cancel(self._anim_after_id)
            except Exception:
                pass
            self._anim_after_id = None
        self._anim_packet_pos = None
        self._anim_broken_at = None
        self._anim_passed_edges = set()

    def start_ping_flow(self, source_id: str, target_id: str) -> None:
        self.stop_packet_animation()
        path = find_shortest_path(self._all_devices, self._links, source_id, target_id)
        if len(path) < 2:
            self._on_status_msg("Chưa có đường nối giữa 2 thiết bị này để mô phỏng luồng Ping.")
            self.redraw()
            return
        self._anim_path = path
        self._anim_seg_idx = 0
        self._anim_t = 0.0
        self._anim_returning = False
        self._anim_broken_at = None
        self._anim_passed_edges = set()
        self._step_ping_flow()

    def _step_ping_flow(self) -> None:
        dmap = {d.id: d for d in self._all_devices}
        if self._anim_seg_idx >= len(self._anim_path) - 1:
            self.redraw()
            return
        u_id, v_id = self._anim_path[self._anim_seg_idx], self._anim_path[self._anim_seg_idx + 1]
        u, v = dmap.get(u_id), dmap.get(v_id)
        if not u or not v:
            self.stop_packet_animation()
            return

        target_dev = dmap.get(self._anim_path[-1])
        target_is_online = bool(target_dev and target_dev.status == STATUS_ONLINE)
        # Nếu thiết bị đích đang Online (phản hồi tốt), không báo đứt tại Gateway chặn ICMP trung gian!
        v_broken = (not self._anim_returning) and (v.status == STATUS_NO_PING) and (not target_is_online or v_id == self._anim_path[-1])
        stop_t = 0.58 if v_broken else 1.0
        self._anim_t += 0.08
        if self._anim_t >= stop_t:
            if v_broken:
                bx, by = u.x + (v.x - u.x) * stop_t, u.y + (v.y - u.y) * stop_t
                self._anim_packet_pos = None
                self._anim_broken_at = (bx, by, f"✕ NGẮT TẠI ĐÂY ({u.name} → {v.name})")
                self._on_status_msg(f"Luồng Ping bị NGẮT tại chặng '{u.name} → {v.name}'.")
                self.redraw()
                self._anim_after_id = self.after(4500, lambda: (self.stop_packet_animation(), self.redraw()))
                return
            self._anim_passed_edges.add((u_id, v_id))
            self._anim_passed_edges.add((v_id, u_id))
            self._anim_seg_idx += 1
            self._anim_t = 0.0
            if self._anim_seg_idx >= len(self._anim_path) - 1:
                if not self._anim_returning:
                    self._anim_returning = True
                    self._anim_path = list(reversed(self._anim_path))
                    self._anim_seg_idx = 0
                    self._anim_t = 0.0
                else:
                    self._anim_packet_pos = None
                    self._on_status_msg("✓ Luồng Ping (ICMP Request/Reply) thông suốt.")
                    self.redraw()
                    self._anim_after_id = self.after(2600, lambda: (self.stop_packet_animation(), self.redraw()))
                    return

        u2, v2 = dmap.get(self._anim_path[self._anim_seg_idx]), dmap.get(self._anim_path[self._anim_seg_idx + 1])
        if u2 and v2:
            self._anim_packet_pos = (
                u2.x + (v2.x - u2.x) * self._anim_t,
                u2.y + (v2.y - u2.y) * self._anim_t,
                "#22c55e" if self._anim_returning else "#38bdf8",
                "REPLY" if self._anim_returning else "PING",
            )
        self.redraw()
        self._anim_after_id = self.after(40, self._step_ping_flow)

    def world_to_screen(self, wx: float, wy: float) -> tuple[float, float]:
        return wx * self.scale + self.offset_x, wy * self.scale + self.offset_y

    def screen_to_world(self, sx: float, sy: float) -> tuple[float, float]:
        return (sx - self.offset_x) / self.scale, (sy - self.offset_y) / self.scale

    def zoom_in(self) -> None:
        self._zoom_at(1.18, max(1, self.canvas.winfo_width() / 2), max(1, self.canvas.winfo_height() / 2))

    def zoom_out(self) -> None:
        self._zoom_at(1 / 1.18, max(1, self.canvas.winfo_width() / 2), max(1, self.canvas.winfo_height() / 2))

    def _zoom_at(self, factor: float, sx: float, sy: float) -> None:
        new_s = max(0.08, min(2.2, self.scale * factor))
        if abs(new_s - self.scale) < 1e-4:
            return
        wx, wy = self.screen_to_world(sx, sy)
        self.scale = new_s
        self.offset_x = sx - wx * self.scale
        self.offset_y = sy - wy * self.scale
        self.redraw()

    def fit_to_view(self) -> None:
        w, h = max(200, self.canvas.winfo_width()), max(200, self.canvas.winfo_height())
        devs = self._visible_devices
        if not devs:
            self.scale, self.offset_x, self.offset_y = 1.0, 0.0, 0.0
            self.redraw()
            return
        xs, ys = [d.x for d in devs], [d.y for d in devs]
        occupied_vlan = [
            ann for ann in self._annotations if _inventory_annotation_network(ann)
            and any(ann.floor == dev.floor and min(ann.x1, ann.x2) <= dev.x <= max(ann.x1, ann.x2)
                    and min(ann.y1, ann.y2) <= dev.y <= max(ann.y1, ann.y2) for dev in devs)
        ]
        min_x = min([min(xs) - 90, *(min(a.x1, a.x2) for a in occupied_vlan)])
        max_x = max([max(xs) + 90, *(max(a.x1, a.x2) for a in occupied_vlan)])
        min_y = min([min(ys) - 75, *(min(a.y1, a.y2) for a in occupied_vlan)])
        max_y = max([max(ys) + 95, *(max(a.y1, a.y2) for a in occupied_vlan)])
        self.scale = max(0.08, min(1.2, (w - 36) / max(240, max_x - min_x),
                                (h - 36) / max(200, max_y - min_y)))
        self.offset_x = w / 2 - ((min_x + max_x) / 2) * self.scale
        self.offset_y = h / 2 - ((min_y + max_y) / 2) * self.scale
        self.redraw()

    def auto_arrange(self, devices: list[Device], group_by_floor: bool = False, floor_order: list[str] | None = None) -> None:
        """Tự xếp thoáng đẹp theo tầng (hỗ trợ xếp thành các dải Tầng tòa nhà kiểu Zabbix/Enterprise để thấy rõ dây nối liên tầng!)."""
        reg = [d for d in devices if d.registered]
        if not reg:
            return

        if group_by_floor:
            fl_names = list(floor_order or sorted({d.floor or DEFAULT_FLOOR for d in reg}))
            # Đảo ngược để Tầng cao hơn nằm phía trên như mặt cắt tòa nhà thực tế
            fl_display = list(reversed(fl_names))
            y_cursor = 110.0
            for fl in fl_display:
                fl_devs = [d for d in reg if (d.floor or DEFAULT_FLOOR) == fl]
                if not fl_devs:
                    continue
                fl_devs.sort(key=lambda d: (0 if (d.is_gateway or d.device_type == TYPE_ROUTER) else (1 if d.device_type in (TYPE_SWITCH, TYPE_WIFI) else 2), d.name.lower()))
                per_row = 6 if len(fl_devs) > 10 else 5
                rows_used = 0
                for idx, dev in enumerate(fl_devs):
                    row, col = divmod(idx, per_row)
                    rows_used = max(rows_used, row + 1)
                    row_len = min(per_row, len(fl_devs) - row * per_row)
                    dev.x = 660.0 - ((row_len - 1) * 265.0) / 2 + col * 265.0
                    dev.y = y_cursor + row * 180.0
                y_cursor += rows_used * 185.0 + 95.0
            self._on_layout_changed()
            self.fit_to_view()
            return

        # Xếp tách từng cụm loại thiết bị riêng biệt (Hạ tầng -> Server -> Máy in -> Máy tính -> Điện thoại/TV -> Khác) cực gọn!
        t_gw = [d for d in reg if d.is_gateway or d.device_type == TYPE_ROUTER]
        t_sw = [d for d in reg if d not in t_gw and d.device_type in (TYPE_SWITCH, TYPE_WIFI)]
        t_srv = sorted([d for d in reg if d not in t_gw and d not in t_sw and d.device_type == TYPE_SERVER], key=lambda d: d.name.lower())
        t_prn = sorted([d for d in reg if d not in t_gw and d not in t_sw and d.device_type == TYPE_PRINTER], key=lambda d: d.name.lower())
        t_pc = sorted([d for d in reg if d not in t_gw and d not in t_sw and d.device_type in (TYPE_PC, TYPE_THIS_PC)], key=lambda d: d.name.lower())
        t_mob = sorted([d for d in reg if d not in t_gw and d not in t_sw and d.device_type in (TYPE_PHONE, TYPE_TV)], key=lambda d: d.name.lower())
        used_ids = {d.id for g in (t_gw, t_sw, t_srv, t_prn, t_pc, t_mob) for d in g}
        t_oth = sorted([d for d in reg if d.id not in used_ids], key=lambda d: d.name.lower())

        y_cursor = 95.0
        for grp in [g for g in (t_gw, t_sw, t_srv, t_prn, t_pc, t_mob, t_oth) if g]:
            per_row = 7 if len(grp) > 12 else 6
            rows_used = 0
            for idx, dev in enumerate(grp):
                row, col = divmod(idx, per_row)
                rows_used = max(rows_used, row + 1)
                row_len = min(per_row, len(grp) - row * per_row)
                dev.x = 700.0 - ((row_len - 1) * 265.0) / 2 + col * 265.0
                dev.y = y_cursor + row * 180.0
            y_cursor += rows_used * 185.0 + 44.0
        self._on_layout_changed()
        self.fit_to_view()

    def place_new_position(self, existing: list[Device]) -> tuple[float, float]:
        occupied = [(d.x, d.y) for d in existing if d.registered]
        for r in range(14):
            for c in range(7):
                cx, cy = 120.0 + c * 220.0, 260.0 + r * 165.0
                if all(math.hypot(cx - ox, cy - oy) > 120.0 for ox, oy in occupied):
                    return cx, cy
        return 200.0, 320.0

    def _hit_test(self, sx: float, sy: float) -> Device | None:
        radius = max(11.0, 32.0 * self.scale)
        best = None
        best_distance = radius
        for dev in reversed(self._visible_devices):
            dx, dy = self.world_to_screen(dev.x, dev.y)
            distance = math.hypot(sx - dx, sy - dy)
            if distance <= best_distance:
                best, best_distance = dev, distance
        return best

    def _hit_annotation(self, wx: float, wy: float) -> CanvasAnnotation | None:
        for ann in reversed(self._annotations):
            if ann.kind == "note":
                if abs(wx - ann.x1) <= 90 and abs(wy - ann.y1) <= 24:
                    return ann
            else:
                x0, x1 = sorted([ann.x1, ann.x2])
                y0, y1 = sorted([ann.y1, ann.y2])
                if x0 <= wx <= x1 and y0 <= wy <= y1:
                    return ann
        return None

    def _on_double_click(self, e: tk.Event) -> None:
        if self._hit_test(e.x, e.y) is not None:
            return
        wx, wy = self.screen_to_world(e.x, e.y)
        ann = self._hit_annotation(wx, wy)
        if ann and messagebox.askyesno("Xóa ghi chú / hình vẽ", f"Xóa '{ann.text or ann.kind}' khỏi sơ đồ?"):
            self._on_delete_annotation(ann.id)

    def _on_left_down(self, e: tk.Event) -> None:
        hit = self._hit_test(e.x, e.y)
        ctrl_held = bool(e.state & 0x0004)
        shift_held = bool(e.state & 0x0001)

        # Công cụ Ghi chú / Vẽ khung / Vẽ tròn kiểu Cisco Packet Tracer
        if self.mode == "note":
            wx, wy = self.screen_to_world(e.x, e.y)
            txt = simpledialog.askstring("Thêm ghi chú trên sơ đồ", "Nhập nội dung ghi chú (ví dụ: Tầng 2 - Phòng Kế toán):", parent=self)
            if txt and txt.strip():
                self._on_add_annotation(CanvasAnnotation(kind="note", x1=round(wx, 1), y1=round(wy, 1), text=txt.strip(), color="#facc15"))
            return
        if self.mode in ("rect", "oval"):
            wx, wy = self.screen_to_world(e.x, e.y)
            self._shape_start = (wx, wy)
            self._shape_end = (wx, wy)
            return

        if self.mode == "link":
            if hit is None:
                self._link_source_id = None
            elif self._link_source_id is None:
                self._link_source_id = hit.id
                self._selected_ids = {hit.id}
                self._on_selection_changed(set(self._selected_ids))
            elif self._link_source_id == hit.id:
                self._link_source_id = None
            else:
                src = self._link_source_id
                self._link_source_id = None
                self._on_create_link(src, hit.id)
            self.redraw()
            return

        if self.mode == "box" or (shift_held and hit is None):
            self._marquee_start = (e.x, e.y)
            self._marquee_end = (e.x, e.y)
            if not ctrl_held:
                self._selected_ids.clear()
            self.redraw()
            return

        if hit is not None:
            self.selected_ann_id = None
            sel_changed = False
            if ctrl_held:
                if hit.id in self._selected_ids:
                    self._selected_ids.remove(hit.id)
                else:
                    self._selected_ids.add(hit.id)
                sel_changed = True
            elif hit.id not in self._selected_ids:
                self._selected_ids = {hit.id}
                sel_changed = True
            self._dragging_group = True
            self._drag_moved = False
            self._pending_sel_notify = sel_changed
            self._drag_last_world = self.screen_to_world(e.x, e.y)
            self._schedule_redraw()
        else:
            wx, wy = self.screen_to_world(e.x, e.y)
            hit_ann = self._hit_annotation(wx, wy)
            self.selected_ann_id = hit_ann.id if hit_ann else None
            if not ctrl_held and self._selected_ids:
                self._selected_ids.clear()
                self._on_selection_changed(set())
            if hit_ann:
                self._dragging_ann_id = hit_ann.id
                self._ann_drag_moved = False
                self._drag_last_world = (wx, wy)
                self.canvas.configure(cursor="fleur")
                self._on_status_msg(f"Kéo chuột để di chuyển '{hit_ann.text or hit_ann.kind}' — bấm Delete để xóa.")
            else:
                self._dragging_ann_id = None
                self._panning = True
                self._pan_start = (e.x, e.y)
                self._pan_origin = (self.offset_x, self.offset_y)
                self.canvas.configure(cursor="fleur")
            self.redraw()

    def _on_left_drag(self, e: tk.Event) -> None:
        if self._shape_start is not None:
            self._shape_end = self.screen_to_world(e.x, e.y)
            self.redraw()
            return
        if self._marquee_start is not None:
            self._marquee_end = (e.x, e.y)
            self.redraw()
            return
        if self._dragging_ann_id:
            wx, wy = self.screen_to_world(e.x, e.y)
            dx, dy = wx - self._drag_last_world[0], wy - self._drag_last_world[1]
            self._drag_last_world = (wx, wy)
            for ann in self._annotations:
                if ann.id == self._dragging_ann_id:
                    ann.x1 = round(ann.x1 + dx, 1)
                    ann.y1 = round(ann.y1 + dy, 1)
                    ann.x2 = round(ann.x2 + dx, 1)
                    ann.y2 = round(ann.y2 + dy, 1)
                    self._ann_drag_moved = True
                    break
            self.redraw()
            return
        if self._dragging_group and self._selected_ids:
            wx, wy = self.screen_to_world(e.x, e.y)
            dx, dy = wx - self._drag_last_world[0], wy - self._drag_last_world[1]
            self._drag_last_world = (wx, wy)
            for d in self._visible_devices:
                if d.id in self._selected_ids:
                    d.x, d.y = round(d.x + dx, 1), round(d.y + dy, 1)
                    self._drag_moved = True
            self._schedule_redraw()
        elif self._panning:
            self.offset_x = self._pan_origin[0] + (e.x - self._pan_start[0])
            self.offset_y = self._pan_origin[1] + (e.y - self._pan_start[1])
            self._schedule_redraw()

    def _on_left_up(self, _e: tk.Event) -> None:
        if self._shape_start is not None and self._shape_end is not None:
            x1, y1 = self._shape_start
            x2, y2 = self._shape_end
            self._shape_start = self._shape_end = None
            if abs(x2 - x1) > 25 and abs(y2 - y1) > 20:
                label = simpledialog.askstring("Tên khu vực / khung vẽ", "Nhập nhãn cho khu vực vừa vẽ (có thể để trống):", parent=self) or ""
                self._on_add_annotation(
                    CanvasAnnotation(
                        kind=self.mode,
                        x1=round(x1, 1), y1=round(y1, 1), x2=round(x2, 1), y2=round(y2, 1),
                        text=label.strip(),
                        color=self.draw_outline_hex,
                        fill_hex=self.draw_fill_hex if self.draw_filled else "",
                        color_name=self.draw_color_name,
                        filled=self.draw_filled,
                        dashed=self.draw_dashed,
                    )
                )
            self.redraw()
            return

        if self._marquee_start is not None and self._marquee_end is not None:
            x0, x1 = sorted([self._marquee_start[0], self._marquee_end[0]])
            y0, y1 = sorted([self._marquee_start[1], self._marquee_end[1]])
            for d in self._visible_devices:
                sx, sy = self.world_to_screen(d.x, d.y)
                if x0 <= sx <= x1 and y0 <= sy <= y1:
                    self._selected_ids.add(d.id)
            self._marquee_start = self._marquee_end = None
            self._on_selection_changed(set(self._selected_ids))
            self.redraw()
            return

        if self._dragging_ann_id:
            if self._ann_drag_moved:
                self._on_layout_changed()
            self._dragging_ann_id = None
            self._ann_drag_moved = False
            self.canvas.configure(cursor="crosshair" if self.mode != "select" else "arrow")
        if self._dragging_group and self._drag_moved:
            self._on_layout_changed()
        need_sel = self._pending_sel_notify
        self._dragging_group = False
        self._drag_moved = False
        self._pending_sel_notify = False
        if need_sel:
            self._on_selection_changed(set(self._selected_ids))
        if self._panning:
            self._panning = False
            self.canvas.configure(cursor="crosshair" if self.mode != "select" else "arrow")

    def _on_pan_down(self, e: tk.Event) -> None:
        self._panning = True
        self._pan_start = (e.x, e.y)
        self._pan_origin = (self.offset_x, self.offset_y)
        self.canvas.configure(cursor="fleur")

    def _on_pan_drag(self, e: tk.Event) -> None:
        if self._panning:
            self.offset_x = self._pan_origin[0] + (e.x - self._pan_start[0])
            self.offset_y = self._pan_origin[1] + (e.y - self._pan_start[1])
            self._schedule_redraw()

    def _on_pan_up(self, _e: tk.Event) -> None:
        self._panning = False
        self.canvas.configure(cursor="crosshair" if self.mode != "select" else "arrow")

    def _draw_device_shape(self, c: tk.Canvas, dtype: str, x: float, y: float, r: float) -> None:
        w = max(1.5, 2.0 * self.scale)
        if dtype == TYPE_ROUTER:
            rx = r * 1.08
            c.create_rectangle(x - rx, y - r * 0.25, x + rx, y + r * 0.45, fill="#0284c7", outline="")
            c.create_oval(x - rx, y + r * 0.02, x + rx, y + r * 0.88, fill="#0369a1", outline="#e0f2fe", width=w)
            c.create_line(x - rx, y - r * 0.25, x - rx, y + r * 0.45, fill="#e0f2fe", width=w)
            c.create_line(x + rx, y - r * 0.25, x + rx, y + r * 0.45, fill="#e0f2fe", width=w)
            c.create_oval(x - rx, y - r * 0.68, x + rx, y + r * 0.18, fill="#0ea5e9", outline="#ffffff", width=w)
            c.create_line(x - r * 0.55, y - r * 0.25, x + r * 0.55, y - r * 0.25, fill="#ffffff", width=w, arrow=tk.BOTH)
            c.create_line(x, y - r * 0.50, x, y + r * 0.02, fill="#ffffff", width=w, arrow=tk.BOTH)
        elif dtype == TYPE_SWITCH:
            c.create_rectangle(x - r * 1.15, y - r * 0.48, x + r * 1.15, y + r * 0.48, fill="#0f766e", outline="#99f6e4", width=w)
            for idx in (-0.75, -0.25, 0.25, 0.75):
                px = x + idx * r * 0.88
                c.create_rectangle(px - r * 0.14, y - r * 0.14, px + r * 0.14, y + r * 0.18, fill="#ffffff", outline="")
            c.create_line(x - r * 0.7, y - r * 0.72, x + r * 0.7, y - r * 0.72, fill="#14b8a6", width=w, arrow=tk.LAST)
            c.create_line(x + r * 0.7, y + r * 0.72, x - r * 0.7, y + r * 0.72, fill="#14b8a6", width=w, arrow=tk.LAST)
        elif dtype == TYPE_WIFI:
            c.create_oval(x - r, y - r, x + r, y + r, fill="#4338ca", outline="#a5b4fc", width=w)
            for rad in (r * 0.72, r * 0.48, r * 0.26):
                c.create_arc(x - rad, y - rad + r * 0.15, x + rad, y + rad + r * 0.15, start=40, extent=100, style=tk.ARC, outline="#ffffff", width=max(2.0, 2.6 * self.scale))
            c.create_oval(x - r * 0.13, y + r * 0.28, x + r * 0.13, y + r * 0.54, fill="#ffffff", outline="")
        elif dtype == TYPE_SERVER:
            c.create_rectangle(x - r * 0.78, y - r * 0.95, x + r * 0.78, y + r * 0.95, fill="#334155", outline="#cbd5e1", width=w)
            for dy in (-0.56, 0.0, 0.56):
                cy = y + dy * r
                c.create_rectangle(x - r * 0.62, cy - r * 0.20, x + r * 0.62, cy + r * 0.20, fill="#475569", outline="#e2e8f0", width=1)
                c.create_oval(x - r * 0.48, cy - r * 0.07, x - r * 0.34, cy + r * 0.07, fill="#4ade80", outline="")
                c.create_line(x - r * 0.16, cy, x + r * 0.46, cy, fill="#cbd5e1", width=max(1.4, 1.8 * self.scale))
        elif dtype == TYPE_PRINTER:
            c.create_rectangle(x - r * 0.52, y - r * 0.92, x + r * 0.52, y - r * 0.35, fill="#ffffff", outline="#b45309", width=1.5)
            c.create_rectangle(x - r * 0.96, y - r * 0.38, x + r * 0.96, y + r * 0.42, fill="#d97706", outline="#fde68a", width=w)
            c.create_oval(x + r * 0.55, y - r * 0.22, x + r * 0.72, y - r * 0.05, fill="#4ade80", outline="")
            c.create_rectangle(x - r * 0.54, y + r * 0.18, x + r * 0.54, y + r * 0.92, fill="#ffffff", outline="#b45309", width=1.5)
            c.create_line(x - r * 0.34, y + r * 0.45, x + r * 0.34, y + r * 0.45, fill="#b45309", width=1.5)
            c.create_line(x - r * 0.34, y + r * 0.68, x + r * 0.22, y + r * 0.68, fill="#b45309", width=1.5)
        elif dtype == TYPE_PHONE:
            c.create_rectangle(x - r * 0.56, y - r * 0.96, x + r * 0.56, y + r * 0.96, fill="#7c3aed", outline="#ddd6fe", width=w)
            c.create_rectangle(x - r * 0.42, y - r * 0.72, x + r * 0.42, y + r * 0.58, fill="#a78bfa", outline="")
            c.create_oval(x - r * 0.10, y + r * 0.68, x + r * 0.10, y + r * 0.86, fill="#ffffff", outline="")
        elif dtype == TYPE_CAMERA:
            c.create_rectangle(x - r * 1.05, y - r * 0.56, x + r * 0.52, y + r * 0.44, fill="#1e293b", outline="#38bdf8", width=w)
            c.create_polygon(x + r * 0.52, y - r * 0.34, x + r * 1.15, y - r * 0.62, x + r * 1.15, y + r * 0.52, x + r * 0.52, y + r * 0.24, fill="#0284c7", outline="#bae6fd", width=w)
            c.create_oval(x - r * 0.78, y - r * 0.30, x - r * 0.52, y - r * 0.04, fill="#ef4444", outline="")
            c.create_line(x - r * 0.25, y + r * 0.44, x - r * 0.55, y + r * 0.88, fill="#64748b", width=max(2.2, 2.8 * self.scale))
        elif dtype == TYPE_TV:
            c.create_rectangle(x - r * 1.18, y - r * 0.72, x + r * 1.18, y + r * 0.48, fill="#0f172a", outline="#38bdf8", width=w)
            c.create_rectangle(x - r * 1.02, y - r * 0.58, x + r * 1.02, y + r * 0.34, fill="#0284c7", outline="")
            c.create_text(x, y - r * 0.12, text="TV", fill="#ffffff", font=("Segoe UI", max(8, int(10 * self.scale)), "bold"))
            c.create_line(x - r * 0.42, y + r * 0.48, x - r * 0.65, y + r * 0.78, fill="#38bdf8", width=max(2.0, 2.5 * self.scale))
            c.create_line(x + r * 0.42, y + r * 0.48, x + r * 0.65, y + r * 0.78, fill="#38bdf8", width=max(2.0, 2.5 * self.scale))
        elif dtype in (TYPE_PC, TYPE_THIS_PC):
            body_col = "#15803d" if dtype == TYPE_THIS_PC else "#1d4ed8"
            scr_col = "#22c55e" if dtype == TYPE_THIS_PC else "#3b82f6"
            border_col = "#bbf7d0" if dtype == TYPE_THIS_PC else "#bfdbfe"
            c.create_rectangle(x - r * 1.0, y - r * 0.80, x + r * 1.0, y + r * 0.40, fill=body_col, outline=border_col, width=w)
            c.create_rectangle(x - r * 0.80, y - r * 0.62, x + r * 0.80, y + r * 0.22, fill=scr_col, outline="")
            if dtype == TYPE_THIS_PC:
                c.create_text(x, y - r * 0.20, text="★", fill="#ffffff", font=("Segoe UI", max(9, int(12 * self.scale)), "bold"))
            c.create_line(x, y + r * 0.40, x, y + r * 0.78, fill=body_col, width=max(3.0, 4.0 * self.scale))
            c.create_line(x - r * 0.52, y + r * 0.78, x + r * 0.52, y + r * 0.78, fill=body_col, width=max(3.0, 4.0 * self.scale))
        else:
            c.create_rectangle(x - r * 0.88, y - r * 0.88, x + r * 0.88, y + r * 0.88, fill="#4b5563", outline="#d1d5db", width=w)
            c.create_text(x, y, text="?", fill="#ffffff", font=("Segoe UI", max(11, int(15 * self.scale)), "bold"))

    def _schedule_redraw(self) -> None:
        if self._redraw_after_id is not None:
            return
        def _flush() -> None:
            self._redraw_after_id = None
            self.redraw()
        self._redraw_after_id = self.after(16, _flush)

    def redraw(self) -> None:
        c = self.canvas
        c.delete("!lanbot_overlay")
        bg, grid_col, pattern, fg, sub, link_confirmed, link_auto = CANVAS_THEMES.get(self.canvas_theme, CANVAS_THEMES["Nền chấm tối"])
        if c.cget("bg") != bg:
            c.configure(bg=bg)
        w, h = max(100, c.winfo_width()), max(100, c.winfo_height())

        # Vẽ lưới siêu nhẹ (~45 đường thay vì 1.600 chấm vuông) để kéo/zoom mượt 60 FPS không bao giờ giựt!
        step = max(36, int(48 * self.scale))
        ox, oy = int(self.offset_x) % step, int(self.offset_y) % step
        dash_grid = (2, 10) if pattern == "dots" else ()
        for gx in range(ox, w, step):
            c.create_line(gx, 0, gx, h, fill=grid_col, dash=dash_grid)
        for gy in range(oy, h, step):
            c.create_line(0, gy, w, gy, fill=grid_col, dash=dash_grid)

        # 0. Khi xem chế độ Tổng quan Tòa nhà (Tất cả tầng > 1 tầng): vẽ khung từng Tầng kiểu Doanh nghiệp / Zabbix để thấy rõ dây nối liên tầng!
        is_dark_canvas = "tối" in self.canvas_theme
        if self.show_floor_bands and self._visible_devices:
            fl_groups: dict[str, list[Device]] = {}
            for d in self._visible_devices:
                fl_groups.setdefault(d.floor or DEFAULT_FLOOR, []).append(d)
            if len(fl_groups) > 1:
                band_colors = [("#0284c7", "#eff6ff", "#0c1e35"), ("#0f766e", "#f0fdfa", "#0c2927"), ("#7c3aed", "#f5f3ff", "#1e1238"), ("#d97706", "#fffbeb", "#2e1f08")]
                for idx_fl, (fl_name, members) in enumerate(fl_groups.items()):
                    pts = [self.world_to_screen(d.x, d.y) for d in members]
                    pad_x, pad_y = 75 * self.scale, 58 * self.scale
                    bx0, by0 = min(p[0] for p in pts) - pad_x, min(p[1] for p in pts) - pad_y
                    bx1, by1 = max(p[0] for p in pts) + pad_x, max(p[1] for p in pts) + pad_y * 1.45
                    bo, bfl, bfd = band_colors[idx_fl % len(band_colors)]
                    c.create_rectangle(bx0, by0, bx1, by1, fill=bfd if is_dark_canvas else bfl, outline=bo, width=1.8, dash=(8, 4))
                    c.create_rectangle(bx0, by0, bx0 + max(110, len(fl_name) * 8 + 42), by0 + 22, fill=bo, outline="")
                    c.create_text(bx0 + 10, by0 + 11, text=f"🏢 {fl_name} ({len(members)})", anchor="w", fill="#ffffff", font=("Segoe UI", 9, "bold"))

        # 1. Vẽ các khung khu vực (có/không tô màu tự chọn) & ghi chú kiểu Cisco Packet Tracer (nằm dưới thiết bị)
        for ann in self._annotations:
            pal = DRAW_COLOR_PALETTE.get(ann.color_name, DRAW_COLOR_PALETTE["Xanh dương"])
            outline_col = ann.color or pal[0]
            if ann.filled:
                fill_col = ann.fill_hex if ann.fill_hex else (pal[2] if is_dark_canvas else pal[1])
            else:
                fill_col = ""
            is_sel = ann.id == self.selected_ann_id
            bw = 3.2 if is_sel else 2.0
            dash_pat = (6, 4) if ann.dashed else ()
            if ann.kind == "rect":
                sx1, sy1 = self.world_to_screen(ann.x1, ann.y1)
                sx2, sy2 = self.world_to_screen(ann.x2, ann.y2)
                is_vlan = _inventory_annotation_network(ann) is not None
                if is_vlan and not fill_col:
                    fill_col = "#101e2c" if is_dark_canvas else "#f4faff"
                c.create_rectangle(sx1, sy1, sx2, sy2, fill=fill_col, outline="#ef4444" if is_sel else outline_col,
                                   width=bw, dash=() if is_vlan else dash_pat)
                if ann.text:
                    if is_vlan and abs(sx2 - sx1) >= 66:
                        inset_x, inset_y = min(sx1, sx2), min(sy1, sy2)
                        shown = ann.text
                        limit = max(8, int((abs(sx2 - sx1) - 22) / 7))
                        if len(shown) > limit:
                            shown = shown[:limit - 1] + "…"
                        label_w = min(abs(sx2 - sx1), 20 + len(shown) * 7)
                        c.create_rectangle(inset_x, inset_y, inset_x + label_w, inset_y + 20,
                                           fill="#164660" if is_dark_canvas else "#dceff9", outline="")
                        c.create_text(inset_x + 9, inset_y + 10, text=shown, anchor="w",
                                      fill="#e0f2fe" if is_dark_canvas else "#075985", font=("Segoe UI", 8, "bold"))
                    elif not is_vlan:
                        c.create_text(min(sx1, sx2) + 10, min(sy1, sy2) + 14, text=ann.text, anchor="w",
                                      fill=outline_col, font=("Segoe UI", max(8, int(10 * self.scale)), "bold"))
            elif ann.kind == "oval":
                sx1, sy1 = self.world_to_screen(ann.x1, ann.y1)
                sx2, sy2 = self.world_to_screen(ann.x2, ann.y2)
                c.create_oval(sx1, sy1, sx2, sy2, fill=fill_col, outline="#ef4444" if is_sel else outline_col, width=bw, dash=dash_pat)
                if ann.text:
                    c.create_text((sx1 + sx2) / 2, min(sy1, sy2) + 16, text=ann.text, fill=outline_col, font=("Segoe UI", max(8, int(10 * self.scale)), "bold"))
            elif ann.kind == "note":
                sx, sy = self.world_to_screen(ann.x1, ann.y1)
                c.create_rectangle(
                    sx - 8, sy - 12, sx + max(84, len(ann.text) * 7.8 * self.scale), sy + 12,
                    fill="#422006" if is_dark_canvas else "#fef9c3",
                    outline="#ef4444" if is_sel else "#eab308",
                    width=2.4 if is_sel else 1.2,
                )
                c.create_text(sx, sy, text=f"📝 {ann.text}", anchor="w", fill="#fef08a" if is_dark_canvas else "#713f12", font=("Segoe UI", max(8, int(9.5 * self.scale)), "bold"))

        if self._shape_start and self._shape_end:
            sx1, sy1 = self.world_to_screen(*self._shape_start)
            sx2, sy2 = self.world_to_screen(*self._shape_end)
            p_fill = self.draw_fill_hex if self.draw_filled else ""
            p_dash = (6, 4) if self.draw_dashed else ()
            if self.mode == "rect":
                c.create_rectangle(sx1, sy1, sx2, sy2, fill=p_fill, outline=self.draw_outline_hex, width=2, dash=p_dash)
            elif self.mode == "oval":
                c.create_oval(sx1, sy1, sx2, sy2, fill=p_fill, outline=self.draw_outline_hex, width=2, dash=p_dash)

        vis_map = {d.id: d for d in self._visible_devices}
        positions = {d.id: self.world_to_screen(d.x, d.y) for d in vis_map.values()}
        in_view = {did for did, (x, y) in positions.items() if -140 <= x <= w + 140 and -95 <= y <= h + 95}

        # 2. Khung cùng subnet
        if self.show_subnet_group and self._visible_devices:
            groups: dict[str, list[Device]] = {}
            for d in self._visible_devices:
                if d.subnet:
                    groups.setdefault(d.subnet, []).append(d)
            for cidr, members in groups.items():
                if len(members) < 2:
                    continue
                pts = [self.world_to_screen(d.x, d.y) for d in members]
                pad = 60 * self.scale
                x0, y0 = min(p[0] for p in pts) - pad, min(p[1] for p in pts) - pad * 0.9
                x1, y1 = max(p[0] for p in pts) + pad, max(p[1] for p in pts) + pad * 1.3
                c.create_rectangle(x0, y0, x1, y1, outline=link_auto, width=1.3, dash=(6, 5))
                c.create_text(x0 + 10, y0 + 12, text=_translate_text_v6(f"Cùng subnet {cidr}", getattr(self, "_lang_code", "vi")), anchor="w", fill=link_auto, font=("Segoe UI", max(8, int(9 * self.scale)), "italic"))

        # 3. Đường nối (có thể tắt dây tự nối nét đứt để sơ đồ đỡ rối khi có 30-50 máy!)
        other_floors: dict[str, list[Device]] = {}
        for lnk in self._links:
            if not lnk.confirmed and not self.show_auto_links:
                continue
            s, t = vis_map.get(lnk.source_id), vis_map.get(lnk.target_id)
            if not s or not t:
                if lnk.confirmed and self.scale >= 0.45:
                    visible, other_id = (s, lnk.target_id) if s else (t, lnk.source_id)
                    peer = self._global_devices.get(other_id)
                    if visible and visible.id in in_view and peer and peer.floor != visible.floor:
                        other_floors.setdefault(visible.id, []).append(peer)
                continue
            x1, y1 = positions[s.id]
            x2, y2 = positions[t.id]
            if (max(x1, x2) < -32 or min(x1, x2) > w + 32
                    or max(y1, y2) < -32 or min(y1, y2) > h + 32):
                continue
            if lnk.id in self._fault_link_ids:
                c.create_line(x1, y1, x2, y2, fill="#f97316", width=4.2)
            elif (lnk.source_id, lnk.target_id) in self._anim_passed_edges:
                c.create_line(x1, y1, x2, y2, fill="#22c55e", width=3.4)
            elif lnk.confirmed:
                is_cross = (s.floor or DEFAULT_FLOOR) != (t.floor or DEFAULT_FLOOR)
                if s.status == STATUS_NO_PING or t.status == STATUS_NO_PING:
                    lcol, lw = "#ef4444", 2.8
                elif is_cross:
                    lcol, lw = "#0ea5e9", 3.0
                else:
                    lcol, lw = link_confirmed, 2.4
                c.create_line(x1, y1, x2, y2, fill=lcol, width=lw)
                if is_cross:
                    mx, my = (x1 + x2) / 2, (y1 + y2) / 2
                    c.create_rectangle(mx - 36, my - 9, mx + 36, my + 9, fill="#0284c7", outline="#bae6fd", width=1)
                    c.create_text(mx, my, text="Liên tầng", fill="#ffffff", font=("Segoe UI", 7, "bold"))
            else:
                c.create_line(x1, y1, x2, y2, fill=link_auto, width=1.3, dash=(4, 4))

        # 4. Vẽ thiết bị
        f_name = ("Segoe UI", max(8, int(9.2 * self.scale)), "bold")
        f_ip = ("Segoe UI", max(7, int(8.2 * self.scale)))
        name_gap = max(16.0, 17.0 * self.scale)
        ip_gap = max(34.0, 35.0 * self.scale)

        for dev in self._visible_devices:
            if dev.id not in in_view:
                continue
            sx, sy = positions[dev.id]
            r = max(5.0, 23.0 * self.scale)
            if dev.id in self._fault_suspect_ids:
                c.create_oval(sx - r - 11, sy - r - 11, sx + r + 11, sy + r + 11, outline="#f97316", width=3.5, dash=(5, 3))
            elif dev.id in self._fault_device_ids:
                c.create_oval(sx - r - 8, sy - r - 8, sx + r + 8, sy + r + 8, outline="#ef4444", width=2.5)
            if dev.id == self._link_source_id:
                c.create_oval(sx - r - 7, sy - r - 7, sx + r + 7, sy + r + 7, outline="#0ea5e9", width=3)
            elif dev.id in self._selected_ids:
                c.create_oval(sx - r - 6, sy - r - 6, sx + r + 6, sy + r + 6, outline="#38bdf8", width=2.6)

            self._draw_device_shape(c, dev.device_type, sx, sy, r)

            dot_c = "#f59e0b" if (0 < dev.consecutive_failures < DEFAULT_FAILURE_THRESHOLD) else STATUS_COLORS.get(dev.status, "#94a3b8")
            dr = max(4.6, 5.8 * self.scale)
            c.create_oval(sx + r * 0.95 - dr, sy - r * 0.95 - dr, sx + r * 0.95 + dr, sy - r * 0.95 + dr, fill=dot_c, outline=bg, width=2)

            if not dev.trusted:
                c.create_oval(sx - r * 0.95 - dr, sy - r * 0.95 - dr, sx - r * 0.95 + dr, sy - r * 0.95 + dr, fill="#eab308", outline=bg, width=1.5)
                c.create_text(sx - r * 0.95, sy - r * 0.95, text="!", fill="#0f172a", font=("Segoe UI", max(7, int(8 * self.scale)), "bold"))

            max_chars = 13 if self.scale < 0.85 else 17
            disp_n = getattr(self, "_name_tr_fn", lambda x: x)(dev.name)
            short_name = disp_n if len(disp_n) <= max_chars else disp_n[:max_chars - 1] + "…"
            if self.scale >= 0.50 or dev.id in self._selected_ids:
                c.create_text(sx, sy + r + name_gap, text=short_name, fill=fg, font=f_name)
            if self.scale >= 0.70 or dev.id in self._selected_ids:
                ip_txt = (f"{dev.ip} ({dev.latency_ms:.0f}ms)" if dev.latency_ms is not None else dev.ip) if dev.ip else "(L2)"
                c.create_text(sx, sy + r + ip_gap, text=ip_txt, fill=sub, font=f_ip)

            cross_targets = other_floors.get(dev.id)
            if cross_targets:
                ct0 = cross_targets[0]
                extra = f" +{len(cross_targets) - 1}" if len(cross_targets) > 1 else ""
                tag_txt = f"↗ {ct0.name[:12]} ({ct0.floor}){extra}"
                tw = max(70, len(tag_txt) * 5.8)
                c.create_rectangle(sx - tw / 2, sy - r - 24, sx + tw / 2, sy - r - 8, fill="#0f766e", outline="#5eead4", width=1.2)
                c.create_text(sx, sy - r - 16, text=tag_txt, fill="#ffffff", font=("Segoe UI", 8, "bold"))

        if self._marquee_start and self._marquee_end:
            c.create_rectangle(self._marquee_start[0], self._marquee_start[1], self._marquee_end[0], self._marquee_end[1], outline="#38bdf8", width=2, dash=(4, 3))

        if self._anim_packet_pos:
            wx, wy, pcol, plbl = self._anim_packet_pos
            px, py = self.world_to_screen(wx, wy)
            c.create_oval(px - 18, py - 11, px + 18, py + 11, fill=pcol, outline="#ffffff", width=2)
            c.create_text(px, py, text=plbl, fill="#0f172a", font=("Segoe UI", 7, "bold"))

        if self._anim_broken_at:
            bx, by, btxt = self._anim_broken_at
            sx, sy = self.world_to_screen(bx, by)
            c.create_oval(sx - 15, sy - 15, sx + 15, sy + 15, fill="#dc2626", outline="#ffffff", width=2.5)
            c.create_text(sx, sy, text="✕", fill="#ffffff", font=("Segoe UI", 12, "bold"))
            c.create_rectangle(sx - 125, sy - 38, sx + 125, sy - 18, fill="#7f1d1d", outline="#f87171", width=1.5)
            c.create_text(sx, sy - 28, text=btxt, fill="#ffffff", font=("Segoe UI", 8, "bold"))

        if self.demo_mode:
            c.create_rectangle(12, 10, 276, 34, fill="#b45309", outline="#fbbf24", width=1.5)
            c.create_text(144, 22, text="DỮ LIỆU MÔ PHỎNG — DEMO OFFLINE", fill="#ffffff", font=("Segoe UI", 9, "bold"))

        if self._is_filtered:
            c.create_rectangle(w - 240, 10, w - 12, 34, fill="#0369a1", outline="#38bdf8", width=1.2)
            c.create_text(w - 126, 22, text=f"Đang lọc: {len(self._visible_devices)}/{len(self._all_devices)} thiết bị", fill="#ffffff", font=("Segoe UI", 9, "bold"))

        tr_fn = getattr(self, "_tr_fn", lambda k: k)
        mode_hints = {
            "link": tr_fn("hint_link"),
            "box": tr_fn("hint_box"),
            "note": tr_fn("hint_note"),
            "rect": tr_fn("hint_shape"),
            "oval": tr_fn("hint_shape"),
        }
        if self.mode in mode_hints:
            txt_h = mode_hints[self.mode]
            bw_h = min(w - 24, max(360, int(len(txt_h) * 6.8) + 28))
            c.create_rectangle(12, h - 32, 12 + bw_h, h - 8, fill="#0369a1", outline="")
            c.create_text(22, h - 20, text=txt_h, anchor="w", fill="#ffffff", font=("Segoe UI", 9, "bold"))


# =============================================================================
# 7. HỘP THOẠI & BẢNG CHI TIẾT (CÓ PHƯƠNG PHÁP KHẮC PHỤC SỰ CỐ)
# =============================================================================

def _fit_dialog(dlg: ctk.CTkToplevel, master: ctk.CTk, min_w: int, min_h: int) -> None:
    dlg.update_idletasks()
    sw, sh = dlg.winfo_screenwidth(), dlg.winfo_screenheight()
    w = min(max(min_w, dlg.winfo_reqwidth() + 24), sw - 60)
    h = min(max(min_h, dlg.winfo_reqheight() + 24), sh - 80)
    x = master.winfo_rootx() + max(20, (master.winfo_width() - w) // 2)
    y = master.winfo_rooty() + max(16, (master.winfo_height() - h) // 2)
    dlg.geometry(f"{w}x{h}+{max(10, x)}+{max(10, y)}")


def center_startup_window(window: ctk.CTk | ctk.CTkToplevel, width: int, height: int) -> None:
    left, top = 0, 0
    right, bottom = window.winfo_screenwidth(), window.winfo_screenheight()
    if sys.platform == "win32":
        from ctypes import wintypes
        rect = wintypes.RECT()
        if ctypes.windll.user32.SystemParametersInfoW(0x0030, 0, ctypes.byref(rect), 0):
            left, top, right, bottom = rect.left, rect.top, rect.right, rect.bottom
    scale = window._get_window_scaling()
    width = min(width, int((right - left) / scale))
    height = min(height, int((bottom - top) / scale))
    x = left + round((right - left - width * scale) / 2)
    y = top + round((bottom - top - height * scale) / 2)
    window.geometry(f"{width}x{height}+{x}+{y}")


def _get_bootloader_splash() -> Any:
    if not getattr(sys, "frozen", False):
        return None
    try:
        import pyi_splash
    except ImportError:
        return None
    return pyi_splash if pyi_splash.is_alive() else None


class SplashScreen(ctk.CTkToplevel):
    """Màn hình khởi động căn giữa chuẩn DPI, chạy quét mạng thật ngay trên thanh tiến trình rồi mới mở giao diện chính."""

    def __init__(
        self,
        master: ctk.CTk,
        logo_png: Path | None,
        splash_png: Path | None = None,
        on_done: Callable[[], None] | None = None,
        on_cancel: Callable[[], None] | None = None,
        live_progress: bool = True,
    ) -> None:
        super().__init__(master)
        self.overrideredirect(True)
        self.attributes("-topmost", True)
        self._bootloader_splash = _get_bootloader_splash()
        self._alpha = 1.0 if self._bootloader_splash else 0.0
        try:
            self.attributes("-alpha", self._alpha)
        except tk.TclError:
            pass
        self._img: ctk.CTkImage | None = None
        self._on_done = on_done
        self._on_cancel = on_cancel
        self._live_progress = live_progress
        self._prog = 0.0
        self._target_prog = 0.06
        self._status_msg = "Đang dò card mạng & chuẩn bị quét LAN..."
        self._closing = False
        self._done_fired = False

        if splash_png and splash_png.exists() and Image is not None:
            w, h = 660, 442
            center_startup_window(self, w, h)
            frame = ctk.CTkFrame(self, corner_radius=14, fg_color="#070d19", border_width=2, border_color="#38bdf8")
            frame.pack(fill="both", expand=True)
            pil = Image.open(splash_png).convert("RGBA")
            aspect = pil.width / max(1, pil.height)
            img_w = min(640, int(332 * aspect))
            img_h = int(img_w / aspect)
            self._img = ctk.CTkImage(light_image=pil, dark_image=pil, size=(img_w, img_h))
            ctk.CTkLabel(frame, image=self._img, text="", fg_color="#070d19").pack(padx=5, pady=(5, 2))
            foot = ctk.CTkFrame(frame, fg_color="transparent")
            foot.pack(fill="x", padx=18, pady=(2, 10))
            self.step_lbl = ctk.CTkLabel(foot, text=self._status_msg, font=ctk.CTkFont(family="Segoe UI", size=12, weight="bold"), text_color="#e0f2fe")
            self.step_lbl.pack(side="left")
            if on_cancel:
                ctk.CTkButton(foot, text="Bỏ qua", width=66, height=24, fg_color="#334155", hover_color="#475569",
                              font=ctk.CTkFont(size=11), command=self._cancel_scan).pack(side="right", padx=(8, 0))
            self.bar = ctk.CTkProgressBar(foot, width=210, height=9, mode="determinate", progress_color="#38bdf8", fg_color="#1e293b")
            self.bar.set(0.0)
            self.bar.pack(side="right", pady=4)
        else:
            w, h = 440, 265
            center_startup_window(self, w, h)
            frame = ctk.CTkFrame(self, corner_radius=16, fg_color="#0f2a52", border_width=2, border_color="#38bdf8")
            frame.pack(fill="both", expand=True)
            if logo_png and logo_png.exists() and Image is not None:
                pil = Image.open(logo_png)
                self._img = ctk.CTkImage(light_image=pil, dark_image=pil, size=(80, 80))
                ctk.CTkLabel(frame, image=self._img, text="").pack(pady=(20, 6))
            ctk.CTkLabel(frame, text=f"{APP_NAME} v{APP_VERSION}", font=ctk.CTkFont(family="Segoe UI", size=22, weight="bold"), text_color="#ffffff").pack()
            self.step_lbl = ctk.CTkLabel(frame, text=self._status_msg, font=ctk.CTkFont(family="Segoe UI", size=12), text_color="#bae6fd")
            self.step_lbl.pack(pady=(2, 8))
            self.bar = ctk.CTkProgressBar(frame, width=280, mode="determinate", progress_color="#38bdf8")
            self.bar.set(0.0)
            self.bar.pack(pady=(4, 10))
            if on_cancel:
                ctk.CTkButton(frame, text="Bỏ qua quét lúc mở", width=130, height=26, fg_color="#1e3a5f", hover_color="#334155",
                              font=ctk.CTkFont(size=11), command=self._cancel_scan).pack(pady=(0, 8))

        self.bind("<Escape>", lambda _e: self._cancel_scan())
        if self._bootloader_splash:
            self.after_idle(self._handoff_bootloader_splash)
        self.after(25, self._animate_in)

    def _handoff_bootloader_splash(self) -> None:
        if self.winfo_viewable():
            self._close_bootloader_splash()
        elif self._bootloader_splash:
            self.after(35, self._handoff_bootloader_splash)

    def _close_bootloader_splash(self) -> None:
        splash = self._bootloader_splash
        self._bootloader_splash = None
        if splash:
            try:
                splash.close()
            except (OSError, RuntimeError):
                pass

    def _cancel_scan(self) -> None:
        if self._on_cancel:
            try:
                self._on_cancel()
            except Exception:
                pass
        self.finish_now("Đang mở LanMap...")

    def set_progress(self, ratio: float, message: str) -> None:
        self._target_prog = max(self._target_prog, min(1.0, float(ratio)))
        self._status_msg = message
        if self.winfo_exists():
            try:
                pct = int(self._target_prog * 100)
                self.step_lbl.configure(text=f"{message} · {pct}%" if "%" not in message else message)
            except Exception:
                pass

    def finish_now(self, message: str = "Sẵn sàng mở LanMap!") -> None:
        if self._closing:
            return
        self._closing = True
        self._target_prog = 1.0
        self._prog = 1.0
        if self.winfo_exists():
            try:
                self.bar.set(1.0)
                self.step_lbl.configure(text=message)
            except Exception:
                pass
            self.after(180, self._animate_out)
        else:
            self._fire_done()

    def _fire_done(self) -> None:
        if self._done_fired:
            return
        self._done_fired = True
        try:
            if self._on_done:
                self._on_done()
        finally:
            self._close_bootloader_splash()

    def _animate_in(self) -> None:
        if not self.winfo_exists() or self._closing:
            return
        if self._alpha < 1.0:
            self._alpha = min(1.0, self._alpha + 0.12)
            try:
                self.attributes("-alpha", self._alpha)
            except Exception:
                pass
        if self._live_progress:
            if self._prog < self._target_prog:
                self._prog = min(self._target_prog, self._prog + max(0.015, (self._target_prog - self._prog) * 0.25))
            self.bar.set(self._prog)
            self.after(35, self._animate_in)
        else:
            self._prog = min(1.0, self._prog + 0.045)
            self.bar.set(self._prog)
            pct = int(self._prog * 100)
            self.step_lbl.configure(text=f"Đang chuẩn bị sơ đồ · {pct}%" if pct < 95 else "Sắp mở LanMap")
            if self._prog < 1.0:
                self.after(38, self._animate_in)
            else:
                self.after(180, self._animate_out)

    def _animate_out(self) -> None:
        if not self.winfo_exists():
            self._fire_done()
            return
        self._alpha = max(0.0, self._alpha - 0.18)
        try:
            self.attributes("-alpha", self._alpha)
        except Exception:
            pass
        if self._alpha > 0.02:
            self.after(22, self._animate_out)
        else:
            self._fire_done()


class UpdateDialog(ctk.CTkToplevel):
    def __init__(self, master: ctk.CTk, current_repo: str, on_save_repo: Callable[[str], None]) -> None:
        super().__init__(master)
        self.title(f"Kiểm tra cập nhật {APP_NAME} (GitHub)")
        self.minsize(520, 340)
        self.resizable(True, True)
        self._on_save_repo = on_save_repo
        self._download_url = ""
        self._check_results: queue.Queue[dict[str, Any]] = queue.Queue()
        self.transient(master)
        self.grab_set()

        footer = ctk.CTkFrame(self, fg_color="transparent")
        footer.pack(side="bottom", fill="x", padx=20, pady=(6, 16))
        self.dl_btn = ctk.CTkButton(footer, text="Tải bản cập nhật", height=36, fg_color="#16a34a", state="disabled", command=lambda: webbrowser.open(self._download_url))
        self.dl_btn.pack(side="left")
        ctk.CTkButton(footer, text="Đóng", width=84, height=36, fg_color="transparent", border_width=1, text_color=("gray15", "gray90"), command=self.destroy).pack(side="right")

        body = ctk.CTkFrame(self, fg_color="transparent")
        body.pack(side="top", fill="both", expand=True, padx=20, pady=(16, 4))
        ctk.CTkLabel(body, text=f"Phiên bản hiện tại: v{APP_VERSION}", font=ctk.CTkFont(size=15, weight="bold")).pack(anchor="w")
        ctk.CTkLabel(body, text="Kho GitHub (ten-tai-khoan/LanMap):", font=ctk.CTkFont(size=12)).pack(anchor="w", pady=(8, 2))
        rrow = ctk.CTkFrame(body, fg_color="transparent")
        rrow.pack(fill="x", pady=(0, 10))
        self.repo_entry = ctk.CTkEntry(rrow)
        self.repo_entry.insert(0, current_repo)
        self.repo_entry.pack(side="left", fill="x", expand=True, padx=(0, 8))
        self.check_btn = ctk.CTkButton(rrow, text="Kiểm tra ngay", width=116, command=self._check)
        self.check_btn.pack(side="right")
        self.result_box = ctk.CTkTextbox(body, height=130)
        self.result_box.pack(fill="both", expand=True)
        self.result_box.insert("1.0", "Bấm 'Kiểm tra ngay' để đối chiếu với GitHub Releases mới nhất.")
        _fit_dialog(self, master, 540, 360)

    def _check(self) -> None:
        repo = self.repo_entry.get().strip()
        self._on_save_repo(repo)
        self.result_box.delete("1.0", "end")
        self.result_box.insert("1.0", f"Đang kiểm tra tại github.com/{repo}...")
        self.dl_btn.configure(state="disabled")
        self.check_btn.configure(state="disabled")
        self.repo_entry.configure(state="disabled")
        threading.Thread(
            target=lambda: self._check_results.put(check_github_release(repo)),
            daemon=True,
        ).start()
        self.after(80, self._poll_check)

    def _poll_check(self) -> None:
        try:
            result = self._check_results.get_nowait()
        except queue.Empty:
            self.after(80, self._poll_check)
            return
        self.check_btn.configure(state="normal")
        self.repo_entry.configure(state="normal")
        self._show_result(result)

    def _show_result(self, res: dict[str, Any]) -> None:
        self.result_box.delete("1.0", "end")
        if not res.get("ok"):
            self.result_box.insert("1.0", res.get("error", "Lỗi không xác định."))
            return
        tag = res["latest_tag"]
        self._download_url = res["download_url"]
        if res["has_update"]:
            self.result_box.insert("1.0", f"🎉 Có phiên bản mới: {tag} (hiện tại: v{APP_VERSION})\n\n{res['notes']}")
            self.dl_btn.configure(state="normal", text=f"Tải bản {tag}")
        else:
            self._download_url = res["html_url"]
            self.result_box.insert("1.0", f"Phiên bản đã phát hành gần nhất trên GitHub là {tag}.\n\n{res['notes']}")
            self.dl_btn.configure(state="normal", text="Mở trang GitHub Releases")


class WelcomeDialog(ctk.CTkToplevel):
    def __init__(self, master: ctk.CTk, logo_png: Path | None = None) -> None:
        super().__init__(master)
        self.title(f"Chào mừng đến với {APP_NAME}")
        self.minsize(520, 380)
        self.resizable(True, True)
        self.choice = "real"
        self._logo: ctk.CTkImage | None = None
        self.transient(master)
        self.grab_set()
        footer = ctk.CTkFrame(self, fg_color="transparent")
