        ctk.CTkButton(top, text="Mở Explorer (\\IP)", width=130, height=28, fg_color="#0369a1", command=lambda: open_shared_folder(device.ip)).pack(side="right")

        self.scroll = ctk.CTkScrollableFrame(self)
        self.scroll.pack(fill="both", expand=True, padx=16, pady=(0, 8))
        ctk.CTkLabel(self.scroll, text="Đang liệt kê thư mục chia sẻ...", font=ctk.CTkFont(size=12)).pack(anchor="w", padx=8, pady=8)
        ctk.CTkButton(self, text="Đóng", width=86, command=self.destroy).pack(anchor="e", padx=16, pady=(0, 12))
        _fit_dialog(self, master, 540, 380)

        def _w() -> None:
            shares = list_smb_shared_folders(device.ip)
