class SubnetCalcDialog(ctk.CTkToplevel):
    """Máy tính chia Subnet / CIDR / VLSM chuyên dụng cho quản trị mạng."""

    def __init__(self, master: ctk.CTk, initial_cidr: str = "192.168.20.0/24") -> None:
        super().__init__(master)
        self.title("🧮 Máy tính chia Subnet / CIDR (VLSM)")
        self.minsize(480, 340)
        self.resizable(True, True)
        self.transient(master)

        top = ctk.CTkFrame(self, fg_color="transparent")
        top.pack(fill="x", padx=16, pady=(14, 8))
        ctk.CTkLabel(top, text="Nhập IP/CIDR:", font=ctk.CTkFont(size=12, weight="bold")).pack(side="left", padx=(0, 6))
        self.cidr_e = ctk.CTkEntry(top, width=210)
        self.cidr_e.insert(0, initial_cidr or "192.168.20.0/24")
        self.cidr_e.pack(side="left", fill="x", expand=True, padx=(0, 6))
        ctk.CTkButton(top, text="Tính toán", width=96, command=self._calc).pack(side="right")

        self.box = ctk.CTkTextbox(self, font=ctk.CTkFont(family="Consolas", size=12))
        self.box.pack(fill="both", expand=True, padx=16, pady=(0, 10))
        ctk.CTkButton(self, text="Đóng", width=86, command=self.destroy).pack(anchor="e", padx=16, pady=(0, 12))
        self.cidr_e.bind("<Return>", lambda _e: self._calc())
        _fit_dialog(self, master, 500, 350)
        self._calc()

    def _calc(self) -> None:
        raw = self.cidr_e.get().strip()
        self.box.delete("1.0", "end")
        try:
            net = ipaddress.IPv4Network(raw, strict=False)
            hosts = list(net.hosts()) if net.num_addresses <= 65536 else []
            first_h = str(hosts[0]) if hosts else str(net.network_address + 1)
            last_h = str(hosts[-1]) if hosts else str(net.broadcast_address - 1)
            usable = max(0, net.num_addresses - 2) if net.prefixlen < 31 else net.num_addresses
            txt = (
                f"Địa chỉ mạng (Network ID) : {net.network_address}/{net.prefixlen}\n"
                f"Subnet Mask               : {net.netmask}\n"
                f"Wildcard Mask             : {net.hostmask}\n"
                f"Broadcast Address         : {net.broadcast_address}\n"
                f"Dải IP khả dụng (Hosts)   : {first_h}  →  {last_h}\n"
                f"Số máy tối đa (Usable)    : {usable:,} thiết bị\n"
                f"Loại dải IP               : {'Mạng nội bộ (Private)' if net.is_private else 'Công khai (Public)'}"
            )
            self.box.insert("1.0", txt)
        except Exception as exc:
            self.box.insert("1.0", f"Định dạng chưa hợp lệ (vd đúng: 192.168.10.0/23):\n{exc}")


class RemoteDesktopDialog(ctk.CTkToplevel):
    """Điều khiển màn hình, chuột & bàn phím máy Client trực tiếp qua LAN (kiểu UltraViewer / AnyDesk)."""

    def __init__(self, master: ctk.CTk, ip: str, dev_name: str, pin: str) -> None:
        super().__init__(master)
        self.title(f"🖥 Điều khiển từ xa (UltraViewer Mode) — {dev_name} ({ip})")
        self.geometry("1020x660")
        self.minsize(760, 520)
        self._ip = ip
        self._pin = pin
        self._running = True
        self._paused = False
        self._photo: Any = None
        self._img_w = 960
        self._img_h = 540
        self.transient(master)
        self.protocol("WM_DELETE_WINDOW", self._close)

        bar = ctk.CTkFrame(self, corner_radius=0)
        bar.pack(fill="x", padx=8, pady=6)
        self.st_lbl = ctk.CTkLabel(bar, text=f"● Đang truyền màn hình {ip} — Bấm chuột trực tiếp vào ảnh để điều khiển, gõ phím để nhập!", font=ctk.CTkFont(size=11, weight="bold"), text_color="#16a34a")
        self.st_lbl.pack(side="left", padx=8)
        for combo in ("Win", "Ctrl+C", "Ctrl+V", "Ctrl+A", "Alt+Tab"):
            ctk.CTkButton(bar, text=combo, width=62, height=24, font=ctk.CTkFont(size=10), fg_color="#334155", command=lambda cb=combo: self._send_combo(cb)).pack(side="right", padx=2)
        self.pause_btn = ctk.CTkButton(bar, text="⏸ Tạm dừng", width=86, height=24, fg_color="#d97706", command=self._toggle_pause)
        self.pause_btn.pack(side="right", padx=(6, 4))

        self.canvas = tk.Canvas(self, bg="#0f172a", highlightthickness=0, cursor="crosshair")
        self.canvas.pack(fill="both", expand=True, padx=8, pady=(0, 8))
        self.canvas.bind("<Button-1>", lambda e: self._on_mouse(e, "click"))
        self.canvas.bind("<Double-Button-1>", lambda e: self._on_mouse(e, "dblclick"))
        self.canvas.bind("<Button-3>", lambda e: self._on_mouse(e, "rclick"))
        self.canvas.bind("<MouseWheel>", lambda e: self._on_mouse(e, "scroll"))
        self.bind("<KeyPress>", self._on_key)
        self.focus_set()

        threading.Thread(target=self._stream_loop, daemon=True).start()

    def _toggle_pause(self) -> None:
        self._paused = not self._paused
        self.pause_btn.configure(text="▶ Tiếp tục" if self._paused else "⏸ Tạm dừng", fg_color="#16a34a" if self._paused else "#d97706")

    def _on_mouse(self, e: tk.Event, ev_type: str) -> None:
        cw = max(1, self.canvas.winfo_width())
        ch = max(1, self.canvas.winfo_height())
        ox = max(0, (cw - self._img_w) // 2)
        oy = max(0, (ch - self._img_h) // 2)
        rx = (e.x - ox) / max(1, self._img_w)
        ry = (e.y - oy) / max(1, self._img_h)
        if not (0.0 <= rx <= 1.0 and 0.0 <= ry <= 1.0):
            return
        payload = json.dumps({"ev": ev_type, "rx": round(rx, 4), "ry": round(ry, 4), "delta": getattr(e, "delta", 120)})
        threading.Thread(target=lambda: query_lanmap_agent(self._ip, self._pin, "mouse", payload, timeout=2.0), daemon=True).start()

    def _on_key(self, e: tk.Event) -> None:
        payload = json.dumps({"keysym": e.keysym, "char": e.char})
        threading.Thread(target=lambda: query_lanmap_agent(self._ip, self._pin, "key", payload, timeout=2.0), daemon=True).start()

    def _send_combo(self, combo: str) -> None:
        payload = json.dumps({"combo": combo})
        threading.Thread(target=lambda: query_lanmap_agent(self._ip, self._pin, "key", payload, timeout=2.0), daemon=True).start()

    def _stream_loop(self) -> None:
        from PIL import ImageTk  # type: ignore
        while self._running:
            if self._paused:
                time.sleep(0.25)
                continue
            res = query_lanmap_agent(self._ip, self._pin, "screen", "", timeout=4.0)
            if not self._running:
                break
            if res.get("ok") and res.get("jpg") and Image is not None:
                try:
                    raw = base64.b64decode(res["jpg"])
                    pil = Image.open(io.BytesIO(raw))
                    cw = max(320, self.canvas.winfo_width() - 8)
                    ch = max(200, self.canvas.winfo_height() - 8)
                    ratio = min(cw / max(1, pil.width), ch / max(1, pil.height))
                    nw, nh = max(100, int(pil.width * ratio)), max(80, int(pil.height * ratio))
                    pil = pil.resize((nw, nh), Image.Resampling.BILINEAR)
                    def _draw(img_obj=pil, w0=nw, h0=nh) -> None:
                        if not self.winfo_exists():
                            return
                        self._img_w, self._img_h = w0, h0
                        self._photo = ImageTk.PhotoImage(img_obj)
                        self.canvas.delete("all")
                        self.canvas.create_image(self.canvas.winfo_width() // 2, self.canvas.winfo_height() // 2, image=self._photo, anchor="center")
                    self.after(0, _draw)
                except Exception:
                    pass
            else:
                err = str(res.get("error", "Mất kết nối màn hình"))
                self.after(0, lambda m=err: self.st_lbl.configure(text=f"✕ {m}", text_color="#dc2626") if self.winfo_exists() else None)
                time.sleep(1.0)
            time.sleep(0.18)

    def _close(self) -> None:
        self._running = False
        self.destroy()


class DeepScanAllDialog(ctk.CTkToplevel):
    """Quét sâu toàn bộ thiết bị trên sơ đồ (OS TTL + Cổng mở + Thư mục chia sẻ SMB + Banner)."""

    def __init__(self, master: ctk.CTk, devices: list[Device]) -> None:
        super().__init__(master)
        targets = [d for d in devices if d.registered and d.ip]
        self.title(f"Quét thiết bị trên sơ đồ ({len(targets)} thiết bị)")
        self.minsize(920, 500)
        self.resizable(True, True)
        self._targets = targets
        self._cancel = threading.Event()
        self._rows_text: list[str] = []
        self.transient(master)
        self.protocol("WM_DELETE_WINDOW", self._close)

        top = ctk.CTkFrame(self, fg_color="transparent")
        top.pack(fill="x", padx=14, pady=(12, 6))
        self.lbl = ctk.CTkLabel(top, text=f"Sẵn sàng quét {len(targets)} thiết bị",
                                font=ctk.CTkFont(size=13, weight="bold"))
        self.lbl.pack(side="left")
        ctk.CTkButton(top, text="Lưu báo cáo (.txt)", width=125, height=28, fg_color="#0f766e",
                      command=self._save_txt).pack(side="right", padx=(6, 0))
        ctk.CTkButton(top, text="Dừng & Đóng", width=96, height=28, fg_color="#dc2626",
                      command=self._close).pack(side="right")
        controls = ctk.CTkFrame(self, fg_color="transparent")
        controls.pack(fill="x", padx=14, pady=(0, 6))
        self.mode = ctk.StringVar(value="fast")
        for title, value in (("Quét nhanh", "fast"), ("Quét kỹ", "deep")):
            ctk.CTkRadioButton(controls, text=title, variable=self.mode, value=value).pack(side="left", padx=(0, 12))
        self.start_button = ctk.CTkButton(controls, text="Bắt đầu", width=90, command=self._start)
        self.start_button.pack(side="right")
        self._results: queue.Queue = queue.Queue()

        self.prog = ctk.CTkProgressBar(self)
        self.prog.pack(fill="x", padx=14, pady=(0, 8))
        self.prog.set(0)

        self.scroll = ctk.CTkScrollableFrame(self)
        self.scroll.pack(fill="both", expand=True, padx=14, pady=(0, 12))
        hdr = ctk.CTkFrame(self.scroll, fg_color=("gray82", "#1e293b"), corner_radius=6)
        hdr.pack(fill="x", pady=(0, 4))
        for txt, w in (("Thiết bị", 122), ("IP", 104), ("Hệ điều hành (TTL)", 160), ("Cổng mở", 136), ("Thư mục chia sẻ (SMB)", 170), ("Banner / Ghi chú", 170)):
            ctk.CTkLabel(hdr, text=txt, width=w, anchor="w", font=ctk.CTkFont(size=11, weight="bold")).pack(side="left", padx=4, pady=4)

        _fit_dialog(self, master, 940, 520)

    def _start(self) -> None:
        if not self._targets:
            self.lbl.configure(text="Sơ đồ chưa có thiết bị có IPv4.")
            return
        self.start_button.configure(state="disabled")
        deep = self.mode.get() == "deep"
        self.lbl.configure(text=f"Đang quét {len(self._targets)} thiết bị…")
        for row in self.scroll.winfo_children()[1:]:
            row.destroy()
        self._rows_text.clear()
        self.prog.set(0)
        threading.Thread(target=self._run, args=(deep,), daemon=True).start()
        self.after(100, self._poll_results)

    def _run(self, deep: bool) -> None:
        def probe(dev: Device) -> tuple:
            if self._cancel.is_set():
                return (dev, "", [], "", "")
            try:
                ports = DEEP_INVENTORY_PORTS if deep else FAST_INVENTORY_PORTS
                opened = [p for p in ports if not self._cancel.is_set() and check_tcp_port(dev.ip, p, 0.45)]
                os_name = detect_os_by_ping_ttl(dev.ip)[0] if deep and not self._cancel.is_set() else "—"
                shares = "—"
                note = "—"
                if deep and not self._cancel.is_set():
                    if 445 in opened:
                        shares = ", ".join(record[0] for record in list_smb_shared_folders(dev.ip)[:4]) or "—"
                    if 80 in opened:
                        title, server = grab_http_title_and_server(dev.ip, timeout=0.55)
                        note = title or server or "—"
                return dev, os_name, opened, shares, note
            except Exception as exc:
                return dev, "—", [], "—", str(exc)

        with ThreadPoolExecutor(max_workers=12) as pool:
            targets = iter(self._targets)
            while not self._cancel.is_set():
                chunk = list(islice(targets, 24))
                if not chunk:
                    break
                for future in as_completed([pool.submit(probe, dev) for dev in chunk]):
                    if self._cancel.is_set():
                        break
                    self._results.put(future.result())
        self._results.put(None)

    def _poll_results(self) -> None:
        for _ in range(24):
            try:
                result = self._results.get_nowait()
            except queue.Empty:
                break
            if result is None:
                self.start_button.configure(state="normal")
                self.lbl.configure(text=f"Đã quét {len(self._rows_text)} thiết bị.")
                return
            dev, os_name, ports, shares, note = result
            port_text = ", ".join(map(str, ports)) or "—"
            self._rows_text.append(f"{dev.name} | {dev.ip} | {os_name} | TCP: {port_text} | SMB: {shares} | {note}")
            self.prog.set(len(self._rows_text) / len(self._targets))
            row = ctk.CTkFrame(self.scroll, corner_radius=5)
            row.pack(fill="x", pady=1)
            for value, width in zip(
                (dev.name[:18], dev.ip, os_name[:24], port_text[:21], shares[:25], note[:26]),
                (122, 104, 160, 136, 170, 170),
            ):
                ctk.CTkLabel(row, text=value, width=width, anchor="w",
                             font=ctk.CTkFont(size=11)).pack(side="left", padx=4, pady=3)
        self.after(100, self._poll_results)

    def _save_txt(self) -> None:
        if not self._rows_text:
            return
        fp = filedialog.asksaveasfilename(defaultextension=".txt", initialfile="LanMap_DeepScan_All.txt", filetypes=[("Text", "*.txt")], parent=self)
        if fp:
            Path(fp).write_text(f"LanMap v{APP_VERSION} Deep Scan + SMB Shares Report ({now_str()})\n" + "=" * 115 + "\n" + "\n".join(self._rows_text), encoding="utf-8")
            messagebox.showinfo(APP_NAME, f"Đã lưu báo cáo quét sâu tại:\n{fp}", parent=self)

    def _close(self) -> None:
        self._cancel.set()
        self.destroy()


class ClientSyncDialog(ctk.CTkToplevel):
    """Đồng bộ & Điều khiển LanMap Client (cổng 55124): Xác nhận PIN 1 lần -> mở khóa UltraViewer, CMD & quản trị."""

    def __init__(self, master: ctk.CTk, device: Device, send_file_after_auth: bool = False) -> None:
        super().__init__(master)
        self.title(f"🔗 Đồng bộ & Điều khiển LanMap Client — {device.name} ({device.ip})")
        self.minsize(690, 510)
        self.resizable(True, True)
        self._dev = device
        self._send_file_after_auth = send_file_after_auth
        self._authenticated = False
        self._ctrl_widgets: list[Any] = []
        self.transient(master)

        auth_bar = ctk.CTkFrame(self, corner_radius=8)
        auth_bar.pack(fill="x", padx=14, pady=(12, 6))
        ctk.CTkLabel(auth_bar, text="Mã PIN:", font=ctk.CTkFont(size=12, weight="bold")).pack(side="left", padx=(10, 6), pady=8)
        self.pin_e = ctk.CTkEntry(auth_bar, width=110, show="*")
        self.pin_e.insert(0, "123456")
        self.pin_e.pack(side="left", padx=(0, 8), pady=8)
        self.auth_btn = ctk.CTkButton(auth_bar, text="🔐 Xác nhận PIN (1 lần)", width=165, height=30, fg_color="#0284c7", font=ctk.CTkFont(size=12, weight="bold"), command=self._verify_pin)
        self.auth_btn.pack(side="left", padx=(0, 10), pady=8)
        self.auth_lbl = ctk.CTkLabel(auth_bar, text="🔒 Chưa xác thực PIN", font=ctk.CTkFont(size=11, weight="bold"), text_color="#d97706")
        self.auth_lbl.pack(side="left", padx=4)
        self.pin_e.bind("<Return>", lambda _e: self._verify_pin())

        arow = ctk.CTkFrame(self, fg_color="transparent")
        arow.pack(fill="x", padx=14, pady=(2, 6))
        for txt, col, cb in (
            ("🖥 Điều khiển màn hình", "#dc2626", self._open_remote_desktop),
            ("🔄 CPU/RAM/OS", "#0f766e", lambda: self._call("sysinfo")),
            ("📋 Ứng dụng", "#475569", lambda: self._call("procs")),
            ("📤 Gửi file", "#16a34a", self._send_file_to_client),
            ("💬 Thông báo", "#0284c7", self._send_notice),
            ("🌐 Mở link", "#7c3aed", self._open_url_client),
            ("🔒 Khóa máy", "#b45309", lambda: self._call("lock_screen")),
        ):
            b = ctk.CTkButton(arow, text=txt, height=28, fg_color=col, state="disabled", command=cb)
            b.pack(side="left", fill="x", expand=True, padx=2)
            self._ctrl_widgets.append(b)

        cmd_bar = ctk.CTkFrame(self, fg_color="transparent")
        cmd_bar.pack(fill="x", padx=14, pady=(0, 6))
        ctk.CTkLabel(cmd_bar, text="💻 CMD Client:", font=ctk.CTkFont(size=12, weight="bold")).pack(side="left", padx=(2, 6))
        self.cmd_e = ctk.CTkEntry(cmd_bar, placeholder_text="Nhập lệnh CMD (vd: ipconfig /all, whoami, hostname, dir)...", state="disabled")
        self.cmd_e.pack(side="left", fill="x", expand=True, padx=(0, 6))
        self.cmd_btn = ctk.CTkButton(cmd_bar, text="▶ Chạy CMD", width=98, height=28, fg_color="#0f766e", state="disabled", command=self._run_remote_cmd)
        self.cmd_btn.pack(side="right")
        self.cmd_e.bind("<Return>", lambda _e: self._run_remote_cmd())
        self._ctrl_widgets.extend([self.cmd_e, self.cmd_btn])

        self.box = ctk.CTkTextbox(self, font=ctk.CTkFont(family="Consolas", size=11))
        self.box.pack(fill="both", expand=True, padx=14, pady=(0, 10))
        self.box.insert("1.0", f"Nhập mã PIN khớp với LanMap Client trên {device.ip} rồi bấm '🔐 Xác nhận PIN (1 lần)'.\nMáy Client chỉ cần bấm ĐỒNG Ý 1 lần duy nhất cho cả phiên (chạy CMD, xem & điều khiển màn hình thoải mái).")
        ctk.CTkButton(self, text="Đóng", width=86, command=self.destroy).pack(anchor="e", padx=14, pady=(0, 12))
        _fit_dialog(self, master, 720, 520)

    def _set_unlocked(self, ok: bool, msg: str) -> None:
        self._authenticated = ok
        st = "normal" if ok else "disabled"
        for w in self._ctrl_widgets:
            w.configure(state=st)
        self.auth_lbl.configure(text=msg, text_color="#16a34a" if ok else "#dc2626")

    def _verify_pin(self) -> None:
        pin = self.pin_e.get().strip()
        if not pin:
            self.auth_lbl.configure(text="Vui lòng nhập mã PIN!", text_color="#dc2626")
            return
        self.auth_lbl.configure(text="Đang chờ máy Client đồng ý...", text_color="#0284c7")
        def _w() -> None:
            res = query_lanmap_agent(self._dev.ip, pin, "auth", "", timeout=22.0)
            def _u() -> None:
                if not self.winfo_exists():
                    return
                if res.get("ok"):
                    self._set_unlocked(True, f"✓ Đã ghép nối ({res.get('host', self._dev.ip)})")
                    self.box.delete("1.0", "end")
                    self.box.insert("1.0", str(res.get("report", "✓ Đã cấp quyền phiên điều khiển!")))
                    if self._send_file_after_auth:
                        self._send_file_after_auth = False
                        self.after_idle(self._send_file_to_client)
                else:
                    self._set_unlocked(False, "✕ Sai mã PIN / Client từ chối")
                    self.box.delete("1.0", "end")
                    self.box.insert("1.0", f"✕ {res.get('error', 'Xác thực thất bại.')}")
            self.after(0, _u)
        threading.Thread(target=_w, daemon=True).start()

    def _open_remote_desktop(self) -> None:
        if self._authenticated:
            RemoteDesktopDialog(self, self._dev.ip, self._dev.name, self.pin_e.get().strip())

    def _send_file_to_client(self) -> None:
        if not self._authenticated:
            return
        fp = filedialog.askopenfilename(title="Chọn file muốn gửi qua mạng LAN tới máy Client (tối đa 50 MB)", parent=self)
        if not fp:
            return
        path = Path(fp)
        sz = path.stat().st_size
        if sz > 50 * 1024 * 1024:
            messagebox.showwarning(APP_NAME, "File vượt quá giới hạn 50 MB cho mỗi lần gửi qua LAN.", parent=self)
            return
        self.box.delete("1.0", "end")
        self.box.insert("1.0", f"📤 Đang gửi '{path.name}' ({sz / 1024.0:.1f} KB) tới {self._dev.ip}...")
        pin = self.pin_e.get().strip()
        def _w() -> None:
            try:
                b64 = base64.b64encode(path.read_bytes()).decode("ascii")
                payload = json.dumps({"name": path.name, "b64": b64}, ensure_ascii=False)
                res = query_lanmap_agent(self._dev.ip, pin, "send_file", payload, timeout=30.0)
                txt = str(res.get("report", "✓ Đã gửi file thành công!")) if res.get("ok") else f"✕ Lỗi gửi file: {res.get('error')}"
            except Exception as exc:
                txt = f"✕ Lỗi đọc/gửi file: {exc}"
            self.after(0, lambda: (self.box.delete("1.0", "end"), self.box.insert("1.0", txt)) if self.winfo_exists() else None)
        threading.Thread(target=_w, daemon=True).start()

    def _send_notice(self) -> None:
        txt = simpledialog.askstring("Gửi thông báo tới Client", "Nhập nội dung hiển thị trên màn hình máy trạm:", parent=self)
        if txt and txt.strip():
            self._call("notify", txt.strip())

    def _open_url_client(self) -> None:
        url = simpledialog.askstring("Mở trang web trên máy Client", "Nhập địa chỉ web (vd: https://github.com):", initialvalue="https://", parent=self)
        if url and url.strip():
            self._call("open_url", url.strip())

    def _run_remote_cmd(self) -> None:
        if not self._authenticated:
            return
        cmd_txt = self.cmd_e.get().strip()
        if not cmd_txt:
            return
        self._call("cmd", cmd_txt)

    def _call(self, action: str, payload: str = "") -> None:
        if not self._authenticated:
            return
        pin = self.pin_e.get().strip()
        self.box.delete("1.0", "end")
        self.box.insert("1.0", f"Đang thực thi '{action}' trên {self._dev.ip}...")
        def _w() -> None:
            res = query_lanmap_agent(self._dev.ip, pin, action, payload, timeout=12.0)
            txt = f"✕ Lỗi: {res.get('error', 'Không rõ lỗi')}" if not res.get("ok") else str(res.get("report", ""))
            self.after(0, lambda: (self.box.delete("1.0", "end"), self.box.insert("1.0", txt)) if self.winfo_exists() else None)
        threading.Thread(target=_w, daemon=True).start()


class CameraViewerDialog(ctk.CTkToplevel):
    """Xem Camera IP trực tiếp từ LanMap Server (hỗ trợ Web quản trị, Snapshot HTTP trực tiếp & mở luồng RTSP)."""

    def __init__(self, master: ctk.CTk, device: Device) -> None:
        super().__init__(master)
        self.title(f"📹 Xem Camera IP — {device.name} ({device.ip})")
        self.geometry("760x560")
        self.minsize(640, 480)
        self._dev = device
        self._running = False
        self._photo: Any = None
        self.transient(master)
        self.protocol("WM_DELETE_WINDOW", self._close)

        top = ctk.CTkFrame(self, corner_radius=8)
        top.pack(fill="x", padx=12, pady=(10, 6))
        r1 = ctk.CTkFrame(top, fg_color="transparent")
        r1.pack(fill="x", padx=8, pady=(6, 3))
        ctk.CTkLabel(r1, text="User:", font=ctk.CTkFont(size=11, weight="bold")).pack(side="left", padx=(0, 4))
        self.user_e = ctk.CTkEntry(r1, width=90, height=26)
        self.user_e.insert(0, "admin")
        self.user_e.pack(side="left", padx=(0, 8))
        ctk.CTkLabel(r1, text="Pass:", font=ctk.CTkFont(size=11, weight="bold")).pack(side="left", padx=(0, 4))
        self.pass_e = ctk.CTkEntry(r1, width=100, height=26, show="*")
        self.pass_e.pack(side="left", padx=(0, 8))
        ctk.CTkLabel(r1, text="Đường dẫn ảnh/RTSP:", font=ctk.CTkFont(size=11, weight="bold")).pack(side="left", padx=(0, 4))
        self.path_e = ctk.CTkEntry(r1, height=26)
        self.path_e.insert(0, "/ISAPI/Streaming/channels/101/picture")
        self.path_e.pack(side="left", fill="x", expand=True)

        r2 = ctk.CTkFrame(top, fg_color="transparent")
        r2.pack(fill="x", padx=8, pady=(3, 6))
        ctk.CTkButton(r2, text="▶ Xem ảnh trực tiếp (HTTP Snapshot)", height=28, fg_color="#0f766e", command=self._toggle_stream).pack(side="left", padx=(0, 6))
        ctk.CTkButton(r2, text="🎬 Mở luồng RTSP (VLC / Trình phát)", height=28, fg_color="#0284c7", command=self._open_rtsp).pack(side="left", padx=(0, 6))
        ctk.CTkButton(r2, text="🌐 Mở Web Camera", height=28, fg_color="#475569", command=lambda: webbrowser.open(f"http://{device.ip}")).pack(side="left")
        self.st_lbl = ctk.CTkLabel(r2, text="Sẵn sàng", font=ctk.CTkFont(size=11), text_color="#0284c7")
        self.st_lbl.pack(side="right", padx=6)

        self.canvas = tk.Canvas(self, bg="#0f172a", highlightthickness=0)
        self.canvas.pack(fill="both", expand=True, padx=12, pady=(0, 10))
        self.canvas.create_text(360, 200, text=f"📹 Camera IP: {device.name} ({device.ip})\nBấm 'Xem ảnh trực tiếp' hoặc 'Mở luồng RTSP' phía trên", fill="#94a3b8", font=("Segoe UI", 12, "bold"))

    def _open_rtsp(self) -> None:
        u = self.user_e.get().strip()
        pw = self.pass_e.get().strip()
        auth = f"{u}:{pw}@" if u else ""
        rtsp_url = f"rtsp://{auth}{self._dev.ip}:554/Streaming/Channels/101"
        try:
            webbrowser.open(rtsp_url)
            self.st_lbl.configure(text=f"Đã mở {rtsp_url}")
        except Exception as exc:
            messagebox.showerror(APP_NAME, f"Không mở được RTSP (hãy cài VLC Media Player):\n{rtsp_url}\n{exc}", parent=self)

    def _toggle_stream(self) -> None:
        if self._running:
            self._running = False
            self.st_lbl.configure(text="Đã dừng xem.")
            return
        self._running = True
        self.st_lbl.configure(text="Đang kết nối ảnh Camera...")
        threading.Thread(target=self._loop, daemon=True).start()

    def _loop(self) -> None:
        from PIL import ImageTk  # type: ignore
        u, pw = self.user_e.get().strip(), self.pass_e.get().strip()
        custom_p = self.path_e.get().strip()
        paths = [custom_p, "/cgi-bin/snapshot.cgi", "/snap.jpg", "/image/jpeg.cgi", "/jpg/image.jpg"]
        auth_h = "Basic " + base64.b64encode(f"{u}:{pw}".encode("utf-8")).decode("ascii") if u else ""
        active_url = ""
        while self._running:
            urls = [active_url] if active_url else [f"http://{self._dev.ip}{p}" for p in paths if p]
            got = False
            for url in urls:
                if not self._running:
                    break
                try:
                    req = urllib.request.Request(url, headers={"Authorization": auth_h} if auth_h else {})
                    with urllib.request.urlopen(req, timeout=2.5) as resp:
                        raw = resp.read()
                    pil = Image.open(io.BytesIO(raw))
                    active_url = url
                    cw = max(320, self.canvas.winfo_width() - 8)
                    ch = max(200, self.canvas.winfo_height() - 8)
                    ratio = min(cw / max(1, pil.width), ch / max(1, pil.height))
                    pil = pil.resize((max(100, int(pil.width * ratio)), max(80, int(pil.height * ratio))), Image.Resampling.BILINEAR)
                    def _draw(img_obj=pil, u_ok=url) -> None:
                        if not self.winfo_exists():
                            return
                        self._photo = ImageTk.PhotoImage(img_obj)
                        self.canvas.delete("all")
                        self.canvas.create_image(self.canvas.winfo_width() // 2, self.canvas.winfo_height() // 2, image=self._photo, anchor="center")
                        self.st_lbl.configure(text=f"● LIVE: {u_ok}", text_color="#16a34a")
                    self.after(0, _draw)
                    got = True
                    break
                except Exception:
                    continue
            if not got:
                self.after(0, lambda: self.st_lbl.configure(text="Không lấy được ảnh HTTP (thử nhập đúng User/Pass hoặc bấm Mở luồng RTSP)", text_color="#dc2626") if self.winfo_exists() else None)
                self._running = False
                break
            time.sleep(0.45)

    def _close(self) -> None:
        self._running = False
        self.destroy()


class DeviceDialog(ctk.CTkToplevel):
    def __init__(self, master: ctk.CTk, device: Device | None = None, title: str = "Thêm thiết bị", default_subnet: str = "", default_type: str = TYPE_PC, floors: list[str] | None = None, default_floor: str = DEFAULT_FLOOR) -> None:
        super().__init__(master)
        self.title(title)
        self.minsize(480, 520)
        self.resizable(True, True)
        self._src = device
        self._subnet = default_subnet
        self.result_device: Device | None = None
        self.transient(master)
        self.grab_set()

        bottom = ctk.CTkFrame(self, fg_color="transparent")
        bottom.pack(side="bottom", fill="x", padx=20, pady=(4, 16))
        self.err_lbl = ctk.CTkLabel(bottom, text="", text_color=("#b91c1c", "#f87171"), font=ctk.CTkFont(size=12))
        self.err_lbl.pack(anchor="w", pady=(0, 6))
        brow = ctk.CTkFrame(bottom, fg_color="transparent")
        brow.pack(fill="x")
        ctk.CTkButton(brow, text="Hủy", width=90, height=36, fg_color="transparent", border_width=1, text_color=("gray15", "gray90"), command=self.destroy).pack(side="right", padx=(8, 0))
        ctk.CTkButton(brow, text="Lưu thiết bị", width=136, height=36, font=ctk.CTkFont(size=13, weight="bold"), command=self._save).pack(side="right")

        body = ctk.CTkScrollableFrame(self, fg_color="transparent")
        body.pack(side="top", fill="both", expand=True, padx=18, pady=(12, 4))
        self.name_e = self._entry(body, "Tên thiết bị *")
        self.ip_e = self._entry(body, "Địa chỉ IPv4 (để trống nếu là Switch L2 không IP)")
        self.mac_e = self._entry(body, "Địa chỉ MAC")

        ctk.CTkLabel(body, text="Loại thiết bị", font=ctk.CTkFont(size=12, weight="bold")).pack(anchor="w", pady=(8, 2))
        self.type_var = ctk.StringVar(value=default_type)
        ctk.CTkOptionMenu(body, variable=self.type_var, values=DEVICE_TYPES).pack(fill="x")

        ctk.CTkLabel(body, text="Tầng / Khu vực sơ đồ", font=ctk.CTkFont(size=12, weight="bold")).pack(anchor="w", pady=(8, 2))
        floor_list = [f for f in (floors or [DEFAULT_FLOOR]) if f and f != ALL_FLOORS_LABEL] or [DEFAULT_FLOOR]
        init_floor = (device.floor if device and device.floor in floor_list else (default_floor if default_floor in floor_list else floor_list[0]))
        self.floor_var = ctk.StringVar(value=init_floor)
        ctk.CTkOptionMenu(body, variable=self.floor_var, values=floor_list).pack(fill="x")

        ctk.CTkLabel(body, text="Nhóm", font=ctk.CTkFont(size=12, weight="bold")).pack(anchor="w", pady=(8, 2))
        self.group_cb = ctk.CTkComboBox(body, values=DEFAULT_GROUPS)
        self.group_cb.pack(fill="x")

        self.trusted_var = ctk.BooleanVar(value=True)
        ctk.CTkCheckBox(body, text="Thiết bị tin cậy (đã duyệt)", variable=self.trusted_var).pack(anchor="w", pady=(8, 2))
        self.loc_e = self._entry(body, "Vị trí vật lý")
        self.svc_e = self._entry(body, "Dịch vụ TCP (Tên:Cổng, ví dụ Web:80, Máy in:9100)")
        ctk.CTkLabel(body, text="Ghi chú", font=ctk.CTkFont(size=12, weight="bold")).pack(anchor="w", pady=(8, 2))
        self.notes_t = ctk.CTkTextbox(body, height=68)
        self.notes_t.pack(fill="x")

        if device:
            self.name_e.insert(0, device.name)
            self.ip_e.insert(0, device.ip)
            self.mac_e.insert(0, device.mac)
            self.type_var.set(device.device_type if device.device_type in DEVICE_TYPES else TYPE_PC)
            self.group_cb.set(device.group or "Chung")
            self.trusted_var.set(device.trusted)
            self.loc_e.insert(0, device.location)
            if device.services:
                self.svc_e.insert(0, ", ".join(f"{s.name}:{s.port}" for s in device.services))
            if device.notes:
                self.notes_t.insert("1.0", device.notes)
        else:
            self.group_cb.set("Hạ tầng" if default_type in (TYPE_SWITCH, TYPE_ROUTER, TYPE_WIFI) else "Chung")
        _fit_dialog(self, master, 530, 580)

    def _entry(self, parent: ctk.CTkBaseClass, label: str) -> ctk.CTkEntry:
        ctk.CTkLabel(parent, text=label, font=ctk.CTkFont(size=12, weight="bold")).pack(anchor="w", pady=(8, 2))
        e = ctk.CTkEntry(parent)
        e.pack(fill="x")
        return e

    def _save(self) -> None:
        name, ip, dtype = self.name_e.get().strip(), self.ip_e.get().strip(), self.type_var.get()
        if not name:
            self.err_lbl.configure(text="Vui lòng nhập tên thiết bị.")
            return
        if ip and not _is_valid_ipv4(ip):
            self.err_lbl.configure(text="Địa chỉ IPv4 không hợp lệ.")
            return
        if not ip and dtype not in (TYPE_SWITCH, TYPE_WIFI):
            self.err_lbl.configure(text="Chỉ Switch / Bộ phát L2 mới được để trống IP.")
            return
        svcs: list[ServiceCheck] = []
        try:
            old_map = {s.port: s for s in (self._src.services if self._src else [])}
            for raw in self.svc_e.get().split(","):
                p = raw.strip()
                if not p:
                    continue
                sname, sport = (p.rsplit(":", 1) if ":" in p else (f"Cổng {p}", p))
                port = int(sport.strip())
                old = old_map.get(port)
                svcs.append(ServiceCheck(sname.strip() or f"Cổng {port}", port, old.status if old else STATUS_UNCHECKED, old.last_checked if old else ""))
        except Exception as exc:
            self.err_lbl.configure(text=f"Lỗi dịch vụ TCP: {exc}")
            return
        dev = self._src if self._src else Device(subnet=self._subnet)
        dev.name, dev.ip, dev.mac = name, ip, self.mac_e.get().strip().upper()
        dev.device_type, dev.group, dev.floor, dev.trusted = dtype, self.group_cb.get().strip() or "Chung", self.floor_var.get() or DEFAULT_FLOOR, self.trusted_var.get()
        dev.location, dev.notes, dev.services, dev.registered = self.loc_e.get().strip(), self.notes_t.get("1.0", "end").strip(), svcs, True
        if not ip:
            dev.status = STATUS_ONLINE
        self.result_device = dev
        self.destroy()





