            ev_tr = {"Mất phản hồi": {"en": "Offline", "zh": "离线告警"}, "Cảnh báo ARP": {"en": "ARP Alert", "zh": "ARP 告警"}, "Khôi phục": {"en": "Recovered", "zh": "已恢复"}}.get(rec.event_type, {}).get(self.real_state.language, rec.event_type)
            ctk.CTkLabel(row, text=f"[{rec.timestamp}] {ev_tr}", font=ctk.CTkFont(size=11, weight="bold"), text_color=col, width=196, anchor="w").pack(side="left", padx=6, pady=3)
            ctk.CTkLabel(row, text=f"{self._tr_display_name(rec.device_name)} ({rec.ip}) — {_translate_text_v6(rec.details, self.real_state.language)}", font=ctk.CTkFont(size=11), anchor="w").pack(side="left", fill="x", expand=True, padx=(0, 6))

