# ==============================================================================
# LANMAP v6.0 PRO: CISCO PACKET TRACER LAB + LANBOT COPILOT + WIN TOAST + I18N
# ==============================================================================
import math as _math_v6
import subprocess as _subp_v6
import collections as _coll_v6


def send_windows_toast(title: str, message: str, level: str = "Warning") -> None:
    """Hiển thị thông báo gốc của Windows (Action Center / BalloonTip) chạy nền không hiện cửa sổ CMD."""
    if os.name != "nt":
        return

    def _run() -> None:
        try:
            t_clean = str(title).replace("'", "''").replace("\n", " ")[:120]
            m_clean = str(message).replace("'", "''").replace("\n", " ")[:240]
            icon_kind = level if level in ("Info", "Warning", "Error") else "Warning"
            ps_script = (
                "Add-Type -AssemblyName System.Windows.Forms; "
                "Add-Type -AssemblyName System.Drawing; "
                "$n = New-Object System.Windows.Forms.NotifyIcon; "
                "$n.Icon = [System.Drawing.SystemIcons]::"
                + ("Error" if icon_kind == "Error" else ("Warning" if icon_kind == "Warning" else "Information"))
                + "; "
                "$n.BalloonTipIcon = [System.Windows.Forms.ToolTipIcon]::" + icon_kind + "; "
                f"$n.BalloonTipTitle = '{t_clean}'; "
                f"$n.BalloonTipText = '{m_clean}'; "
                "$n.Visible = $true; "
                "$n.ShowBalloonTip(7000); "
                "Start-Sleep -Seconds 8; "
                "$n.Dispose();"
            )
            si = _subp_v6.STARTUPINFO()
            si.dwFlags |= _subp_v6.STARTF_USESHOWWINDOW
            _subp_v6.Popen(
                ["powershell", "-NoProfile", "-WindowStyle", "Hidden", "-Command", ps_script],
                startupinfo=si,
                creationflags=getattr(_subp_v6, "CREATE_NO_WINDOW", 0x08000000),
                stdout=_subp_v6.DEVNULL,
                stderr=_subp_v6.DEVNULL,
            )
        except Exception:
            pass

    threading.Thread(target=_run, daemon=True).start()


# --- Bảng dịch bổ sung triệt để cho VI / EN / ZH ---
