def _translate_text_v6(text: str, lang: str) -> str:
    if not text:
        return text
    idx = 0 if lang == "vi" else (1 if lang == "en" else 2)
    out = text
    for triple in _EXTRA_I18N_MAP:
        target = triple[idx]
        for i, src_str in enumerate(triple):
            if i != idx and src_str in out:
                out = out.replace(src_str, target)
    return out


def _sync_extra_i18n_v6(app: Any) -> None:
    """Đồng bộ ngôn ngữ cho các Tab đáy, nút + Khung Tầng, Nhật ký sự cố & Canvas."""
    try:
        lang = app.real_state.language
    except Exception:
        return

    def _walk(widget: Any) -> None:
        try:
            cls_name = widget.__class__.__name__
            if cls_name == "CTkSegmentedButton" and hasattr(widget, "_buttons_dict"):
                for _key, btn in widget._buttons_dict.items():
                    try:
                        cur = btn.cget("text")
                        nt = _translate_text_v6(cur, lang)
                        if nt != cur:
                            btn.configure(text=nt)
                    except Exception:
                        pass
            elif cls_name in ("CTkButton", "CTkLabel"):
                try:
                    cur = widget.cget("text")
                    if isinstance(cur, str) and cur:
                        nt = _translate_text_v6(cur, lang)
                        if nt != cur:
                            widget.configure(text=nt)
                except Exception:
                    pass
            for ch in widget.winfo_children():
                _walk(ch)
        except Exception:
            pass

    _walk(app)
    try:
        if hasattr(app, "topology") and app.topology:
            app.topology.redraw()
    except Exception:
        pass


# ==============================================================================
# PHÒNG LAB MÔ PHỎNG MẠNG PRO (CHUẨN CISCO PACKET TRACER)
# ==============================================================================
class NetworkLabDialog(ctk.CTkToplevel):
    """Phòng Lab Mô phỏng Mạng kiểu Cisco Packet Tracer:
    - Icon Router / Switch / PC / Server / AP / Printer vector sắc nét + đèn LED cổng
    - Nối cáp thẳng / cáp chéo / tự động + hiển thị cổng (Gig0/0, Fa0/1...)
    - Chạy đường đi gói tin động (ICMP Ping, DHCP Discover/Offer/Request/Ack)
    - Cấu hình chuẩn Cisco: IP Config (DHCP/Static), CMD Prompt (ping/ipconfig/tracert/arp), Router Interfaces + DHCP Pool + CLI
    - Nạp mạng thật từ LanMap vào Lab để thử nghiệm đổi IP/Subnet an toàn
    - Tích hợp sẵn Máy tính chia Subnet/VLSM & kết nối trực tiếp trợ lý LanBot AI
    """

    def __init__(self, master: ctk.CTk, preset: str | None = None) -> None:
        super().__init__(master)
        self.master_app = master
        self.title("🧪 Phòng Lab Mô phỏng Mạng Pro (Cisco Packet Tracer Mode)")
        self.geometry("1220x740")
        self.minsize(1020, 620)
        self.transient(master)

        self.nodes: dict[str, dict[str, Any]] = {}
        self.links: list[dict[str, Any]] = []  # {a, b, port_a, port_b, cable}
        self.selected: str | None = None
        self.mode: str = "select"  # select | link_auto | link_straight | link_cross | ping_pdu
        self._link_src: str | None = None
        self._ping_src: str | None = None
        self._drag_id: str | None = None
        self._anim_running: bool = False
        self._dark_canvas: bool = False

        # Đăng ký tham chiếu Lab đang mở lên app để LanBot có thể tương tác trực tiếp
        try:
            master._active_lab = self
        except Exception:
            pass

        self._build_ui()
        if preset == "2dept":
            self.load_preset_two_departments()
        elif preset == "real":
            self.import_real_network()
        else:
            self.load_preset_basic()

    def _build_ui(self) -> None:
        # --- Thanh công cụ trên cùng ---
        top = ctk.CTkFrame(self, fg_color="transparent")
        top.pack(fill="x", padx=12, pady=(10, 6))

        # Nhóm thêm thiết bị
        ctk.CTkButton(top, text="+ Router", width=78, fg_color="#0284c7", hover_color="#0369a1",
                      command=lambda: self._add_node("router")).pack(side="left", padx=2)
        ctk.CTkButton(top, text="+ Switch", width=78, fg_color="#0d9488", hover_color="#0f766e",
                      command=lambda: self._add_node("switch")).pack(side="left", padx=2)
        ctk.CTkButton(top, text="+ PC", width=62, fg_color="#2563eb", hover_color="#1d4ed8",
                      command=lambda: self._add_node("pc")).pack(side="left", padx=2)
        ctk.CTkButton(top, text="+ Server", width=74, fg_color="#475569", hover_color="#334155",
                      command=lambda: self._add_node("server")).pack(side="left", padx=2)
        ctk.CTkButton(top, text="+ Wi-Fi AP", width=80, fg_color="#7c3aed", hover_color="#6d28d9",
                      command=lambda: self._add_node("ap")).pack(side="left", padx=2)

        # Nhóm nối cáp chuẩn Cisco
        self.cable_var = ctk.StringVar(value="⚡ Cáp tự động")
        ctk.CTkOptionMenu(
            top, width=142, variable=self.cable_var,
            values=["⚡ Cáp tự động", "━ Cáp thẳng (Straight)", "┄ Cáp chéo (Cross-Over)"],
        ).pack(side="left", padx=(10, 3))
        self.link_btn = ctk.CTkButton(top, text="🔌 Nối dây", width=82, fg_color="#334155", command=self._toggle_link_mode)
        self.link_btn.pack(side="left", padx=2)

        self.pdu_btn = ctk.CTkButton(top, text="✉ Gửi gói Ping", width=112, fg_color="#16a34a", hover_color="#15803d",
                                     command=self._toggle_pdu_mode)
        self.pdu_btn.pack(side="left", padx=(8, 2))

        ctk.CTkButton(top, text="🗑 Xóa", width=62, fg_color="#dc2626", hover_color="#b91c1c",
                      command=self._del_selected).pack(side="left", padx=2)

        # Nhóm tiện ích bên phải
        ctk.CTkButton(top, text="🤖 Hỏi LanBot", width=96, fg_color="#7c3aed", hover_color="#6d28d9",
                      command=self._open_lanbot_from_lab).pack(side="right", padx=2)
        ctk.CTkButton(top, text="🧮 Máy tính Subnet", width=124, fg_color="#0ea5e9", hover_color="#0284c7",
                      command=self._open_subnet_calc).pack(side="right", padx=2)
        ctk.CTkButton(top, text="📥 Nạp mạng thật", width=122, fg_color="#d97706", hover_color="#b45309",
                      command=self.import_real_network).pack(side="right", padx=2)

        # --- Hàng phụ: Mẫu mạng nhanh + Trạng thái chế độ ---
        sub = ctk.CTkFrame(self, fg_color="transparent")
        sub.pack(fill="x", padx=12, pady=(0, 6))
        ctk.CTkLabel(sub, text="Mẫu nhanh:", font=ctk.CTkFont(size=11, weight="bold")).pack(side="left", padx=(0, 4))
        ctk.CTkButton(sub, text="Cơ bản (1 Router + DHCP)", height=24, width=155, fg_color="#475569",
                      command=self.load_preset_basic).pack(side="left", padx=2)
        ctk.CTkButton(sub, text="2 Phòng ban (2 Subnet)", height=24, width=150, fg_color="#475569",
                      command=self.load_preset_two_departments).pack(side="left", padx=2)
        ctk.CTkButton(sub, text="🔄 Xếp gọn sơ đồ", height=24, width=116, fg_color="#64748b",
                      command=self._auto_layout).pack(side="left", padx=4)
        ctk.CTkButton(sub, text="🌓 Nền Sáng/Tối", height=24, width=108, fg_color="#64748b",
                      command=self._toggle_bg).pack(side="left", padx=2)

        self.mode_lbl = ctk.CTkLabel(
            sub, text="Chế độ: Chọn & kéo thiết bị (nhấp đúp để mở cấu hình)",
            font=ctk.CTkFont(size=11), text_color="#0284c7",
        )
        self.mode_lbl.pack(side="right", padx=4)

        # --- Thân chính: Trái = Canvas + Event List, Phải = Bảng cấu hình chuẩn Cisco ---
        main_pane = ctk.CTkFrame(self, fg_color="transparent")
        main_pane.pack(fill="both", expand=True, padx=12, pady=(0, 10))
        main_pane.grid_columnconfigure(0, weight=1)
        main_pane.grid_columnconfigure(1, weight=0)
        main_pane.grid_rowconfigure(0, weight=1)
        main_pane.grid_rowconfigure(1, weight=0)

        # Canvas sơ đồ Lab
        self.canvas = tk.Canvas(main_pane, bg="#f8fafc", highlightthickness=1, highlightbackground="#cbd5e1")
        self.canvas.grid(row=0, column=0, sticky="nsew", padx=(0, 8), pady=(0, 8))
        self.canvas.bind("<Button-1>", self._on_down)
        self.canvas.bind("<B1-Motion>", self._on_drag)
        self.canvas.bind("<ButtonRelease-1>", lambda _e: setattr(self, "_drag_id", None))
        self.canvas.bind("<Configure>", lambda _e: self._redraw())

        # Bảng Event List (Simulation Panel) rộng rãi ở dưới Canvas (thay khung log bé xíu!)
        ev_wrap = ctk.CTkFrame(main_pane, corner_radius=8)
        ev_wrap.grid(row=1, column=0, sticky="ew", padx=(0, 8))
        ev_hdr = ctk.CTkFrame(ev_wrap, fg_color="transparent")
        ev_hdr.pack(fill="x", padx=8, pady=(5, 2))
        ctk.CTkLabel(ev_hdr, text="📡 Nhật ký Mô phỏng Gói tin (Simulation Event List)",
                     font=ctk.CTkFont(size=12, weight="bold")).pack(side="left")
        ctk.CTkButton(ev_hdr, text="Xóa log", width=64, height=22, fg_color="#64748b",
                      command=self._clear_events).pack(side="right")

        self.event_box = ctk.CTkTextbox(ev_wrap, height=118, font=ctk.CTkFont(family="Consolas", size=11))
        self.event_box.pack(fill="x", padx=8, pady=(0, 6))

        # Bảng cấu hình bên phải (rộng 370px, Tab kiểu Cisco Packet Tracer)
        self.side = ctk.CTkFrame(main_pane, width=370, corner_radius=10)
        self.side.grid(row=0, column=1, rowspan=2, sticky="nsew")
        self.side.grid_propagate(False)

        self.cfg_header = ctk.CTkLabel(self.side, text="⚙ Cấu hình Thiết bị (Cisco Mode)",
                                       font=ctk.CTkFont(size=13, weight="bold"))
        self.cfg_header.pack(anchor="w", padx=12, pady=(10, 4))

        self.cfg_body = ctk.CTkFrame(self.side, fg_color="transparent")
        self.cfg_body.pack(fill="both", expand=True, padx=8, pady=(0, 8))

    # --- Helpers quản lý thiết bị & cổng ---
    def _make_mac(self, seed: int) -> str:
        return f"00:0C:29:{(seed * 17) % 256:02X}:{(seed * 43) % 256:02X}:{(seed * 79) % 256:02X}"

    def _default_ports(self, ntype: str) -> dict[str, dict[str, Any]]:
        if ntype == "router":
            return {
                "Gig0/0": {"ip": "192.168.1.1", "mask": "255.255.255.0", "up": True, "dhcp": True, "pool_start": "192.168.1.10", "dns": "8.8.8.8"},
                "Gig0/1": {"ip": "", "mask": "255.255.255.0", "up": False, "dhcp": False, "pool_start": "", "dns": "8.8.8.8"},
                "Gig0/2": {"ip": "", "mask": "255.255.255.0", "up": False, "dhcp": False, "pool_start": "", "dns": "8.8.8.8"},
            }
        if ntype in ("switch", "ap"):
            return {f"Fa0/{i}": {"up": True} for i in range(1, 9)}
        return {"Fa0": {"up": True}}

    def _free_port(self, nid: str) -> str | None:
        node = self.nodes.get(nid)
        if not node:
            return None
        used = set()
        for lk in self.links:
            if lk["a"] == nid:
                used.add(lk["port_a"])
            elif lk["b"] == nid:
                used.add(lk["port_b"])
        for pname in node.get("ports", {}):
            if pname not in used:
                return pname
        # Tự mở thêm cổng cho Switch nếu đã cắm kín
        if node["type"] in ("switch", "ap"):
            new_p = f"Fa0/{len(node['ports']) + 1}"
            node["ports"][new_p] = {"up": True}
            return new_p
        return None

    def _log_event(self, src: str, dst: str, proto: str, status: str, detail: str) -> None:
        ts = time.strftime("%H:%M:%S")
        line = f"[{ts}] {proto:<5} | {src} → {dst} | {status}: {detail}\n"
        self.event_box.insert("end", line)
        self.event_box.see("end")

    def _clear_events(self) -> None:
        self.event_box.delete("1.0", "end")

    def _toggle_bg(self) -> None:
        self._dark_canvas = not self._dark_canvas
        self.canvas.configure(bg="#0f172a" if self._dark_canvas else "#f8fafc")
        self._redraw()

    def _open_subnet_calc(self) -> None:
        # Tự lấy subnet đầu tiên tìm thấy trong Lab
        cidr = "192.168.1.0/24"
        for n in self.nodes.values():
            if n["type"] == "router":
                for p in n["ports"].values():
                    if p.get("ip") and p.get("mask"):
                        try:
                            cidr = str(ipaddress.IPv4Network(f"{p['ip']}/{p['mask']}", strict=False))
                            break
                        except Exception:
                            pass
        if "SubnetCalcDialogV5" in globals():
            SubnetCalcDialogV5(self, cidr)

    def _open_lanbot_from_lab(self) -> None:
        try:
            if hasattr(self.master_app, "lanbot") and self.master_app.lanbot:
                self.master_app.lanbot.open_chat(from_lab=True)
        except Exception:
            pass

