    def _run_lab_action(self, action_id: str, chat_append_fn: Any) -> None:
        if action_id == "open_subnet":
            if "SubnetCalcDialogV5" in globals():
                SubnetCalcDialogV5(self.app, getattr(self.app.real_state, "subnet_cidr", "192.168.1.0/24") or "192.168.1.0/24")
                chat_append_fn("LanBot 😎: Đã mở Máy tính chia Subnet / VLSM cho bạn rồi nhé!")
            return

        lab = getattr(self.app, "_active_lab", None)
        if not lab or not lab.winfo_exists():
            preset = "2dept" if action_id == "lab_2dept" else ("real" if action_id == "lab_real" else "basic")
            lab = NetworkLabDialog(self.app, preset=preset)
            self.app._active_lab = lab
            if action_id == "lab_fix":
                res = lab.auto_fix_lab_issues()
                chat_append_fn(f"LanBot 😎: {res}")
            else:
                chat_append_fn("LanBot 😎: ✅ Đã mở Phòng Lab và áp dụng cấu hình xong! Bạn hãy bấm '✉ Gửi gói Ping' trong Lab để xem đường đi gói tin nhé.")
            return

        lab.lift()
        if action_id == "lab_basic":
            lab.load_preset_basic()
            chat_append_fn("LanBot 😎: ✅ Đã áp dụng mô hình Cơ bản (1 Router DHCP + Switch + 2 PC + Server) vào Phòng Lab!")
        elif action_id == "lab_2dept":
            lab.load_preset_two_departments()
            chat_append_fn("LanBot 😎: ✅ Đã dựng xong mô hình 2 Phòng ban (192.168.10.0/24 & 192.168.20.0/24) trong Phòng Lab! Thử Ping từ PC-KeToan1 sang PC-IT1 nhé.")
        elif action_id == "lab_real":
            lab.import_real_network()
            chat_append_fn("LanBot 😎: ✅ Đã nạp toàn bộ mạng thật của bạn vào Phòng Lab an toàn rồi nhé!")
        elif action_id == "lab_fix":
            res = lab.auto_fix_lab_issues()
            chat_append_fn(f"LanBot 😎: {res}")

    def open_chat(self, from_lab: bool = False) -> None:
        if self._chat_win and self._chat_win.winfo_exists():
            self._chat_win.lift()
            return
        w = ctk.CTkToplevel(self.app)
        self._chat_win = w
        w.title("🤖 LanBot AI — Trợ lý Quản trị Mạng & Phòng Lab Cisco")
        w.geometry("560x540")
        w.transient(self.app)

        # Thanh trên: Bật/tắt Windows Notification + Test thông báo
        top = ctk.CTkFrame(w, fg_color="transparent")
        top.pack(fill="x", padx=12, pady=(8, 4))
        notif_var = ctk.BooleanVar(value=self._win_notify_enabled)

        def _toggle_notif() -> None:
            self._win_notify_enabled = bool(notif_var.get())

        ctk.CTkSwitch(top, text="🔔 Cảnh báo sự cố qua Windows Notification", variable=notif_var, command=_toggle_notif).pack(side="left")
        ctk.CTkButton(
            top, text="Thử thông báo", width=96, height=24, fg_color="#475569",
            command=lambda: send_windows_toast("🤖 LanBot AI — Kiểm tra thông báo", "Thông báo Windows đang hoạt động! Khi có thiết bị rớt mạng mình sẽ báo ngay tại đây.", "Info"),
        ).pack(side="right")

        box = ctk.CTkTextbox(w, font=ctk.CTkFont(size=12), wrap="word")
        box.pack(fill="both", expand=True, padx=12, pady=(4, 6))

        # Thanh nút hành động động (Áp dụng vào Phòng Lab)
        action_bar = ctk.CTkFrame(w, fg_color="transparent")
        action_bar.pack(fill="x", padx=12, pady=(0, 6))

        def _append(text: str) -> None:
            box.insert("end", text + "\n\n")
            box.see("end")

        def _render_actions(actions: list[tuple[str, str]]) -> None:
            for ch in action_bar.winfo_children():
                ch.destroy()
            for lbl, aid in actions:
                ctk.CTkButton(
                    action_bar, text=lbl, height=28, fg_color="#16a34a", hover_color="#15803d",
                    command=lambda a=aid: self._run_lab_action(a, _append),
                ).pack(side="left", padx=3)

        if from_lab:
            _append("LanBot 😎: Mình đang kết nối trực tiếp với Phòng Lab của bạn! Bạn muốn mình hướng dẫn & dựng mô hình 2 phòng ban, nạp mạng thật hay tự động sửa lỗi trùng IP/Gateway?")
            _render_actions([("🏢 Dựng Lab 2 Phòng ban", "lab_2dept"), ("🛠 Sửa lỗi Lab hiện tại", "lab_fix"), ("📥 Nạp mạng thật", "lab_real")])
        else:
            welcome, init_acts = self._analyze_query("xin chào")
            _append("LanBot 😎: " + welcome)
            _render_actions(init_acts)

        # Gợi ý nhanh
        quick = ctk.CTkFrame(w, fg_color="transparent")
        quick.pack(fill="x", padx=12, pady=(0, 6))

        def ask(text: str) -> None:
            q = text.strip()
            if not q:
                return
            _append(f"Bạn: {q}")
            ans, acts = self._analyze_query(q)
            _append(f"LanBot 😎: {ans}")
            _render_actions(acts)

        for label, prompt in [
            ("Lab 2 phòng ban", "Cấu hình mạng 2 phòng ban trong Lab"),
            ("Sửa lỗi Lab", "Sửa lỗi trùng IP trong Lab"),
            ("Firewall chặn?", "Tại sao Firewall chặn Ping?"),
            ("Chia Subnet", "Hướng dẫn chia Subnet VLSM"),
        ]:
            ctk.CTkButton(quick, text=label, height=26, fg_color="#334155", command=lambda p=prompt: ask(p)).pack(side="left", fill="x", expand=True, padx=2)

        row = ctk.CTkFrame(w, fg_color="transparent")
        row.pack(fill="x", padx=12, pady=(0, 10))
        ent = ctk.CTkEntry(row, placeholder_text="Hỏi LanBot về mạng hoặc nhờ cấu hình Phòng Lab...")
        ent.pack(side="left", fill="x", expand=True, padx=(0, 8))

        def _send(_e: Any = None) -> None:
            q = ent.get().strip()
            if q:
                ent.delete(0, "end")
                ask(q)

        ent.bind("<Return>", _send)
        ctk.CTkButton(row, text="Gửi", width=72, command=_send).pack(side="left")



