def _translate_text_v7(text: str, lang: str) -> str:
    if not text or not isinstance(text, str):
        return text
    idx = 0 if lang == "vi" else (1 if lang == "en" else 2)
    out = text
    for triple in _FULL_I18N_V7:
        target = triple[idx]
        for i, src_str in enumerate(triple):
            if i != idx and src_str in out:
                out = out.replace(src_str, target)
    return out


# Giữ tương thích ngược nếu lanmap.py gọi _translate_text_v6
_translate_text_v6 = _translate_text_v7


def _sync_menu_i18n_v7(menu: Any, lang: str) -> None:
    """Dịch đệ quy toàn bộ mục trong Tkinter Menu bar (Công cụ, Trợ giúp, Tệp, Xem...)."""
    try:
        end_idx = menu.index("end")
        if end_idx is None:
            return
        for i in range(end_idx + 1):
            try:
                mtype = menu.type(i)
                if mtype in ("command", "cascade", "checkbutton", "radiobutton"):
                    lbl = menu.entrycget(i, "label")
                    if lbl:
                        nlbl = _translate_text_v7(lbl, lang)
                        if nlbl != lbl:
                            menu.entryconfig(i, label=nlbl)
                if mtype == "cascade":
                    sub_name = menu.entrycget(i, "menu")
                    if sub_name:
                        sub_menu = menu.nametowidget(sub_name)
                        _sync_menu_i18n_v7(sub_menu, lang)
            except Exception:
                pass
    except Exception:
        pass


def _sync_full_i18n_v7(app: Any) -> None:
    """Đồng bộ ngôn ngữ triệt để cho Menu bar + Tab đáy (CTkTabview/CTkSegmentedButton) + Toolbar + Canvas."""
    try:
        lang = app.real_state.language
    except Exception:
        return

    # 1. Dịch toàn bộ Menu bar (Tệp / Sửa / Xem / Công cụ / Ngôn ngữ / Trợ giúp)
    try:
        mbar_name = app.cget("menu")
        if mbar_name:
            mbar = app.nametowidget(mbar_name)
            _sync_menu_i18n_v7(mbar, lang)
    except Exception:
        pass

    # 2. Dịch đệ quy toàn bộ cây widget (bao gồm cả CTkTabview._segmented_button và CTkSegmentedButton)
    def _walk(widget: Any) -> None:
        try:
            cls_name = widget.__class__.__name__
            if cls_name == "CTkTabview" and hasattr(widget, "_segmented_button"):
                _walk(widget._segmented_button)
            if cls_name == "CTkSegmentedButton" and hasattr(widget, "_buttons_dict"):
                for _key, btn in widget._buttons_dict.items():
                    try:
                        cur = btn.cget("text")
                        nt = _translate_text_v7(cur, lang)
                        if nt != cur:
                            btn.configure(text=nt)
                    except Exception:
                        pass
            elif cls_name in ("CTkButton", "CTkLabel", "CTkSwitch"):
                try:
                    cur = widget.cget("text")
                    if isinstance(cur, str) and cur:
                        nt = _translate_text_v7(cur, lang)
                        if nt != cur:
                            widget.configure(text=nt)
                except Exception:
                    pass
            for ch in widget.winfo_children():
                _walk(ch)
        except Exception:
            pass

    _walk(app)
    try:
        if hasattr(app, "topology") and app.topology:
            app.topology._lang_code = lang
            app.topology.redraw()
    except Exception:
        pass


# ==============================================================================
# SỔ TAY PHÂN TÍCH MẠNG HIỆN TẠI (LIVE NETWORK AUDIT — HỌC TỪ NETALERTX & WATCHYOURLAN)
# ==============================================================================
def build_live_network_analysis_text(app: Any) -> tuple[int, str]:
    """Phân tích trực tiếp sơ đồ mạng đang quét: chấm điểm sức khỏe, Client PC, độ trễ, bảo mật & lịch sử vào/ra."""
    st = getattr(app, "real_state", None)
    devs = list(getattr(st, "devices", []) or [])
    incs = list(getattr(st, "incidents", []) or [])
    sub_cidr = getattr(st, "subnet_cidr", "") or "Chưa quét"
    client_ips = getattr(app, "_lanmap_client_ips", set()) or set()
    history = list(getattr(app, "_presence_history", []) or [])

    if not devs:
        return 0, "Chưa có dữ liệu thiết bị trên sơ đồ. Hãy bấm 'Chọn mạng' → 'Quét lại' trước khi phân tích!"

    total = len(devs)
    online_devs = []
    offline_devs = []
    rogue_devs = []
    pc_with_client = []
    pc_no_client = []
    latencies: list[tuple[float, Any]] = []

    for d in devs:
        st_s = str(getattr(d, "status", "") or "").lower()
        is_off = any(w in st_s for w in ("off", "down", "fail", "lost", "alert", "unreach"))
        if is_off:
            offline_devs.append(d)
        else:
            online_devs.append(d)
        if not getattr(d, "trusted", True):
            rogue_devs.append(d)
        dt = str(getattr(d, "device_type", "") or "").lower()
        if dt in ("pc", "computer", "workstation", "laptop", TYPE_PC.lower()):
            has_cl = _device_has_lanmap_client(d, client_ips)
            (pc_with_client if has_cl else pc_no_client).append(d)
        lat = getattr(d, "latency_ms", None)
        if isinstance(lat, (int, float)) and lat >= 0:
            latencies.append((float(lat), d))

    # Tính điểm sức khỏe mạng (0 - 100)
    score = 100
    off_ratio = len(offline_devs) / max(1, total)
    score -= int(off_ratio * 35)
    score -= min(20, len(rogue_devs) * 4)
    arp_alerts = [r for r in incs if "ARP" in str(getattr(r, "event_type", ""))]
    score -= min(25, len(arp_alerts) * 15)
    avg_lat = sum(x[0] for x in latencies) / len(latencies) if latencies else 0.0
    if avg_lat > 100:
        score -= 15
    elif avg_lat > 50:
        score -= 7
    score = max(10, min(100, score))
    grade = "RẤT TỐT (Ổn định)" if score >= 85 else ("KHÁ (Cần chú ý nhẹ)" if score >= 65 else "CẢNH BÁO (Cần kiểm tra ngay!)")

    lines = [
        f"══════════════════════════════════════════════════════════════",
        f"  📊 BÁO CÁO PHÂN TÍCH MẠNG HIỆN TẠI (LANMAP LIVE AUDIT)",
        f"══════════════════════════════════════════════════════════════",
        f"• Dải mạng đang quản lý : {sub_cidr}",
        f"• Điểm sức khỏe mạng    : {score}/100  —  Đánh giá: {grade}",
        f"• Tổng số thiết bị      : {total}  (🟢 Online: {len(online_devs)} | 🔴 Offline/Cảnh báo: {len(offline_devs)})",
        f"• Độ trễ Ping trung bình: {avg_lat:.1f} ms" if latencies else "• Độ trễ Ping trung bình: Chưa có mẫu đo",
        f"• Thiết bị chưa duyệt tin cậy (Lạ): {len(rogue_devs)}",
        f"• Máy tính (PC) đã cài LanMap Client (🔵 Xanh dương): {len(pc_with_client)}",
        f"• Máy tính (PC) CHƯA cài LanMap Client (🟡 Vàng)    : {len(pc_no_client)}",
        "",
    ]

    if offline_devs:
        lines.append("🔴 THIẾT BỊ ĐANG MẤT KẾT NỐI / KHÔNG PHẢN HỒI:")
        for d in offline_devs[:10]:
            lines.append(f"   - {getattr(d, 'name', '')} ({getattr(d, 'ip', '')}) | MAC: {getattr(d, 'mac', 'N/A')}")
        lines.append("")

    if latencies:
        top_lag = sorted(latencies, key=lambda x: x[0], reverse=True)[:5]
        lines.append("⏱ TOP THIẾT BỊ CÓ ĐỘ TRỄ PING CAO NHẤT:")
        for ms, d in top_lag:
            flag = " ⚠ (Lag cao)" if ms > 80 else ""
            lines.append(f"   - {getattr(d, 'name', '')} ({getattr(d, 'ip', '')}): {ms:.0f} ms{flag}")
        lines.append("")

    if pc_no_client:
        lines.append("🟡 CÁC MÁY TÍNH CHƯA CÀI LANMAP CLIENT (Nên cài để Ping chéo, CMD, UltraViewer):")
        for d in pc_no_client[:10]:
            lines.append(f"   - {getattr(d, 'name', '')} ({getattr(d, 'ip', '')})")
        lines.append("")

    if history:
        lines.append("🕒 LỊCH SỬ THIẾT BỊ VÀO / RA MẠNG (PRESENCE HISTORY):")
        for item in history[-12:]:
            lines.append(f"   - {item}")
        lines.append("")

    lines.append("💡 KHUYẾN NGHỊ TỐI ƯU HÓA TỰ ĐỘNG:")
    if arp_alerts:
        lines.append("1. [KHẨN] Có cảnh báo đổi MAC Gateway (ARP Spoofing). Kiểm tra ngay Router & bật DAI!")
    if rogue_devs:
        lines.append(f"2. Xác minh {len(rogue_devs)} thiết bị lạ (chấm vàng): quen thì bấm 'Duyệt Tin cậy', lạ thì chặn MAC trên Router.")
    if pc_no_client:
        lines.append(f"3. Cài LanMap Client lên {len(pc_no_client)} máy PC màu vàng để chuyển sang màu Xanh dương và mở khóa Ping chéo + điều khiển từ xa.")
    if avg_lat > 60:
        lines.append("4. Độ trễ trung bình đang hơi cao — mở 'Phân tích Sóng Wi-Fi' để đổi sang kênh phát ít nhiễu hơn.")
    if not arp_alerts and not rogue_devs and not offline_devs:
        lines.append("• Hạ tầng mạng hiện tại rất sạch và ổn định! Tiếp tục duy trì chế độ Giám sát nền + Thông báo Windows.")

    return score, "\n".join(lines)


def _device_has_lanmap_client(dev: Any, client_ips: set[str] | None = None) -> bool:
    if not dev:
        return False
    if str(getattr(dev, "vendor", "")).startswith("LanMap Client ("):
        return True
    if getattr(dev, "agent_installed", False):
        return True
    ip = str(getattr(dev, "ip", "") or "")
    if client_ips and ip in client_ips:
        return True
    blob = f"{getattr(dev, 'notes', '')} {getattr(dev, 'model', '')} {getattr(dev, 'name', '')}".lower()
    return ("lanmap client" in blob) or ("lanclient" in blob) or ("[client]" in blob)


# ==============================================================================
# NÂNG CẤP SƠ ĐỒ THẬT: MÀU PC (XANH DƯƠNG/VÀNG) + PING BỨC THƯ 2 MÁY + GỘP TÔ MÀU
# ==============================================================================
def _install_real_topology_upgrades_v7(app: Any) -> None:
    """Gắn các nâng cấp v7.0 vào cửa sổ chính LanMapApp:
    - Phân biệt màu PC: Có LanMap Client = Xanh dương (#2563eb), Chưa cài = Vàng (#eab308)
    - Ping Con trỏ Bức thư (✉) chọn 2 máy bất kỳ trên sơ đồ thật (máy cài Client tự Ping máy đích!)
    - Gộp nút 'Tô màu' vào trong menu 'Vẽ'
    - Thêm mục 'Phân tích & Đánh giá Mạng hiện tại' vào menu Trợ giúp
    """
    if getattr(app, "_v7_installed", False):
        return
    app._v7_installed = True
    app._lanmap_client_ips = set()
    app._presence_history = []
    app._real_ping_mode = False
    app._real_ping_src = None
    app._client_pin_cache = {}

    topo = getattr(app, "topology", None)
    # Tìm tk.Canvas thật bên trong TopologyCanvas
    t_canvas = topo if isinstance(topo, tk.Canvas) else getattr(topo, "canvas", None)

    # --- 1. Bọc redraw() để tô màu PC Xanh dương (có Client) / Vàng (chưa cài Client) ---
    if topo and t_canvas and hasattr(topo, "redraw"):
        orig_redraw = topo.redraw

        def _v7_redraw(*args: Any, **kwargs: Any) -> Any:
            res = orig_redraw(*args, **kwargs)
            try:
                _paint_client_pc_colors_v7(app, topo, t_canvas)
            except Exception:
                pass
            return res

        topo.redraw = _v7_redraw

    # --- 2. Gắn Con trỏ Bức thư (✉) & Ping 2 máy bất kỳ trên sơ đồ thật ---
    if topo and t_canvas:
        def _draw_envelope_cursor(mx: float, my: float) -> None:
            t_canvas.delete("v7_env_cursor")
            if not app._real_ping_mode:
                return
            x, y = mx + 16, my - 16
            t_canvas.create_rectangle(x - 13, y - 9, x + 13, y + 9, fill="#fef08a", outline="#0284c7", width=1.8, tags="v7_env_cursor")
            t_canvas.create_line(x - 13, y - 9, x, y + 1, x + 13, y - 9, fill="#0284c7", width=1.6, tags="v7_env_cursor")
            hint = "Chọn máy ĐÍCH" if app._real_ping_src else "Chọn máy NGUỒN"
            t_canvas.create_text(x + 2, y + 18, text=hint, fill="#0284c7", font=("Segoe UI", 8, "bold"), tags="v7_env_cursor")

        def _find_real_dev_at(mx: float, my: float) -> Any:
            devs = list(getattr(getattr(app, "real_state", None), "devices", []) or [])
            best, best_d = None, 42.0
            for d in devs:
                sx, sy = _topo_world_to_screen(topo, getattr(d, "x", 0), getattr(d, "y", 0))
                dist = _math_v7.hypot(sx - mx, sy - my)
                if dist < best_d:
                    best, best_d = d, dist
            return best

        def _on_real_motion(e: tk.Event) -> None:
            if app._real_ping_mode:
                _draw_envelope_cursor(e.x, e.y)

        def _on_real_click(e: tk.Event) -> str | None:
            if not app._real_ping_mode:
                return None
            dev = _find_real_dev_at(e.x, e.y)
            if not dev:
                return "break"
            if app._real_ping_src is None:
                app._real_ping_src = dev
                _draw_envelope_cursor(e.x, e.y)
                if hasattr(app, "lanbot") and app.lanbot:
                    app.lanbot.show_bubble(f"✉ Đã chọn nguồn: {dev.name} ({dev.ip})\n👉 Bấm vào máy ĐÍCH để gửi gói Ping!", 5000)
                return "break"
            src_dev = app._real_ping_src
            dst_dev = dev
            app._real_ping_mode = False
            app._real_ping_src = None
            t_canvas.delete("v7_env_cursor")
            t_canvas.configure(cursor="")
            if src_dev.id != dst_dev.id:
                _execute_real_two_node_ping_v7(app, topo, t_canvas, src_dev, dst_dev)
            return "break"

        def _on_real_esc(_e: tk.Event) -> None:
            if app._real_ping_mode:
                app._real_ping_mode = False
                app._real_ping_src = None
                t_canvas.delete("v7_env_cursor")
                t_canvas.configure(cursor="")

        t_canvas.bind("<Motion>", _on_real_motion, add="+")
        t_canvas.bind("<Button-1>", _on_real_click, add="+")
        app.bind("<Escape>", _on_real_esc, add="+")

    def _toggle_real_envelope_ping() -> None:
        if not t_canvas:
            return
        app._real_ping_mode = not app._real_ping_mode
        app._real_ping_src = None
        if app._real_ping_mode:
            t_canvas.configure(cursor="tcross")
            if hasattr(app, "lanbot") and app.lanbot:
                app.lanbot.show_bubble("✉ Chế độ Ping Bức thư đã BẬT!\nBấm chọn máy NGUỒN → máy ĐÍCH (hỗ trợ Ping chéo giữa 2 máy có LanMap Client!).", 6000)
        else:
            t_canvas.delete("v7_env_cursor")
            t_canvas.configure(cursor="")

    app._toggle_real_envelope_ping = _toggle_real_envelope_ping

    # --- 3. Gắn nút '▶ Ping' trên toolbar vào Chế độ Bức thư + Gộp nút 'Tô màu' vào menu 'Vẽ' ---
    def _patch_toolbar_widgets() -> None:
        fill_btn = None
        draw_widget = None
        ping_btn = None

        def _scan(w: Any) -> None:
            nonlocal fill_btn, draw_widget, ping_btn
            try:
                cls = w.__class__.__name__
                if cls == "CTkButton":
                    txt = str(w.cget("text") or "")
                    if "Tô màu" in txt or "Fill" in txt or "填充" in txt:
                        fill_btn = w
                    elif "▶ Ping" in txt or txt.strip() == "Ping":
                        ping_btn = w
                elif cls == "CTkOptionMenu":
                    vals = list(w.cget("values") or [])
                    if any("Vẽ" in str(v) or "Chữ nhật" in str(v) or "Draw" in str(v) or "绘图" in str(v) for v in vals):
                        draw_widget = w
                for ch in w.winfo_children():
                    _scan(ch)
            except Exception:
                pass

        _scan(app)
        if ping_btn:
            try:
                ping_btn.configure(command=_toggle_real_envelope_ping)
            except Exception:
                pass

        # Gộp 'Tô màu' vào trong dropdown 'Vẽ' và ẩn nút 'Tô màu' thừa bên ngoài
        if fill_btn and draw_widget:
            try:
                fill_cmd = fill_btn.cget("command")
                orig_vals = list(draw_widget.cget("values") or [])
                orig_cmd = draw_widget.cget("command")
                if "🎨 Tô màu (Fill)" not in orig_vals:
                    orig_vals.append("🎨 Tô màu (Fill)")
                    draw_widget.configure(values=orig_vals)

                    def _wrapped_draw_cmd(choice: str) -> None:
                        if "Tô màu" in choice or "Fill" in choice:
                            if callable(fill_cmd):
                                fill_cmd()
                        elif callable(orig_cmd):
                            orig_cmd(choice)

                    draw_widget.configure(command=_wrapped_draw_cmd)
                fill_btn.pack_forget()
                fill_btn.grid_forget()
            except Exception:
                pass

    app.after(600, _patch_toolbar_widgets)

    # --- 4. Thêm 'Sổ tay Phân tích Mạng hiện tại' vào menu Trợ giúp ---
    def _inject_help_analysis_menu() -> None:
        try:
            mbar_name = app.cget("menu")
            if not mbar_name:
                return
            mbar = app.nametowidget(mbar_name)
            end_i = mbar.index("end")
            if end_i is None:
                return
            # Menu Trợ giúp luôn nằm cuối cùng trên thanh menu
            sub_name = mbar.entrycget(end_i, "menu")
            if not sub_name:
                return
            m_help = mbar.nametowidget(sub_name)
            # Kiểm tra tránh thêm trùng
            h_end = m_help.index("end") or 0
            exists = any("Phân tích" in str(m_help.entrycget(i, "label") or "") or "Live Network Analysis" in str(m_help.entrycget(i, "label") or "") for i in range(h_end + 1) if m_help.type(i) == "command")
            if not exists:
                def _open_live_audit() -> None:
                    _sc, report = build_live_network_analysis_text(app)
                    if "show_scrollable_guide" in globals():
                        show_scrollable_guide(app, "📊 Sổ tay Phân tích & Đánh giá Mạng hiện tại", report)
                    else:
                        messagebox.showinfo("Phân tích Mạng hiện tại", report)

                m_help.insert_command(0, label="📊 Phân tích & Đánh giá Mạng hiện tại...", command=_open_live_audit)
        except Exception:
            pass

    app.after(700, _inject_help_analysis_menu)

    # --- 5. Quét UDP Beacon LanMap Client nền để tô PC Xanh dương tự động ---
    def _poll_client_beacons() -> None:
        if not app.winfo_exists():
            return

        def _bg() -> None:
            try:
                if "discover_lanmap_clients_udp" in globals():
                    found = discover_lanmap_clients_udp(0.7)
                    if found:
                        changed = False
                        for cip, info in found.items():
                            if cip not in app._lanmap_client_ips:
                                app._lanmap_client_ips.add(cip)
                                changed = True
                            for d in getattr(getattr(app, "real_state", None), "devices", []) or []:
                                if getattr(d, "ip", "") == cip:
                                    try:
                                        d.agent_installed = True
                                    except Exception:
                                        pass
                        if changed and topo and hasattr(topo, "redraw"):
                            app.after(0, topo.redraw)
            except Exception:
                pass

        threading.Thread(target=_bg, daemon=True).start()
        app.after(15000, _poll_client_beacons)

    app.after(1800, _poll_client_beacons)


def _topo_world_to_screen(topo: Any, wx: float, wy: float) -> tuple[float, float]:
    if hasattr(topo, "_world_to_screen"):
        try:
            return topo._world_to_screen(wx, wy)
        except Exception:
            pass
    if hasattr(topo, "world_to_screen"):
        try:
            return topo.world_to_screen(wx, wy)
        except Exception:
            pass
    zoom = float(getattr(topo, "zoom", getattr(topo, "_zoom", 1.0)) or 1.0)
    ox = float(getattr(topo, "offset_x", getattr(topo, "pan_x", getattr(topo, "_pan_x", 0.0))) or 0.0)
    oy = float(getattr(topo, "offset_y", getattr(topo, "pan_y", getattr(topo, "_pan_y", 0.0))) or 0.0)
    return wx * zoom + ox, wy * zoom + oy


def _paint_client_pc_colors_v7(app: Any, topo: Any, canvas: tk.Canvas) -> None:
    """Vẽ phủ màu PC phân biệt: Có LanMap Client = Xanh dương (#2563eb), Chưa cài = Vàng (#eab308)."""
    canvas.delete("v7_pc_color")
    devs = topo._visible_devices
    client_ips = getattr(app, "_lanmap_client_ips", set()) or set()
    s = max(0.24, min(1.5, topo.scale))
    width, height = canvas.winfo_width(), canvas.winfo_height()

    for d in devs:
        dt = str(getattr(d, "device_type", "") or "").lower()
        name_l = str(getattr(d, "name", "") or "").lower()
        # Chỉ áp dụng cho PC/Laptop (bỏ qua Máy này màu xanh lá)
        if dt not in ("pc", "computer", "workstation", "laptop", TYPE_PC.lower()):
            continue
        if "máy này" in name_l or "this pc" in name_l or "本机" in name_l:
            continue
        sx, sy = _topo_world_to_screen(topo, getattr(d, "x", 0), getattr(d, "y", 0))
        if not (-50 <= sx <= width + 50 and -50 <= sy <= height + 50):
            continue
        has_cl = _device_has_lanmap_client(d, client_ips)
        fill_col = "#2563eb" if has_cl else "#eab308"
        rim_col = "#1d4ed8" if has_cl else "#a16207"
        # Màn hình PC gọn đẹp đúng vị trí icon
        w2, h2 = 17 * s, 12 * s
        canvas.create_rectangle(sx - w2, sy - h2 - 2 * s, sx + w2, sy + h2 - 4 * s,
                                fill=fill_col, outline=rim_col, width=1.8, tags="v7_pc_color")
        canvas.create_rectangle(sx - 4 * s, sy + h2 - 4 * s, sx + 4 * s, sy + h2 + 1 * s,
                                fill="#64748b", outline="", tags="v7_pc_color")
        canvas.create_rectangle(sx - 10 * s, sy + h2 + 1 * s, sx + 10 * s, sy + h2 + 4 * s,
                                fill="#475569", outline="", tags="v7_pc_color")
        if has_cl and s >= 0.45:
            # Huy hiệu nhỏ 'C' xác nhận đã cài LanMap Client
            canvas.create_oval(sx + w2 - 6 * s, sy - h2 - 6 * s, sx + w2 + 5 * s, sy - h2 + 5 * s,
                               fill="#16a34a", outline="#ffffff", width=1, tags="v7_pc_color")
            canvas.create_text(sx + w2 - 0.5 * s, sy - h2 - 0.5 * s, text="C",
                               fill="#ffffff", font=("Segoe UI", max(6, int(7 * s)), "bold"), tags="v7_pc_color")

    # Chú thích nhỏ ở góc trên phải canvas (dùng chiều rộng cache để kéo mượt không khựng)
    try:
        cw = max(400, int(getattr(app, "_v8_cached_cw", 0) or canvas.winfo_width()))
        canvas.create_rectangle(cw - 246, 8, cw - 10, 32, fill="#ffffff", outline="#cbd5e1", tags="v7_pc_color")
        canvas.create_rectangle(cw - 238, 15, cw - 226, 25, fill="#2563eb", outline="#1d4ed8", tags="v7_pc_color")
        canvas.create_text(cw - 178, 20, text="PC có Client", fill="#1e293b", font=("Segoe UI", 8, "bold"), tags="v7_pc_color")
        canvas.create_rectangle(cw - 124, 15, cw - 112, 25, fill="#eab308", outline="#a16207", tags="v7_pc_color")
        canvas.create_text(cw - 60, 20, text="PC chưa cài", fill="#1e293b", font=("Segoe UI", 8, "bold"), tags="v7_pc_color")
    except Exception:
        pass


def _execute_real_two_node_ping_v7(app: Any, topo: Any, canvas: tk.Canvas, src_dev: Any, dst_dev: Any) -> None:
    """Thực hiện Ping thật giữa 2 máy bất kỳ trên sơ đồ thật (hỗ trợ Ping chéo qua LanMap Client) + hoạt ảnh bức thư bay."""
    src_name, src_ip = getattr(src_dev, "name", ""), getattr(src_dev, "ip", "")
    dst_name, dst_ip = getattr(dst_dev, "name", ""), getattr(dst_dev, "ip", "")
    client_ips = getattr(app, "_lanmap_client_ips", set()) or set()

    is_local = (
        str(getattr(src_dev, "device_type", "")).lower() == "this_pc"
        or "máy này" in src_name.lower()
        or "this pc" in src_name.lower()
        or "本机" in src_name.lower()
    )
    has_client = _device_has_lanmap_client(src_dev, client_ips)

    # Xác định đường đi hoạt ảnh (src -> gateway -> dst)
    devs = list(getattr(getattr(app, "real_state", None), "devices", []) or [])
    gw = next((d for d in devs if str(getattr(d, "device_type", "")).lower() == "router" or "gateway" in str(getattr(d, "name", "")).lower()), None)
    pts = [_topo_world_to_screen(topo, getattr(src_dev, "x", 0), getattr(src_dev, "y", 0))]
    if gw and gw.id not in (src_dev.id, dst_dev.id):
        pts.append(_topo_world_to_screen(topo, getattr(gw, "x", 0), getattr(gw, "y", 0)))
    pts.append(_topo_world_to_screen(topo, getattr(dst_dev, "x", 0), getattr(dst_dev, "y", 0)))

    def _animate_real_mail(ok: bool, summary: str) -> None:
        pkt_r = canvas.create_rectangle(0, 0, 0, 0, fill="#2563eb", outline="#ffffff", width=2, tags="v7_real_pkt")
        pkt_t = canvas.create_text(0, 0, text="✉ PING", fill="#ffffff", font=("Segoe UI", 8, "bold"), tags="v7_real_pkt")

        def _move(path_pts: list[tuple[float, float]], hop: int, step: int, is_reply: bool) -> None:
            if hop >= len(path_pts) - 1:
                if not is_reply and ok:
                    canvas.itemconfig(pkt_r, fill="#16a34a")
                    canvas.itemconfig(pkt_t, text="✉ OK!")
                    _move(list(reversed(path_pts)), 0, 0, True)
                else:
                    if not ok:
                        ex, ey = path_pts[-1]
                        err = canvas.create_text(ex, ey - 26, text="✖ KHÔNG THÔNG", fill="#ef4444", font=("Segoe UI", 9, "bold"), tags="v7_real_pkt")
                        app.after(1400, lambda: (canvas.delete(pkt_r), canvas.delete(pkt_t), canvas.delete(err)))
                    else:
                        app.after(300, lambda: (canvas.delete(pkt_r), canvas.delete(pkt_t)))
                    if hasattr(app, "lanbot") and app.lanbot:
                        app.lanbot.show_bubble(summary, 7500)
                return
            x1, y1 = path_pts[hop]
            x2, y2 = path_pts[hop + 1]
            t = step / 16.0
            cx, cy = x1 + (x2 - x1) * t, y1 + (y2 - y1) * t
            canvas.coords(pkt_r, cx - 24, cy - 11, cx + 24, cy + 11)
            canvas.coords(pkt_t, cx, cy)
            if step < 16:
                app.after(20, lambda: _move(path_pts, hop, step + 1, is_reply))
            else:
                app.after(20, lambda: _move(path_pts, hop + 1, 0, is_reply))

        _move(pts, 0, 0, False)

    if is_local:
        def _bg_local() -> None:
            try:
                si = _subp_v7.STARTUPINFO() if os.name == "nt" else None
                if si:
                    si.dwFlags |= _subp_v7.STARTF_USESHOWWINDOW
                p = _subp_v7.run(
                    ["ping", "-n" if os.name == "nt" else "-c", "2", "-w" if os.name == "nt" else "-W", "1000", dst_ip],
                    capture_output=True, text=True, timeout=6,
                    startupinfo=si,
                    creationflags=getattr(_subp_v7, "CREATE_NO_WINDOW", 0) if os.name == "nt" else 0,
                )
                ok = (p.returncode == 0) and ("TTL=" in p.stdout.upper() or "time=" in p.stdout.lower() or "time<" in p.stdout.lower())
                m_ms = re.search(r"time[=<]\s*(\d+)\s*ms", p.stdout, re.I)
                ms_txt = f"{m_ms.group(1)} ms" if m_ms else "<1 ms"
                msg = f"✅ Ping {src_name} → {dst_name} ({dst_ip}): THÔNG SUỐT ({ms_txt})!" if ok else f"✖ Ping {src_name} → {dst_name} ({dst_ip}): Không phản hồi (Tắt máy hoặc Firewall chặn ICMP)."
                app.after(0, lambda: _animate_real_mail(ok, msg))
            except Exception as exc:
                app.after(0, lambda: _animate_real_mail(False, f"Lỗi Ping: {exc}"))

        threading.Thread(target=_bg_local, daemon=True).start()
        return

    if not has_client:
        if messagebox.askyesno(
            "Máy nguồn chưa cài LanMap Client",
            f"Máy nguồn '{src_name}' ({src_ip}) hiện chưa cài LanMap Client (PC màu vàng) nên Server không thể ra lệnh máy đó tự Ping sang '{dst_name}'.\n\nBạn có muốn Ping trực tiếp từ Máy này tới '{dst_name}' ({dst_ip}) thay thế không?",
        ):
            _execute_real_two_node_ping_v7(app, topo, canvas, next((d for d in devs if "máy này" in str(getattr(d, "name", "")).lower()), src_dev), dst_dev)
        return

    # Ping từ máy trạm A (có LanMap Client) → máy đích B!
    pin = app._client_pin_cache.get(src_ip)
    if not pin:
        dlg = ctk.CTkInputDialog(text=f"Nhập mã PIN của LanMap Client trên máy nguồn {src_name} ({src_ip}):", title="Ping chéo qua LanMap Client")
        pin = (dlg.get_input() or "").strip()
        if not pin:
            return
        app._client_pin_cache[src_ip] = pin

    def _bg_remote_ping() -> None:
        try:
            if "query_lanmap_agent" not in globals():
                app.after(0, lambda: _animate_real_mail(False, "Chưa tìm thấy hàm kết nối LanMap Client trong phiên bản này."))
                return
            res = query_lanmap_agent(src_ip, pin, "cmd", f"ping -n 2 -w 1000 {dst_ip}")
            out = str((res or {}).get("output") or (res or {}).get("message") or (res or {}).get("error") or "")
            ok = bool(res and res.get("ok") and ("TTL=" in out.upper() or "time=" in out.lower() or "time<" in out.lower()))
            m_ms = re.search(r"time[=<]\s*(\d+)\s*ms", out, re.I)
            ms_txt = f"{m_ms.group(1)} ms" if m_ms else ""
            if ok:
                msg = f"✅ Ping chéo (Client) {src_name} → {dst_name} ({dst_ip}): THÔNG SUỐT {ms_txt}!"
            else:
                reason = out.strip()[:120] or "Không phản hồi / sai PIN / máy trạm chưa duyệt phiên"
                msg = f"✖ Ping chéo {src_name} → {dst_name}: Thất bại ({reason})"
            app.after(0, lambda: _animate_real_mail(ok, msg))
        except Exception as exc:
            app.after(0, lambda: _animate_real_mail(False, f"Lỗi Ping chéo qua Client: {exc}"))

    threading.Thread(target=_bg_remote_ping, daemon=True).start()


# ==============================================================================
# PHÒNG LAB MÔ PHỎNG MẠNG PRO v7.0 (THÊM ĐIỆN THOẠI WI-FI + CON TRỎ BỨC THƯ ✉)
