        ctk.CTkButton(top, text="🧮 Subnet", width=84, fg_color="#0ea5e9", hover_color="#0284c7",
                      command=self._open_subnet_calc).pack(side="right", padx=2)
        ctk.CTkButton(top, text="📥 Nạp mạng thật", width=116, fg_color="#d97706", hover_color="#b45309",
                      command=self.import_real_network).pack(side="right", padx=2)

        sub = ctk.CTkFrame(self, fg_color="transparent")
