        ctk.CTkButton(sub, text="Cơ bản (Router + Wi-Fi + ĐT)", height=24, width=176, fg_color="#475569",
                      command=self.load_preset_basic).pack(side="left", padx=2)
        ctk.CTkButton(sub, text="2 Phòng ban (2 Subnet)", height=24, width=148, fg_color="#475569",
                      command=self.load_preset_two_departments).pack(side="left", padx=2)
        ctk.CTkButton(sub, text="🔄 Xếp gọn", height=24, width=84, fg_color="#64748b",
                      command=self._auto_layout).pack(side="left", padx=4)
