import math as _math_v8
import subprocess as _subp_v8
import urllib.request as _urlreq_v8
import json as _json_v8


# --- 1. Camera Viewer Pro v8.0 (RTSP over TCP + Chọn hãng + Snapshot + VLC/Web) ---
_CAMERA_PRESETS_V8: dict[str, str] = {
    "Hikvision / HiLook (RTSP 101)": "rtsp://{user}:{pwd}@{ip}:554/Streaming/Channels/101",
    "Dahua / KBVision / Imou (RTSP)": "rtsp://{user}:{pwd}@{ip}:554/cam/realmonitor?channel=1&subtype=0",
    "TP-Link Tapo / Vigi (RTSP)": "rtsp://{user}:{pwd}@{ip}:554/stream1",
    "Ezviz (RTSP H.264)": "rtsp://{user}:{pwd}@{ip}:554/h264_stream",
    "Yoosee / ONVIF chuẩn (RTSP)": "rtsp://{user}:{pwd}@{ip}:554/onvif1",
    "HTTP Snapshot (Ảnh tĩnh JPEG)": "http://{user}:{pwd}@{ip}/snapshot.jpg",
}


class CameraViewerDialog(ctk.CTkToplevel):
    """Trình xem Camera IP Pro: hỗ trợ RTSP (OpenCV TCP), HTTP Snapshot, chọn hãng, chụp ảnh & mở VLC/Web."""

    def __init__(self, master: ctk.CTk, device: Any) -> None:
        super().__init__(master)
        self.device = device
        self.ip = str(getattr(device, "ip", "") or "")
        self.name = str(getattr(device, "name", "Camera IP") or "Camera IP")
        self.title(f"📹 Xem Camera IP Pro — {self.name} ({self.ip})")
        self.geometry("820x610")
        self.minsize(720, 520)
        self.transient(master)

        self._running = False
        self._cap = None
        self._last_pil = None
        self._img_tk = None
        self.protocol("WM_DELETE_WINDOW", self._close)

        # Thanh cấu hình hãng + User/Pass
        top1 = ctk.CTkFrame(self, fg_color="transparent")
        top1.pack(fill="x", padx=12, pady=(10, 4))
        ctk.CTkLabel(top1, text="Hãng / Chuẩn:", font=ctk.CTkFont(size=11, weight="bold")).pack(side="left", padx=(0, 4))
        self.preset_var = ctk.StringVar(value=list(_CAMERA_PRESETS_V8.keys())[0])
        ctk.CTkOptionMenu(top1, width=230, values=list(_CAMERA_PRESETS_V8.keys()), variable=self.preset_var,
                          command=self._apply_preset).pack(side="left", padx=(0, 8))

        ctk.CTkLabel(top1, text="User:").pack(side="left", padx=(4, 2))
        self.user_e = ctk.CTkEntry(top1, width=82)
        self.user_e.insert(0, "admin")
        self.user_e.pack(side="left", padx=(0, 6))

        ctk.CTkLabel(top1, text="Pass:").pack(side="left", padx=(2, 2))
        self.pwd_e = ctk.CTkEntry(top1, width=110, show="*")
        self.pwd_e.pack(side="left", padx=(0, 6))

        ctk.CTkButton(top1, text="Cập nhật URL", width=96, fg_color="#475569", command=self._apply_preset).pack(side="left")

        top2 = ctk.CTkFrame(self, fg_color="transparent")
        top2.pack(fill="x", padx=12, pady=(0, 6))
        self.url_e = ctk.CTkEntry(top2, placeholder_text="rtsp://admin:password@192.168.1.105:554/Streaming/Channels/101")
        self.url_e.pack(side="left", fill="x", expand=True, padx=(0, 6))
        self.play_btn = ctk.CTkButton(top2, text="▶ Phát luồng", width=102, fg_color="#16a34a", command=self._toggle_stream)
        self.play_btn.pack(side="left", padx=2)
        ctk.CTkButton(top2, text="📸 Chụp ảnh", width=92, fg_color="#0284c7", command=self._save_snapshot).pack(side="left", padx=2)
        ctk.CTkButton(top2, text="🌐 Web Cam", width=84, fg_color="#d97706", command=self._open_web_cam).pack(side="left", padx=2)
        ctk.CTkButton(top2, text="🎬 Mở VLC", width=80, fg_color="#ea580c", command=self._open_vlc).pack(side="left", padx=2)

        self.status_lbl = ctk.CTkLabel(
            self,
            text="💡 Nhập User/Pass (thường in dưới đáy Camera), chọn đúng hãng rồi bấm '▶ Phát luồng' (hoặc '🌐 Web Cam').",
            font=ctk.CTkFont(size=11), text_color="#0284c7",
        )
        self.status_lbl.pack(anchor="w", padx=14, pady=(0, 4))

        self.video_lbl = tk.Label(self, bg="#020617", fg="#94a3b8", text="Chưa phát luồng Camera\n(Hỗ trợ RTSP TCP qua OpenCV / HTTP Snapshot / VLC)", font=("Segoe UI", 12))
        self.video_lbl.pack(fill="both", expand=True, padx=12, pady=(0, 12))
        self._apply_preset()

    def _apply_preset(self, _v: Any = None) -> None:
        tpl = _CAMERA_PRESETS_V8.get(self.preset_var.get(), "")
        u = self.user_e.get().strip() or "admin"
        p = self.pwd_e.get().strip()
        url = tpl.format(user=u, pwd=p, ip=self.ip)
        if not p:
            url = url.replace(f"{u}:@", f"{u}@")
        self.url_e.delete(0, "end")
        self.url_e.insert(0, url)

    def _open_web_cam(self) -> None:
        try:
            webbrowser.open(f"http://{self.ip}")
        except Exception:
            pass

    def _open_vlc(self) -> None:
        url = self.url_e.get().strip()
        if not url:
            return
        candidates = [
            r"C:\Program Files\VideoLAN\VLC\vlc.exe",
            r"C:\Program Files (x86)\VideoLAN\VLC\vlc.exe",
            "vlc",
        ]
        for exe in candidates:
            try:
                _subp_v8.Popen([exe, url])
                self.status_lbl.configure(text=f"🎬 Đã mở luồng bằng VLC: {url}", text_color="#16a34a")
                return
            except Exception:
                continue
        messagebox.showinfo("Mở bằng VLC", f"Máy chưa cài VLC Player. Bạn có thể copy link RTSP này vào VLC:\n\n{url}")

    def _save_snapshot(self) -> None:
        if self._last_pil is None:
            messagebox.showinfo("Chụp ảnh", "Chưa có khung hình nào đang phát để chụp!")
            return
        fname = f"Camera_{self.ip.replace('.', '_')}_{time.strftime('%Y%m%d_%H%M%S')}.png"
        out = Path.cwd() / fname
        try:
            self._last_pil.save(out)
            self.status_lbl.configure(text=f"📸 Đã lưu ảnh chụp: {out.name}", text_color="#16a34a")
        except Exception as exc:
            messagebox.showerror("Lỗi lưu ảnh", str(exc))

    def _toggle_stream(self) -> None:
        if self._running:
            self._running = False
            self.play_btn.configure(text="▶ Phát luồng", fg_color="#16a34a")
            self.status_lbl.configure(text="Đã dừng luồng Camera.", text_color="#64748b")
            return
        url = self.url_e.get().strip()
        if not url:
            return
        self._running = True
        self.play_btn.configure(text="⏹ Dừng", fg_color="#dc2626")
        self.status_lbl.configure(text=f"⏳ Đang kết nối tới {self.ip} (RTSP TCP / HTTP)...", text_color="#d97706")
        threading.Thread(target=self._stream_worker, args=(url,), daemon=True).start()

    def _stream_worker(self, url: str) -> None:
        if url.lower().startswith("http"):
            # Chế độ HTTP Snapshot / MJPEG
            while self._running:
                try:
                    req = _urlreq_v8.Request(url, headers={"User-Agent": "LanMapCam/8.0"})
                    with _urlreq_v8.urlopen(req, timeout=4) as r:
                        raw = r.read()
                    pil = Image.open(io.BytesIO(raw)).convert("RGB")
                    self._push_frame(pil, "🟢 Đang xem HTTP Snapshot (Live)")
                except Exception as exc:
                    self._push_err(f"Không đọc được HTTP Snapshot ({exc}). Hãy thử đổi sang chuẩn RTSP hoặc bấm '🌐 Web Cam'!")
                    break
                time.sleep(0.5)
            return

        # Chế độ RTSP qua OpenCV (ép TCP giảm giật lag, học từ Qengineering/mpolinowski)
        try:
            import cv2  # type: ignore
        except Exception:
            self._push_err("Chưa cài thư viện OpenCV để giải mã luồng RTSP trong app!\n👉 Chạy lệnh sau trong Terminal PyCharm rồi mở lại:  pip install opencv-python\nHoặc bấm nút '🎬 Mở VLC' / '🌐 Web Cam' ở trên để xem ngay.")
            return

        os.environ["OPENCV_FFMPEG_CAPTURE_OPTIONS"] = "rtsp_transport;tcp"
        cap = cv2.VideoCapture(url, cv2.CAP_FFMPEG)
        cap.set(cv2.CAP_PROP_BUFFERSIZE, 1)
        if not cap.isOpened():
            cap.release()
            self._push_err(f"Không kết nối được luồng RTSP ({self.ip}:554).\nKiểm tra lại: (1) Đúng User/Password in dưới đáy camera chưa? (2) Đã chọn đúng hãng (Hikvision/Dahua/Tapo/Ezviz/Yoosee) chưa? (3) Camera đã bật RTSP/ONVIF trong app điện thoại chưa?")
            return

        self._cap = cap
        fail_cnt = 0
        while self._running:
            ok, frame = cap.read()
            if not ok or frame is None:
                fail_cnt += 1
                if fail_cnt > 25:
                    self._push_err("Mất tín hiệu luồng RTSP từ Camera.")
                    break
                time.sleep(0.05)
                continue
            fail_cnt = 0
            rgb = cv2.cvtColor(frame, cv2.COLOR_BGR2RGB)
            pil = Image.fromarray(rgb)
            self._push_frame(pil, f"🟢 LIVE RTSP (TCP) — {self.ip} ({pil.width}x{pil.height})")
            time.sleep(0.03)
        cap.release()
        self._cap = None

    def _push_frame(self, pil: Any, status_txt: str) -> None:
        self._last_pil = pil

        def _ui() -> None:
            if not self.winfo_exists():
                return
            w = max(320, self.video_lbl.winfo_width() - 8)
            h = max(240, self.video_lbl.winfo_height() - 8)
            resized = pil.copy()
            resized.thumbnail((w, h))
            tk_img = ImageTk.PhotoImage(resized)
            self._img_tk = tk_img
            self.video_lbl.configure(image=tk_img, text="")
            self.status_lbl.configure(text=status_txt, text_color="#16a34a")

        self.after(0, _ui)

    def _push_err(self, msg: str) -> None:
        self._running = False

        def _ui() -> None:
            if not self.winfo_exists():
                return
            self.play_btn.configure(text="▶ Phát luồng", fg_color="#16a34a")
            self.status_lbl.configure(text="✖ Không mở được luồng Camera", text_color="#dc2626")
            self.video_lbl.configure(image="", text=msg, fg="#f87171", wraplength=620, justify="left")

        self.after(0, _ui)

    def _close(self) -> None:
        self._running = False
        try:
            if self._cap:
                self._cap.release()
        except Exception:
            pass
        self.destroy()


# --- 2. Tách các Subnet chồng chéo sang 2 bên Trái / Phải & Hỏi khi đổi mạng mới ---
def _get_subnet_prefix_24(ip: str) -> str:
    parts = str(ip or "").split(".")
    return ".".join(parts[:3]) + ".0/24" if len(parts) == 4 else "Khác"


def _separate_subnets_side_by_side_v8(app: Any) -> int:
    """Tách toàn bộ thiết bị thuộc các subnet khác nhau (vd 192.168.100.x vs 192.168.1.x) sang các cụm Trái/Phải không chồng chéo!"""
    devs = list(getattr(getattr(app, "real_state", None), "devices", []) or [])
    if not devs:
        return 0
    groups: dict[str, list[Any]] = {}
    for d in devs:
        sub = _get_subnet_prefix_24(getattr(d, "ip", ""))
        groups.setdefault(sub, []).append(d)

    col_w = 640
    for g_idx, (sub, items) in enumerate(sorted(groups.items())):
        base_x = 120 + g_idx * col_w
        routers = [d for d in items if str(getattr(d, "device_type", "")).lower() == "router" or "gateway" in str(getattr(d, "name", "")).lower()]
        infra = [d for d in items if d not in routers and str(getattr(d, "device_type", "")).lower() in ("switch", "wifi", "ap", "server")]
        hosts = [d for d in items if d not in routers and d not in infra]

        for i, d in enumerate(routers):
            d.x = base_x + 240 + (i - len(routers) / 2.0 + 0.5) * 120
            d.y = 95
        for i, d in enumerate(infra):
            d.x = base_x + 240 + (i - len(infra) / 2.0 + 0.5) * 120
            d.y = 215
        cols = 5
        for i, d in enumerate(hosts):
            r, c = divmod(i, cols)
            d.x = base_x + 40 + c * 112
            d.y = 335 + r * 110

    try:
        if hasattr(app, "topology") and app.topology:
            app.topology.redraw()
            if hasattr(app.topology, "fit_to_view"):
                app.topology.fit_to_view()
    except Exception:
        pass
    return len(groups)


def _check_multi_subnet_overlap_v8(app: Any) -> None:
    """Tự phát hiện khi quét đổi mạng mới làm xuất hiện ≥ 2 subnet chồng chéo → Hỏi người dùng Xóa cũ hay Tách 2 bên!"""
    devs = list(getattr(getattr(app, "real_state", None), "devices", []) or [])
    if len(devs) < 2:
        return
    subs = sorted({_get_subnet_prefix_24(getattr(d, "ip", "")) for d in devs if getattr(d, "ip", "")})
    if len(subs) < 2:
        return
    sig = "|".join(subs)
    if getattr(app, "_v8_last_multi_sub_sig", "") == sig:
        return
    app._v8_last_multi_sub_sig = sig

    # Xác định subnet hiện tại của máy này
    cur_sub = _get_subnet_prefix_24(getattr(getattr(app, "real_state", None), "subnet_cidr", "").split("/")[0])
    if cur_sub not in subs:
        local_d = next((d for d in devs if "máy này" in str(getattr(d, "name", "")).lower() or str(getattr(d, "device_type", "")).lower() == "this_pc"), None)
        cur_sub = _get_subnet_prefix_24(getattr(local_d, "ip", "")) if local_d else subs[-1]

    dlg = ctk.CTkToplevel(app)
    dlg.title("🔀 Phát hiện chuyển sang mạng mới (Nhiều Subnet)")
    dlg.geometry("520x250")
    dlg.transient(app)
    dlg.grab_set()

    ctk.CTkLabel(
        dlg,
        text="Phát hiện trên sơ đồ đang có nhiều dải mạng khác nhau:",
        font=ctk.CTkFont(size=13, weight="bold"),
    ).pack(anchor="w", padx=18, pady=(16, 4))
    ctk.CTkLabel(
        dlg,
        text=f"• Các dải mạng: {', '.join(subs)}\n• Mạng hiện tại của máy bạn: {cur_sub}\n\nBạn muốn xử lý sơ đồ mạng cũ như thế nào để không bị chồng chéo?",
        justify="left", font=ctk.CTkFont(size=12),
    ).pack(anchor="w", padx=18, pady=(0, 14))

    def _replace_with_new() -> None:
        kept = [d for d in devs if _get_subnet_prefix_24(getattr(d, "ip", "")) == cur_sub]
        kept_ids = {d.id for d in kept}
        app.real_state.devices = kept
        if hasattr(app.real_state, "links"):
            app.real_state.links = [lk for lk in app.real_state.links if getattr(lk, "source_id", "") in kept_ids and getattr(lk, "target_id", "") in kept_ids]
        _separate_subnets_side_by_side_v8(app)
        dlg.destroy()

    def _keep_and_split() -> None:
        _separate_subnets_side_by_side_v8(app)
        dlg.destroy()

    brow = ctk.CTkFrame(dlg, fg_color="transparent")
    brow.pack(fill="x", padx=18, pady=(4, 14))
    ctk.CTkButton(brow, text="🧹 Xóa mạng cũ, chỉ giữ mạng mới", fg_color="#dc2626", hover_color="#b91c1c",
                  command=_replace_with_new).pack(fill="x", pady=3)
    ctk.CTkButton(brow, text="↔ Giữ cả 2 mạng & Tách riêng 2 bên Trái / Phải", fg_color="#0284c7", hover_color="#0369a1",
                  command=_keep_and_split).pack(fill="x", pady=3)
    ctk.CTkButton(brow, text="Để sau", fg_color="#64748b", command=dlg.destroy).pack(fill="x", pady=3)


# --- 3. Sửa triệt để Ping Bức thư KHÔNG KÉO PC + Đậu bức thư cạnh máy gửi + Phân tích nghẽn + Hết khựng kéo ---
def _patch_real_ping_and_drag_smooth_v8(app: Any) -> None:
    if getattr(app, "_v8_real_patched", False):
        return
    app._v8_real_patched = True
    topo = getattr(app, "topology", None)
    t_canvas = topo if isinstance(topo, tk.Canvas) else getattr(topo, "canvas", None)
    if not topo or not t_canvas:
        return

    # 3A. Chặn hoàn toàn drag gốc của TopologyCanvas khi đang ở chế độ Ping Bức thư bằng bindtags ưu tiên!
    intercept_tag = "v8_ping_intercept"
    tags = list(t_canvas.bindtags())
    if intercept_tag not in tags:
        t_canvas.bindtags((intercept_tag,) + tuple(tags))

    def _find_dev_at(mx: float, my: float) -> Any:
        devs = list(getattr(getattr(app, "real_state", None), "devices", []) or [])
        best, best_d = None, 44.0
        for d in devs:
            sx, sy = _topo_world_to_screen(topo, getattr(d, "x", 0), getattr(d, "y", 0))
            dist = _math_v8.hypot(sx - mx, sy - my)
            if dist < best_d:
                best, best_d = d, dist
        return best

    def _draw_pinned_src_envelope(dev: Any) -> None:
        t_canvas.delete("v8_pinned_mail")
        sx, sy = _topo_world_to_screen(topo, getattr(dev, "x", 0), getattr(dev, "y", 0))
        t_canvas.create_oval(sx - 28, sy - 26, sx + 28, sy + 26, outline="#f59e0b", width=2.5, dash=(4, 2), tags="v8_pinned_mail")
        # Phong bì đậu ngay góc trên phải máy gửi!
        ex, ey = sx + 22, sy - 20
        t_canvas.create_rectangle(ex - 13, ey - 9, ex + 13, ey + 9, fill="#fde047", outline="#0284c7", width=2, tags="v8_pinned_mail")
        t_canvas.create_line(ex - 13, ey - 9, ex, ey + 1, ex + 13, ey - 9, fill="#0284c7", width=1.8, tags="v8_pinned_mail")

    def _on_intercept_down(e: tk.Event) -> str | None:
        if not getattr(app, "_real_ping_mode", False):
            return None
        dev = _find_dev_at(e.x, e.y)
        if not dev:
            return "break"
        if getattr(app, "_real_ping_src", None) is None:
            app._real_ping_src = dev
            _draw_pinned_src_envelope(dev)
            if hasattr(app, "lanbot") and app.lanbot:
                app.lanbot.show_bubble(f"✉ Bức thư đã đặt tại máy gửi: {dev.name} ({dev.ip})\n👉 Bấm vào máy NHẬN để gửi đi & phân tích nghẽn!", 5500)
            return "break"

        src_dev = app._real_ping_src
        dst_dev = dev
        app._real_ping_mode = False
        app._real_ping_src = None
        t_canvas.delete("v7_env_cursor")
        t_canvas.delete("v8_pinned_mail")
        t_canvas.configure(cursor="")
        if src_dev.id != dst_dev.id:
            _execute_real_ping_with_bottleneck_v8(app, topo, t_canvas, src_dev, dst_dev)
        return "break"

    def _on_intercept_drag(_e: tk.Event) -> str | None:
        # Khóa tuyệt đối việc kéo thả thiết bị khi đang bật chế độ Ping Bức thư
        if getattr(app, "_real_ping_mode", False):
            return "break"
        return None

    t_canvas.bind_class(intercept_tag, "<Button-1>", _on_intercept_down)
    t_canvas.bind_class(intercept_tag, "<B1-Motion>", _on_intercept_drag)

    # 3B. Tối ưu vẽ màu PC Xanh/Vàng: bỏ gọi nặng lặp lại lúc kéo chuột (hết khựng 1 nhịp!)
    app._v8_cached_cw = 900
    t_canvas.bind("<Configure>", lambda e: setattr(app, "_v8_cached_cw", max(400, e.width)), add="+")

    # 3C. Thêm nút '↔ Tách Subnet' ngay cạnh thanh công cụ
    def _add_split_subnet_btn() -> None:
        try:
            def _find_auto_btn(w: Any) -> Any:
                if w.__class__.__name__ == "CTkButton" and any(k in str(w.cget("text") or "") for k in ("Tự xếp", "Auto", "排列")):
                    return w
                for ch in w.winfo_children():
                    r = _find_auto_btn(ch)
                    if r:
                        return r
                return None

            ab = _find_auto_btn(app)
            if ab and ab.master:
                ctk.CTkButton(
                    ab.master, text="↔ Tách Subnet", width=98, height=26,
                    fg_color="#0ea5e9", hover_color="#0284c7",
                    command=lambda: _separate_subnets_side_by_side_v8(app),
                ).pack(side="left", padx=2, after=ab)
        except Exception:
            pass

    app.after(900, _add_split_subnet_btn)


def _execute_real_ping_with_bottleneck_v8(app: Any, topo: Any, canvas: tk.Canvas, src_dev: Any, dst_dev: Any) -> None:
    """Ping 2 máy trên sơ đồ thật + hoạt ảnh bức thư bay + tự động phân tích điểm nghẽn từng chặng!"""
    src_name, src_ip = getattr(src_dev, "name", ""), getattr(src_dev, "ip", "")
    dst_name, dst_ip = getattr(dst_dev, "name", ""), getattr(dst_dev, "ip", "")
    client_ips = getattr(app, "_lanmap_client_ips", set()) or set()
    devs = list(getattr(getattr(app, "real_state", None), "devices", []) or [])
    gw = next((d for d in devs if str(getattr(d, "device_type", "")).lower() == "router" or "gateway" in str(getattr(d, "name", "")).lower()), None)

    is_local = (
        str(getattr(src_dev, "device_type", "")).lower() == "this_pc"
        or "máy này" in src_name.lower() or "this pc" in src_name.lower() or "本机" in src_name.lower()
    )
    has_client = _device_has_lanmap_client(src_dev, client_ips)

    pts = [_topo_world_to_screen(topo, getattr(src_dev, "x", 0), getattr(src_dev, "y", 0))]
    if gw and gw.id not in (src_dev.id, dst_dev.id):
        pts.append(_topo_world_to_screen(topo, getattr(gw, "x", 0), getattr(gw, "y", 0)))
    pts.append(_topo_world_to_screen(topo, getattr(dst_dev, "x", 0), getattr(dst_dev, "y", 0)))

    def _ping_once(ip: str) -> tuple[bool, float]:
        try:
            si = _subp_v8.STARTUPINFO() if os.name == "nt" else None
            if si:
                si.dwFlags |= _subp_v8.STARTF_USESHOWWINDOW
            p = _subp_v8.run(
                ["ping", "-n" if os.name == "nt" else "-c", "2", "-w" if os.name == "nt" else "-W", "900", ip],
                capture_output=True, text=True, timeout=4,
                startupinfo=si,
                creationflags=getattr(_subp_v8, "CREATE_NO_WINDOW", 0) if os.name == "nt" else 0,
            )
            ok = (p.returncode == 0) and ("TTL=" in p.stdout.upper() or "time=" in p.stdout.lower() or "time<" in p.stdout.lower())
            m = re.search(r"time[=<]\s*(\d+)\s*ms", p.stdout, re.I)
            return ok, float(m.group(1)) if m else 1.0
        except Exception:
            return False, -1.0

    def _animate(ok: bool, report: str) -> None:
        pkt_r = canvas.create_rectangle(0, 0, 0, 0, fill="#2563eb", outline="#ffffff", width=2, tags="v8_real_pkt")
        pkt_t = canvas.create_text(0, 0, text="✉ PING", fill="#ffffff", font=("Segoe UI", 8, "bold"), tags="v8_real_pkt")

        def _move(path_pts: list[tuple[float, float]], hop: int, step: int, is_reply: bool) -> None:
            if hop >= len(path_pts) - 1:
                if not is_reply and ok:
                    canvas.itemconfig(pkt_r, fill="#16a34a")
                    canvas.itemconfig(pkt_t, text="✉ OK!")
                    _move(list(reversed(path_pts)), 0, 0, True)
                else:
                    if not ok:
                        ex, ey = path_pts[-1]
                        err = canvas.create_text(ex, ey - 28, text="✖ NGHẼN / RỚT GÓI", fill="#ef4444", font=("Segoe UI", 9, "bold"), tags="v8_real_pkt")
                        app.after(1500, lambda: (canvas.delete(pkt_r), canvas.delete(pkt_t), canvas.delete(err)))
                    else:
                        app.after(300, lambda: (canvas.delete(pkt_r), canvas.delete(pkt_t)))
                    if hasattr(app, "lanbot") and app.lanbot:
                        app.lanbot.show_bubble(report, 9000)
                return
            x1, y1 = path_pts[hop]
            x2, y2 = path_pts[hop + 1]
            t = step / 14.0
            cx, cy = x1 + (x2 - x1) * t, y1 + (y2 - y1) * t
            canvas.coords(pkt_r, cx - 24, cy - 11, cx + 24, cy + 11)
            canvas.coords(pkt_t, cx, cy)
            if step < 14:
                app.after(18, lambda: _move(path_pts, hop, step + 1, is_reply))
            else:
                app.after(18, lambda: _move(path_pts, hop + 1, 0, is_reply))

        _move(pts, 0, 0, False)

    if is_local:
        def _bg() -> None:
            gw_ok, gw_ms = _ping_once(getattr(gw, "ip", "")) if gw else (True, 1.0)
            dst_ok, dst_ms = _ping_once(dst_ip)
            if dst_ok:
                if dst_ms > 80:
                    rep = f"⚠ Ping {src_name} → {dst_name}: THÔNG ({dst_ms:.0f} ms) nhưng NGHẼN ĐỘ TRỄ CAO!\n• Chặng Gateway: {gw_ms:.0f} ms\n• Nguyên nhân: Sóng Wi-Fi yếu hoặc nhiều thiết bị tải nặng."
                else:
                    rep = f"✅ Ping {src_name} → {dst_name}: THÔNG SUỐT ({dst_ms:.0f} ms)\n• Chặng Gateway: {gw_ms:.0f} ms | Không phát hiện nghẽn!"
            else:
                if gw and not gw_ok:
                    rep = f"✖ NGHẼN NGAY TẠI GATEWAY ({gw.ip})!\n• Máy bạn không chạm tới Router → Kiểm tra dây LAN/Wi-Fi hoặc Router bị treo."
                else:
                    rep = f"✖ NGHẼN TẠI CHẶNG ĐÍCH {dst_name} ({dst_ip})!\n• Gateway thông ({gw_ms:.0f} ms) nhưng đích không phản hồi → Máy đích đang tắt, ngủ đông, hoặc bật Firewall chặn ICMP."
            app.after(0, lambda: _animate(dst_ok, rep))

        threading.Thread(target=_bg, daemon=True).start()
        return

    if not has_client:
        if messagebox.askyesno(
            "Máy gửi chưa cài LanMap Client",
            f"Máy gửi '{src_name}' ({src_ip}) chưa cài LanMap Client (PC màu vàng).\nBạn muốn Ping từ Máy này tới '{dst_name}' ({dst_ip}) để phân tích nghẽn thay thế không?",
        ):
            local_d = next((d for d in devs if "máy này" in str(getattr(d, "name", "")).lower()), src_dev)
            _execute_real_ping_with_bottleneck_v8(app, topo, canvas, local_d, dst_dev)
        return

    pin = app._client_pin_cache.get(src_ip)
    if not pin:
        dlg = ctk.CTkInputDialog(text=f"Nhập mã PIN của LanMap Client trên máy gửi {src_name} ({src_ip}):", title="Ping chéo qua Client")
        pin = (dlg.get_input() or "").strip()
        if not pin:
            return
        app._client_pin_cache[src_ip] = pin

    def _bg_cl() -> None:
        try:
            res = query_lanmap_agent(src_ip, pin, "cmd", f"ping -n 2 -w 1000 {dst_ip}")
            out = str((res or {}).get("output") or (res or {}).get("message") or "")
            ok = bool(res and res.get("ok") and ("TTL=" in out.upper() or "time=" in out.lower() or "time<" in out.lower()))
            m = re.search(r"time[=<]\s*(\d+)\s*ms", out, re.I)
            ms_s = f"{m.group(1)} ms" if m else "<1 ms"
            rep = f"✅ Ping chéo (Client) {src_name} → {dst_name}: THÔNG SUỐT ({ms_s})!" if ok else f"✖ NGHẼN giữa {src_name} → {dst_name}: Không nhận được phản hồi ICMP (Firewall chặn hoặc khác VLAN)."
            app.after(0, lambda: _animate(ok, rep))
        except Exception as exc:
            app.after(0, lambda: _animate(False, f"Lỗi Ping chéo: {exc}"))

    threading.Thread(target=_bg_cl, daemon=True).start()


# --- 4. Nâng cấp FULL CISCO IOS CLI + Sửa dây Switch-AP + Bức thư đậu cạnh máy gửi trong Phòng Lab ---
_orig_lab_cls_v7 = NetworkLabDialog


class NetworkLabDialog(_orig_lab_cls_v7):
    """Mở rộng Phòng Lab v7.0:
    - Cisco IOS CLI đầy đủ (enable, conf t, hostname, int g0/0, ip address, no shutdown, ip dhcp pool, ip route, sh run, sh ip int br, sh ip rou, ping, ?)
    - Sửa dây Switch ↔ Wi-Fi AP dùng cáp chéo / tự động để luôn Xanh lá khi Nạp mạng thật
    - Khi chọn máy gửi trong chế độ Ping Bức thư → đậu bức thư ✉ ngay cạnh máy gửi!
    """

    def import_real_network(self) -> None:
        super().import_real_network()
        # Sửa dây Switch ↔ AP sang cáp chéo đúng chuẩn Cisco để hiện đèn xanh lá!
        for lk in self.links:
            na, nb = self.nodes.get(lk["a"]), self.nodes.get(lk["b"])
            if na and nb and {na["type"], nb["type"]} == {"switch", "ap"}:
                lk["cable"] = "cross"
        self._redraw()

    def _redraw(self) -> None:
        super()._redraw()
        # Nếu đang chọn máy nguồn Ping trong Lab → vẽ phong bì đậu ngay góc máy nguồn!
        if self.mode == "ping_pdu" and self._ping_src and self._ping_src in self.nodes:
            n = self.nodes[self._ping_src]
            ex, ey = n["x"] + 24, n["y"] - 22
            self.canvas.create_rectangle(ex - 13, ey - 9, ex + 13, ey + 9, fill="#fde047", outline="#0284c7", width=2)
            self.canvas.create_line(ex - 13, ey - 9, ex, ey + 1, ex + 13, ey - 9, fill="#0284c7", width=1.8)

    def _render_router_cfg(self, n: dict[str, Any]) -> None:
        tabs = ctk.CTkTabview(self.cfg_body)
        tabs.pack(fill="both", expand=True)
        t_if = tabs.add("Interfaces & DHCP")
        t_cli = tabs.add("Cisco CLI (Full)")

        # Tab 1: GUI Interfaces & DHCP
        pnames = list(n["ports"].keys())
        sel_p = ctk.StringVar(value=pnames[0])
        p_menu = ctk.CTkOptionMenu(t_if, values=pnames, variable=sel_p)
        p_menu.pack(fill="x", padx=6, pady=(6, 6))

        up_var = ctk.BooleanVar(value=True)
        dhcp_var = ctk.BooleanVar(value=True)
        ctk.CTkSwitch(t_if, text="Port Status (no shutdown)", variable=up_var).pack(anchor="w", padx=6, pady=2)
        ip_e = ctk.CTkEntry(t_if, placeholder_text="Gateway IP")
        ip_e.pack(fill="x", padx=6, pady=(4, 4))
        mask_e = ctk.CTkEntry(t_if, placeholder_text="Subnet Mask")
        mask_e.pack(fill="x", padx=6, pady=(2, 5))
        ctk.CTkSwitch(t_if, text="Bật DHCP Server", variable=dhcp_var).pack(anchor="w", padx=6, pady=3)
        pool_e = ctk.CTkEntry(t_if, placeholder_text="DHCP Start IP")
        pool_e.pack(fill="x", padx=6, pady=(2, 6))

        def _load_port(_v: Any = None) -> None:
            pc = n["ports"][sel_p.get()]
            up_var.set(bool(pc.get("up", True)))
            dhcp_var.set(bool(pc.get("dhcp", False)))
            ip_e.delete(0, "end"); ip_e.insert(0, pc.get("ip", ""))
            mask_e.delete(0, "end"); mask_e.insert(0, pc.get("mask", "255.255.255.0"))
            pool_e.delete(0, "end"); pool_e.insert(0, pc.get("pool_start", ""))

        def _save_port() -> None:
            pc = n["ports"][sel_p.get()]
            pc["up"], pc["dhcp"] = bool(up_var.get()), bool(dhcp_var.get())
            pc["ip"], pc["mask"], pc["pool_start"] = ip_e.get().strip(), mask_e.get().strip() or "255.255.255.0", pool_e.get().strip()
            self._redraw()
            self._log_event(n["name"], sel_p.get(), "IOS", "Cập nhật", f"IP={pc['ip']} | UP={pc['up']} | DHCP={pc['dhcp']}")

        p_menu.configure(command=_load_port)
        _load_port()
        ctk.CTkButton(t_if, text="💾 Lưu cổng Router", fg_color="#0284c7", command=_save_port).pack(fill="x", padx=6, pady=6)

        # Tab 2: Cisco IOS CLI FULL (enable -> conf t -> int g0/0 -> ip address -> no sh -> ip dhcp pool -> ip route!)
        n.setdefault("_cli_mode", "user")  # user | priv | config | if | dhcp
        n.setdefault("_cli_if", "Gig0/0")
        n.setdefault("_cli_pool", "LAN")
        n.setdefault("static_routes", [])

        def _prompt() -> str:
            m = n["_cli_mode"]
            hn = n["name"]
            if m == "user":
                return f"{hn}> "
            if m == "priv":
                return f"{hn}# "
            if m == "config":
                return f"{hn}(config)# "
            if m == "if":
                return f"{hn}(config-if)# "
            return f"{hn}(dhcp-config)# "

        cli_out = ctk.CTkTextbox(t_cli, fg_color="#020617", text_color="#38bdf8", font=ctk.CTkFont(family="Consolas", size=11))
        cli_out.pack(fill="both", expand=True, padx=4, pady=(4, 6))
        cli_out.insert("end", "Cisco IOS CLI Simulator (Full Mode)\nGõ '?' hoặc 'help' để xem danh sách lệnh (enable, conf t, int g0/0, ip address, no sh, ip dhcp pool, sh run...)\n\n" + _prompt())

        cli_row = ctk.CTkFrame(t_cli, fg_color="transparent")
        cli_row.pack(fill="x", padx=4, pady=(0, 4))
        cli_e = ctk.CTkEntry(cli_row, placeholder_text="enable  →  conf t  →  int g0/0  →  ip address ...")
        cli_e.pack(side="left", fill="x", expand=True, padx=(0, 4))

        def _resolve_port_name(raw_if: str) -> str | None:
            s = raw_if.lower().replace("gigabitethernet", "gig").replace("g0/", "gig0/")
            for pn in n["ports"]:
                if pn.lower() == s or pn.lower().startswith(s):
                    return pn
            return None

        def _exec_cli(_e: Any = None) -> None:
            raw = cli_e.get().strip()
            if not raw:
                return
            cli_e.delete(0, "end")
            cli_out.insert("end", raw + "\n")
            low = raw.lower()
            parts = raw.split()
            m = n["_cli_mode"]

            if low in ("?", "help"):
                cli_out.insert(
                    "end",
                    "Lệnh Cisco IOS hỗ trợ:\n"
                    "  enable (en)                 - Vào chế độ đặc quyền (#)\n"
                    "  configure terminal (conf t) - Vào chế độ cấu hình toàn cục\n"
                    "  hostname <Tên>              - Đổi tên Router\n"
                    "  interface gig0/0 (int g0/0) - Vào cấu hình cổng\n"
                    "  ip address <IP> <Mask>      - Gán IP cho cổng đang chọn\n"
                    "  no shutdown / shutdown      - Bật / Tắt cổng\n"
                    "  ip dhcp pool <Tên>          - Tạo DHCP Pool (network, default-router)\n"
                    "  ip route <Net> <Mask> <NH>  - Thêm tuyến tĩnh (Static Route)\n"
                    "  show ip interface brief     - Xem trạng thái các cổng\n"
                    "  show ip route | show run    - Xem bảng định tuyến / cấu hình\n"
                    "  ping <IP> | exit | end | wr - Kiểm tra Ping / Thoát / Lưu\n",
                )
            elif low in ("en", "enable"):
                n["_cli_mode"] = "priv"
            elif low in ("end",):
                n["_cli_mode"] = "priv"
            elif low == "exit":
                n["_cli_mode"] = "config" if m in ("if", "dhcp") else ("priv" if m == "config" else "user")
            elif low.startswith("conf") and m == "priv":
                n["_cli_mode"] = "config"
                cli_out.insert("end", "Enter configuration commands, one per line. End with 'end'.\n")
            elif low.startswith("hostname ") and m == "config":
                n["name"] = parts[1]
                self.cfg_header.configure(text=f"⚙ {n['name']}  (ROUTER)")
                self._redraw()
            elif (low.startswith("int ") or low.startswith("interface ")) and m in ("config", "if"):
                pn = _resolve_port_name(parts[1]) if len(parts) >= 2 else None
                if pn:
                    n["_cli_if"] = pn
                    n["_cli_mode"] = "if"
                else:
                    cli_out.insert("end", f"% Invalid interface. Có sẵn: {', '.join(n['ports'].keys())}\n")
            elif low.startswith("ip addr") and m == "if" and len(parts) >= 4:
                pn = n["_cli_if"]
                n["ports"][pn]["ip"] = parts[2]
                n["ports"][pn]["mask"] = parts[3]
                self._redraw()
                _load_port()
                self._log_event(n["name"], pn, "CLI", "Đặt IP", f"ip address {parts[2]} {parts[3]}")
            elif (low in ("no sh", "no shut", "no shutdown")) and m == "if":
                pn = n["_cli_if"]
                n["ports"][pn]["up"] = True
                self._redraw()
                _load_port()
                cli_out.insert("end", f"%LINK-3-UPDOWN: Interface {pn}, changed state to up\n")
                self._log_event(n["name"], pn, "CLI", "UP", "no shutdown")
            elif (low in ("sh", "shut", "shutdown")) and m == "if":
                pn = n["_cli_if"]
                n["ports"][pn]["up"] = False
                self._redraw()
                _load_port()
                cli_out.insert("end", f"%LINK-5-CHANGED: Interface {pn}, changed state to administratively down\n")
            elif low.startswith("ip dhcp pool ") and m == "config":
                n["_cli_pool"] = parts[3]
                n["_cli_mode"] = "dhcp"
            elif low.startswith("network ") and m == "dhcp" and len(parts) >= 3:
                try:
                    net = ipaddress.IPv4Network(f"{parts[1]}/{parts[2]}", strict=False)
                    for pn, pc in n["ports"].items():
                        if pc.get("ip") and ipaddress.IPv4Address(pc["ip"]) in net:
                            pc["dhcp"] = True
                            pc["pool_start"] = str(list(net.hosts())[9])
                            cli_out.insert("end", f"✓ Đã bật DHCP Pool '{n['_cli_pool']}' trên cổng {pn} ({net})\n")
                            _load_port()
                            break
                except Exception as exc:
                    cli_out.insert("end", f"% Lỗi network: {exc}\n")
            elif low.startswith("default-router ") and m == "dhcp" and len(parts) >= 2:
                cli_out.insert("end", f"✓ Default-router set to {parts[1]}\n")
            elif low.startswith("ip route ") and m == "config" and len(parts) >= 5:
                n["static_routes"].append((parts[2], parts[3], parts[4]))
                cli_out.insert("end", f"✓ Đã thêm Static Route: {parts[2]} {parts[3]} via {parts[4]}\n")
            elif low in ("wr", "write", "write memory", "copy run start"):
                cli_out.insert("end", "Building configuration...\n[OK]\n")
            elif (low.startswith("sh ") or low.startswith("show ") or low.startswith("do sh")) and "int" in low:
                cli_out.insert("end", "Interface    IP-Address       Status        DHCP\n")
                for pn, pc in n["ports"].items():
                    cli_out.insert("end", f"{pn:<12} {(pc.get('ip') or 'unassigned'):<16} {'up' if pc.get('up') else 'admin down':<13} {'ON' if pc.get('dhcp') else 'OFF'}\n")
            elif (low.startswith("sh ") or low.startswith("show ") or low.startswith("do sh")) and "rou" in low:
                for pn, pc in n["ports"].items():
                    if pc.get("up") and pc.get("ip"):
                        net = ipaddress.IPv4Network(f"{pc['ip']}/{pc.get('mask', '255.255.255.0')}", strict=False)
                        cli_out.insert("end", f"C   {net} is directly connected, {pn}\n")
                for dst_n, dst_m, nh in n["static_routes"]:
                    cli_out.insert("end", f"S   {dst_n} {dst_m} via {nh}\n")
            elif (low.startswith("sh ") or low.startswith("show ") or low.startswith("do sh")) and "run" in low:
                cli_out.insert("end", f"hostname {n['name']}\n!\n")
                for pn, pc in n["ports"].items():
                    cli_out.insert("end", f"interface {pn}\n")
                    if pc.get("ip"):
                        cli_out.insert("end", f" ip address {pc['ip']} {pc.get('mask', '255.255.255.0')}\n")
                    cli_out.insert("end", f" {'no shutdown' if pc.get('up') else 'shutdown'}\n!\n")
            elif low.startswith("ping ") or low.startswith("do ping "):
                tip = parts[-1]
                dst_nid = self._find_node_by_ip(tip)
                cli_out.insert("end", (self._run_ping_between(n["id"], dst_nid)[1] if dst_nid else "..... (0% success rate)") + "\n")
            else:
                cli_out.insert("end", f"% Lệnh chưa hợp lệ ở chế độ hiện tại ({m}). Gõ '?' để xem hướng dẫn!\n")

            cli_out.insert("end", "\n" + _prompt())
            cli_out.see("end")

        cli_e.bind("<Return>", _exec_cli)
        ctk.CTkButton(cli_row, text="Gửi", width=48, command=_exec_cli).pack(side="left")


# --- 5. Nâng cấp LanBot AI v8.0: Trích xuất IP thực tế + Nhớ ngữ cảnh + Tùy chọn Local LLM (Ollama) ---
_orig_lanbot_cls_v7 = LanBotAssistant


class LanBotAssistant(_orig_lanbot_cls_v7):
    """LanBot AI v8.0:
    - Kế thừa toàn bộ tính năng v7.0 (không viền, Bubble Chat, Windows Toast, kết nối Lab)
    - Tự động cài đặt bản vá v8.0 (No-drag Envelope Ping, hết khựng kéo thả, tách Subnet, hỏi khi đổi mạng)
    - Hybrid NLU: Tự đọc IP người dùng nhắc tới trong câu chat (vd 'kiểm tra 192.168.1.105') để tra cứu thiết bị thật!
    - Tùy chọn bật Local LLM (Ollama localhost:11434) giống các dự án chatbot AI mã nguồn mở trên GitHub!
    """

    def __init__(self, app: "LanMapApp") -> None:
        self._ollama_enabled = False
        self._ollama_model = "llama3.2"
        self._ollama_url = "http://localhost:11434/api/generate"
        self._chat_history: list[str] = []
        super().__init__(app)
        _patch_real_ping_and_drag_smooth_v8(app)

    def _watch_network_and_i18n(self) -> None:
        super()._watch_network_and_i18n()

    def _query_ollama_local(self, user_q: str) -> str | None:
        if not self._ollama_enabled:
            return None
        try:
            _sc, audit_txt = build_live_network_analysis_text(self.app)
            ctx = (
                "Bạn là LanBot AI, trợ lý quản trị mạng tiếng Việt ngắn gọn, thân thiện của ứng dụng LanMap.\n"
                f"Tóm tắt mạng hiện tại của người dùng:\n{audit_txt[:900]}\n\n"
                f"Câu hỏi người dùng: {user_q}\nTrả lời ngắn gọn, thực tế bằng tiếng Việt:"
            )
            payload = _json_v8.dumps({"model": self._ollama_model, "prompt": ctx, "stream": False}).encode("utf-8")
            req = _urlreq_v8.Request(self._ollama_url, data=payload, headers={"Content-Type": "application/json"})
            with _urlreq_v8.urlopen(req, timeout=12) as r:
                data = _json_v8.loads(r.read().decode("utf-8", errors="ignore"))
                ans = str(data.get("response", "")).strip()
                return ans or None
        except Exception:
            return None

    def _analyze_query(self, raw_q: str) -> tuple[str, list[tuple[str, str]]]:
        self._chat_history.append(raw_q)
        # 1. Kiểm tra xem người dùng có nhắc tới 1 địa chỉ IP cụ thể không (Entity Extraction!)
        m_ip = re.search(r"\b(\d{1,3}(?:\.\d{1,3}){3})\b", raw_q)
        if m_ip:
            tip = m_ip.group(1)
            devs = list(getattr(getattr(self.app, "real_state", None), "devices", []) or [])
            found = next((d for d in devs if getattr(d, "ip", "") == tip), None)
            if found:
                has_cl = _device_has_lanmap_client(found, getattr(self.app, "_lanmap_client_ips", set()))
                st = getattr(found, "status", "online")
                lat = getattr(found, "latency_ms", None)
                dt = getattr(found, "device_type", "unknown")
                return (
                    f"🔎 Mình đã tra cứu thiết bị **{found.name}** (`{tip}`) trên sơ đồ thật:\n"
                    f"• Loại: {dt} | Trạng thái: **{st}** | Ping: {f'{lat:.0f} ms' if isinstance(lat, (int, float)) else 'N/A'}\n"
                    f"• MAC: `{getattr(found, 'mac', 'N/A')}` | LanMap Client: **{'🔵 Đã cài' if has_cl else '🟡 Chưa cài'}**\n"
                    f"• Tin cậy: {'✓ Đã duyệt' if getattr(found, 'trusted', True) else '⚠ Thiết bị lạ chưa duyệt'}"
                ), [("✉ Bật Ping Bức thư", "real_ping"), ("📊 Phân tích toàn mạng", "live_audit")]

        # 2. Hỏi về Camera không xem được / RTSP
        low = raw_q.lower()
        if any(k in low for k in ("camera", "cam ", "rtsp", "không xem được cam", "xem cam")):
            return (
                "📹 **Cách xem Camera IP thành công 100% ở bản v8.0:**\n"
                "1. Bấm vào biểu tượng Camera trên sơ đồ → chọn **Xem Camera trực tiếp**.\n"
                "2. Chọn đúng hãng (Hikvision, Dahua/KBVision, Tapo, Ezviz, Yoosee...) và nhập **User / Password** (thường in dưới đáy camera).\n"
                "3. Nếu muốn phát luồng RTSP trực tiếp trong app cần cài 1 lần lệnh: `pip install opencv-python` (hoặc bấm nút **🎬 Mở VLC** / **🌐 Web Cam** để xem ngay lập tức!)."
            ), []

        # 3. Hỏi về lệnh Cisco CLI trên Router
        if any(k in low for k in ("cli", "enable", "conf t", "lệnh router", "cấu hình route", "cấu hình router")):
            return (
                "💻 **Phòng Lab v8.0 đã hỗ trợ FULL Cisco IOS CLI trên Router!**\n"
                "Bạn vào tab `Cisco CLI (Full)` trên Router và gõ y như Cisco Packet Tracer:\n"
                "• `enable` → `conf t` → `int g0/0`\n"
                "• `ip address 192.168.10.1 255.255.255.0` → `no shutdown`\n"
                "• `ip dhcp pool LAN1` → `network 192.168.10.0 255.255.255.0`\n"
                "• `show ip interface brief` | `show ip route` | `show run`"
            ), [("🧪 Mở Phòng Lab Cisco", "lab_basic"), ("🏢 Dựng Lab 2 Phòng ban", "lab_2dept")]

        # 4. Hỏi về tách mạng / đổi mạng chồng chéo
        if any(k in low for k in ("chồng chéo", "tách mạng", "tách subnet", "đổi mạng", "mạng cũ")):
            _separate_subnets_side_by_side_v8(self.app)
            return "✅ Mình vừa tự động tách các dải mạng (Subnet) trên sơ đồ sang 2 bên Trái / Phải gọn gàng cho bạn rồi nhé!", []

        # 5. Nếu đã bật Ollama Local LLM → gọi AI thật trước khi rơi về fallback
        if self._ollama_enabled:
            llm_ans = self._query_ollama_local(raw_q)
            if llm_ans:
                return llm_ans, [("📊 Phân tích mạng", "live_audit"), ("🧪 Mở Phòng Lab", "lab_basic")]

        return super()._analyze_query(raw_q)

    def open_chat(self, from_lab: bool = False) -> None:
        super().open_chat(from_lab=from_lab)
        # Thêm nút '⚙ AI Local (Ollama)' trên thanh header của cửa sổ chat LanBot
        try:
            w = self._chat_win
            if w and w.winfo_exists() and not getattr(w, "_v8_ai_btn", False):
                w._v8_ai_btn = True
                hdr = w.winfo_children()[0]

                def _cfg_ollama() -> None:
                    d = ctk.CTkToplevel(w)
                    d.title("⚙ Kết nối Local AI (Ollama)")
                    d.geometry("420x210")
                    d.transient(w)
                    ev = ctk.BooleanVar(value=self._ollama_enabled)
                    ctk.CTkSwitch(d, text="Bật Ollama Local LLM (miễn phí, chạy offline trên máy)", variable=ev).pack(anchor="w", padx=16, pady=(14, 8))
                    ctk.CTkLabel(d, text="Tên model Ollama (vd: llama3.2, qwen2.5, gemma2):").pack(anchor="w", padx=16)
                    me = ctk.CTkEntry(d)
                    me.insert(0, self._ollama_model)
                    me.pack(fill="x", padx=16, pady=(2, 12))

                    def _save() -> None:
                        self._ollama_enabled = bool(ev.get())
                        self._ollama_model = me.get().strip() or "llama3.2"
                        d.destroy()

                    ctk.CTkButton(d, text="Lưu cấu hình AI", fg_color="#0284c7", command=_save).pack(padx=16, pady=4)

                ctk.CTkButton(hdr, text="⚙ AI Local", width=76, height=26, fg_color="#334155", command=_cfg_ollama).pack(side="right", padx=4)
        except Exception:
            pass



