import csv as _csv_v9
import socket as _sock_v9
import subprocess as _subp_v9
from tkinter import filedialog as _fd_v9


# --- 1. Xuất Báo cáo CSV ĐẸP (UTF-8 BOM cho Excel + Tổng quan + Bảng thiết bị + Sự cố) ---
def export_pretty_csv_report_v9(app: Any) -> str | None:
    """Xuất file CSV trình bày chuyên nghiệp, mở bằng Excel không lỗi font tiếng Việt."""
    default_name = f"LanMap_BaoCaoMang_{time.strftime('%Y%m%d_%H%M%S')}.csv"
    fpath = _fd_v9.asksaveasfilename(
        parent=app,
        title="Lưu Báo cáo Mạng CSV Chuyên nghiệp",
        initialfile=default_name,
        defaultextension=".csv",
        filetypes=[("CSV (Excel UTF-8)", "*.csv"), ("All files", "*.*")],
    )
    if not fpath:
        return None

    st = getattr(app, "real_state", None)
    devs = list(getattr(st, "devices", []) or [])
    incs = list(getattr(st, "incidents", []) or [])
    sub_cidr = getattr(st, "subnet_cidr", "") or "N/A"
    client_ips = getattr(app, "_lanmap_client_ips", set()) or set()
    security_markers = security_marker_levels(app)
    score, _ = build_live_network_analysis_text(app)

    on_cnt = sum(1 for d in devs if not any(w in str(getattr(d, "status", "")).lower() for w in ("off", "down", "fail", "lost", "alert")))
    off_cnt = len(devs) - on_cnt
    cl_cnt = sum(1 for d in devs if _device_has_lanmap_client(d, client_ips))

    with open(fpath, "w", encoding="utf-8-sig", newline="") as f:
        w = _csv_v9.writer(f)
        # Khối tiêu đề & tổng quan
        w.writerow(["BÁO CÁO QUẢN LÝ & GIÁM SÁT THIẾT BỊ MẠNG NỘI BỘ (LANMAP PRO)"])
        w.writerow(["Thời gian xuất báo cáo", time.strftime("%d/%m/%Y %H:%M:%S"), "Dải mạng (Subnet)", sub_cidr])
        w.writerow(["Điểm sức khỏe mạng", f"{score}/100", "Tổng số thiết bị", len(devs)])
        w.writerow(["Thiết bị Online", on_cnt, "Thiết bị Offline / Cảnh báo", off_cnt])
        w.writerow(["PC đã cài LanMap Client", cl_cnt, "Thiết bị có dấu kiểm tra an toàn", len(security_markers)])
        w.writerow([])

        # Bảng thiết bị chi tiết
        w.writerow(["I. DANH SÁCH CHI TIẾT THIẾT BỊ TRONG MẠNG"])
        w.writerow([
            "STT", "Tên thiết bị", "Địa chỉ IP", "Địa chỉ MAC", "Loại thiết bị",
            "Trạng thái", "Độ trễ (ms)", "LanMap Client", "Độ tin cậy",
            "Kiểm tra an toàn", "Ghi chú",
        ])
        for idx, d in enumerate(devs, 1):
            ip = str(getattr(d, "ip", "") or "")
            st_raw = str(getattr(d, "status", "online") or "online")
            st_nice = "Offline / Mất kết nối" if any(k in st_raw.lower() for k in ("off", "down", "fail", "lost", "alert")) else "Online (Hoạt động)"
            lat = getattr(d, "latency_ms", None)
            lat_s = f"{lat:.1f}" if isinstance(lat, (int, float)) else "-"
            has_cl = "Đã cài (Xanh dương)" if _device_has_lanmap_client(d, client_ips) else "Chưa cài"
            trust_s = "Tin cậy" if getattr(d, "trusted", True) else "Thiết bị lạ (Chưa duyệt)"
            inf_s = security_markers.get(d.id, "Chưa ghi nhận cảnh báo")
            w.writerow([
                idx,
                str(getattr(d, "name", "") or ""),
                ip,
                str(getattr(d, "mac", "") or "-"),
                str(getattr(d, "device_type", "") or "unknown").upper(),
                st_nice,
                lat_s,
                has_cl,
                trust_s,
                inf_s,
                str(getattr(d, "notes", "") or ""),
            ])

        # Bảng Nhật ký sự cố
        if incs:
            w.writerow([])
            w.writerow(["II. NHẬT KÝ SỰ CỐ MẠNG"])
            w.writerow(["STT", "Thời gian", "Loại sự cố", "Thiết bị", "Địa chỉ IP", "Chi tiết"])
            for idx, rec in enumerate(incs, 1):
                w.writerow([
                    idx,
                    str(getattr(rec, "timestamp", "") or ""),
                    str(getattr(rec, "event_type", "") or ""),
                    str(getattr(rec, "device_name", "") or ""),
                    str(getattr(rec, "ip", "") or ""),
                    str(getattr(rec, "message", "") or getattr(rec, "details", "") or ""),
                ])

    messagebox.showinfo("Xuất CSV thành công", f"Đã xuất báo cáo CSV chuyên nghiệp (UTF-8 chuẩn Excel):\n\n{fpath}")
    try:
        if os.name == "nt":
            os.startfile(str(Path(fpath).parent))
    except Exception:
        pass
    return fpath


