def scan_security_inventory(
    devices: list[tuple[str, str, str, str]],
    stop: threading.Event,
    progress: Callable[[int, int], None],
) -> tuple[list[SecurityFinding], set[str], str]:
    """Kiểm tra các cổng đã định trên thiết bị được chọn, theo từng lô nhỏ."""
    def probe(item: tuple[str, str, str, str]) -> tuple[str, list[SecurityFinding], bool]:
        did, name, ip, kind = item
        items = []
        for port, (title, reason, remedy) in _SECURITY_PORTS.items():
            if stop.is_set():
                break
            if check_tcp_port(ip, port, timeout=0.24):
                expected = port in (445, 3389) and kind in (TYPE_PC, TYPE_THIS_PC, TYPE_SERVER)
                items.append(SecurityFinding(
                    "Thông tin" if expected else "Cần xem lại", f"{name} ({ip})",
                    f"TCP {port} kết nối được · Gợi ý {title}",
                    "LanMap thiết lập được kết nối TCP từ máy quét. Cần kiểm tra cấu hình thiết bị để xác định dịch vụ.\n\n"
                    + reason, remedy, did,
                ))
        return did, items, not stop.is_set()

    pending = iter(devices)
    findings: list[SecurityFinding] = []
    checked: set[str] = set()
    with ThreadPoolExecutor(max_workers=10) as pool:
        while not stop.is_set():
            batch = list(islice(pending, 20))
            if not batch:
                break
            jobs = [pool.submit(probe, item) for item in batch]
            for job in as_completed(jobs):
                if stop.is_set():
                    for queued in jobs:
                        queued.cancel()
                    break
                did, items, complete = job.result()
                if complete:
                    findings.extend(items)
                    checked.add(did)
                    progress(len(checked), len(devices))
    alerts = sum(f.level == "Cần xem lại" for f in findings)
    return findings, checked, (
        f"Đã thử các cổng trong danh sách trên {len(checked)}/{len(devices)} thiết bị. "
        f"Có {alerts} dấu hiệu cần xem lại. Timeout có thể do máy, đường mạng hoặc firewall."
    )


def read_windows_defender(quick_scan: bool, stop: threading.Event) -> dict[str, Any]:
    if sys.platform != "win32":
        raise RuntimeError("Microsoft Defender khả dụng trên Windows.")
    powershell = Path(os.environ.get("SystemRoot", r"C:\Windows")) / "System32" / "WindowsPowerShell" / "v1.0" / "powershell.exe"
    if not powershell.is_file():
        raise RuntimeError("Không tìm thấy Windows PowerShell để đọc trạng thái Defender.")
    script = (
        "$ErrorActionPreference='Stop'; "
        "[Console]::OutputEncoding=[System.Text.Encoding]::UTF8; "
        "$s=Get-MpComputerStatus; "
        "$t=@(Get-MpThreat | Select-Object ThreatID,ThreatName,IsActive,DidThreatExecute); "
        "$d=@(Get-MpThreatDetection | Sort-Object InitialDetectionTime -Descending | Select-Object -First 25 "
        "ThreatID,ActionSuccess,Resources,@{n='Time';e={if ($_.InitialDetectionTime) {$_.InitialDetectionTime.ToString('yyyy-MM-dd HH:mm:ss')}}}); "
        "@{antivirus=$s.AntivirusEnabled; realtime=$s.RealTimeProtectionEnabled; threats=$t; history=$d} "
        "| ConvertTo-Json -Depth 5 -Compress"
    )
    if quick_scan:
        script = "$ErrorActionPreference='Stop'; $null=Start-MpScan -ScanType QuickScan; " + script
    deadline = time.monotonic() + (1200 if quick_scan else 35)
    with subprocess.Popen(
        [str(powershell), "-NoProfile", "-NonInteractive", "-Command", script],
        stdout=subprocess.PIPE, stderr=subprocess.PIPE, creationflags=_subproc_flags(),
    ) as proc:
        try:
            while not stop.is_set() and time.monotonic() < deadline:
                try:
                    out, err = proc.communicate(timeout=0.25)
                except subprocess.TimeoutExpired:
                    continue
                if proc.returncode:
                    detail = err.decode("utf-8", errors="replace").strip().splitlines()
                    raise RuntimeError(detail[0][:270] if detail else "Defender từ chối yêu cầu hoặc chưa sẵn sàng.")
                result = json.loads(out.decode("utf-8-sig"))
                if not isinstance(result, dict) or not isinstance(result.get("threats"), list):
                    raise RuntimeError("Windows không trả về báo cáo Defender hợp lệ.")
                return result
            if stop.is_set():
                return {}
            raise TimeoutError("Hết thời gian chờ Defender. Kiểm tra tiến trình quét trong Bảo mật Windows.")
        finally:
            if proc.poll() is None:
                proc.kill()
                proc.communicate()


def defender_findings(
    data: dict[str, Any], local_id: str, quick_scan: bool = False,
) -> tuple[list[SecurityFinding], str]:
    rows = []
    by_threat: dict[Any, dict[str, Any]] = {}
    for record in data.get("history") or []:
        by_threat.setdefault(record.get("ThreatID"), record)

    def evidence_for(record: dict[str, Any]) -> list[str]:
        items = []
        if record.get("Time"):
            items.append(f"Thời điểm ghi nhận: {record['Time']}")
        action = record.get("ActionSuccess")
        if isinstance(action, bool):
            items.append("Hành động xử lý thành công" if action else "Hành động xử lý chưa thành công")
        resources = record.get("Resources") or []
        if isinstance(resources, str):
            resources = [resources]
        if resources:
            items.append("Tài nguyên Defender báo cáo")
            items.extend(f"• {resource}" for resource in resources)
        return items

    windows_history = "Mở Bảo mật Windows → Bảo vệ khỏi vi-rút và mối đe dọa → Lịch sử bảo vệ."
    for threat in data["threats"]:
        detection = by_threat.pop(threat.get("ThreatID"), {})
        active = threat.get("IsActive")
        executed = threat.get("DidThreatExecute")
        action_failed = detection.get("ActionSuccess") is False
        name = str(threat.get("ThreatName") or threat.get("ThreatID") or "Mục phát hiện Defender")
        evidence = [f"Microsoft Defender · {name}"]
        if active is True:
            evidence.append("Trạng thái: đang hoạt động")
        elif active is False:
            evidence.append("Trạng thái: không còn hoạt động")
        else:
            evidence.append("Trạng thái: chưa rõ")
        if executed is True:
            evidence.append("Defender ghi nhận mối đe dọa đã chạy")
        elif executed is False:
            evidence.append("Defender không ghi nhận mối đe dọa đã chạy")
        evidence.extend(evidence_for(detection))

        if active is True:
            level = "Defender cảnh báo"
            reason = ("Công cụ chống mã độc của Windows đã ghi nhận đối tượng và báo còn hoạt động. "
                      "Tên phát hiện và tài nguyên phía trên giúp bạn đối chiếu đúng mục trong Lịch sử bảo vệ.")
        elif action_failed or active is None:
            level = "Cần xem lại"
            reason = ("Defender ghi nhận lần phát hiện này. Hãy xem trạng thái trong Lịch sử bảo vệ "
                      "để biết hành động còn chờ hoặc kiểm tra nguyên nhân xử lý chưa thành công.")
        else:
            level = "Thông tin"
            reason = ("Defender ghi nhận lần phát hiện trong lịch sử và trạng thái hiện tại là không còn hoạt động. "
                      "Lịch sử có thể giữ lại bản ghi sau khi tệp đã bị chặn hoặc cách ly.")

        if level != "Thông tin":
            remedy = (
                f"1. {windows_history} Chọn mục theo tên và thời gian phía trên.\n"
                "2. Đọc trạng thái và áp dụng hành động Defender đề xuất. Nếu đã báo cách ly, giữ tệp trong vùng cách ly khi chưa xác minh nguồn.\n"
                "3. Cập nhật thông tin bảo mật rồi quét lại. Nếu Defender vẫn báo còn hoạt động, kiểm tra "
                "Tùy chọn quét → Quét toàn bộ hoặc Quét ngoại tuyến. Quét ngoại tuyến sẽ khởi động lại máy.\n"
                "4. Nếu phát hiện đã chạy hoặc kết quả lặp lại trên máy công ty, gửi tên phát hiện, "
                "thời điểm và tài nguyên cho bộ phận IT để họ kiểm tra phạm vi ảnh hưởng."
            )
        else:
            remedy = (
                f"1. {windows_history} Kiểm tra xem Windows ghi đã chặn, cách ly hay đã loại bỏ.\n"
                "2. Đối chiếu đường dẫn với nguồn tệp đã tải. Giữ nguyên mục cách ly khi chưa xác minh được nguồn.\n"
                "3. Nếu xuất hiện lại sau khi cập nhật và quét, chuyển thông tin phát hiện cho người quản trị."
            )
        rows.append(SecurityFinding(level, "Máy này", "\n".join(evidence), reason, remedy, local_id))
    for threat_id, detection in by_threat.items():
        failed = detection.get("ActionSuccess") is False
        evidence = [f"Lịch sử Defender · Mã {threat_id}", *evidence_for(detection)]
        rows.append(SecurityFinding(
            "Cần xem lại" if failed else "Thông tin", "Máy này", "\n".join(evidence),
            "Defender có bản ghi phát hiện nhưng báo cáo hiện tại thiếu trạng thái tương ứng.",
            f"1. {windows_history} Đối chiếu thời điểm và tài nguyên.\n"
            "2. Nếu mục đang chờ hoặc xử lý thất bại, áp dụng hành động Defender đề xuất rồi cập nhật và quét lại.",
            local_id,
        ))
    antivirus, realtime = data.get("antivirus"), data.get("realtime")
    if antivirus is False or realtime is False:
        state = {True: "đang bật", False: "đang tắt", None: "chưa rõ"}
        rows.append(SecurityFinding(
            "Cần xem lại", "Máy này",
            f"Chống mã độc Defender {state[antivirus]} · Bảo vệ thời gian thực {state[realtime]}",
            "Máy có thể đang dùng nhà cung cấp bảo mật khác, có chính sách doanh nghiệp hoặc bị tắt một lớp bảo vệ.",
            "1. Trong Bảo mật Windows, kiểm tra nhà cung cấp bảo vệ đang hoạt động.\n"
            "2. Nếu máy dùng Defender và tính năng bị tắt ngoài dự kiến, liên hệ IT hoặc bật lại theo chính sách của máy.\n"
            "3. Xem phần cập nhật bảo vệ và kiểm tra trạng thái lại sau khi hoàn tất.",
            local_id,
        ))
    active_count = sum(f.level == "Defender cảnh báo" for f in rows)
    prefix = "Quét nhanh đã trả kết quả" if quick_scan else "Lịch sử Defender đã đọc"
    return rows, f"{prefix} · Máy này · {active_count} mục đang hoạt động · {len(rows)} mục để xem."

def inspect_local_security_connections(stop: threading.Event) -> tuple[list[SecurityFinding], str]:
    if psutil is None:
        raise RuntimeError("Cần psutil để đọc kết nối của máy này.")
    before = psutil.net_io_counters()
    started = time.monotonic()
    if stop.wait(0.6):
        return [], ""
    after = psutil.net_io_counters()
    upload = max(0, after.bytes_sent - before.bytes_sent) / max(0.1, time.monotonic() - started) / 1024 if before and after else None
    rows = []
    seen = set()
    for conn in psutil.net_connections(kind="inet"):
        if stop.is_set():
            break
        if not conn.raddr or conn.status != psutil.CONN_ESTABLISHED:
            continue
        host, port = conn.raddr.ip, conn.raddr.port
        if not ipaddress.ip_address(host.split("%")[0]).is_global:
            continue
        key = conn.pid, host, port
        if key in seen:
            continue
        seen.add(key)
        try:
            proc_name = psutil.Process(conn.pid).name() if conn.pid else "Chưa rõ tiến trình"
        except (psutil.Error, OSError):
            proc_name = "Chưa rõ tiến trình"
        unusual = port in (4444, 1337, 31337, 5555, 6667)
        rows.append(SecurityFinding(
            "Cần xem lại" if unusual else "Thông tin",
            f"{proc_name} · PID {conn.pid or '—'}", f"Đích {host} · TCP {port} · Đang kết nối",
            "Kết nối từ máy này đến địa chỉ ngoài LAN. Số cổng và tốc độ tải lên không cho biết nội dung truyền.",
            "Đối chiếu tiến trình trong Trình quản lý tác vụ và kiểm tra đường dẫn tệp nếu bạn không nhận ra ứng dụng.",
        ))
        if len(rows) >= 200:
            break
    rate = f" · Upload tổng {upload:.0f} KiB/s" if upload is not None else ""
    return rows, f"Kết nối máy này · {len(rows)} bản ghi (tối đa 200){rate}."


class ThreatAndExfilScannerDialog(ctk.CTkToplevel):
    def __init__(self, master: ctk.CTk) -> None:
        super().__init__(master)
        self.app = master
        self.title("🔎 Kiểm tra an toàn mạng & Microsoft Defender")
        self.minsize(772, 523)
        self.transient(master)
        self.protocol("WM_DELETE_WINDOW", self._close)
        self._cancel = threading.Event()
        self._events: queue.Queue = queue.Queue()
        self._running = False
        self._closing = False
        self._session = ""
        self._rows: list[SecurityFinding] = []
        self._displayed = 0
        self._summary = ""

        bar = ctk.CTkFrame(self, fg_color="transparent")
        bar.pack(fill="x", padx=14, pady=(14, 6))
        self._mode_buttons = []
        for label, mode in (
            ("Kiểm tra LAN", "lan"), ("Lịch sử Defender", "defender"),
            ("Quét nhanh Defender", "quick"), ("Kết nối máy này", "connections"),
        ):
            button = ctk.CTkButton(bar, text=label, width=137, command=lambda m=mode: self._start(m))
            button.pack(side="left", padx=(0, 6))
            self._mode_buttons.append(button)
        self.cancel_btn = ctk.CTkButton(bar, text="Dừng", width=73, state="disabled", command=self._stop)
        self.cancel_btn.pack(side="right")
        help_row = ctk.CTkFrame(self, fg_color="transparent")
        help_row.pack(fill="x", padx=14, pady=(0, 6))
        ctk.CTkLabel(
            help_row, text="LAN kiểm tra máy tính, laptop và camera IP · Defender quét máy Windows này",
            anchor="w", justify="left", font=ctk.CTkFont(size=12, weight="bold"),
        ).pack(side="left", fill="x", expand=True)
        ctk.CTkButton(help_row, text="Giải thích", width=95, command=self._show_guide).pack(side="right")
        self.status = ctk.CTkLabel(self, text="Chọn kiểu kiểm tra phía trên. Bấm một kết quả để xem các bước xử lý.", anchor="w", wraplength=730, justify="left")
        self.status.pack(fill="x", padx=15, pady=(0, 4))
        self.progress = ctk.CTkProgressBar(self)
        self.progress.set(0)
        self.progress.pack(fill="x", padx=15, pady=(0, 8))

        listing = ctk.CTkFrame(self)
        listing.pack(fill="both", expand=True, padx=14)
        self.table = ttk.Treeview(listing, columns=("level", "subject", "evidence"), show="headings", height=8, selectmode="browse")
        for col, title, width in (("level", "Mức", 148), ("subject", "Thiết bị / Tiến trình", 212), ("evidence", "Bằng chứng", 360)):
            self.table.heading(col, text=title)
            self.table.column(col, width=width, minwidth=85, stretch=col != "level")
        self.table.pack(side="left", fill="both", expand=True)
        scroll = ttk.Scrollbar(listing, orient="vertical", command=self.table.yview)
        scroll.pack(side="right", fill="y")
        self.table.configure(yscrollcommand=scroll.set)
        self.table.bind("<<TreeviewSelect>>", self._details)
        self.detail = ctk.CTkTextbox(self, height=235, wrap="word", font=ctk.CTkFont(size=13), state="disabled")
        self.detail.pack(fill="both", expand=True, padx=14, pady=(8, 6))
        bottom = ctk.CTkFrame(self, fg_color="transparent")
        bottom.pack(fill="x", padx=14, pady=(0, 12))
        ctk.CTkButton(bottom, text="Xuất báo cáo TXT", width=142, command=self._export).pack(side="right")
        self.more_btn = ctk.CTkButton(bottom, text="Xem thêm", width=112, state="disabled", command=self._append_results)
        self.more_btn.pack(side="left", padx=(8, 0))
        ctk.CTkButton(bottom, text="Mở Bảo mật Windows", width=161, command=self._open_windows_security).pack(side="right", padx=8)
        ctk.CTkButton(bottom, text="Xóa dấu trên sơ đồ", width=140, fg_color="#475569",
                      command=self._clear_markers).pack(side="left")
        self._detail_text(_SECURITY_GUIDE)
        _fit_dialog(self, master, 920, 680)

    def _show_guide(self) -> None:
        if self.table.selection():
            self.table.selection_remove(*self.table.selection())
        self._detail_text(_SECURITY_GUIDE)

    def _detail_text(self, text: str) -> None:
        self.detail.configure(state="normal")
        self.detail.delete("1.0", "end")
        self.detail.insert("1.0", text)
        self.detail.yview_moveto(0)
        self.detail.configure(state="disabled")

    def _lan_targets(self) -> list[tuple[str, str, str, str]]:
        state = self.app.real_state
        devices = []
        seen = set()
        try:
            allowed = [ipaddress.IPv4Network(state.selected_subnet, strict=False)]
        except ValueError:
            return devices
        if state.vlan_scan_inputs.strip():
            try:
                allowed.extend(parse_inventory_networks(state.vlan_scan_inputs))
            except ValueError:
                pass
        for d in state.devices:
            kind = TYPE_THIS_PC if d.is_this_pc else normalize_device_type(d.device_type)
            if (
                not d.registered or d.is_gateway or kind not in _SECURITY_LAN_TYPES
                or not d.ip or d.ip == state.selected_gateway or d.ip in seen
            ):
                continue
            try:
                ip = ipaddress.IPv4Address(d.ip)
            except ValueError:
                continue
            if ip.is_multicast or ip.is_unspecified or ip.is_loopback or ip.is_global or ip.is_reserved or not any(ip in net for net in allowed):
                continue
            seen.add(d.ip)
            devices.append((d.id, d.name, d.ip, kind))
        return devices

    def _start(self, mode: str) -> None:
        if self._running or getattr(self.app, "_security_busy", False):
            self.status.configure(text="Đang có một phiên kiểm tra. Hãy chờ hoặc bấm Dừng ở cửa sổ đang chạy.")
            return
        if mode == "lan" and self.app.demo_mode:
            self.status.configure(text="Chế độ demo · Đang hiện báo cáo mô phỏng.")
            self._show_results([
                SecurityFinding(
                    "Cần xem lại", "Camera cổng chính · Mô phỏng", "TCP 23 phản hồi · Telnet",
                    _SECURITY_PORTS[23][1], _SECURITY_PORTS[23][2],
                ),
                SecurityFinding(
                    "Thông tin", "Máy trạm · Mô phỏng", "TCP 445 phản hồi · SMB",
                    _SECURITY_PORTS[445][1], _SECURITY_PORTS[445][2],
                ),
            ], "Mô phỏng · 2 dấu hiệu minh họa.")
            return
        local = next((d for d in self.app.real_state.devices if d.is_this_pc), None)
        local_id = local.id if local else ""
        targets = []
        if mode == "lan":
            if not self.app.real_state.network_authorized:
                self.status.configure(text="Hãy xác nhận card mạng trong Chọn mạng trước khi kiểm tra LAN.")
                return
            targets = self._lan_targets()
            if not targets:
                self._show_results([], "Chưa có máy tính, laptop hoặc camera IP nào có IPv4 thuộc dải đã chọn.")
                self._detail_text("Thêm thiết bị lên sơ đồ hoặc chỉnh đúng Loại thiết bị trong mục Sửa rồi kiểm tra lại.")
                self.progress.set(0)
                return
        if mode in ("defender", "quick") and sys.platform != "win32":
            self.status.configure(text="Microsoft Defender khả dụng khi chạy LanMap trên Windows.")
            return

        self._session = mode
        self._cancel.clear()
        self._running = self.app._security_busy = True
        for button in self._mode_buttons:
            button.configure(state="disabled")
        self.cancel_btn.configure(state="normal")
        self.status.configure(text={
            "lan": f"Đang kiểm tra {len(targets)} máy tính, laptop và camera IP trong dải đã chọn…",
            "quick": "Đang chờ Microsoft Defender quét nhanh máy Windows này…",
            "defender": "Đang đọc lịch sử và trạng thái Microsoft Defender trên máy Windows này…",
            "connections": "Đang đối chiếu kết nối ra ngoài LAN với tiến trình trên máy này…",
        }[mode])
        self.progress.set(0)
        if mode != "lan":
            self.progress.configure(mode="indeterminate")
            self.progress.start()

        def worker() -> None:
            try:
                if mode == "lan":
                    rows, checked, summary = scan_security_inventory(
                        targets, self._cancel, lambda n, total: self._events.put(("progress", (n, total))),
                    )
                elif mode == "connections":
                    rows, summary = inspect_local_security_connections(self._cancel)
                    checked = set()
                else:
                    data = read_windows_defender(mode == "quick", self._cancel)
                    rows, summary = defender_findings(data, local_id, quick_scan=mode == "quick") if data else ([], "")
                    checked = {local_id} if local_id else set()
                self._events.put(("done", (rows, checked, summary)))
            except Exception as exc:
                self._events.put(("error", str(exc)))

        threading.Thread(target=worker, daemon=True).start()
        self.after(100, self._poll)

    def _stop(self) -> None:
        self._cancel.set()
        self.cancel_btn.configure(state="disabled")
        self.status.configure(text="Đang dừng. Phiên Defender có thể tiếp tục trong Bảo mật Windows." if self._session == "quick" else "Đang dừng…")

    def _poll(self) -> None:
        latest = None
        for _ in range(250):
            try:
                kind, value = self._events.get_nowait()
            except queue.Empty:
                break
            if kind == "progress":
                latest = value
                continue
            self._running = self.app._security_busy = False
            self.progress.stop()
            if self._closing:
                self.destroy()
                return
            self.progress.configure(mode="determinate")
            for button in self._mode_buttons:
                button.configure(state="normal")
            self.cancel_btn.configure(state="disabled")
            if self._cancel.is_set():
                self.status.configure(text="Đã dừng chờ. Kiểm tra Bảo mật Windows nếu Defender vẫn đang quét." if self._session == "quick" else "Đã dừng phiên kiểm tra.")
            elif kind == "error":
                self.status.configure(text=f"Không lấy được kết quả. {value}")
                if self._session in ("quick", "defender"):
                    self._detail_text(
                        "Mở Bảo mật Windows để kiểm tra Defender đang hoạt động hay máy dùng phần mềm chống mã độc khác. "
                        "Nếu Windows báo thiếu quyền, thử kiểm tra trực tiếp trong Bảo mật Windows hoặc hỏi người quản trị máy."
                    )
            else:
                rows, checked, summary = value
                self.progress.set(1)
                self._show_results(rows, summary)
                if self._session != "connections" and not self.app.demo_mode:
                    sources = self.app._security_indicators
                    channel = "lan" if self._session == "lan" else "defender"
                    marks = sources.setdefault(channel, {})
                    for did in checked:
                        marks.pop(did, None)
                    for f in sorted(rows, key=lambda f: _SECURITY_RANK[f.level], reverse=True):
                        if f.device_id and f.level in _SECURITY_COLORS:
                            marks[f.device_id] = f.level
                    self.app.topology._schedule_redraw()
            return
        if latest and not self._cancel.is_set():
            n, total = latest
            self.progress.set(n / total)
            self.status.configure(text=f"Đã kiểm tra {n}/{total} thiết bị")
        self.after(100, self._poll)

    def _show_results(self, rows: list[SecurityFinding], summary: str) -> None:
        self._rows = sorted(rows, key=lambda v: (_SECURITY_RANK[v.level], v.subject.casefold(), v.evidence))
        self._summary = summary
        self.status.configure(text=summary)
        self.table.delete(*self.table.get_children())
        self._displayed = 0
        self._append_results()
        if self._rows:
            self.table.selection_set("0")
            self._details()
        else:
            self._detail_text("Phiên kiểm tra chưa ghi nhận dấu hiệu trong phạm vi đã thử. Xem dòng trạng thái để biết phạm vi.")

    def _append_results(self) -> None:
        until = min(len(self._rows), self._displayed + 100)
        for idx in range(self._displayed, until):
            f = self._rows[idx]
            self.table.insert("", "end", iid=str(idx), values=(f.level, f.subject, f.evidence.splitlines()[0]))
        self._displayed = until
        self.more_btn.configure(text=f"{until}/{len(self._rows)} · Xem thêm" if until < len(self._rows) else "Xem thêm",
                                state="normal" if until < len(self._rows) else "disabled")

    def _details(self, _event: Any = None) -> None:
        selection = self.table.selection()
        if selection and int(selection[0]) < len(self._rows):
            self._detail_text(self._format_finding(self._rows[int(selection[0])]))

    @staticmethod
    def _format_finding(f: SecurityFinding) -> str:
        return (f"{f.subject}  ·  {f.level}\n\nBằng chứng\n{f.evidence}\n\n"
                f"Vì sao cần xem\n{f.reason}\n\nCách kiểm tra hoặc khắc phục\n{f.remedy}")

    def _clear_markers(self) -> None:
        self.app._security_indicators.clear()
        self.app.topology._schedule_redraw()

    def _open_windows_security(self) -> None:
        if sys.platform == "win32":
            try:
                os.startfile("windowsdefender:")
            except OSError:
                self.status.configure(text="Mở Bảo mật Windows từ Start để xem Lịch sử bảo vệ.")

    def _export(self) -> None:
        if not self._summary:
            return
        name = filedialog.asksaveasfilename(parent=self, defaultextension=".txt",
                                            initialfile="lanmap-bao-cao-an-toan.txt")
        if name:
            content = f"LanMap · Báo cáo an toàn · {now_str()}\n{self._summary}\n\n"
            content += "\n\n".join(self._format_finding(f) for f in self._rows)
            try:
                Path(name).write_text(content, encoding="utf-8")
            except OSError as exc:
                messagebox.showerror(APP_NAME, str(exc), parent=self)

    def _close(self) -> None:
        if self._running:
            self._closing = True
            self._cancel.set()
            self.withdraw()
        else:
            self.destroy()

def security_marker_levels(app: Any) -> dict[str, str]:
    markers: dict[str, str] = {}
    for channel in getattr(app, "_security_indicators", {}).values():
        for did, level in channel.items():
            if did not in markers or _SECURITY_RANK[level] < _SECURITY_RANK[markers[did]]:
                markers[did] = level
    return markers



# --- 3. Biểu đồ Ping & Uptime Thời gian thực (Live Latency Chart) ---
class LiveLatencyChartDialog(ctk.CTkToplevel):
    """Đồ thị đường theo dõi độ trễ Ping (ms) và tỷ lệ Uptime theo thời gian thực."""

    def __init__(self, master: ctk.CTk) -> None:
        super().__init__(master)
        self.app = master
        self.title("📈 Biểu đồ Ping & Uptime Thời gian thực (Live Monitor)")
        self.geometry("760x440")
        self.transient(master)
        self._running = True
        self._samples: list[float | None] = []
        self.protocol("WM_DELETE_WINDOW", self._close)

        devs = list(getattr(getattr(master, "real_state", None), "devices", []) or [])
        opts = [f"{getattr(d, 'name', '')} ({getattr(d, 'ip', '')})" for d in devs if getattr(d, "ip", "")] or ["Google DNS (8.8.8.8)"]
        top = ctk.CTkFrame(self, fg_color="transparent")
        top.pack(fill="x", padx=12, pady=(10, 6))
        ctk.CTkLabel(top, text="Thiết bị theo dõi:", font=ctk.CTkFont(size=12, weight="bold")).pack(side="left", padx=(0, 6))
        self.sel_var = ctk.StringVar(value=opts[0])
        ctk.CTkOptionMenu(top, width=280, values=opts, variable=self.sel_var, command=lambda _v: self._samples.clear()).pack(side="left", padx=(0, 10))
        self.stat_lbl = ctk.CTkLabel(top, text="Đang đo...", font=ctk.CTkFont(size=12, weight="bold"), text_color="#16a34a")
        self.stat_lbl.pack(side="right")

        self.cv = tk.Canvas(self, bg="#0f172a", highlightthickness=1, highlightbackground="#334155")
        self.cv.pack(fill="both", expand=True, padx=12, pady=(0, 12))
        self._tick()

    def _current_ip(self) -> str:
        m = re.search(r"\(([^)]+)\)", self.sel_var.get())
        return m.group(1) if m else "8.8.8.8"

    def _tick(self) -> None:
        if not self._running or not self.winfo_exists():
            return
        ip = self._current_ip()

        def _bg() -> None:
            ms: float | None = None
            try:
                si = _subp_v9.STARTUPINFO() if os.name == "nt" else None
                if si:
                    si.dwFlags |= _subp_v9.STARTF_USESHOWWINDOW
                p = _subp_v9.run(
                    ["ping", "-n" if os.name == "nt" else "-c", "1", "-w" if os.name == "nt" else "-W", "900", ip],
                    capture_output=True, text=True, timeout=2.5,
                    startupinfo=si,
                    creationflags=getattr(_subp_v9, "CREATE_NO_WINDOW", 0) if os.name == "nt" else 0,
                )
                if p.returncode == 0 and ("TTL=" in p.stdout.upper() or "time=" in p.stdout.lower() or "time<" in p.stdout.lower()):
                    m = re.search(r"time[=<]\s*(\d+)\s*ms", p.stdout, re.I)
                    ms = float(m.group(1)) if m else 1.0
            except Exception:
                ms = None
            self.after(0, lambda: self._push(ms))

        threading.Thread(target=_bg, daemon=True).start()
        self.after(1500, self._tick)

    def _push(self, ms: float | None) -> None:
        if not self.winfo_exists():
            return
        self._samples.append(ms)
        if len(self._samples) > 45:
            self._samples = self._samples[-45:]
        ok_vals = [x for x in self._samples if x is not None]
        uptime = (len(ok_vals) / max(1, len(self._samples))) * 100.0
        avg = sum(ok_vals) / len(ok_vals) if ok_vals else 0.0
        cur_txt = f"{ms:.0f} ms" if ms is not None else "TIMEOUT"
        self.stat_lbl.configure(
            text=f"Hiện tại: {cur_txt} | TB: {avg:.1f} ms | Uptime: {uptime:.1f}%",
            text_color="#16a34a" if ms is not None else "#ef4444",
        )
        c = self.cv
        c.delete("all")
        w, h = max(400, c.winfo_width()), max(220, c.winfo_height())
        pad_l, pad_r, pad_t, pad_b = 46, 18, 22, 28
        max_ms = max(50.0, max(ok_vals) * 1.25) if ok_vals else 100.0

        for frac in (0.0, 0.25, 0.5, 0.75, 1.0):
            y = pad_t + (h - pad_t - pad_b) * frac
            val = max_ms * (1.0 - frac)
            c.create_line(pad_l, y, w - pad_r, y, fill="#1e293b", dash=(2, 4))
            c.create_text(pad_l - 6, y, text=f"{val:.0f}", fill="#94a3b8", anchor="e", font=("Consolas", 8))

        pts = []
        n = len(self._samples)
        step_x = (w - pad_l - pad_r) / max(1, 44)
        for i, v in enumerate(self._samples):
            x = pad_l + i * step_x
            if v is None:
                c.create_line(x, pad_t, x, h - pad_b, fill="#ef4444", dash=(2, 2))
                pts = []
            else:
                y = h - pad_b - (v / max_ms) * (h - pad_t - pad_b)
                pts.append((x, y))
                if len(pts) >= 2:
                    c.create_line(pts[-2][0], pts[-2][1], x, y, fill="#38bdf8", width=2.4)
                c.create_oval(x - 3, y - 3, x + 3, y + 3, fill="#22c55e" if v < 60 else "#f59e0b", outline="")

    def _close(self) -> None:
        self._running = False
        self.destroy()


# --- 4. Sửa TRIỆT ĐỂ Cisco IOS CLI & PC CMD tương tác trực tiếp (Enter chạy + Ctrl+C dừng!) ---
_orig_lab_cls_v8 = NetworkLabDialog


class NetworkLabDialog(_orig_lab_cls_v8):
    """Phòng Lab v9.0: Gõ trực tiếp lệnh trong khung đen Terminal, bấm Enter chạy, bấm Ctrl+C / Ctrl+Z dừng ngay!"""

    def _make_interactive_terminal(self, parent: Any, fg_col: str, banner: str, get_prompt: Any, handle_cmd: Any, on_ctrl_c: Any) -> ctk.CTkTextbox:
        tb = ctk.CTkTextbox(parent, fg_color="#020617", text_color=fg_col, font=ctk.CTkFont(family="Consolas", size=11))
        tb.pack(fill="both", expand=True, padx=4, pady=4)
        raw_t = tb._textbox  # tk.Text gốc bên trong CTkTextbox
        history: list[str] = []
        hist_idx = [-1]

        raw_t.insert("end", banner + "\n\n" + get_prompt())
        raw_t.mark_set("prompt_end", "end-1c")
        raw_t.mark_gravity("prompt_end", "left")

        def _ensure_cursor_after_prompt() -> None:
            if raw_t.compare("insert", "<", "prompt_end"):
                raw_t.mark_set("insert", "end")

        def _on_key(e: tk.Event) -> str | None:
            # Cho phép Ctrl+C để dừng lệnh (như Cisco thật!)
            if (e.state & 0x4) and e.keysym.lower() in ("c", "z"):
                raw_t.insert("end", "^C\n")
                on_ctrl_c()
                raw_t.insert("end", get_prompt())
                raw_t.mark_set("prompt_end", "end-1c")
                raw_t.mark_set("insert", "end")
                raw_t.see("end")
                return "break"
            if e.keysym in ("BackSpace", "Left"):
                if raw_t.compare("insert", "<=", "prompt_end"):
                    return "break"
                return None
            if e.keysym == "Home":
                raw_t.mark_set("insert", "prompt_end")
                return "break"
            if e.keysym == "Up":
                if history:
                    hist_idx[0] = max(0, (len(history) - 1) if hist_idx[0] < 0 else hist_idx[0] - 1)
                    raw_t.delete("prompt_end", "end")
                    raw_t.insert("end", history[hist_idx[0]])
                    raw_t.see("end")
                return "break"
            if e.keysym == "Down":
                if history and hist_idx[0] >= 0:
                    hist_idx[0] += 1
                    raw_t.delete("prompt_end", "end")
                    if hist_idx[0] < len(history):
                        raw_t.insert("end", history[hist_idx[0]])
                    else:
                        hist_idx[0] = -1
                    raw_t.see("end")
                return "break"
            if e.keysym in ("Return", "KP_Enter"):
                cmd = raw_t.get("prompt_end", "end-1c").strip()
                raw_t.insert("end", "\n")
                if cmd:
                    history.append(cmd)
                    hist_idx[0] = -1
                    out = handle_cmd(cmd)
                    if out == "__CLS__":
                        raw_t.delete("1.0", "end")
                    elif out:
                        raw_t.insert("end", out.rstrip("\n") + "\n")
                raw_t.insert("end", get_prompt())
                raw_t.mark_set("prompt_end", "end-1c")
                raw_t.mark_set("insert", "end")
                raw_t.see("end")
                return "break"
            if e.char and e.char.isprintable():
                _ensure_cursor_after_prompt()
            return None

        raw_t.bind("<KeyPress>", _on_key)
        raw_t.bind("<Button-1>", lambda _e: self.after(10, _ensure_cursor_after_prompt), add="+")
        return tb

    def _render_router_cfg(self, n: dict[str, Any]) -> None:
        tabs = ctk.CTkTabview(self.cfg_body)
        tabs.pack(fill="both", expand=True)
        t_if = tabs.add("Interfaces & DHCP")
        t_cli = tabs.add("Cisco CLI (Full)")

        # Tab 1: GUI Interfaces & DHCP
        pnames = list(n["ports"].keys())
        sel_p = ctk.StringVar(value=pnames[0])
        p_menu = ctk.CTkOptionMenu(t_if, values=pnames, variable=sel_p)
        p_menu.pack(fill="x", padx=6, pady=(6, 6))

        up_var = ctk.BooleanVar(value=True)
        dhcp_var = ctk.BooleanVar(value=True)
        ctk.CTkSwitch(t_if, text="Port Status (no shutdown)", variable=up_var).pack(anchor="w", padx=6, pady=2)
        ip_e = ctk.CTkEntry(t_if, placeholder_text="Gateway IP")
        ip_e.pack(fill="x", padx=6, pady=(4, 4))
        mask_e = ctk.CTkEntry(t_if, placeholder_text="Subnet Mask")
        mask_e.pack(fill="x", padx=6, pady=(2, 5))
        ctk.CTkSwitch(t_if, text="Bật DHCP Server", variable=dhcp_var).pack(anchor="w", padx=6, pady=3)
        pool_e = ctk.CTkEntry(t_if, placeholder_text="DHCP Start IP")
        pool_e.pack(fill="x", padx=6, pady=(2, 6))

        def _load_port(_v: Any = None) -> None:
            pc = n["ports"][sel_p.get()]
            up_var.set(bool(pc.get("up", True)))
            dhcp_var.set(bool(pc.get("dhcp", False)))
            ip_e.delete(0, "end"); ip_e.insert(0, pc.get("ip", ""))
            mask_e.delete(0, "end"); mask_e.insert(0, pc.get("mask", "255.255.255.0"))
            pool_e.delete(0, "end"); pool_e.insert(0, pc.get("pool_start", ""))

        def _save_port() -> None:
            pc = n["ports"][sel_p.get()]
            pc["up"], pc["dhcp"] = bool(up_var.get()), bool(dhcp_var.get())
            pc["ip"], pc["mask"], pc["pool_start"] = ip_e.get().strip(), mask_e.get().strip() or "255.255.255.0", pool_e.get().strip()
            self._redraw()
            self._log_event(n["name"], sel_p.get(), "IOS", "Cập nhật", f"IP={pc['ip']} | UP={pc['up']} | DHCP={pc['dhcp']}")

        p_menu.configure(command=_load_port)
        _load_port()
        ctk.CTkButton(t_if, text="💾 Lưu cổng Router", fg_color="#0284c7", command=_save_port).pack(fill="x", padx=6, pady=6)

        # Tab 2: Cisco IOS CLI tương tác TRỰC TIẾP (bấm vào khung đen gõ + Enter + Ctrl+C!)
        n.setdefault("_cli_mode", "user")
        n.setdefault("_cli_if", "Gig0/0")
        n.setdefault("_cli_pool", "LAN")
        n.setdefault("static_routes", [])

        def _prompt() -> str:
            m, hn = n["_cli_mode"], n["name"]
            return f"{hn}> " if m == "user" else (f"{hn}# " if m == "priv" else (f"{hn}(config)# " if m == "config" else (f"{hn}(config-if)# " if m == "if" else f"{hn}(dhcp-config)# ")))

        def _resolve_port(raw_if: str) -> str | None:
            s = raw_if.lower().replace("gigabitethernet", "gig").replace("g0/", "gig0/")
            return next((pn for pn in n["ports"] if pn.lower() == s or pn.lower().startswith(s)), None)

        def _handle_ios(raw: str) -> str:
            low = raw.lower()
            parts = raw.split()
            m = n["_cli_mode"]
            if low in ("cls", "clear"):
                return "__CLS__"
            if low in ("?", "help"):
                return (
                    "Lệnh Cisco IOS (gõ trực tiếp + Enter | Ctrl+C để dừng):\n"
                    "  enable (en)                 - Vào chế độ đặc quyền (#)\n"
                    "  configure terminal (conf t) - Vào cấu hình toàn cục\n"
                    "  hostname <Tên>              - Đổi tên Router\n"
                    "  interface gig0/0 (int g0/0) - Vào cổng Router\n"
                    "  ip address <IP> <Mask>      - Gán IP cho cổng\n"
                    "  no shutdown / shutdown      - Bật / Tắt cổng\n"
                    "  ip dhcp pool <Tên>          - Cấu hình DHCP (network, default-router)\n"
                    "  ip route <Net> <Mask> <NH>  - Thêm Static Route\n"
                    "  show ip interface brief | show ip route | show run | ping <IP> | wr"
                )
            if low in ("en", "enable"):
                n["_cli_mode"] = "priv"
                return ""
            if low == "end":
                n["_cli_mode"] = "priv"
                return ""
            if low == "exit":
                n["_cli_mode"] = "config" if m in ("if", "dhcp") else ("priv" if m == "config" else "user")
                return ""
            if low.startswith("conf") and m == "priv":
                n["_cli_mode"] = "config"
                return "Enter configuration commands, one per line. End with Ctrl+C or 'end'."
            if low.startswith("hostname ") and m == "config":
                n["name"] = parts[1]
                self.cfg_header.configure(text=f"⚙ {n['name']}  (ROUTER)")
                self._redraw()
                return ""
            if (low.startswith("int ") or low.startswith("interface ")) and m in ("config", "if"):
                pn = _resolve_port(parts[1]) if len(parts) >= 2 else None
                if pn:
                    n["_cli_if"] = pn
                    n["_cli_mode"] = "if"
                    return ""
                return f"% Invalid interface. Có sẵn: {', '.join(n['ports'].keys())}"
            if low.startswith("ip addr") and m == "if" and len(parts) >= 4:
                pn = n["_cli_if"]
                n["ports"][pn]["ip"], n["ports"][pn]["mask"] = parts[2], parts[3]
                self._redraw(); _load_port()
                self._log_event(n["name"], pn, "CLI", "Đặt IP", f"ip address {parts[2]} {parts[3]}")
                return ""
            if low in ("no sh", "no shut", "no shutdown") and m == "if":
                pn = n["_cli_if"]
                n["ports"][pn]["up"] = True
                self._redraw(); _load_port()
                return f"%LINK-3-UPDOWN: Interface {pn}, changed state to up"
            if low in ("sh", "shut", "shutdown") and m == "if":
                pn = n["_cli_if"]
                n["ports"][pn]["up"] = False
                self._redraw(); _load_port()
                return f"%LINK-5-CHANGED: Interface {pn}, changed state to administratively down"
            if low.startswith("ip dhcp pool ") and m == "config":
                n["_cli_pool"] = parts[3]
                n["_cli_mode"] = "dhcp"
                return ""
            if low.startswith("network ") and m == "dhcp" and len(parts) >= 3:
                try:
                    net = ipaddress.IPv4Network(f"{parts[1]}/{parts[2]}", strict=False)
                    for pn, pc in n["ports"].items():
                        if pc.get("ip") and ipaddress.IPv4Address(pc["ip"]) in net:
                            pc["dhcp"] = True
                            pc["pool_start"] = str(list(net.hosts())[9])
                            _load_port()
                            return f"✓ Đã bật DHCP Pool '{n['_cli_pool']}' trên cổng {pn} ({net})"
                except Exception as exc:
                    return f"% Lỗi: {exc}"
            if low.startswith("default-router ") and m == "dhcp" and len(parts) >= 2:
                return f"✓ Default-router set to {parts[1]}"
            if low.startswith("ip route ") and m == "config" and len(parts) >= 5:
                n["static_routes"].append((parts[2], parts[3], parts[4]))
                return f"✓ Static Route: {parts[2]} {parts[3]} via {parts[4]}"
            if low in ("wr", "write", "write memory", "copy run start"):
                return "Building configuration...\n[OK]"
            if (low.startswith("sh ") or low.startswith("show ") or low.startswith("do sh")) and "int" in low:
                out_l = ["Interface    IP-Address       Status        DHCP"]
                for pn, pc in n["ports"].items():
                    out_l.append(f"{pn:<12} {(pc.get('ip') or 'unassigned'):<16} {'up' if pc.get('up') else 'admin down':<13} {'ON' if pc.get('dhcp') else 'OFF'}")
                return "\n".join(out_l)
            if (low.startswith("sh ") or low.startswith("show ") or low.startswith("do sh")) and "rou" in low:
                out_l = []
                for pn, pc in n["ports"].items():
                    if pc.get("up") and pc.get("ip"):
                        net = ipaddress.IPv4Network(f"{pc['ip']}/{pc.get('mask', '255.255.255.0')}", strict=False)
                        out_l.append(f"C   {net} is directly connected, {pn}")
                for dst_n, dst_m, nh in n["static_routes"]:
                    out_l.append(f"S   {dst_n} {dst_m} via {nh}")
                return "\n".join(out_l) or "(Chưa có tuyến định tuyến)"
            if (low.startswith("sh ") or low.startswith("show ") or low.startswith("do sh")) and "run" in low:
                out_l = [f"hostname {n['name']}", "!"]
                for pn, pc in n["ports"].items():
                    out_l.append(f"interface {pn}")
                    if pc.get("ip"):
                        out_l.append(f" ip address {pc['ip']} {pc.get('mask', '255.255.255.0')}")
                    out_l.append(f" {'no shutdown' if pc.get('up') else 'shutdown'}")
                    out_l.append("!")
                return "\n".join(out_l)
            if low.startswith("ping ") or low.startswith("do ping "):
                dst_nid = self._find_node_by_ip(parts[-1])
                return self._run_ping_between(n["id"], dst_nid)[1] if dst_nid else "..... (0% success rate)"
            return f"% Lệnh chưa hợp lệ ở chế độ '{m}'. Gõ '?' để xem danh sách lệnh!"

        self._make_interactive_terminal(
            t_cli, "#38bdf8",
            "Cisco IOS CLI (Gõ trực tiếp tại đây + Enter | Ctrl+C để dừng | ↑↓ lịch sử lệnh)\nGõ '?' để xem hướng dẫn.",
            _prompt, _handle_ios,
            lambda: n.__setitem__("_cli_mode", "priv" if n["_cli_mode"] in ("config", "if", "dhcp") else n["_cli_mode"]),
        )


# --- 5. Tự động thêm thiết bị MỚI vào sơ đồ + Vẽ vòng SÁNG ĐỎ (☣) máy nghi nhiễm Virus ---
def _install_v9_app_hooks(app: Any) -> None:
    if getattr(app, "_v9_installed", False):
        return
    app._v9_installed = True
    app._security_indicators = {}

    topo = getattr(app, "topology", None)
    t_canvas = topo if isinstance(topo, tk.Canvas) else getattr(topo, "canvas", None)

    # 5A. Bọc redraw() để vẽ hào quang SÁNG ĐỎ (☣) quanh các thiết bị nghi nhiễm Virus / Tẩu tán dữ liệu!
    if topo and t_canvas and hasattr(topo, "redraw"):
        prev_redraw = topo.redraw

        def _v9_redraw(*args: Any, **kwargs: Any) -> Any:
            res = prev_redraw(*args, **kwargs)
            try:
                t_canvas.delete("v9_virus_glow")
                markers = security_marker_levels(app)
                width, height = t_canvas.winfo_width(), t_canvas.winfo_height()
                if not app.demo_mode and markers:
                    radius = max(8.0, 30.0 * topo.scale)
                    for d in topo._visible_devices:
                        level = markers.get(d.id)
                        if level is None:
                            continue
                        sx, sy = _topo_world_to_screen(topo, d.x, d.y)
                        if not (-radius <= sx <= width + radius and -radius <= sy <= height + radius):
                            continue
                        color = _SECURITY_COLORS[level]
                        t_canvas.create_oval(sx - radius, sy - radius, sx + radius, sy + radius,
                                             outline=color, width=2.2, tags="v9_virus_glow")
                        if topo.scale >= 0.42:
                            t_canvas.create_text(sx + radius, sy - radius, text="!", fill=color,
                                                  font=("Segoe UI", 11, "bold"), tags="v9_virus_glow")
            except Exception:
                pass
            return res

        topo.redraw = _v9_redraw

    # 5B. Thêm Công cụ Pro vào menu Công cụ & Thay nút Xuất CSV bằng bản CSV Đẹp v9!
    def _inject_v9_menus_and_csv() -> None:
        try:
            mbar_name = app.cget("menu")
            if mbar_name:
                mbar = app.nametowidget(mbar_name)
                end_i = mbar.index("end") or 0
                for i in range(end_i + 1):
                    if mbar.type(i) != "cascade":
                        continue
                    lbl = str(mbar.entrycget(i, "label") or "")
                    sub = mbar.nametowidget(mbar.entrycget(i, "menu"))
                    if any(k in lbl for k in ("Công cụ", "Tools", "工具")):
                        s_end = sub.index("end") or 0
                        has_vir = any("Virus" in str(sub.entrycget(j, "label") or "") for j in range(s_end + 1) if sub.type(j) == "command")
                        if not has_vir:
                            sub.insert_command(0, label="🦠 Quét Virus & Kiểm tra an toàn...", command=lambda: ThreatAndExfilScannerDialog(app))
                            sub.insert_command(1, label="📈 Biểu đồ Ping & Uptime Thời gian thực...", command=lambda: LiveLatencyChartDialog(app))
                    elif any(k in lbl for k in ("Tệp", "File", "文件")):
                        s_end = sub.index("end") or 0
                        has_csv = any("CSV Đẹp" in str(sub.entrycget(j, "label") or "") for j in range(s_end + 1) if sub.type(j) == "command")
                        if not has_csv:
                            sub.add_command(label="📄 Xuất Báo cáo CSV Đẹp (Chuẩn Excel)...", command=lambda: export_pretty_csv_report_v9(app))
        except Exception:
            pass

        # Gắn luôn nút 'Xuất CSV' ở bảng đáy sang bản CSV Đẹp v9!
        def _hook_csv_btn(w: Any) -> None:
            try:
                if w.__class__.__name__ == "CTkButton":
                    txt = str(w.cget("text") or "")
                    if "Xuất CSV" in txt or "Export CSV" in txt or "导出 CSV" in txt:
                        w.configure(command=lambda: export_pretty_csv_report_v9(app))
                for ch in w.winfo_children():
                    _hook_csv_btn(ch)
            except Exception:
                pass

        _hook_csv_btn(app)

    app.after(1100, _inject_v9_menus_and_csv)



# --- 6. Nâng cấp LanBot AI v9.0 (Action Copilot hiểu 'xuất báo cáo', 'quét virus', 'biểu đồ'...) ---
_orig_lanbot_cls_v8 = LanBotAssistant


class LanBotAssistant(_orig_lanbot_cls_v8):
    def __init__(self, app: "LanMapApp") -> None:
        super().__init__(app)
        _install_v9_app_hooks(app)

    def _analyze_query(self, raw_q: str) -> tuple[str, list[tuple[str, str]]]:
        low = raw_q.lower().strip()

        # 1. Xuất báo cáo mạng / Xuất CSV đẹp (fix ảnh người dùng gõ 'xuất báo cáo mạng'!)
        if any(k in low for k in ("xuất báo cáo", "xuat bao cao", "xuất csv", "xuat csv", "xuất file", "báo cáo mạng", "bao cao mang", "export")):
            return (
                "📄 Mình sẵn sàng xuất **Báo cáo Mạng chuyên nghiệp** cho bạn!\n"
                "• **File CSV Đẹp (Chuẩn Excel UTF-8):** Có bảng Tổng quan điểm sức khỏe, danh sách toàn bộ thiết bị (IP, MAC, độ trễ, LanMap Client, cảnh báo Virus) và Nhật ký sự cố.\n"
                "• **Sổ tay Phân tích trực tiếp:** Xem ngay điểm sức khỏe và khuyến nghị tối ưu.\n\n"
                "👉 Bấm nút bên dưới để xuất ngay nhé!"
            ), [("📄 Xuất Báo cáo CSV Đẹp ngay", "export_csv_v9"), ("📊 Xem Phân tích trực tiếp", "live_audit")]

        # 2. Quét Virus / Tẩu tán dữ liệu / Mã độc / Kết nối ra ngoài
        if any(k in low for k in ("virus", "mã độc", "ma doc", "tẩu tán", "tau tan", "trojan", "backdoor", "hack", "kết nối ra ngoài", "quét độc")):
            return (
                "🦠 **Kiểm tra an toàn mạng:**\n"
                "• Kiểm tra cổng TCP trên các thiết bị nội bộ đã ghi nhận. Mỗi dấu hiệu có lý do và cách xác minh.\n"
                "• Xem lịch sử và chạy quét nhanh bằng Microsoft Defender trên máy Windows này.\n"
                "• Xem kết nối của máy này và tiến trình liên quan."
            ), [("🦠 Mở Kiểm tra an toàn", "open_virus_v9")]

        # 3. Biểu đồ Ping / Uptime
        if any(k in low for k in ("biểu đồ", "bieu do", "đồ thị", "do thi", "uptime", "theo dõi ping")):
            return (
                "📈 Mình đã tích hợp **Biểu đồ Ping & Uptime Thời gian thực** để bạn theo dõi độ trễ liên tục của Gateway hoặc bất kỳ thiết bị nào!"
            ), [("📈 Mở Biểu đồ Ping & Uptime", "open_chart_v9")]

        return super()._analyze_query(raw_q)

    def _run_action(self, action_id: str, add_bot_bubble: Any) -> None:
        if action_id == "export_csv_v9":
            p = export_pretty_csv_report_v9(self.app)
            if p:
                add_bot_bubble(f"✅ Đã xuất báo cáo CSV chuẩn Excel thành công tại:\n{p}")
            return
        if action_id == "open_virus_v9":
            ThreatAndExfilScannerDialog(self.app)
            add_bot_bubble("🦠 Đã mở Kiểm tra an toàn. Chọn Kiểm tra LAN để xem dấu hiệu, hoặc đọc báo cáo của Microsoft Defender.")
            return
        if action_id == "open_chart_v9":
            LiveLatencyChartDialog(self.app)
            add_bot_bubble("📈 Đã mở Biểu đồ Ping & Uptime Thời gian thực!")
            return
        super()._run_action(action_id, add_bot_bubble)



