# 2. QUÉT SÂU TOÀN MẠNG 5 LỚP (KHÔNG BAO GIỜ SÓT ROUTER / SWITCH / AP / CAMERA!)
# ==============================================================================
_INFRA_PORTS_V10 = (80, 443, 22, 23, 8080, 8291, 8443, 445, 554, 9100, 55124)


def _probe_http_title_v10(ip: str, port: int = 80) -> str:
    try:
        s = _sock_v10.socket(_sock_v10.AF_INET, _sock_v10.SOCK_STREAM)
        s.settimeout(0.35)
        s.connect((ip, port))
        s.sendall(f"GET / HTTP/1.0\r\nHost: {ip}\r\n\r\n".encode())
        raw = s.recv(2048).decode("utf-8", errors="ignore")
        s.close()
        m = re.search(r"<title[^>]*>(.*?)</title>", raw, re.I | re.S)
        srv = re.search(r"Server:\s*([^\r\n]+)", raw, re.I)
        return ((m.group(1).strip() if m else "") + " " + (srv.group(1).strip() if srv else "")).strip()
    except Exception:
        return ""


def _classify_infra_v10(ip: str, open_ports: list[int], banner: str, is_gw: bool) -> tuple[str, str]:
    b = banner.lower()
    suffix = ip.rsplit(".", 1)[-1]
    if is_gw:
        return "router", f"Gateway ({ip})"
    if _looks_like_switch(b):
        return "switch", f"Switch .{suffix}"
    if any(k in b for k in ("unifi", "access point", "eap", "deco", "mesh", "wi-fi", "ap ")):
        return "wifi", f"Wi-Fi AP .{suffix}"
    if 8291 in open_ports or any(k in b for k in ("router", "mikrotik", "draytek", "openwrt", "pfsense", "fortigate", "gateway")):
        return "router", f"Router .{suffix}"
    if 554 in open_ports or any(k in b for k in ("hikvision", "dahua", "ipc", "camera", "nvr", "dvr", "ezviz", "imou")):
        return "camera", f"Camera IP .{suffix}"
    if 9100 in open_ports or any(k in b for k in ("printer", "epson", "canon", "brother", "hp laser", "ricoh")):
        return "printer", f"Máy in .{suffix}"
    if 55124 in open_ports or 445 in open_ports:
        return "pc", f"Máy tính .{suffix}"
    return "unknown", f"Thiết bị .{suffix}"

class DeepInfraScanDialog(ctk.CTkToplevel):
    """Quét sâu 5 lớp toàn bộ dải mạng (ICMP + 11 cổng TCP quản trị + HTTP Banner + ARP + Route) — Bắt hết Router & Switch!"""

    def __init__(self, master: ctk.CTk) -> None:
        super().__init__(master)
        self.app = master
        self.title("🔍 Quét Sâu Toàn Mạng 5 Lớp (Bắt hết Router / Switch / Wi-Fi AP / Camera / PC)")
        self.geometry("760x500")
        self.transient(master)

        self.prog_lbl = ctk.CTkLabel(self, text="⏳ Đang quét sâu 5 lớp (ICMP + TCP 11 cổng + HTTP Banner + ARP + Định tuyến)...",
                                     font=ctk.CTkFont(size=12, weight="bold"), text_color="#0284c7")
        self.prog_lbl.pack(anchor="w", padx=14, pady=(12, 4))
        self.pbar = ctk.CTkProgressBar(self)
        self.pbar.pack(fill="x", padx=14, pady=(0, 8))
        self.pbar.set(0.05)

        self.box = ctk.CTkTextbox(self, font=ctk.CTkFont(family="Consolas", size=11))
        self.box.pack(fill="both", expand=True, padx=14, pady=(0, 10))
        ctk.CTkButton(self, text="Đóng", width=90, command=self.destroy).pack(anchor="e", padx=14, pady=(0, 10))
        threading.Thread(target=self._run_deep_scan, daemon=True).start()

    def _run_deep_scan(self) -> None:
        st = getattr(self.app, "real_state", None)
        sub_cidr = getattr(st, "subnet_cidr", "") or ""
        devs = list(getattr(st, "devices", []) or [])
        if "/" not in sub_cidr:
            # Suy ra từ IP đầu tiên trên sơ đồ
            ip0 = next((getattr(d, "ip", "") for d in devs if getattr(d, "ip", "")), "192.168.1.1")
            sub_cidr = ".".join(ip0.split(".")[:3]) + ".0/24"
        try:
            net = ipaddress.IPv4Network(sub_cidr, strict=False)
            hosts = [str(h) for h in list(net.hosts())[:254]]
        except Exception as exc:
            self.after(0, lambda: self.box.insert("end", f"Lỗi subnet: {exc}\n"))
            return

        # 1. Tìm Gateway từ route print
        gw_ips: set[str] = set()
        try:
            si = _subp_v10.STARTUPINFO() if os.name == "nt" else None
            if si:
                si.dwFlags |= _subp_v10.STARTF_USESHOWWINDOW
            rp = _subp_v10.run(["route", "print", "0.0.0.0"], capture_output=True, text=True, timeout=3,
                               startupinfo=si, creationflags=getattr(_subp_v10, "CREATE_NO_WINDOW", 0) if os.name == "nt" else 0)
            for m in re.finditer(r"0\.0\.0\.0\s+0\.0\.0\.0\s+(\d{1,3}(?:\.\d{1,3}){3})", rp.stdout):
                gw_ips.add(m.group(1))
        except Exception:
            pass

        # 2. Quét song song 64 luồng: TCP cổng hạ tầng + Ping nhẹ
        found_map: dict[str, dict[str, Any]] = {}
        done_cnt = [0]

        def _probe_host(ip: str) -> None:
            open_p: list[int] = []
            for port in _INFRA_PORTS_V10:
                s = _sock_v10.socket(_sock_v10.AF_INET, _sock_v10.SOCK_STREAM)
                s.settimeout(0.14)
                try:
                    if s.connect_ex((ip, port)) == 0:
                        open_p.append(port)
                except Exception:
                    pass
                finally:
                    s.close()
            if open_p or ip in gw_ips:
                banner = _probe_http_title_v10(ip, 80) if 80 in open_p else (_probe_http_title_v10(ip, 8080) if 8080 in open_p else "")
                dtype, dname = _classify_infra_v10(ip, open_p, banner, ip in gw_ips)
                found_map[ip] = {"ip": ip, "ports": open_p, "banner": banner, "type": dtype, "name": dname}
            done_cnt[0] += 1
            if done_cnt[0] % 16 == 0:
                frac = done_cnt[0] / max(1, len(hosts))
                self.after(0, lambda f=frac: self.pbar.set(f) if self.winfo_exists() else None)

        with _cf_v10.ThreadPoolExecutor(max_workers=64) as ex:
            ex.map(_probe_host, hosts)

        # 3. Đọc bảng ARP sau khi quét TCP để lấy MAC và bắt nốt máy không mở cổng TCP
        arp_mac: dict[str, str] = {}
        try:
            si = _subp_v10.STARTUPINFO() if os.name == "nt" else None
            if si:
                si.dwFlags |= _subp_v10.STARTF_USESHOWWINDOW
            ap = _subp_v10.run(["arp", "-a"], capture_output=True, text=True, timeout=3,
                               startupinfo=si, creationflags=getattr(_subp_v10, "CREATE_NO_WINDOW", 0) if os.name == "nt" else 0)
            for line in ap.stdout.splitlines():
                m = re.search(r"(\d{1,3}(?:\.\d{1,3}){3})\s+([0-9a-fA-F-]{17})", line)
                if m:
                    ip_s, mac_s = m.group(1), m.group(2).replace("-", ":").upper()
                    if mac_s not in ("FF:FF:FF:FF:FF:FF", "00:00:00:00:00:00"):
                        arp_mac[ip_s] = mac_s
        except Exception:
            pass

        def _apply_results() -> None:
            if not self.winfo_exists():
                return
            self.pbar.set(1.0)
            existing = {str(getattr(d, "ip", "")): d for d in getattr(st, "devices", [])}
            added = 0
            upgraded = 0
            dev_cls = type(devs[0]) if devs else None
            gw = next((d for d in getattr(st, "devices", []) if str(getattr(d, "device_type", "")).lower() == "router"), None)

            self.box.insert("end", f"=== KẾT QUẢ QUÉT SÂU 5 LỚP ({sub_cidr}) ===\n")
            self.box.insert("end", f"Phát hiện {len(found_map)} thiết bị có cổng quản trị / hạ tầng (Router, Switch, AP, Camera, PC):\n\n")

            for ip, info in sorted(found_map.items()):
                mac = arp_mac.get(ip, "")
                tag = f"[{info['type'].upper():<7}] {ip:<15} | Cổng: {info['ports']} | {info['banner'][:42]}"
                self.box.insert("end", tag + "\n")
                if ip in existing:
                    d = existing[ip]
                    # Nâng cấp phân loại nếu trước đó bị nhận nhầm là unknown / pc trong khi thực tế là router/switch/wifi/camera!
                    if info["type"] in ("router", "switch", "wifi", "camera", "printer") and str(getattr(d, "device_type", "")).lower() in ("unknown", "pc", ""):
                        d.device_type = info["type"]
                        if "Thiết bị" in str(getattr(d, "name", "")):
                            d.name = info["name"]
                        upgraded += 1
                elif dev_cls is not None:
                    try:
                        nd = dev_cls(
                            id=f"deep_{ip.replace('.', '_')}",
                            name=info["name"],
                            ip=ip,
                            mac=mac,
                            device_type=info["type"],
                            status="online",
                            trusted=(info["type"] in ("router", "switch")),
                            x=180 + (len(st.devices) % 6) * 115,
                            y=190 if info["type"] in ("router", "switch", "wifi") else 360,
                        )
                        st.devices.append(nd)
                        if gw and hasattr(st, "links") and st.links:
                            lk_cls = type(st.links[0])
                            st.links.append(lk_cls(source_id=gw.id, target_id=nd.id))
                        added += 1
                    except Exception:
                        pass

            self.box.insert("end", f"\n✓ Đã bổ sung thêm {added} thiết bị bị sót (RT/SW/AP/Host) & phân loại chính xác lại {upgraded} thiết bị!\n")
            self.prog_lbl.configure(text=f"✅ Quét sâu hoàn tất! Bổ sung +{added} thiết bị mới, chuẩn hóa +{upgraded} RT/SW.", text_color="#16a34a")
            try:
                self.app.topology.redraw()
            except Exception:
                pass

        self.after(0, _apply_results)


# ==============================================================================
# 3. BẢNG GIÁM SÁT THIẾT BỊ VÀO / RA MẠNG RÕ RÀNG (LIVE PRESENCE MONITOR)
# ==============================================================================
class LivePresenceMonitorDialog(ctk.CTkToplevel):
    """Bảng theo dõi Thiết bị Vừa Vào Mạng / Vừa Rời Mạng cực trực quan 2 cột + Tự động quét 10s."""

    def __init__(self, master: ctk.CTk) -> None:
        super().__init__(master)
        self.app = master
        self.title("📡 Giám sát Thiết bị Vào / Ra Mạng Thời gian thực (Live Presence Monitor)")
        self.geometry("840x520")
        self.transient(master)
        self._running = True
        self.protocol("WM_DELETE_WINDOW", self._close)

        top = ctk.CTkFrame(self, fg_color="transparent")
        top.pack(fill="x", padx=12, pady=(10, 6))
        self.auto_var = ctk.BooleanVar(value=True)
        ctk.CTkSwitch(top, text="Tự động kiểm tra Vào/Ra mỗi 10 giây", variable=self.auto_var).pack(side="left")
        ctk.CTkButton(top, text="🔄 Kiểm tra ngay", width=116, fg_color="#0284c7", command=self._refresh).pack(side="right", padx=4)

        grid = ctk.CTkFrame(self, fg_color="transparent")
        grid.pack(fill="both", expand=True, padx=12, pady=(0, 10))
        grid.grid_columnconfigure(0, weight=1)
        grid.grid_columnconfigure(1, weight=1)
        grid.grid_rowconfigure(1, weight=1)

        ctk.CTkLabel(grid, text="🟢 THIẾT BỊ ĐANG ONLINE & VỪA GIA NHẬP MẠNG", font=ctk.CTkFont(size=12, weight="bold"), text_color="#16a34a").grid(row=0, column=0, sticky="w", padx=4, pady=(0, 4))
        ctk.CTkLabel(grid, text="🔴 THIẾT BỊ VỪA RỜI MẠNG / MẤT PHẢN HỒI", font=ctk.CTkFont(size=12, weight="bold"), text_color="#dc2626").grid(row=0, column=1, sticky="w", padx=4, pady=(0, 4))

        self.in_box = ctk.CTkTextbox(grid, font=ctk.CTkFont(family="Consolas", size=11))
        self.in_box.grid(row=1, column=0, sticky="nsew", padx=(0, 6))
        self.out_box = ctk.CTkTextbox(grid, font=ctk.CTkFont(family="Consolas", size=11))
        self.out_box.grid(row=1, column=1, sticky="nsew", padx=(6, 0))

        self.hist_box = ctk.CTkTextbox(self, height=130, font=ctk.CTkFont(family="Consolas", size=11))
        self.hist_box.pack(fill="x", padx=12, pady=(0, 10))

        self._refresh()
        self._loop()

    def _refresh(self) -> None:
        if not self.winfo_exists():
            return
        devs = list(getattr(getattr(self.app, "real_state", None), "devices", []) or [])
        hist = list(getattr(self.app, "_presence_history", []) or [])
        self.in_box.delete("1.0", "end")
        self.out_box.delete("1.0", "end")
        self.hist_box.delete("1.0", "end")

        on_cnt = off_cnt = 0
        for d in devs:
            st_s = str(getattr(d, "status", "") or "").lower()
            is_off = any(w in st_s for w in ("off", "down", "fail", "lost", "alert", "unreach"))
            line = f"{getattr(d, 'name', '')[:18]:<19} | {getattr(d, 'ip', ''):<15} | {getattr(d, 'mac', '') or '-'}\n"
            if is_off:
                self.out_box.insert("end", "🔴 " + line)
                off_cnt += 1
            else:
                self.in_box.insert("end", "🟢 " + line)
                on_cnt += 1

        if off_cnt == 0:
            self.out_box.insert("end", "✅ Hiện chưa có thiết bị nào rời mạng / mất kết nối!\n")
        self.hist_box.insert("end", f"=== DÒNG THỜI GIAN VÀO / RA MẠNG (Online: {on_cnt} | Rời mạng: {off_cnt}) ===\n")
        if hist:
            for item in reversed(hist[-20:]):
                self.hist_box.insert("end", item + "\n")
        else:
            self.hist_box.insert("end", "(Đang theo dõi nền... Khi có thiết bị mới vào mạng hoặc ngắt kết nối sẽ ghi lại ngay tại đây!)\n")

    def _loop(self) -> None:
        if not self._running or not self.winfo_exists():
            return
        if self.auto_var.get():
            self._refresh()
        self.after(10000, self._loop)

    def _close(self) -> None:
        self._running = False
        self.destroy()


# ==============================================================================
# 4. KICK / CÔ LẬP THIẾT BỊ KHỎI MẠNG (AN TOÀN & HỢP PHÁP CHO QUẢN TRỊ VIÊN LAN)
# ==============================================================================
class KickIsolateDialog(ctk.CTkToplevel):
    """Cô lập / Kick thiết bị khỏi mạng:
    - Máy cài LanMap Client: Ngắt mạng tức thì 1-click (isolate_net / restore_net).
    - Thiết bị lạ / Điện thoại / Camera: Copy MAC + Mở trang quản trị Router + Chặn Firewall Server + Đánh dấu 🚫.
    """

    def __init__(self, master: ctk.CTk) -> None:
        super().__init__(master)
        self.app = master
        self.title("🚫 Kick / Cô lập Thiết bị khỏi Mạng (Access Control)")
        self.geometry("680x460")
        self.transient(master)

        if not hasattr(master, "_kicked_ips"):
            master._kicked_ips = set()

        devs = list(getattr(getattr(master, "real_state", None), "devices", []) or [])
        self._dev_map = {f"{getattr(d, 'name', '')} ({getattr(d, 'ip', '')})": d for d in devs if getattr(d, "ip", "")}
        opts = list(self._dev_map.keys()) or ["(Chưa có thiết bị)"]

        ctk.CTkLabel(self, text="Chọn thiết bị cần Kick / Cô lập khỏi mạng:", font=ctk.CTkFont(size=12, weight="bold")).pack(anchor="w", padx=16, pady=(12, 4))
        self.sel_var = ctk.StringVar(value=opts[0])
        ctk.CTkOptionMenu(self, width=420, values=opts, variable=self.sel_var, command=self._update_info).pack(anchor="w", padx=16, pady=(0, 8))

        self.info_lbl = ctk.CTkLabel(self, text="", justify="left", font=ctk.CTkFont(size=11))
        self.info_lbl.pack(anchor="w", padx=16, pady=(0, 8))

        btn_f = ctk.CTkFrame(self, fg_color="transparent")
        btn_f.pack(fill="x", padx=16, pady=4)
        ctk.CTkButton(btn_f, text="⚡ Ngắt mạng tức thì (LanMap Client)", fg_color="#dc2626", hover_color="#b91c1c",
                      command=lambda: self._client_isolate(True)).pack(side="left", fill="x", expand=True, padx=(0, 4))
        ctk.CTkButton(btn_f, text="🔌 Khôi phục mạng (Client)", fg_color="#16a34a", hover_color="#15803d",
                      command=lambda: self._client_isolate(False)).pack(side="left", fill="x", expand=True, padx=(4, 0))

        btn_f2 = ctk.CTkFrame(self, fg_color="transparent")
        btn_f2.pack(fill="x", padx=16, pady=4)
        ctk.CTkButton(btn_f2, text="📋 Copy MAC & Mở Web Router để Chặn", fg_color="#d97706", hover_color="#b45309",
                      command=self._kick_via_router).pack(side="left", fill="x", expand=True, padx=(0, 4))
        ctk.CTkButton(btn_f2, text="🧱 Chặn Firewall & Đánh dấu 🚫", fg_color="#7c3aed", hover_color="#6d28d9",
                      command=self._block_fw_and_mark).pack(side="left", fill="x", expand=True, padx=(4, 0))

        self.guide = ctk.CTkTextbox(self, font=ctk.CTkFont(family="Consolas", size=11), wrap="word")
        self.guide.pack(fill="both", expand=True, padx=16, pady=(8, 12))
        self._update_info()

    def _cur_dev(self) -> Any:
        return self._dev_map.get(self.sel_var.get())

    def _update_info(self, _v: Any = None) -> None:
        d = self._cur_dev()
        self.guide.delete("1.0", "end")
        if not d:
            return
        ip = str(getattr(d, "ip", ""))
        mac = str(getattr(d, "mac", "") or "Chưa có MAC")
        has_cl = _device_has_lanmap_client(d, getattr(self.app, "_lanmap_client_ips", set()))
        self.info_lbl.configure(
            text=f"• IP: {ip}  |  MAC: {mac}  |  LanMap Client: {'🔵 Đã cài (Kick trực tiếp được!)' if has_cl else '🟡 Chưa cài (Chặn qua Router/Firewall)'}"
        )
        gw = next((x for x in getattr(self.app.real_state, "devices", []) if str(getattr(x, "device_type", "")).lower() == "router"), None)
        gw_ip = getattr(gw, "ip", "192.168.1.1") if gw else "192.168.1.1"
        self.guide.insert(
            "1.0",
            f"HƯỚNG DẪN KICK / CÔ LẬP THIẾT BỊ {getattr(d, 'name', '')} ({ip}):\n\n"
            f"1. Với máy tính có cài LanMap Client (màu Xanh dương):\n"
            f"   → Bấm nút đỏ '⚡ Ngắt mạng tức thì' ở trên để thu hồi IP (ipconfig /release) & cách ly máy ngay lập tức!\n\n"
            f"2. Với Điện thoại / Thiết bị lạ (Chặn vĩnh viễn tại Router Gateway {gw_ip}):\n"
            f"   → Bấm '📋 Copy MAC & Mở Web Router' — hệ thống đã copy sẵn MAC ({mac}).\n"
            f"   → Trong trang Web Router ({gw_ip}):\n"
            f"     • TP-Link / Asus / Totolink : Security → Access Control / Blacklist → Dán MAC → Block.\n"
            f"     • Viettel / FPT / VNPT      : Network / Security → MAC Filter → Blacklist → Dán MAC → Apply.\n"
            f"     • DrayTek / MikroTik        : Firewall / Wireless MAC Filter → Deny MAC.\n\n"
            f"3. Cô lập tức thì khỏi máy Server:\n"
            f"   → Bấm '🧱 Chặn Firewall & Đánh dấu 🚫' để chặn toàn bộ kết nối từ {ip} vào máy bạn và gắn biểu tượng 🚫 trên sơ đồ.",
        )

    def _client_isolate(self, isolate: bool) -> None:
        d = self._cur_dev()
        if not d:
            return
        ip = str(getattr(d, "ip", ""))
        pin = getattr(self.app, "_client_pin_cache", {}).get(ip)
        if not pin:
            dlg = ctk.CTkInputDialog(text=f"Nhập mã PIN của LanMap Client trên {getattr(d, 'name', ip)} ({ip}):", title="Xác thực quản trị")
            pin = (dlg.get_input() or "").strip()
            if not pin:
                return
            self.app._client_pin_cache[ip] = pin
        act = "isolate_net" if isolate else "restore_net"
        res = query_lanmap_agent(ip, pin, act, "") if "query_lanmap_agent" in globals() else {"ok": False, "error": "Chưa có module Client"}
        if res and res.get("ok"):
            if isolate:
                self.app._kicked_ips.add(ip)
            else:
                self.app._kicked_ips.discard(ip)
            try:
                self.app.topology.redraw()
            except Exception:
                pass
            messagebox.showinfo("Thành công", str(res.get("report") or ("Đã cô lập mạng máy trạm!" if isolate else "Đã khôi phục mạng máy trạm!")))
        else:
            messagebox.showwarning("Chưa thực hiện được", f"Không gửi được lệnh tới {ip}: {(res or {}).get('error', 'Máy chưa cài LanMap Client v2.5 hoặc sai PIN')}.\nHãy dùng nút 'Copy MAC & Mở Web Router' ở dưới!")

    def _kick_via_router(self) -> None:
        d = self._cur_dev()
        if not d:
            return
        mac = str(getattr(d, "mac", "") or "")
        if mac:
            self.clipboard_clear()
            self.clipboard_append(mac)
        gw = next((x for x in getattr(self.app.real_state, "devices", []) if str(getattr(x, "device_type", "")).lower() == "router"), None)
        gw_ip = getattr(gw, "ip", "192.168.1.1") if gw else "192.168.1.1"
        webbrowser.open(f"http://{gw_ip}")
        self.app._kicked_ips.add(str(getattr(d, "ip", "")))
        try:
            self.app.topology.redraw()
        except Exception:
            pass
        messagebox.showinfo("Đã Copy MAC & Mở Router", f"Đã copy địa chỉ MAC: {mac or '(Trống)'}\nĐã mở trang quản trị Router: http://{gw_ip}\n\nBạn chỉ cần dán MAC vào mục MAC Filter / Access Control để kick thiết bị khỏi mạng!")

    def _block_fw_and_mark(self) -> None:
        d = self._cur_dev()
        if not d:
            return
        ip = str(getattr(d, "ip", ""))
        self.app._kicked_ips.add(ip)
        try:
            self.app.topology.redraw()
        except Exception:
            pass
        cmd_in = f'netsh advfirewall firewall add rule name="LanMap_KickIn_{ip}" dir=in action=block remoteip={ip}'
        cmd_out = f'netsh advfirewall firewall add rule name="LanMap_KickOut_{ip}" dir=out action=block remoteip={ip}'
        try:
            si = _subp_v10.STARTUPINFO() if os.name == "nt" else None
            if si:
                si.dwFlags |= _subp_v10.STARTF_USESHOWWINDOW
            p = _subp_v10.run(f"{cmd_in} && {cmd_out}", shell=True, capture_output=True, text=True, startupinfo=si)
            if p.returncode == 0:
                messagebox.showinfo("Đã cô lập Firewall", f"🚫 Đã chặn toàn bộ kết nối 2 chiều với {ip} trên Windows Firewall và đánh dấu 🚫 trên sơ đồ!")
            else:
                messagebox.showinfo("Đã đánh dấu 🚫 trên sơ đồ", f"Đã gắn cờ 🚫 trên sơ đồ. Để khóa cứng trên Windows Firewall cần chạy LanMap bằng quyền Administrator.")
        except Exception:
            pass


