# 5. NÂNG CẤP QUÉT VIRUS CHÉO QUA LANMAP CLIENT + GẮN 4 NÚT NỔI LÊN TOOLBAR
# ==============================================================================

def _install_v10_ui_and_handbook(app: Any) -> None:
    if getattr(app, "_v10_installed", False):
        return
    app._v10_installed = True
    app._kicked_ips = set()

    topo = getattr(app, "topology", None)
    t_canvas = topo if isinstance(topo, tk.Canvas) else getattr(topo, "canvas", None)

    # Vẽ biểu tượng 🚫 đỏ trên thiết bị bị Kick/Cô lập
    if topo and t_canvas and hasattr(topo, "redraw"):
        prev_redraw = topo.redraw

        def _v10_redraw(*args: Any, **kwargs: Any) -> Any:
            res = prev_redraw(*args, **kwargs)
            try:
                t_canvas.delete("v10_kick_badge")
                kicked = getattr(app, "_kicked_ips", set()) or set()
                if kicked:
                    for d in getattr(getattr(app, "real_state", None), "devices", []) or []:
                        if str(getattr(d, "ip", "")) in kicked:
                            sx, sy = _topo_world_to_screen(topo, getattr(d, "x", 0), getattr(d, "y", 0))
                            t_canvas.create_oval(sx + 10, sy - 30, sx + 30, sy - 10, fill="#991b1b", outline="#ffffff", width=1.5, tags="v10_kick_badge")
                            t_canvas.create_text(sx + 20, sy - 20, text="🚫", fill="#ffffff", font=("Segoe UI", 9, "bold"), tags="v10_kick_badge")
            except Exception:
                pass
            return res

        topo.redraw = _v10_redraw

    # Thêm 4 nút NỔI BẬT ngay trên thanh công cụ chính + Cập nhật Sổ tay chuẩn Giáo trình vào menu Trợ giúp!
    def _inject_v10_toolbar_and_menus() -> None:
        # 1. Nút nổi trên toolbar (cạnh nút Speedtest / Tách Subnet)
        try:
            def _find_anchor(w: Any) -> Any:
                if w.__class__.__name__ == "CTkButton" and any(k in str(w.cget("text") or "") for k in ("Tách Subnet", "Speedtest", "Tự xếp")):
                    return w
                for ch in w.winfo_children():
                    r = _find_anchor(ch)
                    if r:
                        return r
                return None

            anc = _find_anchor(app)
            if anc and anc.master:
                bar = anc.master
                ctk.CTkButton(bar, text="🔍 Quét Sâu", width=86, height=26, fg_color="#0284c7", hover_color="#0369a1",
                              command=lambda: DeepInfraScanDialog(app)).pack(side="left", padx=2)
                ctk.CTkButton(bar, text="🦠 Quét Virus", width=92, height=26, fg_color="#dc2626", hover_color="#b91c1c",
                              command=lambda: ThreatAndExfilScannerDialog(app)).pack(side="left", padx=2)
                ctk.CTkButton(bar, text="📡 Vào/Ra", width=78, height=26, fg_color="#7c3aed", hover_color="#6d28d9",
                              command=lambda: LivePresenceMonitorDialog(app)).pack(side="left", padx=2)
                ctk.CTkButton(bar, text="🚫 Kick", width=66, height=26, fg_color="#991b1b", hover_color="#7f1d1d",
                              command=lambda: KickIsolateDialog(app)).pack(side="left", padx=2)
        except Exception:
            pass

        # 2. Thay mục Sổ tay Khắc phục sự cố trong menu Trợ giúp bằng bản Giáo trình OSI 7 tầng & CCNA
        try:
            mbar_name = app.cget("menu")
            if mbar_name:
                mbar = app.nametowidget(mbar_name)
                end_i = mbar.index("end") or 0
                for i in range(end_i + 1):
                    if mbar.type(i) != "cascade":
                        continue
                    lbl = str(mbar.entrycget(i, "label") or "")
                    sub = mbar.nametowidget(mbar.entrycget(i, "menu"))
                    if any(k in lbl for k in ("Trợ giúp", "Help", "帮助")):
                        h_end = sub.index("end") or 0
                        for j in range(h_end + 1):
                            if sub.type(j) == "command":
                                sl = str(sub.entrycget(j, "label") or "")
                                if any(k in sl for k in ("Sổ tay khắc phục", "Troubleshooting", "故障排查")):
                                    sub.entryconfig(j, label="📘 Sổ tay Khắc phục sự cố (Giáo trình OSI & CCNA)...", command=lambda: TextbookHandbookDialog(app))
                    elif any(k in lbl for k in ("Công cụ", "Tools", "工具")):
                        sub.insert_command(0, label="🔍 Quét mạng hiện tại (Nhanh / Kỹ)...", command=lambda: DeepInfraScanDialog(app))
                        sub.insert_command(1, label="📡 Giám sát Thiết bị Vào / Ra Mạng...", command=lambda: LivePresenceMonitorDialog(app))
                        sub.insert_command(2, label="🚫 Kick / Cô lập Thiết bị khỏi Mạng...", command=lambda: KickIsolateDialog(app))
        except Exception:
            pass

    app.after(1300, _inject_v10_toolbar_and_menus)


_orig_lanbot_cls_v9 = LanBotAssistant


class LanBotAssistant(_orig_lanbot_cls_v9):
    def __init__(self, app: "LanMapApp") -> None:
        super().__init__(app)
        _install_v10_ui_and_handbook(app)

    def _analyze_query(self, raw_q: str) -> tuple[str, list[tuple[str, str]]]:
        low = raw_q.lower().strip()
        if any(k in low for k in ("kick", "cô lập", "co lap", "ngắt mạng", "ngat mang", "chặn máy", "chan may", "đuổi")):
            return (
                "🚫 **Kick / Cô lập thiết bị khỏi mạng (v10.0):**\n"
                "• Với PC cài **LanMap Client**: ngắt mạng tức thì 1-click (`ipconfig /release`) & khôi phục lại dễ dàng.\n"
                "• Với Điện thoại / Thiết bị lạ: tự copy MAC + mở thẳng Web Router chặn MAC + chặn Firewall Server!\n"
                "👉 Bấm nút bên dưới để mở bảng Kick / Cô lập ngay:"
            ), [("🚫 Mở bảng Kick / Cô lập", "open_kick_v10")]
        if any(k in low for k in ("quét sâu", "quet sau", "sót router", "sót switch", "tìm router", "tìm switch")):
            return (
                "🔍 **Quét Sâu 5 Lớp (v10.0):** Quét đồng thời ICMP + 11 cổng quản trị TCP + HTTP Banner + ARP + Route để bắt trọn Router phụ, Switch quản lý, Wi-Fi AP & Camera!"
            ), [("🔍 Chạy Quét Sâu (RT/SW) ngay", "open_deep_v10")]
        if any(k in low for k in ("vào mạng", "rời mạng", "vao mang", "roi mang", "lịch sử")):
            return (
                "📡 Mở ngay bảng **Giám sát Thiết bị Vào / Ra Mạng** 2 cột to rõ để theo dõi từng thiết bị vừa kết nối hoặc vừa ngắt mạng:"
            ), [("📡 Mở Giám sát Vào/Ra Mạng", "open_presence_v10")]
        if any(k in low for k in ("sổ tay", "so tay", "giáo trình", "osi", "ccna")):
            return (
                "📘 Sổ tay Khắc phục Sự cố đã được nâng cấp theo **Giáo trình Mạng Máy Tính (Mô hình OSI 7 Tầng & 6 phương pháp luận Cisco CCNA)** với 5 tab và ô tìm kiếm!"
            ), [("📘 Mở Sổ tay Giáo trình OSI/CCNA", "open_handbook_v10")]
        return super()._analyze_query(raw_q)

    def _run_action(self, action_id: str, add_bot_bubble: Any) -> None:
        if action_id == "open_kick_v10":
            KickIsolateDialog(self.app)
            add_bot_bubble("🚫 Đã mở hộp thoại Kick / Cô lập Thiết bị!")
            return
        if action_id == "open_deep_v10":
            DeepInfraScanDialog(self.app)
            add_bot_bubble("🔍 Đang chạy Quét Sâu 5 Lớp để tìm toàn bộ Router / Switch / Wi-Fi AP!")
            return
        if action_id == "open_presence_v10":
            LivePresenceMonitorDialog(self.app)
            add_bot_bubble("📡 Đã mở bảng Giám sát Thiết bị Vào / Ra Mạng!")
            return
        if action_id == "open_handbook_v10":
            TextbookHandbookDialog(self.app)
            add_bot_bubble("📘 Đã mở Sổ tay Khắc phục Sự cố chuẩn Giáo trình OSI & CCNA!")
            return
        super()._run_action(action_id, add_bot_bubble)



