import concurrent.futures as _cf_v11
import socket as _sock_v11
import subprocess as _subp_v11


def _fast_ping_v11(ip: str) -> bool:
    """Ping 1 gói nhanh (timeout 600ms) để phát hiện thiết bị vừa tắt/bật Wi-Fi trong 1-2 giây."""
    try:
        si = _subp_v11.STARTUPINFO() if os.name == "nt" else None
        if si:
            si.dwFlags |= _subp_v11.STARTF_USESHOWWINDOW
        p = _subp_v11.run(
            ["ping", "-n" if os.name == "nt" else "-c", "1", "-w" if os.name == "nt" else "-W", "600", ip],
            capture_output=True, text=True, timeout=1.6,
            startupinfo=si,
            creationflags=getattr(_subp_v11, "CREATE_NO_WINDOW", 0) if os.name == "nt" else 0,
        )
        return (p.returncode == 0) and ("TTL=" in p.stdout.upper() or "time=" in p.stdout.lower() or "time<" in p.stdout.lower())
    except Exception:
        return False


# --- 1. Giám sát Thiết bị Vào / Ra Mạng v11.0 (Tự Ping thật + 3 Khung kéo chỉnh kích thước!) ---
class LivePresenceMonitorDialog(ctk.CTkToplevel):
    """3 khung kéo chỉnh tự do (PanedWindow):
    - Trên Trái : 🟢 Thiết bị VỪA KẾT NỐI / VÀO MẠNG
    - Trên Phải : 🔴 Thiết bị VỪA RỜI MẠNG / OUT
    - Dưới      : 📋 Danh sách toàn bộ thiết bị (tìm kiếm & cuộn mượt)
    Chủ động Ping 32 luồng + đọc ARP thật để phát hiện điện thoại tắt/bật Wi-Fi ngay lập tức!
    """

    def __init__(self, master: ctk.CTk) -> None:
        super().__init__(master)
        self.app = master
        self.title("📡 Giám sát Thiết bị Vào / Ra Mạng Thời gian thực (3 Khung tinh chỉnh)")
        self.geometry("920x620")
        self.minsize(780, 500)
        self.transient(master)

        self._running = True
        self._scanning = False
        self._last_alive: dict[str, bool] = {}
        self._joined_events: list[str] = []
        self._left_events: list[str] = []
        self.protocol("WM_DELETE_WINDOW", self._close)

        # Thanh điều khiển trên cùng
        top = ctk.CTkFrame(self, fg_color="transparent")
        top.pack(fill="x", padx=12, pady=(10, 6))
        self.auto_var = ctk.BooleanVar(value=True)
        ctk.CTkSwitch(top, text="Tự động quét Ping Vào/Ra mỗi 8 giây", variable=self.auto_var).pack(side="left")
        self.stat_lbl = ctk.CTkLabel(top, text="⏳ Đang quét trạng thái thực tế...", font=ctk.CTkFont(size=11, weight="bold"), text_color="#0284c7")
        self.stat_lbl.pack(side="left", padx=14)
        self.btn_now = ctk.CTkButton(top, text="🔄 Quét Vào/Ra ngay", width=136, fg_color="#0284c7", command=self._trigger_scan)
        self.btn_now.pack(side="right")

        # 3 khung kéo chỉnh kích thước bằng tk.PanedWindow (Trên chia 2 cột Trái/Phải, Dưới là Danh sách thiết bị)
        v_pane = tk.PanedWindow(self, orient=tk.VERTICAL, sashwidth=6, bg="#cbd5e1", bd=0)
        v_pane.pack(fill="both", expand=True, padx=12, pady=(0, 10))

        h_pane = tk.PanedWindow(v_pane, orient=tk.HORIZONTAL, sashwidth=6, bg="#cbd5e1", bd=0)
        v_pane.add(h_pane, minsize=180, height=250)

        # Khung Trên-Trái: Thiết bị VỪA KẾT NỐI / VÀO MẠNG
        f_in = ctk.CTkFrame(h_pane, corner_radius=8)
        ctk.CTkLabel(f_in, text="🟢 THIẾT BỊ VỪA KẾT NỐI / VÀO MẠNG", font=ctk.CTkFont(size=12, weight="bold"), text_color="#16a34a").pack(anchor="w", padx=10, pady=(8, 4))
        self.in_box = ctk.CTkTextbox(f_in, font=ctk.CTkFont(family="Consolas", size=11))
        self.in_box.pack(fill="both", expand=True, padx=8, pady=(0, 8))
        h_pane.add(f_in, minsize=240, width=440)

        # Khung Trên-Phải: Thiết bị VỪA RỜI MẠNG / OUT
        f_out = ctk.CTkFrame(h_pane, corner_radius=8)
        ctk.CTkLabel(f_out, text="🔴 THIẾT BỊ VỪA RỜI MẠNG (OUT / MẤT PING)", font=ctk.CTkFont(size=12, weight="bold"), text_color="#dc2626").pack(anchor="w", padx=10, pady=(8, 4))
        self.out_box = ctk.CTkTextbox(f_out, font=ctk.CTkFont(family="Consolas", size=11))
        self.out_box.pack(fill="both", expand=True, padx=8, pady=(0, 8))
        h_pane.add(f_out, minsize=240, width=440)

        # Khung Dưới: Danh sách toàn bộ thiết bị (có ô tìm kiếm + cuộn mượt)
        f_all = ctk.CTkFrame(v_pane, corner_radius=8)
        hdr_all = ctk.CTkFrame(f_all, fg_color="transparent")
        hdr_all.pack(fill="x", padx=10, pady=(8, 4))
        ctk.CTkLabel(hdr_all, text="📋 DANH SÁCH TOÀN BỘ THIẾT BỊ (Kéo thanh chia giữa 3 khung để tinh chỉnh)", font=ctk.CTkFont(size=12, weight="bold")).pack(side="left")
        self.filter_e = ctk.CTkEntry(hdr_all, width=210, height=26, placeholder_text="Lọc theo tên hoặc IP...")
        self.filter_e.pack(side="right")
        self.filter_e.bind("<KeyRelease>", lambda _e: self._render_all_list())

        self.all_box = ctk.CTkTextbox(f_all, font=ctk.CTkFont(family="Consolas", size=11))
        self.all_box.pack(fill="both", expand=True, padx=8, pady=(0, 8))
        v_pane.add(f_all, minsize=160)

        self._trigger_scan()
        self._schedule_next()

    def _trigger_scan(self) -> None:
        if self._scanning or not self.winfo_exists():
            return
        self._scanning = True
        self.btn_now.configure(state="disabled")
        self.stat_lbl.configure(text="⏳ Đang Ping trực tiếp toàn bộ thiết bị...", text_color="#d97706")
        threading.Thread(target=self._bg_ping_all, daemon=True).start()

    def _bg_ping_all(self) -> None:
        devs = list(getattr(getattr(self.app, "real_state", None), "devices", []) or [])
        ips = [str(getattr(d, "ip", "")) for d in devs if getattr(d, "ip", "")]
        alive_now: dict[str, bool] = {}

        def _chk(ip: str) -> tuple[str, bool]:
            return ip, _fast_ping_v11(ip)

        with _cf_v11.ThreadPoolExecutor(max_workers=32) as ex:
            for ip, ok in ex.map(_chk, ips):
                alive_now[ip] = ok

        ts = time.strftime("%H:%M:%S")
        joined_now = []
        left_now = []
        first_run = len(self._last_alive) == 0

        for d in devs:
            ip = str(getattr(d, "ip", "") or "")
            if not ip:
                continue
            nm = str(getattr(d, "name", ip) or ip)
            ok = alive_now.get(ip, False)
            # Đồng bộ ngược trạng thái thật về sơ đồ chính luôn!
            try:
                d.status = STATUS_ONLINE if ok else STATUS_NO_PING
            except Exception:
                pass
            if not first_run:
                prev = self._last_alive.get(ip)
                if prev is False and ok is True:
                    ev = f"[{ts}] 🟢 VÀO LẠI MẠNG: {nm} ({ip})"
                    self._joined_events.insert(0, ev)
                    joined_now.append((nm, ip))
                elif prev is True and ok is False:
                    ev = f"[{ts}] 🔴 VỪA RỜI MẠNG: {nm} ({ip})"
                    self._left_events.insert(0, ev)
                    left_now.append((nm, ip))
                elif prev is None and ok is True:
                    ev = f"[{ts}] 🆕 THIẾT BỊ MỚI: {nm} ({ip})"
                    self._joined_events.insert(0, ev)
                    joined_now.append((nm, ip))
            self._last_alive[ip] = ok

        self.after(0, lambda: self._on_scan_done(alive_now, joined_now, left_now))

    def _on_scan_done(self, alive_now: dict[str, bool], joined_now: list[tuple[str, str]], left_now: list[tuple[str, str]]) -> None:
        self._scanning = False
        if not self.winfo_exists():
            return
        self.btn_now.configure(state="normal")
        on_c = sum(1 for v in alive_now.values() if v)
        off_c = len(alive_now) - on_c
        self.stat_lbl.configure(text=f"✅ Cập nhật lúc {time.strftime('%H:%M:%S')} — Online: {on_c} | Mất kết nối: {off_c}", text_color="#16a34a")

        self.in_box.delete("1.0", "end")
        if self._joined_events:
            self.in_box.insert("end", "\n".join(self._joined_events[:40]) + "\n")
        else:
            self.in_box.insert("end", "(Đang theo dõi... Bật Wi-Fi điện thoại hoặc kết nối thiết bị mới sẽ hiện ngay tại đây!)\n")

        self.out_box.delete("1.0", "end")
        if self._left_events:
            self.out_box.insert("end", "\n".join(self._left_events[:40]) + "\n")
        else:
            self.out_box.insert("end", "(Đang theo dõi... Tắt Wi-Fi điện thoại hoặc rút dây mạng sẽ hiện ngay tại đây!)\n")

        if len(left_now) >= 2:
            branch_groups = group_branch_outages(self.app.active_devices, self.app.active_links)
            root_branches = [g for g in branch_groups if g.get("root") is not None]
            if root_branches:
                msg_txt = " | ".join(g["summary"] for g in root_branches[:2])
                send_windows_toast("🌳 LanMap — Sự cố nhánh mạng (LibreNMS)", msg_txt, "Error")
            else:
                sample = ", ".join(f"{nm} ({ip})" for nm, ip in left_now[:3])
                send_windows_toast("🚨 LanMap — MẠNG CÓ VẤN ĐỀ!", f"Đồng loạt {len(left_now)} thiết bị vừa rời mạng ({sample})!", "Error")

        self._render_all_list()
        try:
            self.app.topology.redraw()
        except Exception:
            pass

    def _render_all_list(self) -> None:
        if not self.winfo_exists():
            return
        q = self.filter_e.get().strip().lower()
        devs = list(getattr(getattr(self.app, "real_state", None), "devices", []) or [])
        self.all_box.delete("1.0", "end")
        self.all_box.insert("end", f"{'TRẠNG THÁI':<12} {'TÊN THIẾT BỊ':<22} {'ĐỊA CHỈ IP':<16} {'ĐỊA CHỈ MAC':<19} {'LOẠI'}\n")
        self.all_box.insert("end", "-" * 86 + "\n")
        for d in devs:
            nm = str(getattr(d, "name", "") or "")
            ip = str(getattr(d, "ip", "") or "")
            mac = str(getattr(d, "mac", "") or "-")
            dt = str(getattr(d, "device_type", "") or "").upper()
            if q and (q not in nm.lower() and q not in ip.lower() and q not in mac.lower()):
                continue
            ok = self._last_alive.get(ip, True)
            st = "🟢 Online" if ok else "🔴 Out   "
            self.all_box.insert("end", f"{st:<12} {nm[:21]:<22} {ip:<16} {mac:<19} {dt}\n")

    def _schedule_next(self) -> None:
        if not self._running or not self.winfo_exists():
            return
        if self.auto_var.get():
            self._trigger_scan()
        self.after(8000, self._schedule_next)

    def _close(self) -> None:
        self._running = False
        self.destroy()


# --- 2. Cửa sổ Kick / Cô lập Thiết bị v11.0 (Danh sách cuộn mượt + Tự chọn máy trên sơ đồ + KHÔNG đòi PIN với ĐT lạ!) ---
class KickIsolateDialog(ctk.CTkToplevel):
    def __init__(self, master: ctk.CTk) -> None:
        super().__init__(master)
        self.app = master
        self.title("🚫 Kick / Cô lập Thiết bị khỏi Mạng (Chọn từ sơ đồ hoặc danh sách cuộn)")
        self.geometry("860x520")
        self.minsize(740, 460)
        self.transient(master)

        if not hasattr(master, "_kicked_ips"):
            master._kicked_ips = set()

        self._devs = [d for d in (getattr(getattr(master, "real_state", None), "devices", []) or []) if getattr(d, "ip", "")]
        # Tự động chọn đúng thiết bị người dùng đang chọn trên sơ đồ!
        sel_id = getattr(getattr(master, "topology", None), "selected_id", None) or getattr(master, "selected_device_id", None)
        self._selected_dev = next((d for d in self._devs if getattr(d, "id", None) == sel_id), self._devs[0] if self._devs else None)
        self._row_btns: dict[str, ctk.CTkButton] = {}

        body = ctk.CTkFrame(self, fg_color="transparent")
        body.pack(fill="both", expand=True, padx=12, pady=10)
        body.grid_columnconfigure(0, weight=0)
        body.grid_columnconfigure(1, weight=1)
        body.grid_rowconfigure(0, weight=1)

        # Cột Trái: Danh sách thiết bị CUỘN MƯỢT + Tìm kiếm (thay dropdown đơ dài màn hình!)
        left = ctk.CTkFrame(body, width=300, corner_radius=8)
        left.grid(row=0, column=0, sticky="nsew", padx=(0, 10))
        left.grid_propagate(False)
        ctk.CTkLabel(left, text="📋 Chọn thiết bị (cuộn mượt):", font=ctk.CTkFont(size=12, weight="bold")).pack(anchor="w", padx=10, pady=(8, 4))
        self.search_e = ctk.CTkEntry(left, placeholder_text="Tìm tên hoặc IP (vd .55)...")
        self.search_e.pack(fill="x", padx=8, pady=(0, 6))
        self.search_e.bind("<KeyRelease>", lambda _e: self._populate_list())

        self.list_frame = ctk.CTkScrollableFrame(left, fg_color="transparent")
        self.list_frame.pack(fill="both", expand=True, padx=4, pady=(0, 6))

        # Cột Phải: Hành động Kick thông minh theo từng loại thiết bị
        right = ctk.CTkFrame(body, corner_radius=8)
        right.grid(row=0, column=1, sticky="nsew")

        self.hdr_lbl = ctk.CTkLabel(right, text="Chọn một thiết bị bên trái", font=ctk.CTkFont(size=14, weight="bold"))
        self.hdr_lbl.pack(anchor="w", padx=14, pady=(12, 4))
        self.sub_lbl = ctk.CTkLabel(right, text="", justify="left", font=ctk.CTkFont(size=11), text_color="#64748b")
        self.sub_lbl.pack(anchor="w", padx=14, pady=(0, 10))

        self.actions_frame = ctk.CTkFrame(right, fg_color="transparent")
        self.actions_frame.pack(fill="x", padx=14, pady=(0, 8))

        self.guide = ctk.CTkTextbox(right, font=ctk.CTkFont(family="Consolas", size=11), wrap="word")
        self.guide.pack(fill="both", expand=True, padx=14, pady=(4, 12))

        self._populate_list()
        self._render_selected()

    def _populate_list(self) -> None:
        for w in self.list_frame.winfo_children():
            w.destroy()
        self._row_btns.clear()
        q = self.search_e.get().strip().lower()
        cips = getattr(self.app, "_lanmap_client_ips", set()) or set()
        for d in self._devs:
            nm = str(getattr(d, "name", "") or "")
            ip = str(getattr(d, "ip", "") or "")
            if q and q not in nm.lower() and q not in ip.lower():
                continue
            has_cl = _device_has_lanmap_client(d, cips)
            is_k = ip in getattr(self.app, "_kicked_ips", set())
            icon = "🚫" if is_k else ("🔵" if has_cl else "📱")
            is_sel = self._selected_dev is d
            btn = ctk.CTkButton(
                self.list_frame,
                text=f"{icon} {nm[:15]} ({ip})",
                anchor="w",
                height=30,
                fg_color="#0284c7" if is_sel else ("#e2e8f0", "#1e293b"),
                text_color="#ffffff" if is_sel else ("#0f172a", "#f8fafc"),
                hover_color="#0369a1",
                command=lambda dev=d: self._select_dev(dev),
            )
            btn.pack(fill="x", pady=2)
            self._row_btns[ip] = btn

    def _select_dev(self, dev: Any) -> None:
        self._selected_dev = dev
        self._populate_list()
        self._render_selected()

    def _real_gateway_ip(self) -> str:
        for d in self._devs:
            if "gateway" in str(getattr(d, "name", "")).lower():
                return str(getattr(d, "ip", "192.168.1.1"))
        for d in self._devs:
            if str(getattr(d, "device_type", "")).lower() == "router":
                return str(getattr(d, "ip", "192.168.1.1"))
        return "192.168.1.1"

    def _render_selected(self) -> None:
        for w in self.actions_frame.winfo_children():
            w.destroy()
        self.guide.delete("1.0", "end")
        d = self._selected_dev
        if not d:
            return
        nm = str(getattr(d, "name", ""))
        ip = str(getattr(d, "ip", ""))
        mac = str(getattr(d, "mac", "") or "Chưa có MAC")
        has_cl = _device_has_lanmap_client(d, getattr(self.app, "_lanmap_client_ips", set()))
        gw_ip = self._real_gateway_ip()

        self.hdr_lbl.configure(text=f"🚫 {nm}  ({ip})")
        self.sub_lbl.configure(
            text=f"MAC: {mac}  |  Gateway Router: {gw_ip}\nTrạng thái: {'🔵 PC có LanMap Client (Ngắt trực tiếp được)' if has_cl else '📱 Thiết bị di động / Không cài Client → Chặn trực tiếp trên Router & Firewall'}"
        )

        # Chỉ hiện nút LanMap Client khi thiết bị THỰC SỰ cài LanMap Client (không đòi PIN cho ĐT xài ké!)
        if has_cl:
            r1 = ctk.CTkFrame(self.actions_frame, fg_color="transparent")
            r1.pack(fill="x", pady=3)
            ctk.CTkButton(r1, text="⚡ Ngắt mạng ngay (Client)", fg_color="#dc2626", hover_color="#b91c1c",
                          command=lambda: self._client_isolate(True)).pack(side="left", fill="x", expand=True, padx=(0, 4))
            ctk.CTkButton(r1, text="🔌 Khôi phục mạng (Client)", fg_color="#16a34a", hover_color="#15803d",
                          command=lambda: self._client_isolate(False)).pack(side="left", fill="x", expand=True, padx=(4, 0))

        r2 = ctk.CTkFrame(self.actions_frame, fg_color="transparent")
        r2.pack(fill="x", pady=3)
        ctk.CTkButton(r2, text=f"📋 Copy MAC & Mở Web Router ({gw_ip}) để Kick", fg_color="#d97706", hover_color="#b45309",
                      command=self._kick_via_router).pack(fill="x", pady=2)
        ctk.CTkButton(r2, text="🧱 Chặn giao tiếp trên Firewall & Gắn cờ 🚫", fg_color="#7c3aed", hover_color="#6d28d9",
                      command=self._block_fw_and_mark).pack(fill="x", pady=2)

        self.guide.insert(
            "1.0",
            f"CÁCH KICK ĐÚNG KỸ THUẬT CHO THIẾT BỊ '{nm}' ({ip}):\n\n"
            f"• Tại sao điện thoại xài ké Wi-Fi KHÔNG dùng được app Client?\n"
            f"  Vì điện thoại lạ không cài phần mềm quản trị của bạn; trong mạng thực tế, chỉ có ROUTER (Gateway {gw_ip}) mới có quyền đuổi thiết bị lạ ra khỏi Wi-Fi vĩnh viễn bằng MAC Filtering.\n\n"
            f"• 3 bước Kick thiết bị lạ nhanh nhất (15 giây):\n"
            f"  1. Bấm nút màu cam '📋 Copy MAC & Mở Web Router ({gw_ip})' ở trên (đã copy sẵn MAC: {mac}).\n"
            f"  2. Đăng nhập trang quản trị Router (user/pass in mặt sau cục Wi-Fi).\n"
            f"  3. Vào mục Access Control / MAC Filter / Blacklist → Dán MAC ({mac}) → Block / Deny.\n\n"
            f"• Muốn cô lập ngay khỏi máy bạn (chống lây virus): bấm nút tím '🧱 Chặn giao tiếp trên Firewall'!",
        )

    def _client_isolate(self, isolate: bool) -> None:
        d = self._selected_dev
        if not d:
            return
        ip = str(getattr(d, "ip", ""))
        pin = getattr(self.app, "_client_pin_cache", {}).get(ip)
        if not pin:
            dlg = ctk.CTkInputDialog(text=f"Nhập mã PIN của LanMap Client trên {ip}:", title="Xác thực quản trị")
            pin = (dlg.get_input() or "").strip()
            if not pin:
                return
            self.app._client_pin_cache[ip] = pin
        res = query_lanmap_agent(ip, pin, "isolate_net" if isolate else "restore_net", "")
        if res and res.get("ok"):
            if isolate:
                self.app._kicked_ips.add(ip)
            else:
                self.app._kicked_ips.discard(ip)
            self._populate_list()
            try:
                self.app.topology.redraw()
            except Exception:
                pass
            messagebox.showinfo("Thành công", str(res.get("report") or "Hoàn tất!"))
        else:
            messagebox.showwarning("Thất bại", str((res or {}).get("error") or "Không kết nối được LanMap Client!"))

    def _kick_via_router(self) -> None:
        d = self._selected_dev
        if not d:
            return
        mac = str(getattr(d, "mac", "") or "")
        if mac:
            self.clipboard_clear()
            self.clipboard_append(mac)
        gw_ip = self._real_gateway_ip()
        webbrowser.open(f"http://{gw_ip}")
        self.app._kicked_ips.add(str(getattr(d, "ip", "")))
        self._populate_list()
        try:
            self.app.topology.redraw()
        except Exception:
            pass
        messagebox.showinfo("Đã Copy MAC & Mở Router", f"✓ Đã copy MAC: {mac}\n✓ Đã mở Web Router: http://{gw_ip}\n\nBạn hãy dán MAC vào mục MAC Filter / Blacklist để kick thiết bị khỏi Wi-Fi!")

    def _block_fw_and_mark(self) -> None:
        d = self._selected_dev
        if not d:
            return
        ip = str(getattr(d, "ip", ""))
        self.app._kicked_ips.add(ip)
        self._populate_list()
        try:
            self.app.topology.redraw()
        except Exception:
            pass
        cmd = f'netsh advfirewall firewall add rule name="LanMap_KickIn_{ip}" dir=in action=block remoteip={ip} && netsh advfirewall firewall add rule name="LanMap_KickOut_{ip}" dir=out action=block remoteip={ip}'
        try:
            si = _subp_v11.STARTUPINFO() if os.name == "nt" else None
            if si:
                si.dwFlags |= _subp_v11.STARTF_USESHOWWINDOW
            p = _subp_v11.run(cmd, shell=True, capture_output=True, text=True, startupinfo=si)
            if p.returncode == 0:
                messagebox.showinfo("Đã chặn Firewall", f"🧱 Đã chặn giao tiếp 2 chiều với {ip} trên Windows Firewall & đánh dấu 🚫 trên sơ đồ!")
            else:
                messagebox.showinfo("Đã đánh dấu 🚫", f"Đã đánh dấu 🚫 trên sơ đồ. (Để khóa cứng Windows Firewall cần chạy LanMap bằng quyền Administrator).")
        except Exception:
            pass


# --- 4. Dọn sạch 4 nút tràn khỏi thanh công cụ chính & Nâng cấp Tự xếp thoáng đẹp hơn! ---
def _polish_toolbar_and_layout_v11(app: Any) -> None:
    def _clean_overflow_btns() -> None:
        overflow_labels = {"🔍 Quét Sâu", "🦠 Quét Virus", "📡 Vào/Ra", "🚫 Kick"}

        def _walk(w: Any) -> None:
            try:
                if w.__class__.__name__ == "CTkButton":
                    txt = str(w.cget("text") or "").strip()
                    if txt in overflow_labels:
                        w.pack_forget()
                        w.grid_forget()
                for ch in w.winfo_children():
                    _walk(ch)
            except Exception:
                pass

        _walk(app)

    # Chạy sau khi v10 đã chèn nút để ẩn gọn chúng đi (vẫn giữ đầy đủ trong menu Công cụ!)
    app.after(1800, _clean_overflow_btns)

    # Tối ưu khoảng cách hàm tách/xếp sơ đồ rộng thoáng hơn (không dính chữ IP!)
    global _separate_subnets_side_by_side_v8

    def _pretty_layout_v11(target_app: Any) -> int:
        devs = list(getattr(getattr(target_app, "real_state", None), "devices", []) or [])
        if not devs:
            return 0
        groups: dict[str, list[Any]] = {}
        for d in devs:
            sub = _get_subnet_prefix_24(getattr(d, "ip", ""))
            groups.setdefault(sub, []).append(d)

        col_w = 820
        for g_idx, (_sub, items) in enumerate(sorted(groups.items())):
            base_x = 120 + g_idx * col_w
            routers = [d for d in items if str(getattr(d, "device_type", "")).lower() == "router" or "gateway" in str(getattr(d, "name", "")).lower()]
            infra = [d for d in items if d not in routers and str(getattr(d, "device_type", "")).lower() in ("switch", "wifi", "ap", "server")]
            hosts = [d for d in items if d not in routers and d not in infra]

            for i, d in enumerate(routers):
                d.x = base_x + 320 + (i - len(routers) / 2.0 + 0.5) * 155
                d.y = 90
            for i, d in enumerate(infra):
                d.x = base_x + 320 + (i - len(infra) / 2.0 + 0.5) * 155
                d.y = 215
            cols = 6
            for i, d in enumerate(hosts):
                r, c = divmod(i, cols)
                d.x = base_x + 30 + c * 138
                d.y = 345 + r * 118

        try:
            if hasattr(target_app, "topology") and target_app.topology:
                target_app.topology.redraw()
                if hasattr(target_app.topology, "fit_to_view"):
                    target_app.topology.fit_to_view()
        except Exception:
            pass
        return len(groups)

    _separate_subnets_side_by_side_v8 = _pretty_layout_v11


_orig_lanbot_cls_v10 = LanBotAssistant


class LanBotAssistant(_orig_lanbot_cls_v10):
    def __init__(self, app: "LanMapApp") -> None:
        super().__init__(app)
        _polish_toolbar_and_layout_v11(app)



