# --- 1. Cửa sổ Kick v12.0: Dùng tk.Listbox siêu mượt 60fps (không cà giật, không trắng khi tìm IP!) ---
class KickIsolateDialog(ctk.CTkToplevel):
    def __init__(self, master: ctk.CTk, preselect_dev: Any = None) -> None:
        super().__init__(master)
        self.app = master
        self.title("🚫 Kick / Cô lập Thiết bị khỏi Mạng")
        self.geometry("840x500")
        self.minsize(720, 440)
        self.transient(master)

        if not hasattr(master, "_kicked_ips"):
            master._kicked_ips = set()

        self._devs = [d for d in (getattr(getattr(master, "real_state", None), "devices", []) or []) if getattr(d, "ip", "")]
        self._filtered_devs: list[Any] = list(self._devs)
        if preselect_dev is not None and preselect_dev in self._devs:
            self._selected_dev = preselect_dev
        else:
            sel_id = getattr(getattr(master, "topology", None), "selected_id", None) or getattr(master, "selected_device_id", None)
            self._selected_dev = next((d for d in self._devs if getattr(d, "id", None) == sel_id), self._devs[0] if self._devs else None)

        body = ctk.CTkFrame(self, fg_color="transparent")
        body.pack(fill="both", expand=True, padx=12, pady=10)
        body.grid_columnconfigure(0, weight=0)
        body.grid_columnconfigure(1, weight=1)
        body.grid_rowconfigure(0, weight=1)

        # Cột Trái: tk.Listbox gốc siêu mượt + thanh cuộn + lọc nhanh
        left = ctk.CTkFrame(body, width=290, corner_radius=8)
        left.grid(row=0, column=0, sticky="nsew", padx=(0, 10))
        left.grid_propagate(False)
        ctk.CTkLabel(left, text="📋 Danh sách thiết bị (cuộn mượt):", font=ctk.CTkFont(size=12, weight="bold")).pack(anchor="w", padx=10, pady=(8, 4))
        self.search_e = ctk.CTkEntry(left, placeholder_text="Gõ tên hoặc IP (vd .55)...")
        self.search_e.pack(fill="x", padx=8, pady=(0, 6))
        self.search_e.bind("<KeyRelease>", lambda _e: self._populate_listbox())

        lb_wrap = tk.Frame(left, bg="#f8fafc")
        lb_wrap.pack(fill="both", expand=True, padx=8, pady=(0, 8))
        sb = tk.Scrollbar(lb_wrap, orient="vertical")
        self.lb = tk.Listbox(
            lb_wrap, yscrollcommand=sb.set, font=("Segoe UI", 10),
            bg="#ffffff", fg="#0f172a", selectbackground="#0284c7", selectforeground="#ffffff",
            activestyle="none", relief="flat", bd=1, highlightthickness=1, highlightcolor="#cbd5e1",
        )
        sb.config(command=self.lb.yview)
        sb.pack(side="right", fill="y")
        self.lb.pack(side="left", fill="both", expand=True)
        self.lb.bind("<<ListboxSelect>>", self._on_lb_select)

        # Cột Phải: Hành động Kick
        right = ctk.CTkFrame(body, corner_radius=8)
        right.grid(row=0, column=1, sticky="nsew")
        self.hdr_lbl = ctk.CTkLabel(right, text="Chọn thiết bị bên trái", font=ctk.CTkFont(size=14, weight="bold"))
        self.hdr_lbl.pack(anchor="w", padx=14, pady=(12, 4))
        self.sub_lbl = ctk.CTkLabel(right, text="", justify="left", font=ctk.CTkFont(size=11), text_color="#64748b")
        self.sub_lbl.pack(anchor="w", padx=14, pady=(0, 8))

        self.actions_frame = ctk.CTkFrame(right, fg_color="transparent")
        self.actions_frame.pack(fill="x", padx=14, pady=(0, 6))

        self.guide = ctk.CTkTextbox(right, font=ctk.CTkFont(family="Consolas", size=11), wrap="word")
        self.guide.pack(fill="both", expand=True, padx=14, pady=(4, 12))

        self._populate_listbox()
        self._render_selected()

    def _populate_listbox(self) -> None:
        q = self.search_e.get().strip().lower()
        cips = getattr(self.app, "_lanmap_client_ips", set()) or set()
        kicked = getattr(self.app, "_kicked_ips", set()) or set()
        self._filtered_devs = []
        self.lb.delete(0, "end")
        sel_idx = 0
        for d in self._devs:
            nm = str(getattr(d, "name", "") or "")
            ip = str(getattr(d, "ip", "") or "")
            if q and q not in nm.lower() and q not in ip.lower():
                continue
            idx = len(self._filtered_devs)
            self._filtered_devs.append(d)
            tag = "[CHẶN]" if ip in kicked else ("[Client]" if _device_has_lanmap_client(d, cips) else " • ")
            self.lb.insert("end", f"{tag} {nm[:16]} ({ip})")
            if d is self._selected_dev:
                sel_idx = idx
        if self._filtered_devs:
            self.lb.selection_set(sel_idx)
            self.lb.see(sel_idx)
            self._selected_dev = self._filtered_devs[sel_idx]
            self._render_selected()

    def _on_lb_select(self, _e: Any = None) -> None:
        sel = self.lb.curselection()
        if sel and sel[0] < len(self._filtered_devs):
            self._selected_dev = self._filtered_devs[sel[0]]
            self._render_selected()

    def _real_gateway_ip(self) -> str:
        for d in self._devs:
            if "gateway" in str(getattr(d, "name", "")).lower():
                return str(getattr(d, "ip", "192.168.1.1"))
        for d in self._devs:
            if str(getattr(d, "device_type", "")).lower() == "router":
                return str(getattr(d, "ip", "192.168.1.1"))
        return "192.168.1.1"

    def _render_selected(self) -> None:
        for w in self.actions_frame.winfo_children():
            w.destroy()
        self.guide.delete("1.0", "end")
        d = self._selected_dev
        if not d:
            return
        nm, ip = str(getattr(d, "name", "")), str(getattr(d, "ip", ""))
        mac = str(getattr(d, "mac", "") or "Chưa có MAC")
        has_cl = _device_has_lanmap_client(d, getattr(self.app, "_lanmap_client_ips", set()))
        gw_ip = self._real_gateway_ip()

        self.hdr_lbl.configure(text=f"🚫 {nm}  ({ip})")
        self.sub_lbl.configure(text=f"MAC: {mac}  |  Router Gateway: {gw_ip}")

        if has_cl:
            r1 = ctk.CTkFrame(self.actions_frame, fg_color="transparent")
            r1.pack(fill="x", pady=3)
            ctk.CTkButton(r1, text="⚡ Kick thẳng (Ngắt mạng Client)", fg_color="#dc2626", hover_color="#b91c1c",
                          command=lambda: self._client_isolate(True)).pack(side="left", fill="x", expand=True, padx=(0, 4))
            ctk.CTkButton(r1, text="🔌 Mở lại mạng (Client)", fg_color="#16a34a", hover_color="#15803d",
                          command=lambda: self._client_isolate(False)).pack(side="left", fill="x", expand=True, padx=(4, 0))

        ctk.CTkButton(self.actions_frame, text=f"📋 Copy MAC & Mở Web Router ({gw_ip}) để Chặn Wi-Fi",
                      fg_color="#d97706", hover_color="#b45309", command=self._kick_via_router).pack(fill="x", pady=3)
        ctk.CTkButton(self.actions_frame, text="🧱 Chặn giao tiếp trên Firewall máy này & Gắn cờ 🚫",
                      fg_color="#7c3aed", hover_color="#6d28d9", command=self._block_fw_and_mark).pack(fill="x", pady=3)

        self.guide.insert(
            "1.0",
            f"GIẢI THÍCH 2 CƠ CHẾ KICK CHO '{nm}' ({ip}):\n"
            f"1. Nút Cam (Chặn tại Router {gw_ip}): Đuổi vĩnh viễn thiết bị lạ/điện thoại xài ké ra khỏi Wi-Fi bằng MAC Filter trên Router (đã copy sẵn MAC: {mac}).\n"
            f"2. Nút Tím (Chặn Firewall máy bạn): Cô lập tức thì, không cho {ip} truy cập hay lây mã độc sang máy của bạn và gắn biểu tượng 🚫 trên sơ đồ.\n"
            f"(Với PC có cài LanMap Client màu Xanh dương sẽ có thêm nút Đỏ 'Kick thẳng' ngắt mạng 1-click!)",
        )

    def _client_isolate(self, isolate: bool) -> None:
        d = self._selected_dev
        if not d:
            return
        ip = str(getattr(d, "ip", ""))
        pin = getattr(self.app, "_client_pin_cache", {}).get(ip)
        if not pin:
            dlg = ctk.CTkInputDialog(text=f"Nhập mã PIN của LanMap Client trên {ip}:", title="Xác thực quản trị")
            pin = (dlg.get_input() or "").strip()
            if not pin:
                return
            self.app._client_pin_cache[ip] = pin
        res = query_lanmap_agent(ip, pin, "isolate_net" if isolate else "restore_net", "")
        if res and res.get("ok"):
            (self.app._kicked_ips.add if isolate else self.app._kicked_ips.discard)(ip)
            self._populate_listbox()
            try:
                self.app.topology.redraw()
            except Exception:
                pass
            messagebox.showinfo("Thành công", str(res.get("report") or "Hoàn tất!"))
        else:
            messagebox.showwarning("Thất bại", str((res or {}).get("error") or "Không kết nối được LanMap Client!"))

    def _kick_via_router(self) -> None:
        d = self._selected_dev
        if not d:
            return
        mac = str(getattr(d, "mac", "") or "")
        if mac:
            self.clipboard_clear()
            self.clipboard_append(mac)
        gw_ip = self._real_gateway_ip()
        webbrowser.open(f"http://{gw_ip}")
        self.app._kicked_ips.add(str(getattr(d, "ip", "")))
        self._populate_listbox()
        try:
            self.app.topology.redraw()
        except Exception:
            pass
        messagebox.showinfo("Đã Copy MAC & Mở Router", f"✓ Đã copy MAC: {mac}\n✓ Đã mở Web Router: http://{gw_ip}")

    def _block_fw_and_mark(self) -> None:
        d = self._selected_dev
        if not d:
            return
        ip = str(getattr(d, "ip", ""))
        self.app._kicked_ips.add(ip)
        self._populate_listbox()
        try:
            self.app.topology.redraw()
        except Exception:
            pass
        cmd = f'netsh advfirewall firewall add rule name="LanMap_KickIn_{ip}" dir=in action=block remoteip={ip} && netsh advfirewall firewall add rule name="LanMap_KickOut_{ip}" dir=out action=block remoteip={ip}'
        try:
            si = _subp_v11.STARTUPINFO() if os.name == "nt" else None
            if si:
                si.dwFlags |= _subp_v11.STARTF_USESHOWWINDOW
            p = _subp_v11.run(cmd, shell=True, capture_output=True, text=True, startupinfo=si)
            if p.returncode == 0:
                messagebox.showinfo("Đã chặn Firewall", f"🧱 Đã chặn 2 chiều với {ip} trên Windows Firewall & gắn cờ 🚫!")
            else:
                messagebox.showinfo("Đã gắn cờ 🚫", "Đã đánh dấu 🚫 trên sơ đồ. (Chạy LanMap bằng quyền Admin để khóa cứng Firewall).")
        except Exception:
            pass


# --- 2. Gửi File trực tiếp qua mạng LAN (dùng cho nút trong Panel Chi tiết) ---
def _quick_send_file_lan_v12(app: Any, dev: Any) -> None:
    ip = str(getattr(dev, "ip", "") or "")
    nm = str(getattr(dev, "name", ip) or ip)
    if not ip:
        return
    fpath = _fd_v12.askopenfilename(parent=app, title=f"Chọn tệp cần gửi tới {nm} ({ip})")
    if not fpath:
        return
    pin = getattr(app, "_client_pin_cache", {}).get(ip)
    if not pin:
        dlg = ctk.CTkInputDialog(text=f"Nhập mã PIN của LanMap Client trên {nm} ({ip}):", title="Gửi File qua LAN")
        pin = (dlg.get_input() or "").strip()
        if not pin:
            return
        app._client_pin_cache[ip] = pin
    try:
        raw = Path(fpath).read_bytes()
        if len(raw) > 50 * 1024 * 1024:
            messagebox.showwarning("File quá lớn", "Giới hạn gửi nhanh qua LAN là 50 MB!")
            return
        payload = json.dumps({"filename": Path(fpath).name, "data_b64": base64.b64encode(raw).decode("ascii")})
        res = query_lanmap_agent(ip, pin, "send_file", payload)
        if res and res.get("ok"):
            messagebox.showinfo("Gửi file thành công", str(res.get("report") or f"Đã gửi {Path(fpath).name} tới {nm}!"))
        else:
            messagebox.showwarning("Không gửi được", str((res or {}).get("error") or "Kiểm tra lại LanMap Client hoặc mã PIN trên máy nhận!"))
    except Exception as exc:
        messagebox.showerror("Lỗi gửi file", str(exc))


# --- 3. Sắp xếp lại Menu 'Công cụ' khoa học (Chọn card mạng lên đầu!) & KHÔNG BAO GIỜ MẤT KHI ĐỔI NGÔN NGỮ ---
def _organize_menus_v12(app: Any) -> None:
    return
    try:
        mbar_name = app.cget("menu")
        if not mbar_name:
            return
        mbar = app.nametowidget(mbar_name)
        end_i = mbar.index("end")
        if end_i is None:
            return
        lang = getattr(getattr(app, "real_state", None), "language", "vi")

        for i in range(end_i + 1):
            if mbar.type(i) != "cascade":
                continue
            lbl = str(mbar.entrycget(i, "label") or "")
            sub = mbar.nametowidget(mbar.entrycget(i, "menu"))

            # Sắp xếp Menu CÔNG CỤ: Giữ 'Chọn card mạng & Phát hiện' ở NGAY ĐẦU, đưa các công cụ nâng cao xuống nhóm dưới!
            if any(k in lbl for k in ("Công cụ", "Tools", "工具")):
                s_end = sub.index("end") or 0
                existing_labels = [str(sub.entrycget(j, "label") or "") for j in range(s_end + 1) if sub.type(j) == "command"]
                # Xóa các mục bị v9/v10 chèn nhầm lên đầu (index 0..4) để xếp lại đúng vị trí gọn gàng bên dưới!
                top_pro_keys = ("Quét mạng hiện tại", "Giám sát Thiết bị Vào / Ra", "Kick / Cô lập", "Quét Virus & Phát hiện", "Biểu đồ Ping & Uptime",
                                "5-Layer Deep", "Live Presence", "Kick / Isolate", "Virus & Data", "Live Ping & Uptime")
                for j in range(s_end, -1, -1):
                    if sub.type(j) == "command":
                        sl = str(sub.entrycget(j, "label") or "")
                        if any(k in sl for k in top_pro_keys):
                            sub.delete(j)

                # Chèn nhóm Công cụ Pro vào ĐÚNG vị trí (ngay trước dòng 'Bật / Tắt Chế độ Demo' ở cuối menu!)
                s_end2 = sub.index("end") or 0
                insert_pos = s_end2
                for j in range(s_end2 + 1):
                    if sub.type(j) == "command":
                        sl = str(sub.entrycget(j, "label") or "")
                        if any(k in sl for k in ("Demo", "演示")):
                            insert_pos = max(0, j - 1)
                            break

                pro_items = [
                    ("🔍 Quét mạng hiện tại (Nhanh / Kỹ)...", lambda: DeepInfraScanDialog(app)),
                    ("📤 Gửi File qua mạng LAN...", lambda: LanFileTransferDialog(app)),
                    ("🔌 Tra cổng Switch theo IP / MAC (Netdisco)...", lambda: SwitchPortLookupDialog(app)),
                    ("🌳 Gom cảnh báo theo nhánh mạng (LibreNMS)...", lambda: BranchFaultGroupingDialog(app)),
                    ("🗂️ Hồ sơ VLAN theo phòng ban (NetBox CSV)...", lambda: VlanProfileManagerDialog(app)),
                    ("📝 So sánh cấu hình Switch (Oxidized Diff)...", lambda: SwitchConfigDiffDialog(app)),
                    ("📡 Giám sát Thiết bị Vào / Ra Mạng...", lambda: LivePresenceMonitorDialog(app)),
                    ("📈 Biểu đồ Ping & Uptime Thời gian thực...", lambda: LiveLatencyChartDialog(app)),
                    ("🦠 Quét Virus & Kiểm tra an toàn...", lambda: ThreatAndExfilScannerDialog(app)),
                    ("🚫 Kick / Cô lập Thiết bị khỏi Mạng...", lambda: KickIsolateDialog(app)),
                ]
                sub.insert_separator(insert_pos)
                for offset, (item_lbl, item_cmd) in enumerate(pro_items, 1):
                    sub.insert_command(insert_pos + offset, label=_translate_text_v7(item_lbl, lang), command=item_cmd)

            # Đảm bảo Menu TRỢ GIÚP luôn có đủ: Phân tích mạng hiện tại + Sổ tay Giáo trình OSI/CCNA + Sổ tay sử dụng + LanBot
            elif any(k in lbl for k in ("Trợ giúp", "Help", "帮助")):
                h_end = sub.index("end") or 0
                h_labels = [str(sub.entrycget(j, "label") or "") for j in range(h_end + 1) if sub.type(j) == "command"]
                for j in range(h_end + 1):
                    if sub.type(j) == "command":
                        sl = str(sub.entrycget(j, "label") or "")
                        if any(k in sl for k in ("Sổ tay khắc phục", "Troubleshooting", "故障排查")):
                            sub.entryconfig(j, label=_translate_text_v7("📘 Sổ tay Khắc phục sự cố (Giáo trình OSI & CCNA)...", lang),
                                            command=lambda: TextbookHandbookDialog(app))
                if not any("Phân tích" in x or "Live Network Analysis" in x or "当前网络" in x for x in h_labels):
                    def _open_audit() -> None:
                        _sc, rep = build_live_network_analysis_text(app)
                        show_scrollable_guide(app, "📊 Sổ tay Phân tích & Đánh giá Mạng hiện tại", rep)
                    sub.insert_command(0, label=_translate_text_v7("📊 Phân tích & Đánh giá Mạng hiện tại...", lang), command=_open_audit)
                if not any("LanBot" in x for x in h_labels):
                    sub.add_command(label=_translate_text_v7("🤖 Mở Trợ lý LanBot AI", lang), command=lambda: app.lanbot.open_chat())

            # Đảm bảo Menu TỆP luôn có Xuất Báo cáo CSV Đẹp
            elif any(k in lbl for k in ("Tệp", "File", "文件")):
                f_end = sub.index("end") or 0
                f_labels = [str(sub.entrycget(j, "label") or "") for j in range(f_end + 1) if sub.type(j) == "command"]
                if not any("CSV Đẹp" in x or "Excel" in x for x in f_labels):
                    sub.add_command(label="📄 Xuất Báo cáo CSV Đẹp (Chuẩn Excel)...", command=lambda: export_pretty_csv_report_v9(app))
    except Exception:
        pass


# --- 4. Lọc nút thông minh trong Panel Chi tiết (Xóa RDP, ẩn SNMP/SSH/WoL không hợp lệ, thêm Kick + Gửi File!) ---
def _refine_detail_panel_v12(app: Any) -> None:
    """Đã dựng trực tiếp trong DetailPanel.render() — vô hiệu hóa hook hậu kỳ."""
    return
    try:
        # Tìm thiết bị đang chọn
        sel_id = getattr(getattr(app, "topology", None), "selected_id", None) or getattr(app, "selected_device_id", None)
        devs = list(getattr(getattr(app, "real_state", None), "devices", []) or [])
        dev = next((d for d in devs if getattr(d, "id", None) == sel_id), None)
        if not dev:
            return
        dt = str(getattr(dev, "device_type", "") or "").lower()
        nm_l = str(getattr(dev, "name", "") or "").lower()
        is_this_pc = dt == "this_pc" or "máy này" in nm_l or "this pc" in nm_l or "本机" in nm_l
        is_pc_or_srv = dt in ("pc", "computer", "workstation", "laptop", "server", "this_pc")
        is_infra = dt in ("router", "switch", "wifi", "ap", "server")

        # Tìm container chứa nút 'Công cụ quản trị chủ động' (có nút 'Web quản trị' / 'Remote RDP' / 'Quét cổng')
        anchor_parent = None

        def _walk_detail(w: Any) -> None:
            nonlocal anchor_parent
            try:
                if w.__class__.__name__ == "CTkButton":
                    txt = str(w.cget("text") or "")
                    # 1. XÓA HẲN Remote RDP ở mọi thiết bị
                    if "Remote RDP" in txt or "RDP" in txt:
                        w.grid_forget(); w.pack_forget()
                        anchor_parent = anchor_parent or w.master
                    # 2. Đọc SNMP & Mở SSH chỉ dành cho Router / Switch / Wi-Fi AP / Server
                    elif ("SNMP" in txt or "Mở SSH" in txt or "SSH" in txt) and not is_infra:
                        w.grid_forget(); w.pack_forget()
                        anchor_parent = anchor_parent or w.master
                    # 3. Bật máy (WoL) chỉ dành cho PC & Server (không hiện trên Điện thoại / Router / Camera!)
                    elif ("WoL" in txt or "Bật máy" in txt) and not is_pc_or_srv:
                        w.grid_forget(); w.pack_forget()
                        anchor_parent = anchor_parent or w.master
                    # 4. Chia sẻ (\IP), Xem chia sẻ, Đồng bộ LanMap Client chỉ dành cho PC & Server
                    elif any(k in txt for k in ("Chia sẻ", "Xem chia sẻ", "LanMap Client")) and not is_pc_or_srv:
                        w.grid_forget(); w.pack_forget()
                        anchor_parent = anchor_parent or w.master
                    elif "Đánh dấu Thiết bị lạ" in txt or "Duyệt Tin cậy" in txt or "Quét sâu (Nmap)" in txt:
                        anchor_parent = anchor_parent or w.master
                for ch in w.winfo_children():
                    _walk_detail(ch)
            except Exception:
                pass

        _walk_detail(app)

        # Thêm trực tiếp 2 nút '🚫 Kick / Cô lập thiết bị' và '📤 Gửi File qua LAN' ngay vào Panel Chi tiết!
        if anchor_parent is not None:
            # Xóa nút v12 cũ nếu có để tránh lặp khi chọn máy khác
            for ch in list(anchor_parent.winfo_children()):
                if getattr(ch, "_is_v12_btn", False):
                    ch.destroy()
            parent_pack = anchor_parent.master if anchor_parent.grid_slaves() else anchor_parent
            for ch in list(parent_pack.winfo_children()):
                if getattr(ch, "_is_v12_btn", False):
                    ch.destroy()

            if is_pc_or_srv and not is_this_pc:
                b_file = ctk.CTkButton(
                    parent_pack, text="📤 Gửi File qua mạng LAN...", height=28,
                    fg_color="#0284c7", hover_color="#0369a1",
                    command=lambda d=dev: _quick_send_file_lan_v12(app, d),
                )
                b_file._is_v12_btn = True
                b_file.pack(fill="x", padx=6, pady=(3, 2))

            if not is_this_pc:
                b_kick = ctk.CTkButton(
                    parent_pack, text="🚫 Kick / Cô lập thiết bị này...", height=28,
                    fg_color="#dc2626", hover_color="#b91c1c",
                    command=lambda d=dev: KickIsolateDialog(app, preselect_dev=d),
                )
                b_kick._is_v12_btn = True
                b_kick.pack(fill="x", padx=6, pady=(2, 4))
    except Exception:
        pass


# --- 5. Ghi đè Giám sát Vào/Ra & LanBot v12.0: CHỈ bắn cảnh báo Windows khi ĐỒNG LOẠT ≥ 2 máy mất kết nối! ---
_orig_presence_v11 = LivePresenceMonitorDialog


class LivePresenceMonitorDialog(_orig_presence_v11):
    def _on_scan_done(self, alive_now: dict[str, bool], joined_now: list[tuple[str, str]], left_now: list[tuple[str, str]]) -> None:
        # Chặn thông báo khi chỉ 1 thiết bị rời mạng — chỉ báo khi đồng loạt ≥ 2 thiết bị!
        filtered_left = left_now if len(left_now) >= 2 else []
        super()._on_scan_done(alive_now, [], filtered_left)
        if len(left_now) >= 2:
            send_windows_toast("🚨 LanMap — MẠNG CÓ VẤN ĐỀ!", f"Đồng loạt {len(left_now)} thiết bị vừa mất kết nối khỏi mạng!", "Error")


_orig_lanbot_v11 = LanBotAssistant


class LanBotAssistant(_orig_lanbot_v11):
    def __init__(self, app: "LanMapApp") -> None:
        super().__init__(app)
        self._last_sel_id = None
        self._apply_v12_startup_and_hooks(app)

    def _apply_v12_startup_and_hooks(self, app: Any) -> None:
        # 1. Tự phóng to FULL màn hình (zoomed) ngay khi khởi động — hết bị lệch xéo!
        def _maximize_and_center() -> None:
            try:
                if os.name == "nt":
                    app.state("zoomed")
                else:
                    app.attributes("-zoomed", True)
                if hasattr(app, "topology") and hasattr(app.topology, "fit_to_view"):
                    app.after(250, app.topology.fit_to_view)
            except Exception:
                pass

        app.after(150, _maximize_and_center)
        app.after(1600, lambda: _organize_menus_v12(app))

        # 3. Bọc hàm đổi ngôn ngữ để KHÔNG BAO GIỜ mất mục menu khi chuyển qua lại VI/EN/ZH!
        for lname in ("_set_language", "_apply_language", "set_language"):
            if hasattr(app, lname):
                orig_l = getattr(app, lname)

                def _wrap_lang(*a: Any, _orig: Any = orig_l, **kw: Any) -> Any:
                    r = _orig(*a, **kw)
                    app.after(150, lambda: (_organize_menus_v12(app), _sync_full_i18n_v7(app)))
                    return r

                setattr(app, lname, _wrap_lang)

    def _watch_network_and_i18n(self) -> None:
        """Tối ưu hiệu năng (5 giây/lần thay vì 2.8s) + CHỈ bắn cảnh báo khi đồng loạt ≥ 2 thiết bị mất kết nối!"""
        if not self.app.winfo_exists():
            return
        try:
            # Đồng bộ ngôn ngữ & menu CHỈ KHI ngôn ngữ thay đổi (không gây khựng!)
            cur_lang = getattr(getattr(self.app, "real_state", None), "language", "vi")
            if cur_lang != self._last_lang:
                self._last_lang = cur_lang
                _organize_menus_v12(self.app)
                _sync_full_i18n_v7(self.app)

            # Theo dõi đồng loạt mất kết nối (≥ 2 máy mới cảnh báo, bỏ cảnh báo lẻ 1 máy!)
            devs = list(getattr(getattr(self.app, "real_state", None), "devices", []) or [])
            dropped: list[tuple[str, str]] = []
            ts = time.strftime("%H:%M:%S")
            hist = getattr(self.app, "_presence_history", [])
            for d in devs:
                key = str(getattr(d, "id", "") or getattr(d, "ip", ""))
                nm, ip = str(getattr(d, "name", key)), str(getattr(d, "ip", ""))
                st_raw = str(getattr(d, "status", "") or "").lower()
                if d.status == STATUS_UNCHECKED:
                    continue
                norm_st = "offline" if d.status == STATUS_NO_PING or any(
                    word in st_raw for word in ("off", "down", "fail", "lost", "unreach")
                ) else "online"
                prev = self._prev_status.get(key)
                if prev == "online" and norm_st == "offline":
                    dropped.append((nm, ip))
                    hist.append(f"[{ts}] 🔴 Rời mạng: {nm} ({ip})")
                elif prev == "offline" and norm_st == "online":
                    hist.append(f"[{ts}] 🟢 Kết nối lại: {nm} ({ip})")
                self._prev_status[key] = norm_st

            if len(dropped) >= 2:
                self._mood = "alert"
                self._draw_bot()
                sample = ", ".join(f"{nm} ({ip})" for nm, ip in dropped[:3])
                msg = f"Đồng loạt {len(dropped)} thiết bị mất kết nối ({sample}...). Kiểm tra ngay Router/Switch hoặc dây mạng!"
                self.show_bubble(f"🚨 MẠNG CÓ VẤN ĐỀ! Đồng loạt {len(dropped)} thiết bị rớt mạng!")
                if self._win_notify_enabled:
                    send_windows_toast("🚨 LanMap — CẢNH BÁO MẠNG CÓ VẤN ĐỀ!", msg, "Error")

        except Exception:
            pass
        self.app.after(5000, self._watch_network_and_i18n)



