import unicodedata as _ud_v13


def _strip_vn_v13(s: str) -> str:
    s = s.replace("đ", "d").replace("Đ", "D")
    return "".join(c for c in _ud_v13.normalize("NFD", s) if _ud_v13.category(c) != "Mn").lower()


# --- 1. Bảng dịch ĐẦY ĐỦ 100% VI / EN / ZH (ưu tiên cụm từ dài trước để KHÔNG BAO GIỜ dịch nửa vời!) ---
_I18N_V13: list[tuple[str, str, str]] = [
    ("🔍 Quét mạng hiện tại (Nhanh / Kỹ)...", "🔍 Scan current network (Fast / Deep)...", "🔍 扫描当前网络（快速 / 深度）..."),
    ("📡 Giám sát Thiết bị Vào / Ra Mạng...", "📡 Live Device Join / Leave Monitor...", "📡 设备上下线实时监控..."),
    ("📈 Biểu đồ Ping & Uptime Thời gian thực...", "📈 Live Ping & Uptime Chart...", "📈 实时 Ping 与在线率图表..."),
    ("🦠 Quét Virus & Kiểm tra an toàn...", "🦠 Malware & Data Safety Review...", "🦠 病毒与数据安全检查..."),
    ("🚫 Kick / Cô lập Thiết bị khỏi Mạng...", "🚫 Kick / Isolate Device from Network...", "🚫 踢出 / 隔离网络设备..."),
    ("📘 Sổ tay Khắc phục sự cố (Giáo trình OSI & CCNA)...", "📘 Network Troubleshooting Handbook (OSI & CCNA)...", "📘 网络故障排查教材手册 (OSI & CCNA)..."),
    ("📊 Phân tích & Đánh giá Mạng hiện tại...", "📊 Live Network Health Analysis & Audit...", "📊 当前网络健康分析与评估..."),
    ("📄 Xuất Báo cáo CSV Đẹp (Chuẩn Excel)...", "📄 Export Formatted CSV Report (Excel)...", "📄 导出精美 CSV 报表 (Excel)..."),
    ("🤖 Mở Trợ lý LanBot AI", "🤖 Open LanBot AI Assistant", "🤖 打开 LanBot AI 助手"),
    ("+ Khung Tầng", "+ Floor Zone", "+ 楼层区域"),
    ("↔ Tách Subnet", "↔ Split Subnets", "↔ 拆分网段"),
    ("PC có Client", "PC w/ Client", "已装客户端"),
    ("PC chưa cài", "PC No Client", "未装客户端"),
    ("Chưa ghi nhận", "Unregistered", "未登记设备"),
    ("Nhật ký sự cố", "Incident Log", "故障日志"),
    ("Lưu lượng & Ứng dụng", "Traffic & Apps", "流量与应用"),
    ("Cùng subnet", "Same subnet", "同网段"),
]


def _tr_v13(text: str, lang: str) -> str:
    if not text:
        return text
    idx = 0 if lang == "vi" else (1 if lang == "en" else 2)
    # Khớp chính xác chuỗi đầy đủ trước
    for triple in _I18N_V13:
        if text in triple:
            return triple[idx]
    out = text
    for triple in _I18N_V13:
        target = triple[idx]
        for i, src_s in enumerate(triple):
            if i != idx and src_s in out:
                out = out.replace(src_s, target)
    return _translate_text_v7(out, lang)


# --- 2. Dọn sạch Menu Công cụ (KHÔNG trùng lặp, KHÔNG 3 đường kẻ -----, dịch chuẩn 100% VI/EN/ZH!) ---
def _clean_and_rebuild_pro_menus_v13(app: Any) -> None:
    try:
        mbar_name = app.cget("menu")
        if not mbar_name:
            return
        mbar = app.nametowidget(mbar_name)
        end_i = mbar.index("end")
        if end_i is None:
            return
        lang = getattr(getattr(app, "real_state", None), "language", "vi")

        pro_signatures = (
            "Quét mạng hiện tại", "Scan current network", "扫描当前网络",
            "Gửi File qua mạng LAN", "Send LAN file",
            "Tra cổng Switch", "Switch Port Lookup",
            "Gom cảnh báo theo nhánh", "Branch Fault",
            "Hồ sơ VLAN theo phòng ban", "VLAN Profile",
            "So sánh cấu hình Switch", "Switch Config Diff",
            "Giám sát Thiết bị Vào", "Giám sát Device Vào", "Live Device Join", "设备上下线",
            "Biểu đồ Ping", "Live Ping & Uptime", "实时 Ping",
            "Quét Virus", "Malware & Data", "病毒与数据",
            "Kick / Cô lập", "Kick / Isolate", "踢出 / 隔离",
        )

        for i in range(end_i + 1):
            if mbar.type(i) != "cascade":
                continue
            lbl = str(mbar.entrycget(i, "label") or "")
            sub = mbar.nametowidget(mbar.entrycget(i, "menu"))

            if any(k in lbl for k in ("Công cụ", "Tools", "工具")):
                # 1. Xóa sạch mọi mục Pro cũ (dù ở bất kỳ ngôn ngữ hay bị dịch lỗi nào)
                s_end = sub.index("end")
                if s_end is not None:
                    for j in range(s_end, -1, -1):
                        if sub.type(j) == "command":
                            sl = str(sub.entrycget(j, "label") or "")
                            if any(sig in sl for sig in pro_signatures):
                                sub.delete(j)

                # 2. Xóa sạch các đường kẻ separator liên tiếp hoặc ở đầu/cuối menu
                s_end2 = sub.index("end")
                if s_end2 is not None:
                    prev_sep = True
                    for j in range(s_end2, -1, -1):
                        if sub.type(j) == "separator":
                            if prev_sep or j == 0:
                                sub.delete(j)
                            else:
                                prev_sep = True
                        else:
                            prev_sep = False

                # 3. Chèn DUY NHẤT 1 nhóm Công cụ Pro vào ngay trên nhóm cuối (Demo/Desktop/GitHub)
                s_end3 = sub.index("end") or 0
                insert_pos = s_end3 + 1
                for j in range(s_end3 + 1):
                    if sub.type(j) == "command":
                        sl = str(sub.entrycget(j, "label") or "")
                        if any(k in sl for k in ("Demo", "演示")):
                            insert_pos = j
                            break

                pro_items = [
                    ("🔍 Quét mạng hiện tại (Nhanh / Kỹ)...", lambda: DeepInfraScanDialog(app)),
                    ("🔌 Tra cổng Switch theo IP / MAC (Netdisco)...", lambda: SwitchPortLookupDialog(app)),
                    ("🌳 Gom cảnh báo theo nhánh mạng (LibreNMS)...", lambda: BranchFaultGroupingDialog(app)),
                    ("🗂️ Hồ sơ VLAN theo phòng ban (NetBox CSV)...", lambda: VlanProfileManagerDialog(app)),
                    ("📝 So sánh cấu hình Switch (Oxidized Diff)...", lambda: SwitchConfigDiffDialog(app)),
                    ("📡 Giám sát Thiết bị Vào / Ra Mạng...", lambda: LivePresenceMonitorDialog(app)),
                    ("📈 Biểu đồ Ping & Uptime Thời gian thực...", lambda: LiveLatencyChartDialog(app)),
                    ("🦠 Quét Virus & Kiểm tra an toàn...", lambda: ThreatAndExfilScannerDialog(app)),
                    ("🚫 Kick / Cô lập Thiết bị khỏi Mạng...", lambda: KickIsolateDialog(app)),
                ]
                # Nếu ngay trước insert_pos chưa có separator thì thêm 1 cái duy nhất
                if insert_pos > 0 and sub.type(insert_pos - 1) != "separator":
                    sub.insert_separator(insert_pos)
                    insert_pos += 1
                for idx_p, (vi_lbl, cmd_fn) in enumerate(pro_items):
                    sub.insert_command(insert_pos + idx_p, label=_tr_v13(vi_lbl, lang), command=cmd_fn)
                after_pos = insert_pos + len(pro_items)
                if after_pos <= (sub.index("end") or 0) and sub.type(after_pos) != "separator":
                    sub.insert_separator(after_pos)

            elif any(k in lbl for k in ("Trợ giúp", "Help", "帮助")):
                h_end = sub.index("end") or 0
                h_labels = [str(sub.entrycget(j, "label") or "") for j in range(h_end + 1) if sub.type(j) == "command"]
                for j in range(h_end + 1):
                    if sub.type(j) == "command":
                        sl = str(sub.entrycget(j, "label") or "")
                        if any(k in sl for k in ("Sổ tay khắc phục", "Troubleshooting", "故障排查", "OSI")):
                            sub.entryconfig(j, label=_tr_v13("📘 Sổ tay Khắc phục sự cố (Giáo trình OSI & CCNA)...", lang),
                                            command=lambda: TextbookHandbookDialog(app))
                if not any(k in x for x in h_labels for k in ("Phân tích", "Live Network Health", "当前网络")):
                    def _open_audit() -> None:
                        _sc, rep = build_live_network_analysis_text(app)
                        show_scrollable_guide(app, "📊 Sổ tay Phân tích & Đánh giá Mạng hiện tại", rep)
                    sub.insert_command(0, label=_tr_v13("📊 Phân tích & Đánh giá Mạng hiện tại...", lang), command=_open_audit)
                if not any("LanBot" in x for x in h_labels):
                    sub.add_command(label=_tr_v13("🤖 Mở Trợ lý LanBot AI", lang), command=lambda: app.lanbot.open_chat())
    except Exception:
        pass


# --- 3. Sửa TRIỆT ĐỂ Panel Chi tiết (Đọc trực tiếp IP đang hiện + Xóa RDP/SNMP/WoL sai chỗ + Thêm Kick/Gửi File + Cuộn chuột mượt!) ---
def _enable_recursive_mousewheel_v13(sf: Any) -> None:
    """Gắn sự kiện cuộn con lăn chuột <MouseWheel> cho toàn bộ widget con bên trong CTkScrollableFrame!"""
    canvas = getattr(sf, "_parent_canvas", None)
    if not canvas:
        return

    def _on_wheel(e: tk.Event) -> str:
        try:
            delta = int(-1 * (e.delta / 120)) if e.delta else (1 if e.num == 5 else -1)
            canvas.yview_scroll(delta, "units")
        except Exception:
            pass
        return "break"

    def _bind_all(w: Any) -> None:
        try:
            if not getattr(w, "_v13_mw_bound", False):
                w._v13_mw_bound = True
                w.bind("<MouseWheel>", _on_wheel, add="+")
            for ch in w.winfo_children():
                _bind_all(ch)
        except Exception:
            pass

    _bind_all(sf)


def _find_detail_scrollable_and_ip_v13(app: Any) -> tuple[Any, str | None]:
    """Tìm đúng CTkScrollableFrame của Panel Chi tiết bên phải & đọc địa chỉ IP đang hiển thị trên đó."""
    found_sf = None
    found_ip = None

    def _walk(w: Any, cur_sf: Any = None) -> None:
        nonlocal found_sf, found_ip
        try:
            if w.__class__.__name__ == "CTkScrollableFrame":
                cur_sf = w
            elif w.__class__.__name__ == "CTkButton":
                txt = str(w.cget("text") or "")
                if any(k in txt for k in ("Web quản trị", "Remote RDP", "Quét cổng", "Quét sâu (Nmap)", "Web Admin")):
                    if cur_sf is not None:
                        found_sf = cur_sf
            elif w.__class__.__name__ == "CTkLabel" and cur_sf is not None:
                txt = str(w.cget("text") or "").strip()
                if re.fullmatch(r"\d{1,3}(?:\.\d{1,3}){3}", txt):
                    if found_sf is cur_sf or found_ip is None:
                        found_ip = txt
            for ch in w.winfo_children():
                _walk(ch, cur_sf)
        except Exception:
            pass

    _walk(app)
    return found_sf, found_ip


def _smart_refine_detail_panel_v13(app: Any) -> None:
    """Lọc sạch nút thừa theo đúng loại thiết bị + Thêm Kick thẳng / Gửi File + Bật cuộn chuột mượt!"""
    try:
        sf, ip_shown = _find_detail_scrollable_and_ip_v13(app)
        if sf is None:
            return
        _enable_recursive_mousewheel_v13(sf)
        if not ip_shown:
            return

        devs = list(getattr(getattr(app, "real_state", None), "devices", []) or [])
        dev = next((d for d in devs if str(getattr(d, "ip", "")) == ip_shown), None)
        if not dev:
            return

        dt = str(getattr(dev, "device_type", "") or "").lower()
        nm_l = str(getattr(dev, "name", "") or "").lower()
        is_this_pc = dt == "this_pc" or "máy này" in nm_l or "this pc" in nm_l or "本机" in nm_l
        is_pc_or_srv = dt in ("pc", "computer", "workstation", "laptop", "server", "this_pc")
        is_infra = dt in ("router", "switch", "wifi", "ap", "server")
        has_cl = _device_has_lanmap_client(dev, getattr(app, "_lanmap_client_ips", set()))

        # Tránh lặp lại vô ích nếu đã lọc xong đúng thiết bị này trên đúng frame này
        sig = f"{id(sf)}|{ip_shown}|{has_cl}"
        if getattr(sf, "_v13_refined_sig", "") == sig:
            return
        sf._v13_refined_sig = sig

        btn_container = None

        def _filter_btns(w: Any) -> None:
            nonlocal btn_container
            try:
                if w.__class__.__name__ == "CTkButton" and not getattr(w, "_v13_custom", False):
                    txt = str(w.cget("text") or "")
                    # 1. XÓA HẲN Remote RDP trên MỌI thiết bị
                    if "RDP" in txt:
                        w.grid_forget(); w.pack_forget()
                        btn_container = btn_container or w.master
                    # 2. Đọc SNMP & Mở SSH chỉ dành cho Router / Switch / Wi-Fi AP / Server
                    elif ("SNMP" in txt or "SSH" in txt) and not is_infra:
                        w.grid_forget(); w.pack_forget()
                        btn_container = btn_container or w.master
                    # 3. Bật máy (WoL) chỉ dành cho PC & Server
                    elif ("WoL" in txt or "Bật máy" in txt or "Wake" in txt) and not is_pc_or_srv:
                        w.grid_forget(); w.pack_forget()
                        btn_container = btn_container or w.master
                    # 4. Chia sẻ (\IP), Xem chia sẻ, LanMap Client chỉ dành cho PC & Server
                    elif any(k in txt for k in ("Chia sẻ", "Xem chia sẻ", "LanMap Client", "Share", "SMB")) and not is_pc_or_srv:
                        w.grid_forget(); w.pack_forget()
                        btn_container = btn_container or w.master
                    elif any(k in txt for k in ("Đánh dấu Thiết bị lạ", "Duyệt Thiết bị", "Quét sâu (Nmap)", "Trust")):
                        btn_container = btn_container or w.master
                for ch in w.winfo_children():
                    _filter_btns(ch)
            except Exception:
                pass

        _filter_btns(sf)

        # Gắn các nút hành động đúng loại thiết bị ngay dưới nhóm nút quản trị
        target_box = sf
        for ch in list(target_box.winfo_children()):
            if getattr(ch, "_v13_custom", False):
                ch.destroy()

        if is_pc_or_srv and not is_this_pc:
            b_file = ctk.CTkButton(
                target_box, text="📤 Gửi File qua mạng LAN...", height=30,
                fg_color="#0284c7", hover_color="#0369a1",
                command=lambda d=dev: _quick_send_file_lan_v12(app, d),
            )
            b_file._v13_custom = True
            b_file.pack(fill="x", padx=8, pady=(4, 2))

        if has_cl and not is_this_pc:
            def _instant_kick(d: Any = dev) -> None:
                ip = str(getattr(d, "ip", ""))
                pin = getattr(app, "_client_pin_cache", {}).get(ip)
                if not pin:
                    dlg = ctk.CTkInputDialog(text=f"Nhập PIN LanMap Client trên {d.name} ({ip}) để Kick thẳng:", title="⚡ Kick thẳng")
                    pin = (dlg.get_input() or "").strip()
                    if not pin:
                        return
                    app._client_pin_cache[ip] = pin
                res = query_lanmap_agent(ip, pin, "isolate_net", "")
                if res and res.get("ok"):
                    app._kicked_ips.add(ip)
                    app.topology.redraw()
                    messagebox.showinfo("⚡ Đã Kick thẳng!", str(res.get("report") or f"Đã ngắt mạng máy {d.name}!"))
                else:
                    messagebox.showwarning("Chưa Kick được", str((res or {}).get("error") or "Kiểm tra lại Client v2.5 / PIN!"))

            b_ik = ctk.CTkButton(
                target_box, text="⚡ Kick thẳng (Ngắt mạng Client)", height=30,
                fg_color="#b91c1c", hover_color="#991b1b", command=_instant_kick,
            )
            b_ik._v13_custom = True
            b_ik.pack(fill="x", padx=8, pady=(2, 2))

        if not is_this_pc:
            b_kick = ctk.CTkButton(
                target_box, text="🚫 Kick / Cô lập thiết bị này...", height=30,
                fg_color="#dc2626", hover_color="#b91c1c",
                command=lambda d=dev: KickIsolateDialog(app, preselect_dev=d),
            )
            b_kick._v13_custom = True
            b_kick.pack(fill="x", padx=8, pady=(2, 6))

        _enable_recursive_mousewheel_v13(sf)
    except Exception:
        pass


