class TextbookHandbookDialog(ctk.CTkToplevel):
    """Sổ tay Khắc phục Sự cố Mạng giao diện Thẻ Hiện Đại (Sidebar mục lục + Card màu sắc + Nút Copy lệnh!)."""

    def __init__(self, master: ctk.CTk) -> None:
        super().__init__(master)
        self.title("📘 Sổ tay Khắc phục Sự cố Mạng Pro (Giáo trình OSI 7 Tầng & Cisco CCNA)")
        self.geometry("980x660")
        self.minsize(820, 520)
        self.transient(master)

        body = ctk.CTkFrame(self, fg_color="transparent")
        body.pack(fill="both", expand=True, padx=12, pady=12)
        body.grid_columnconfigure(0, weight=0)
        body.grid_columnconfigure(1, weight=1)
        body.grid_rowconfigure(0, weight=1)

        # Sidebar mục lục bên trái (Modern Docs UI)
        side = ctk.CTkFrame(body, width=230, corner_radius=12, fg_color=("#f1f5f9", "#0f172a"))
        side.grid(row=0, column=0, sticky="nsew", padx=(0, 12))
        side.grid_propagate(False)
        ctk.CTkLabel(side, text="📘 GIÁO TRÌNH MẠNG", font=ctk.CTkFont(size=14, weight="bold"), text_color="#0284c7").pack(anchor="w", padx=14, pady=(14, 6))
        self.search_e = ctk.CTkEntry(side, placeholder_text="🔎 Tìm nhanh (DNS, OSI...)")
        self.search_e.pack(fill="x", padx=12, pady=(0, 10))
        self.search_e.bind("<KeyRelease>", lambda _e: self._render_cards(self._cur_cat))

        self._cur_cat = list(_MODERN_HANDBOOK_CARDS_V13.keys())[0]
        self._nav_btns: dict[str, ctk.CTkButton] = {}
        for cat in _MODERN_HANDBOOK_CARDS_V13:
            b = ctk.CTkButton(
                side, text=cat, anchor="w", height=36, corner_radius=8,
                command=lambda c=cat: self._select_cat(c),
            )
            b.pack(fill="x", padx=10, pady=3)
            self._nav_btns[cat] = b

        # Khu vực hiển thị Thẻ kiến thức bên phải (có cuộn mượt)
        self.scroll = ctk.CTkScrollableFrame(body, corner_radius=12, fg_color=("#ffffff", "#111827"))
        self.scroll.grid(row=0, column=1, sticky="nsew")
        self._select_cat(self._cur_cat)

    def _select_cat(self, cat: str) -> None:
        self._cur_cat = cat
        for k, b in self._nav_btns.items():
            b.configure(
                fg_color="#0284c7" if k == cat else "transparent",
                text_color="#ffffff" if k == cat else ("#0f172a", "#e2e8f0"),
            )
        self._render_cards(cat)

    def _render_cards(self, cat: str) -> None:
        for w in self.scroll.winfo_children():
            w.destroy()
        q = self.search_e.get().strip().lower()
        items = []
        if q:
            for c_list in _MODERN_HANDBOOK_CARDS_V13.values():
                for it in c_list:
                    if q in (it[0] + " " + it[2] + " " + it[3]).lower():
                        items.append(it)
        else:
            items = _MODERN_HANDBOOK_CARDS_V13.get(cat, [])

        for title, color, desc, cmd in items:
            card = ctk.CTkFrame(self.scroll, corner_radius=12, fg_color=("#f8fafc", "#1e293b"), border_width=1, border_color=("#cbd5e1", "#334155"))
            card.pack(fill="x", padx=10, pady=7)
            hdr = ctk.CTkFrame(card, fg_color=color, corner_radius=8, height=34)
            hdr.pack(fill="x", padx=8, pady=(8, 4))
            ctk.CTkLabel(hdr, text=f"  {title}", font=ctk.CTkFont(size=13, weight="bold"), text_color="#ffffff").pack(side="left", pady=5)

            ctk.CTkLabel(card, text=desc, font=ctk.CTkFont(size=12), justify="left", wraplength=640, text_color=("#1e293b", "#e2e8f0")).pack(anchor="w", padx=14, pady=(4, 8))

            if cmd:
                cbox = ctk.CTkFrame(card, fg_color="#020617", corner_radius=8)
                cbox.pack(fill="x", padx=12, pady=(0, 10))
                ctk.CTkLabel(cbox, text=cmd, font=ctk.CTkFont(family="Consolas", size=11), text_color="#38bdf8", justify="left").pack(side="left", padx=10, pady=8)

                def _copy(txt: str = cmd) -> None:
                    self.clipboard_clear()
                    self.clipboard_append(txt)
                    messagebox.showinfo("Đã Copy", f"Đã copy lệnh:\n\n{txt}")

                ctk.CTkButton(cbox, text="📋 Copy", width=72, height=26, fg_color="#0284c7", command=_copy).pack(side="right", padx=8, pady=6)

        _enable_recursive_mousewheel_v13(self.scroll)


# --- 5. Nâng cấp Tạo hình LanBot AI v13.0 (Cắm dây mạng, Sửa Router, Chơi Game, Kính Râm) + NLU thông minh! ---
_orig_lanbot_v12 = LanBotAssistant


class LanBotAssistant(_orig_lanbot_v12):
    """LanBot AI v13.0:
    - 5 biểu cảm sinh động: 🔌 Cắm cáp mạng, 🔧 Sửa Router, 🎮 Chơi game, 😎 Kính râm, 😊 Cười tươi
    - NLU bỏ dấu tiếng Việt hiểu tự nhiên 'kiểm tra mạng', 'check mạng', 'quét mạng', 'xuất báo cáo'...
    - Sửa timing Splash Screen: đợi Splash đóng hẳn mới mở full màn hình & tự quét mạng!
    """

    def _apply_v12_startup_and_hooks(self, app: Any) -> None:
        app.after(1600, lambda: _clean_and_rebuild_pro_menus_v13(app))

        # Bọc đổi ngôn ngữ để dọn sạch menu & không bao giờ bị lẫn EN/VI hay 3 đường kẻ -----
        for lname in ("_set_language", "_apply_language", "set_language"):
            if hasattr(app, lname):
                orig_l = getattr(app, lname)

                def _wrap_lang(*a: Any, _orig: Any = orig_l, **kw: Any) -> Any:
                    r = _orig(*a, **kw)
                    app.after(120, lambda: (_clean_and_rebuild_pro_menus_v13(app), _sync_full_i18n_v7(app)))
                    return r

                setattr(app, lname, _wrap_lang)

    def _draw_bot(self) -> None:
        """Vẽ bé LanBot với 5 tư thế siêu dễ thương: Cắm dây mạng, Sửa Router, Chơi game, Kính râm, Cười tươi!"""
        c = self.canvas
        c.delete("all")
        alert = self._mood == "alert"
        body_col = "#fee2e2" if alert else "#fef3c7"
        rim_col = "#dc2626" if alert else "#d97706"

        # Ăng-ten
        c.create_line(24, 22, 18, 6, fill=body_col, width=3.2, capstyle=tk.ROUND)
        c.create_line(52, 22, 58, 6, fill=body_col, width=3.2, capstyle=tk.ROUND)
        c.create_oval(14, 3, 22, 11, fill="#ef4444" if alert else "#38bdf8", outline=rim_col)
        c.create_oval(54, 3, 62, 11, fill="#ef4444" if alert else "#22c55e", outline=rim_col)

        # Đầu/Thân robot bo tròn
        c.create_oval(12, 16, 64, 62, fill=body_col, outline=rim_col, width=2.2)
        c.create_rectangle(19, 25, 57, 51, fill="#0f172a", outline="#38bdf8", width=1.8)

        if self._mood == "cool":
            c.create_rectangle(22, 31, 37, 41, fill="#020617", outline="#38bdf8", width=1.6)
            c.create_rectangle(39, 31, 54, 41, fill="#020617", outline="#38bdf8", width=1.6)
            c.create_line(37, 35, 39, 35, fill="#38bdf8", width=2)
            c.create_arc(31, 42, 45, 48, start=200, extent=140, style=tk.ARC, outline="#38bdf8", width=2)
            tag_txt = "Ngầu 😎"
        elif self._mood == "cable":
            # Cắm dây cáp mạng RJ45 🔌
            c.create_text(29, 35, text="•", fill="#38bdf8", font=("Segoe UI", 14, "bold"))
            c.create_text(47, 35, text="•", fill="#38bdf8", font=("Segoe UI", 14, "bold"))
            c.create_arc(33, 41, 43, 47, start=200, extent=140, style=tk.ARC, outline="#22c55e", width=2)
            # Dây cáp mạng xanh + đầu cắm vàng bên tay phải
            c.create_line(60, 46, 72, 38, fill="#0284c7", width=3)
            c.create_rectangle(67, 31, 75, 40, fill="#fbbf24", outline="#0369a1", width=1.2)
            tag_txt = "Cắm cáp"
        elif self._mood == "wrench":
            # Sửa Router 🔧
            c.create_text(29, 35, text=">", fill="#f59e0b", font=("Consolas", 11, "bold"))
            c.create_text(47, 35, text="<", fill="#f59e0b", font=("Consolas", 11, "bold"))
            c.create_line(33, 45, 43, 45, fill="#fbbf24", width=2)
            # Cờ-lê sửa Router bên tay trái
            c.create_line(4, 34, 15, 48, fill="#94a3b8", width=3.5)
            c.create_oval(1, 29, 10, 38, fill="#cbd5e1", outline="#475569")
            tag_txt = "Sửa RT"
        elif self._mood == "gaming":
            # Chơi game 🎮
            c.create_text(29, 35, text="★", fill="#a855f7", font=("Segoe UI", 11, "bold"))
            c.create_text(47, 35, text="★", fill="#a855f7", font=("Segoe UI", 11, "bold"))
            c.create_arc(32, 41, 44, 48, start=200, extent=140, style=tk.ARC, outline="#c084fc", width=2)
            # Tay cầm Gamepad trước ngực
            c.create_rectangle(22, 54, 54, 66, fill="#1e293b", outline="#a855f7", width=1.4)
            c.create_oval(26, 58, 31, 63, fill="#38bdf8", outline="")
            c.create_oval(45, 57, 49, 61, fill="#22c55e", outline="")
            c.create_oval(49, 60, 53, 64, fill="#ef4444", outline="")
            tag_txt = "Game 🎮"
        elif alert:
            c.create_text(38, 38, text="! _ !", fill="#ef4444", font=("Consolas", 11, "bold"))
            tag_txt = "CẢNH BÁO"
        else:
            c.create_text(29, 35, text="^", fill="#38bdf8", font=("Segoe UI", 12, "bold"))
            c.create_text(47, 35, text="^", fill="#38bdf8", font=("Segoe UI", 12, "bold"))
            c.create_arc(32, 41, 44, 48, start=200, extent=140, style=tk.ARC, outline="#38bdf8", width=2)
            tag_txt = "LanBot"

        c.create_oval(10, 68, 66, 82, fill="#0284c7" if not alert else "#dc2626", outline="#ffffff", width=1)
        c.create_text(38, 75, text=tag_txt, fill="#ffffff", font=("Segoe UI", 7, "bold"))

    def _cycle_mood(self) -> None:
        if not self.app.winfo_exists():
            return
        if self._mood != "alert":
            moods = ["happy", "cable", "wrench", "gaming", "cool"]
            self._mood = moods[(moods.index(self._mood) + 1) % len(moods)] if self._mood in moods else "happy"
            self._draw_bot()
        self.app.after(4500, self._cycle_mood)

    def _analyze_query(self, raw_q: str) -> tuple[str, list[tuple[str, str]]]:
        """NLU bỏ dấu tiếng Việt thông minh — hiểu tự nhiên 'kiểm tra mạng', 'check mạng', 'quét mạng'..."""
        norm = _strip_vn_v13(raw_q).strip()

        if any(k in norm for k in ("xin chao", "chao", "hello", "hi ", "hey", "alo", "ban la ai")) and len(norm) < 25:
            return (
                "Chào bạn! 👋 Mình là **LanBot AI v13.0** — trợ lý quản trị mạng của LanMap.\n"
                "Bạn có thể hỏi mình bất cứ điều gì như:\n"
                "• \"Kiểm tra mạng\" / \"Mạng có ổn không?\"\n"
                "• \"Quét sâu tìm Router/Switch\" hoặc \"Quét virus\"\n"
                "• \"Xuất báo cáo mạng\" / \"Dựng Lab 2 phòng ban\" / \"Kick thiết bị\""
            ), [("📊 Kiểm tra & Phân tích mạng", "live_audit"), ("🔍 Quét Sâu 5 Lớp", "open_deep_v10"), ("🦠 Quét Virus", "open_virus_v9")]

        # Fix trực tiếp ảnh người dùng gõ 'kiểm tra mạng'!
        if any(k in norm for k in ("kiem tra mang", "check mang", "xem mang", "tinh trang mang", "mang sao roi", "mang co on", "phan tich mang", "suc khoe mang", "quet mang")):
            score, _full = build_live_network_analysis_text(self.app)
            devs = list(getattr(getattr(self.app, "real_state", None), "devices", []) or [])
            cips = getattr(self.app, "_lanmap_client_ips", set()) or set()
            on_c = sum(1 for d in devs if not any(w in str(getattr(d, "status", "")).lower() for w in ("off", "down", "fail", "lost", "alert")))
            off_c = len(devs) - on_c
            cl_c = sum(1 for d in devs if _device_has_lanmap_client(d, cips))
            inf_c = len(security_marker_levels(self.app))
            return (
                f"✅ Mình vừa kiểm tra nhanh toàn bộ mạng của bạn:\n"
                f"• Điểm sức khỏe mạng: **{score}/100**\n"
                f"• Thiết bị: **{len(devs)}** (🟢 Online: {on_c} | 🔴 Mất phản hồi: {off_c})\n"
                f"• PC có LanMap Client: **{cl_c}** | Dấu kiểm tra an toàn: **{inf_c}**\n\n"
                "Bạn muốn xem báo cáo chi tiết, chạy Quét Sâu 5 Lớp hay Quét Virus không?"
            ), [("📊 Xem Báo cáo Chi tiết", "live_audit"), ("🔍 Quét Sâu 5 Lớp", "open_deep_v10"), ("🦠 Quét Virus", "open_virus_v9")]

        return super()._analyze_query(raw_q)

    def _watch_network_and_i18n(self) -> None:
        super()._watch_network_and_i18n()



