# --- 1. Sửa TRIỆT ĐỂ Panel Chi tiết (Nhấp 1 lần hay 10 lần đều chuẩn + Re-grid không lỗ trống + Gợi ý riêng ĐT + Cuộn nhanh x4!) ---
def _enable_fast_mousewheel_v14(sf: Any) -> None:
    canvas = getattr(sf, "_parent_canvas", None)
    if not canvas:
        return

    def _on_wheel(e: tk.Event) -> str:
        try:
            step = -4 if (e.delta and e.delta > 0) else 4
            canvas.yview_scroll(step, "units")
        except Exception:
            pass
        return "break"

    def _bind_all(w: Any) -> None:
        try:
            w.bind("<MouseWheel>", _on_wheel)
            for ch in w.winfo_children():
                _bind_all(ch)
        except Exception:
            pass

    _bind_all(sf)


def _smart_refine_detail_panel_v14(app: Any) -> None:
    try:
        sf, ip_shown = _find_detail_scrollable_and_ip_v13(app)
        if sf is None:
            return
        _enable_fast_mousewheel_v14(sf)
        if not ip_shown:
            return

        devs = list(getattr(getattr(app, "real_state", None), "devices", []) or [])
        dev = next((d for d in devs if str(getattr(d, "ip", "")) == ip_shown), None)
        if not dev:
            return

        dt = str(getattr(dev, "device_type", "") or "").lower()
        nm_l = str(getattr(dev, "name", "") or "").lower()
        is_this_pc = dt == "this_pc" or "máy này" in nm_l or "this pc" in nm_l or "本机" in nm_l
        is_phone = dt in ("phone", "mobile") or "điện thoại" in nm_l or "phone" in nm_l or "手机" in nm_l
        is_pc_or_srv = (dt in ("pc", "computer", "workstation", "laptop", "server", "this_pc")) and not is_phone
        is_infra = dt in ("router", "switch", "wifi", "ap", "server")
        has_cl = _device_has_lanmap_client(dev, getattr(app, "_lanmap_client_ips", set()))

        # 1. Sửa hộp 'Phương pháp khắc phục gợi ý' riêng cho ĐIỆN THOẠI (không gợi ý WoL / Windows Firewall!)
        if is_phone:
            def _fix_phone_tips(w: Any) -> None:
                try:
                    if w.__class__.__name__ == "CTkLabel":
                        txt = str(w.cget("text") or "")
                        if "Windows Firewall" in txt or "Bật máy (WoL)" in txt:
                            w.configure(
                                text=(
                                    "1. Kiểm tra điện thoại có đang tắt Wi-Fi, bật Chế độ máy bay hoặc ra ngoài vùng phủ sóng không.\n"
                                    "2. Nhiều điện thoại iOS/Android tự động tắt phản hồi Ping khi khóa màn hình để tiết kiệm pin.\n"
                                    "3. Nếu là điện thoại lạ xài ké Wi-Fi: bấm nút '🚫 Kick / Cô lập thiết bị này' bên dưới để copy MAC & chặn trên Router!"
                                )
                            )
                    for ch in w.winfo_children():
                        _fix_phone_tips(ch)
                except Exception:
                    pass

            _fix_phone_tips(sf)

        # 2. Tìm khung lưới nút 'Công cụ quản trị chủ động' và lọc + XẾP LẠI 2 CỘT KHÔNG LỖ TRỐNG!
        grid_parents: set[Any] = set()

        def _filter_all(w: Any) -> None:
            try:
                if w.__class__.__name__ == "CTkButton" and not getattr(w, "_v14_custom", False):
                    txt = str(w.cget("text") or "")
                    hide = False
                    if "RDP" in txt:
                        hide = True
                    elif ("SNMP" in txt or "SSH" in txt) and not is_infra:
                        hide = True
                    elif ("WoL" in txt or "Bật máy" in txt or "Wake" in txt) and not is_pc_or_srv:
                        hide = True
                    elif any(k in txt for k in ("Chia sẻ", "Xem chia sẻ", "LanMap Client", "Share", "SMB", "tin nhắn qua mạng")) and not is_pc_or_srv:
                        hide = True
                    elif is_phone and ("Web quản trị" in txt or "Web Admin" in txt):
                        hide = True

                    if hide:
                        if w.winfo_manager() == "grid":
                            grid_parents.add(w.master)
                        w.grid_forget()
                        w.pack_forget()
                    elif w.winfo_manager() == "grid" and any(k in txt for k in ("Quét cổng", "Traceroute", "Quét sâu", "Web quản trị")):
                        grid_parents.add(w.master)
                for ch in w.winfo_children():
                    _filter_all(ch)
            except Exception:
                pass

        _filter_all(sf)

        # Xếp gọn lại các nút còn sống trong grid 2 cột liên tục để KHÔNG CÓ LỖ TRỐNG!
        for gp in grid_parents:
            try:
                visible_btns = [ch for ch in gp.winfo_children() if ch.__class__.__name__ == "CTkButton" and ch.winfo_manager() == "grid"]
                for idx_b, b in enumerate(visible_btns):
                    r, c = divmod(idx_b, 2)
                    b.grid(row=r, column=c, sticky="ew", padx=3, pady=3)
            except Exception:
                pass

        # 3. Gắn nút Kick thẳng / Kick / Gửi File sạch sẽ (chỉ gắn 1 lần cho đúng thiết bị hiện tại)
        for ch in list(sf.winfo_children()):
            if getattr(ch, "_v13_custom", False) or getattr(ch, "_v14_custom", False):
                ch.destroy()

        if is_pc_or_srv and not is_this_pc:
            bf = ctk.CTkButton(sf, text="📤 Gửi File qua mạng LAN...", height=30, fg_color="#0284c7", hover_color="#0369a1",
                               command=lambda d=dev: _quick_send_file_lan_v12(app, d))
            bf._v14_custom = True
            bf.pack(fill="x", padx=8, pady=(4, 2))

        if has_cl and not is_this_pc:
            def _ik(d: Any = dev) -> None:
                ip = str(getattr(d, "ip", ""))
                pin = getattr(app, "_client_pin_cache", {}).get(ip)
                if not pin:
                    dlg = ctk.CTkInputDialog(text=f"Nhập PIN LanMap Client trên {d.name} ({ip}):", title="⚡ Kick thẳng")
                    pin = (dlg.get_input() or "").strip()
                    if not pin:
                        return
                    app._client_pin_cache[ip] = pin
                res = query_lanmap_agent(ip, pin, "isolate_net", "")
                if res and res.get("ok"):
                    app._kicked_ips.add(ip)
                    app.topology.redraw()
                    messagebox.showinfo("⚡ Đã Kick thẳng!", str(res.get("report") or f"Đã ngắt mạng {d.name}!"))
                else:
                    messagebox.showwarning("Chưa Kick được", str((res or {}).get("error") or "Kiểm tra lại Client v2.5 / PIN!"))

            bik = ctk.CTkButton(sf, text="⚡ Kick thẳng (Ngắt mạng Client)", height=30, fg_color="#b91c1c", hover_color="#991b1b", command=_ik)
            bik._v14_custom = True
            bik.pack(fill="x", padx=8, pady=(2, 2))

        if not is_this_pc:
            bk = ctk.CTkButton(sf, text="🚫 Kick / Cô lập thiết bị này...", height=30, fg_color="#dc2626", hover_color="#b91c1c",
                               command=lambda d=dev: KickIsolateDialog(app, preselect_dev=d))
            bk._v14_custom = True
            bk.pack(fill="x", padx=8, pady=(2, 6))

        _enable_fast_mousewheel_v14(sf)
    except Exception:
        pass


# --- 2. Quét Toàn Bộ Nhiều VLAN / Công ty (Multi-VLAN Enterprise Scanner) ---
class LiveNetworkDashboardDialog(ctk.CTkToplevel):
    def __init__(self, master: ctk.CTk) -> None:
        super().__init__(master)
        self.app = master
        self.title("📊 Dashboard Phân tích & Đánh giá Sức khỏe Mạng hiện tại")
        self.geometry("940x650")
        self.minsize(800, 540)
        self.transient(master)

        score, full_txt = build_live_network_analysis_text(master)
        devs = list(getattr(getattr(master, "real_state", None), "devices", []) or [])
        cips = getattr(master, "_lanmap_client_ips", set()) or set()
        inf = security_marker_levels(master)
        on_c = sum(1 for d in devs if not any(w in str(getattr(d, "status", "")).lower() for w in ("off", "down", "fail", "lost", "alert")))
        off_c = len(devs) - on_c
        rogue_c = sum(1 for d in devs if not getattr(d, "trusted", True))
        cl_c = sum(1 for d in devs if _device_has_lanmap_client(d, cips))

        # Hàng 1: 5 Thẻ KPI màu sắc trực quan
        kpi_row = ctk.CTkFrame(self, fg_color="transparent")
        kpi_row.pack(fill="x", padx=14, pady=(12, 8))
        kpis = [
            ("Điểm sức khỏe", f"{score}/100", "#16a34a" if score >= 80 else ("#d97706" if score >= 60 else "#dc2626")),
            ("Online / Tổng", f"{on_c} / {len(devs)}", "#0284c7"),
            ("Mất phản hồi", str(off_c), "#dc2626" if off_c else "#16a34a"),
            ("Thiết bị lạ (!)", str(rogue_c), "#d97706" if rogue_c else "#16a34a"),
            ("Client / Cần xem", f"{cl_c} / {len(inf)}", "#7c3aed" if not inf else "#dc2626"),
        ]
        for lbl, val, col in kpis:
            card = ctk.CTkFrame(kpi_row, corner_radius=10, fg_color=col)
            card.pack(side="left", fill="x", expand=True, padx=4)
            ctk.CTkLabel(card, text=lbl, text_color="#f8fafc", font=ctk.CTkFont(size=11)).pack(pady=(8, 0))
            ctk.CTkLabel(card, text=val, text_color="#ffffff", font=ctk.CTkFont(size=20, weight="bold")).pack(pady=(0, 8))

        # Hàng 2: Biểu đồ thanh ngang phân bố loại thiết bị trong mạng
        chart_card = ctk.CTkFrame(self, corner_radius=10)
        chart_card.pack(fill="x", padx=14, pady=(0, 8))
        ctk.CTkLabel(chart_card, text="📊 Phân bố hạ tầng thiết bị trong mạng hiện tại:", font=ctk.CTkFont(size=12, weight="bold")).pack(anchor="w", padx=12, pady=(8, 4))
        cv = tk.Canvas(chart_card, height=96, bg="#0f172a", highlightthickness=0)
        cv.pack(fill="x", padx=12, pady=(0, 10))

        counts = {"Router/SW": 0, "PC/Server": 0, "Điện thoại": 0, "Camera IP": 0, "Máy in/Khác": 0}
        for d in devs:
            dt = str(getattr(d, "device_type", "") or "").lower()
            nm = str(getattr(d, "name", "") or "").lower()
            if dt in ("router", "switch", "wifi", "ap"):
                counts["Router/SW"] += 1
            elif dt in ("phone", "mobile") or "điện thoại" in nm:
                counts["Điện thoại"] += 1
            elif dt == "camera" or "camera" in nm:
                counts["Camera IP"] += 1
            elif dt in ("pc", "computer", "laptop", "server", "this_pc"):
                counts["PC/Server"] += 1
            else:
                counts["Máy in/Khác"] += 1

        colors = ["#0ea5e9", "#2563eb", "#a855f7", "#f59e0b", "#64748b"]
        max_v = max(1, max(counts.values()))
        for idx_c, ((k_name, v_cnt), col) in enumerate(zip(counts.items(), colors)):
            x0 = 20 + idx_c * 172
            bw = int((v_cnt / max_v) * 140)
            cv.create_text(x0, 22, text=f"{k_name}: {v_cnt}", fill="#f8fafc", anchor="w", font=("Segoe UI", 9, "bold"))
            cv.create_rectangle(x0, 38, x0 + 145, 58, fill="#1e293b", outline="")
            if bw > 0:
                cv.create_rectangle(x0, 38, x0 + max(8, bw), 58, fill=col, outline="")

        # Hàng 3: Báo cáo phân tích chi tiết + Nút xuất CSV
        tb = ctk.CTkTextbox(self, font=ctk.CTkFont(family="Consolas", size=11), wrap="word")
        tb.pack(fill="both", expand=True, padx=14, pady=(0, 8))
        tb.insert("1.0", full_txt)
        tb.configure(state="disabled")

        foot = ctk.CTkFrame(self, fg_color="transparent")
        foot.pack(fill="x", padx=14, pady=(0, 10))
        ctk.CTkButton(foot, text="📄 Xuất Báo cáo CSV Đẹp (Excel)", fg_color="#16a34a",
                      command=lambda: export_pretty_csv_report_v9(master)).pack(side="left")
        ctk.CTkButton(foot, text="Đóng", width=90, command=self.destroy).pack(side="right")


