# --- 5. Gộp Lưu sơ đồ & Sao lưu thành 1 + Mở file .lanmap trực tiếp từ Windows ---
def _register_lanmap_file_assoc_v14() -> None:
    """Đăng ký đuôi .lanmap trong HKCU (không cần Admin) để bấm đúp mở bằng LanMap!"""
    if os.name != "nt":
        return
    try:
        import winreg
        exe = _sys_v14.executable
        cmd = f'"{exe}" "{Path(_sys_v14.argv[0]).resolve()}" "%1"' if exe.lower().endswith("python.exe") or exe.lower().endswith("pythonw.exe") else f'"{exe}" "%1"'
        with winreg.CreateKey(winreg.HKEY_CURRENT_USER, r"Software\Classes\.lanmap") as k:
            winreg.SetValue(k, "", winreg.REG_SZ, "LanMap.TopologyFile")
        with winreg.CreateKey(winreg.HKEY_CURRENT_USER, r"Software\Classes\LanMap.TopologyFile") as k:
            winreg.SetValue(k, "", winreg.REG_SZ, "LanMap Network Topology")
        with winreg.CreateKey(winreg.HKEY_CURRENT_USER, r"Software\Classes\LanMap.TopologyFile\shell\open\command") as k:
            winreg.SetValue(k, "", winreg.REG_SZ, cmd)
    except Exception:
        pass


def _unified_save_topology_v14(app: Any) -> None:
    app._save_real()
    filename = filedialog.asksaveasfilename(
        parent=app, title="Lưu & sao lưu sơ đồ LanMap", initialfile="LanMap.lanmap",
        defaultextension=".lanmap", filetypes=[("Sơ đồ LanMap", "*.lanmap"), ("Sao lưu JSON", "*.json")],
    )
    if not filename:
        return
    try:
        app.repo.backup_topology(
            app.active_devices, app.active_links, app.active_annotations, app.active_incidents,
            DEMO_SUBNET if app.demo_mode else app.real_state.selected_subnet,
            DEMO_GATEWAY if app.demo_mode else app.real_state.selected_gateway,
            Path(filename),
            floors=app.active_floors,
        )
    except OSError as exc:
        messagebox.showerror("Lỗi lưu sơ đồ", str(exc), parent=app)
    else:
        app._set_status(f"Đã lưu sơ đồ {Path(filename).name}.")


# --- 6. Dọn sạch Menu Công cụ (KHÔNG BAO GIỜ CÒN 2 ĐƯỜNG -----) + Gộp Menu Tệp + Thêm Quét Multi-VLAN ---
def _clean_menus_v14(app: Any) -> None:
    _clean_and_rebuild_pro_menus_v13(app)
    try:
        mbar_name = app.cget("menu")
        if not mbar_name:
            return
        mbar = app.nametowidget(mbar_name)
        lang = getattr(getattr(app, "real_state", None), "language", "vi")
        for i in range((mbar.index("end") or 0) + 1):
            if mbar.type(i) != "cascade":
                continue
            lbl = str(mbar.entrycget(i, "label") or "")
            sub = mbar.nametowidget(mbar.entrycget(i, "menu"))

            if any(k in lbl for k in ("Công cụ", "Tools", "工具")):
                # Thêm mục Quét nhiều VLAN công ty (nếu chưa có)
                end_j = sub.index("end") or 0
                scan_labels = ("quét nhiều vlan", "multi-vlan company scanner", "多 vlan 企业全网扫描")
                has_vlan = any(
                    any(label in str(sub.entrycget(j, "label")).casefold() for label in scan_labels)
                    for j in range(end_j + 1) if sub.type(j) == "command"
                )
                if not has_vlan:
                    pos = end_j
                    for j in range(end_j + 1):
                        if sub.type(j) == "command" and any(k in str(sub.entrycget(j, "label") or "") for k in ("Quét mạng hiện tại", "Scan current network", "扫描当前网络")):
                            pos = j + 1
                            break
                    vlan_lbl = "🏢 Quét Nhiều VLAN / Toàn Công ty..." if lang == "vi" else ("🏢 Multi-VLAN Company Scanner..." if lang == "en" else "🏢 多 VLAN 企业全网扫描...")
                    sub.insert_command(pos, label=vlan_lbl, command=lambda: MultiVlanScannerDialog(app))

                # BƯỚC QUÉT CUỐI: Xóa TRIỆT ĐỂ mọi separator đứng liền kề nhau!
                end_k = sub.index("end")
                if end_k is not None:
                    prev_is_sep = True
                    for j in range(end_k, -1, -1):
                        if sub.type(j) == "separator":
                            if prev_is_sep or j == 0:
                                sub.delete(j)
                            else:
                                prev_is_sep = True
                        else:
                            prev_is_sep = False

            elif any(k in lbl for k in ("Trợ giúp", "Help", "帮助")):
                # Nối 'Phân tích & Đánh giá Mạng hiện tại' sang Dashboard KPI trực quan mới!
                end_h = sub.index("end") or 0
                for j in range(end_h + 1):
                    if sub.type(j) == "command":
                        sl = str(sub.entrycget(j, "label") or "")
                        if any(k in sl for k in ("Phân tích", "Live Network Health", "当前网络")):
                            sub.entryconfig(j, command=lambda: LiveNetworkDashboardDialog(app))

            elif any(k in lbl for k in ("Tệp", "File", "文件")):
                # Gộp 'Lưu sơ đồ' và 'Sao lưu sơ đồ' thành 1 mục duy nhất gọn đẹp!
                end_f = sub.index("end") or 0
                for j in range(end_f, -1, -1):
                    if sub.type(j) == "command":
                        sl = str(sub.entrycget(j, "label") or "")
                        if "Sao lưu sơ đồ" in sl or "Backup Topology" in sl:
                            sub.delete(j)
                        elif "Lưu sơ đồ" in sl or "Save Topology" in sl:
                            sub.entryconfig(j, label="💾 Lưu & Sao lưu sơ đồ (.lanmap) [Ctrl+S]", command=lambda: _unified_save_topology_v14(app))
    except Exception:
        pass


# --- 7. Vẽ lại LanBot GIỐNG HỆT Router Robot 3D màu kem bo tròn (bỏ chữ phiên bản v7/v13!) ---
_orig_lanbot_v13 = LanBotAssistant


class LanBotAssistant(_orig_lanbot_v13):
    def _apply_v12_startup_and_hooks(self, app: Any) -> None:
        super()._apply_v12_startup_and_hooks(app)
        app.after(1800, lambda: _clean_menus_v14(app))
        # Tự đăng ký đuôi .lanmap trên Windows
        app.after(2500, _register_lanmap_file_assoc_v14)

    def _draw_bot(self) -> None:
        """Tạo hình Router Robot kem 3D siêu dễ thương (giống mẫu người dùng gửi: 2 ăng-ten dày, 5 khe tản nhiệt, nút cam, 2 chân, 3 đèn LED!)."""
        c = self.canvas
        c.delete("all")
        alert = self._mood == "alert"
        cream = "#fee2e2" if alert else "#f5ebe0"
        shade = "#fca5a5" if alert else "#e3d5ca"
        rim = "#dc2626" if alert else "#c8b6a6"

        # 2 ăng-ten dày hơi nghiêng ra 2 bên (đặc trưng Router Robot!)
        c.create_line(23, 24, 15, 6, fill=cream, width=7, capstyle=tk.ROUND)
        c.create_line(23, 24, 15, 6, fill=rim, width=1.2)
        c.create_line(53, 24, 61, 6, fill=cream, width=7, capstyle=tk.ROUND)
        c.create_line(53, 24, 61, 6, fill=rim, width=1.2)

        # 2 chân đế nhỏ màu xanh đậm ở dưới
        c.create_oval(19, 57, 31, 65, fill="#0f3d56", outline=rim, width=1.2)
        c.create_oval(45, 57, 57, 65, fill="#0f3d56", outline=rim, width=1.2)

        # 2 tay tròn nhỏ màu kem 2 bên
        c.create_oval(3, 38, 13, 47, fill=cream, outline=rim, width=1.3)
        c.create_oval(63, 38, 73, 47, fill=cream, outline=rim, width=1.3)

        # Thân Router bo tròn bầu bĩnh màu kem
        c.create_oval(10, 18, 66, 61, fill=cream, outline=rim, width=1.8)
        c.create_rectangle(15, 22, 61, 57, fill=cream, outline="")
        # 5 khe tản nhiệt nhỏ trên đỉnh đầu
        for gx in (26, 32, 38, 44, 50):
            c.create_line(gx, 21, gx + 2, 24, fill="#b09e8c", width=1.6, capstyle=tk.ROUND)
        # Nút bấm cam bên hông trái
        c.create_oval(10, 31, 15, 38, fill="#f97316", outline="#ea580c")

        # Màn hình xanh dương đậm bo tròn
        c.create_oval(18, 27, 58, 54, fill="#04334a", outline="#0c4a6e", width=1.6)
        c.create_rectangle(23, 28, 53, 53, fill="#04334a", outline="")

        if self._mood == "cool":
            c.create_rectangle(22, 34, 36, 42, fill="#020617", outline="#38bdf8", width=1.5)
            c.create_rectangle(40, 34, 54, 42, fill="#020617", outline="#38bdf8", width=1.5)
            c.create_line(36, 37, 40, 37, fill="#38bdf8", width=2)
            c.create_arc(32, 43, 44, 48, start=200, extent=140, style=tk.ARC, outline="#22d3ee", width=2)
            tag_txt = "Ngầu 😎"
        elif self._mood == "cable":
            c.create_text(29, 38, text="∩", fill="#22d3ee", font=("Segoe UI", 12, "bold"))
            c.create_text(47, 38, text="∩", fill="#22d3ee", font=("Segoe UI", 12, "bold"))
            c.create_arc(33, 42, 43, 47, start=200, extent=140, style=tk.ARC, outline="#22d3ee", width=2)
            c.create_line(64, 43, 74, 35, fill="#0284c7", width=2.8)
            c.create_rectangle(68, 29, 75, 37, fill="#fbbf24", outline="#0369a1")
            tag_txt = "Cắm cáp"
        elif self._mood == "wrench":
            c.create_text(29, 38, text=">", fill="#38bdf8", font=("Consolas", 11, "bold"))
            c.create_text(47, 38, text="<", fill="#38bdf8", font=("Consolas", 11, "bold"))
            c.create_line(34, 45, 42, 45, fill="#22d3ee", width=2)
            c.create_line(2, 33, 12, 44, fill="#94a3b8", width=3)
            tag_txt = "Sửa RT"
        elif self._mood == "gaming":
            c.create_text(29, 38, text="★", fill="#38bdf8", font=("Segoe UI", 10, "bold"))
            c.create_text(47, 38, text="★", fill="#38bdf8", font=("Segoe UI", 10, "bold"))
            c.create_arc(33, 42, 43, 47, start=200, extent=140, style=tk.ARC, outline="#22d3ee", width=2)
            tag_txt = "Game 🎮"
