# Khôi phục LanBot 3D Windows 11, Đủ nút Nhắn tin & Đồng bộ Client, Sắp xếp bảng theo Tên/IP & Tối ưu máy yếu.

import copy as _v22_copy
import html as _v22_html
import http.server as _v22_http_server
import socketserver as _v22_socketserver
import urllib.parse as _v22_urlparse


_INVENTORY_DEVICE_ORDER = (
    TYPE_ROUTER, TYPE_SWITCH, TYPE_WIFI, TYPE_THIS_PC, TYPE_PC, TYPE_SERVER,
    TYPE_PHONE, TYPE_PRINTER, TYPE_CAMERA, TYPE_TV, TYPE_UNKNOWN,
)
_INVENTORY_DEVICE_RANK = {kind: rank for rank, kind in enumerate(_INVENTORY_DEVICE_ORDER)}
INVENTORY_TYPE_IP = "Loại → IP tăng dần"


def _inventory_device_type(dev: Device) -> str:
    if dev.is_gateway:
        return TYPE_ROUTER
    if dev.is_this_pc:
        return TYPE_THIS_PC
    return normalize_device_type(dev.device_type)


def _v22_ip_sort_key(dev: Device) -> tuple[int, int, str, str]:
    name = (dev.name or "").casefold()
    try:
        ip_value = int(ipaddress.IPv4Address(dev.ip.strip()))
    except (ValueError, AttributeError):
        return (1, 0, name, dev.id)
    return (0, ip_value, name, dev.id)


def _descending_ip_sort_key(dev: Device) -> tuple[int, int, str, str]:
    invalid, ip_value, name, device_id = _v22_ip_sort_key(dev)
    return invalid, -ip_value, name, device_id


def _device_inventory_sort_key(dev: Device) -> tuple[int, int, int, str, str]:
    return (_INVENTORY_DEVICE_RANK[_inventory_device_type(dev)], *_v22_ip_sort_key(dev))


def _sort_unregistered(devices: list[Device], mode: str) -> list[Device]:
    pending = [d for d in devices if not d.registered]
    if mode == "Tên A-Z":
        return sorted(pending, key=lambda d: ((d.name or "").casefold(), _v22_ip_sort_key(d)))
    if mode == "IP ↑":
        return sorted(pending, key=_v22_ip_sort_key)
    return sorted(pending, key=_device_inventory_sort_key)


def _v22_get_local_lan_ip(app: Any) -> str:
    st = getattr(app, "real_state", None)
    ip = str(getattr(st, "selected_ip", "") or "").strip()
    if ip and not ip.startswith("127."):
        return ip
    for d in list(getattr(app, "active_devices", []) or []):
        if getattr(d, "is_this_pc", False) and getattr(d, "ip", ""):
            return str(d.ip)
    try:
        s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        s.connect(("8.8.8.8", 80))
        ip = s.getsockname()[0]
        s.close()
        return ip
    except Exception:
        return "127.0.0.1"


