        frow.pack(fill="x", pady=(0, 6))
        ctk.CTkLabel(frow, text="Tệp muốn chia sẻ:", font=ctk.CTkFont(size=12, weight="bold")).pack(side="left")
        ctk.CTkButton(frow, text="🗑 Xóa danh sách", width=116, height=28, fg_color="#64748b", command=self._clear_files).pack(side="right", padx=(6, 0))
        ctk.CTkButton(frow, text="+ Chọn tệp...", width=112, height=28, fg_color="#0284c7", command=self._pick_files).pack(side="right")

        self.files_box = ctk.CTkTextbox(body, height=96, font=ctk.CTkFont(family="Consolas", size=11))
