        self.files_box.insert("1.0", "Chưa chọn tệp nào. Bấm '+ Chọn tệp...' để thêm (hoặc chỉ bật Chia sẻ để máy khác gửi tệp lên máy này).")
        self.files_box.configure(state="disabled")

        # Khung điều khiển Web Share (Không cần Client)
        web_card = ctk.CTkFrame(body, corner_radius=8)
        web_card.pack(fill="x", pady=(0, 8))
        ctk.CTkLabel(
            web_card,
            text="🌐 Chia sẻ qua trình duyệt LAN (Điện thoại iOS/Android, Laptop, PC mở link là tải/gửi ngay)",
            font=ctk.CTkFont(size=12, weight="bold"),
            anchor="w",
        ).pack(fill="x", padx=10, pady=(8, 4))

        url_row = ctk.CTkFrame(web_card, fg_color="transparent")
