        self.url_entry = ctk.CTkEntry(url_row, textvariable=self.url_var, state="readonly", font=ctk.CTkFont(family="Consolas", size=12, weight="bold"))
        self.url_entry.pack(side="left", fill="x", expand=True, padx=(0, 6))
        ctk.CTkButton(url_row, text="📋 Copy Link", width=96, height=30, command=self._copy_url).pack(side="left", padx=(0, 4))
        ctk.CTkButton(url_row, text="🌐 Mở thử", width=82, height=30, fg_color="#475569", command=self._open_url).pack(side="left")

